window.NTS_BANK={"v":"2026-11","q":[{"id":"nt-001","cd":"nt","m":1,"l":"kt","q":"Theo Hiến pháp, Nhân dân thực hiện quyền lực nhà nước bằng dân chủ trực tiếp và bằng dân chủ đại diện thông qua những cơ quan nào?","a":["Quốc hội, HĐND và các cơ quan khác của Nhà nước","Chỉ thông qua Quốc hội và Chính phủ","Ủy ban MTTQ Việt Nam và các tổ chức chính trị - xã hội","Chỉ thông qua HĐND và UBND các cấp"],"why":"Điều 6 Hiến pháp: Nhân dân thực hiện quyền lực nhà nước bằng dân chủ trực tiếp, bằng dân chủ đại diện thông qua Quốc hội, HĐND và các cơ quan khác của Nhà nước. HĐND là một kênh dân chủ đại diện được hiến định.","cc":"Điều 6 Hiến pháp nước Cộng hòa xã hội chủ nghĩa Việt Nam năm 2013 (văn bản hợp nhất năm 2025)"},{"id":"nt-004","cd":"nt","m":1,"l":"kt","q":"Theo Hiến pháp, công dân đủ bao nhiêu tuổi trở lên thì có quyền bầu cử và có quyền ứng cử vào Quốc hội, HĐND?","a":["Đủ 18 tuổi có quyền bầu cử; đủ 21 tuổi có quyền ứng cử","Đủ 18 tuổi có quyền bầu cử và có quyền ứng cử","Đủ 16 tuổi có quyền bầu cử; đủ 18 tuổi có quyền ứng cử","Đủ 18 tuổi có quyền bầu cử; đủ 25 tuổi có quyền ứng cử"],"why":"Điều 27 Hiến pháp: công dân đủ mười tám tuổi trở lên có quyền bầu cử và đủ hai mươi mốt tuổi trở lên có quyền ứng cử vào Quốc hội, HĐND. Tuổi ứng cử cao hơn tuổi bầu cử.","cc":"Điều 27 Hiến pháp nước Cộng hòa xã hội chủ nghĩa Việt Nam năm 2013 (văn bản hợp nhất năm 2025)"},{"id":"nt-005","cd":"nt","m":1,"l":"kt","q":"Theo Hiến pháp (sửa đổi, bổ sung năm 2025), các đơn vị hành chính của nước ta được tổ chức thành mấy cấp?","a":["Hai cấp: tỉnh, thành phố trực thuộc trung ương và các đơn vị hành chính dưới đó do luật định","Ba cấp: tỉnh, huyện, xã và các đơn vị hành chính tương đương do luật định","Hai cấp: tỉnh, thành phố trực thuộc trung ương và huyện, quận, thị xã","Bốn cấp: trung ương, tỉnh, huyện, xã và các đơn vị hành chính tương đương"],"why":"Khoản 1 Điều 110 Hiến pháp (sửa đổi năm 2025): đơn vị hành chính được tổ chức thành hai cấp, gồm tỉnh, thành phố trực thuộc trung ương và các đơn vị hành chính dưới tỉnh, thành phố trực thuộc trung ương do luật định; không còn cấp huyện.","cc":"Khoản 1 Điều 110 Hiến pháp nước Cộng hòa xã hội chủ nghĩa Việt Nam năm 2013 (văn bản hợp nhất năm 2025)"},{"id":"nt-008","cd":"nt","m":1,"l":"kt","q":"Theo Hiến pháp, HĐND có vị trí như thế nào trong bộ máy nhà nước ở địa phương?","a":["Là cơ quan quyền lực nhà nước ở địa phương","Là cơ quan hành chính nhà nước ở địa phương","Là cơ quan chấp hành của Quốc hội ở địa phương","Là cơ quan thường trực của chính quyền địa phương"],"why":"Khoản 1 Điều 113 Hiến pháp: HĐND là cơ quan quyền lực nhà nước ở địa phương, đại diện cho ý chí, nguyện vọng và quyền làm chủ của Nhân dân. Cơ quan hành chính nhà nước ở địa phương là UBND.","cc":"Khoản 1 Điều 113 Hiến pháp nước Cộng hòa xã hội chủ nghĩa Việt Nam năm 2013 (văn bản hợp nhất năm 2025)"},{"id":"nt-009","cd":"nt","m":1,"l":"kt","q":"Theo Hiến pháp, HĐND do Nhân dân địa phương bầu ra và chịu trách nhiệm trước những chủ thể nào?","a":["Nhân dân địa phương và cơ quan nhà nước cấp trên","Nhân dân địa phương và UBND cùng cấp","Ủy ban MTTQ Việt Nam cùng cấp và cử tri địa phương","Chỉ trước cơ quan nhà nước cấp trên trực tiếp"],"why":"Khoản 1 Điều 113 Hiến pháp: HĐND do Nhân dân địa phương bầu ra, chịu trách nhiệm trước Nhân dân địa phương và cơ quan nhà nước cấp trên. HĐND không chịu trách nhiệm trước UBND; ngược lại, UBND chịu trách nhiệm trước HĐND.","cc":"Khoản 1 Điều 113 Hiến pháp nước Cộng hòa xã hội chủ nghĩa Việt Nam năm 2013 (văn bản hợp nhất năm 2025)"},{"id":"nt-010","cd":"nt","m":1,"l":"kt","q":"Theo Hiến pháp, UBND ở cấp chính quyền địa phương do cơ quan nào bầu và là cơ quan chấp hành của cơ quan nào?","a":["Do HĐND cùng cấp bầu, là cơ quan chấp hành của HĐND","Do cử tri địa phương bầu, là cơ quan chấp hành của Chính phủ","Do HĐND cấp trên bầu, là cơ quan chấp hành của UBND cấp trên","Do HĐND cùng cấp bầu, là cơ quan chấp hành của Chính phủ"],"why":"Khoản 1 Điều 114 Hiến pháp: UBND ở cấp chính quyền địa phương do HĐND cùng cấp bầu, là cơ quan chấp hành của HĐND, cơ quan hành chính nhà nước ở địa phương. Chính phủ mới là cơ quan chấp hành của Quốc hội.","cc":"Khoản 1 Điều 114 Hiến pháp nước Cộng hòa xã hội chủ nghĩa Việt Nam năm 2013 (văn bản hợp nhất năm 2025)"},{"id":"nt-014","cd":"nt","m":1,"l":"kt","q":"Theo Hiến pháp, đại biểu HĐND thực hiện chế độ tiếp xúc, báo cáo với cử tri về những hoạt động nào?","a":["Hoạt động của mình và của HĐND","Hoạt động của mình và của UBND cùng cấp","Chỉ hoạt động của cá nhân đại biểu","Hoạt động của HĐND và của Ủy ban MTTQ cùng cấp"],"why":"Khoản 1 Điều 115 Hiến pháp: đại biểu HĐND liên hệ chặt chẽ với cử tri, chịu sự giám sát của cử tri, thực hiện chế độ tiếp xúc, báo cáo với cử tri về hoạt động của mình và của HĐND, trả lời những yêu cầu, kiến nghị của cử tri.","cc":"Khoản 1 Điều 115 Hiến pháp nước Cộng hòa xã hội chủ nghĩa Việt Nam năm 2013 (văn bản hợp nhất năm 2025)"},{"id":"nt-016","cd":"nt","m":1,"l":"kt","q":"Theo Hiến pháp, HĐND, UBND thực hiện chế độ thông báo tình hình của địa phương cho những tổ chức nào?","a":["MTTQ Việt Nam và các đoàn thể nhân dân","Tòa án nhân dân và Viện kiểm sát nhân dân","Các doanh nghiệp, hợp tác xã trên địa bàn","Hội đồng bầu cử quốc gia và Kiểm toán nhà nước"],"why":"Khoản 1 Điều 116 Hiến pháp: HĐND, UBND thực hiện chế độ thông báo tình hình của địa phương cho MTTQ Việt Nam và các đoàn thể nhân dân, lắng nghe ý kiến, kiến nghị của các tổ chức này về xây dựng chính quyền và phát triển kinh tế - xã hội.","cc":"Khoản 1 Điều 116 Hiến pháp nước Cộng hòa xã hội chủ nghĩa Việt Nam năm 2013 (văn bản hợp nhất năm 2025)"},{"id":"nt-019","cd":"nt","m":1,"l":"kt","q":"Theo Nghị quyết số 203/2025/QH15 sửa đổi, bổ sung Hiến pháp, đơn vị hành chính cấp huyện trong cả nước kết thúc hoạt động từ ngày nào?","a":["Ngày 01/7/2025","Ngày 16/6/2025","Ngày 01/01/2026","Ngày 15/3/2026"],"why":"Khoản 2 Điều 2 Nghị quyết 203/2025/QH15: kết thúc hoạt động của đơn vị hành chính cấp huyện trong cả nước từ ngày 01/7/2025. Ngày 16/6/2025 là ngày Nghị quyết được thông qua và có hiệu lực thi hành.","cc":"Khoản 2 Điều 2 Nghị quyết số 203/2025/QH15 của Quốc hội sửa đổi, bổ sung một số điều của Hiến pháp"},{"id":"nt-022","cd":"nt","m":1,"l":"kt","q":"Theo Nghị quyết số 202/2025/QH15, sau khi sắp xếp, cả nước có bao nhiêu đơn vị hành chính cấp tỉnh?","a":["34 đơn vị, gồm 28 tỉnh và 06 thành phố","34 đơn vị, gồm 29 tỉnh và 05 thành phố","63 đơn vị, gồm 57 tỉnh và 06 thành phố","32 đơn vị, gồm 26 tỉnh và 06 thành phố"],"why":"Khoản 24 Điều 1 Nghị quyết 202/2025/QH15: sau khi sắp xếp, cả nước có 34 đơn vị hành chính cấp tỉnh, gồm 28 tỉnh và 06 thành phố; trong đó 19 tỉnh và 04 thành phố hình thành sau sắp xếp, 11 tỉnh, thành phố không sắp xếp.","cc":"Khoản 24 Điều 1 Nghị quyết số 202/2025/QH15 của Quốc hội về việc sắp xếp đơn vị hành chính cấp tỉnh"},{"id":"nt-023","cd":"nt","m":1,"l":"kt","q":"Theo Nghị quyết số 202/2025/QH15 về việc sắp xếp đơn vị hành chính cấp tỉnh, tỉnh Thanh Hóa thuộc trường hợp nào?","a":["Thuộc 11 tỉnh, thành phố không thực hiện sắp xếp","Hợp nhất với tỉnh Nghệ An thành tỉnh mới","Hợp nhất với tỉnh Ninh Bình thành tỉnh mới","Hợp nhất với tỉnh Hòa Bình thành tỉnh mới"],"why":"Khoản 24 Điều 1 Nghị quyết 202/2025/QH15 nêu 11 tỉnh, thành phố không thực hiện sắp xếp, trong đó có Thanh Hóa (cùng Cao Bằng, Điện Biên, Hà Tĩnh, Lai Châu, Lạng Sơn, Nghệ An, Quảng Ninh, Sơn La, Hà Nội, Huế).","cc":"Khoản 24 Điều 1 Nghị quyết số 202/2025/QH15 của Quốc hội về việc sắp xếp đơn vị hành chính cấp tỉnh"},{"id":"nt-025","cd":"nt","m":1,"l":"kt","q":"Theo Luật Tổ chức chính quyền địa phương số 72/2025/QH15, đơn vị hành chính cấp xã gồm những loại nào?","a":["Xã, phường, đặc khu trực thuộc cấp tỉnh","Xã, phường, thị trấn trực thuộc cấp huyện","Xã, phường, thị trấn, đặc khu trực thuộc cấp tỉnh","Huyện, quận, thị xã, thành phố thuộc tỉnh"],"why":"Điểm b khoản 1 Điều 1 Luật 72/2025: cấp xã gồm xã, phường, đặc khu trực thuộc cấp tỉnh. Mô hình hai cấp không còn cấp huyện và trong các loại đơn vị cấp xã cũng không còn thị trấn.","cc":"Điểm b khoản 1 Điều 1 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nt-026","cd":"nt","m":1,"l":"kt","q":"Theo Luật số 72/2025/QH15, đặc khu là đơn vị hành chính được thành lập ở địa bàn nào?","a":["Ở một số hải đảo có vị trí quan trọng","Ở các khu kinh tế cửa khẩu biên giới","Ở các đô thị lớn có mật độ dân cư cao","Ở các xã miền núi đặc biệt khó khăn"],"why":"Khoản 1 Điều 1 Luật 72/2025: xã là đơn vị hành chính ở nông thôn; phường ở đô thị; đặc khu ở một số hải đảo có vị trí quan trọng. Đặc khu là đơn vị cấp xã, khác với đơn vị hành chính - kinh tế đặc biệt do Quốc hội quyết định thành lập.","cc":"Khoản 1 Điều 1 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nt-027","cd":"nt","m":1,"l":"kt","q":"Theo Luật số 72/2025/QH15, HĐND hoạt động theo chế độ nào?","a":["Chế độ tập thể, quyết định theo đa số","Chế độ thủ trưởng, Chủ tịch HĐND quyết định","Chế độ tập thể, quyết định khi mọi đại biểu đều nhất trí","Chế độ thường trực, Thường trực HĐND quyết định"],"why":"Khoản 1 Điều 4 Luật 72/2025: HĐND hoạt động theo chế độ tập thể, quyết định theo đa số. Chủ tịch HĐND hay Thường trực HĐND không quyết định thay tập thể HĐND.","cc":"Khoản 1 Điều 4 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nt-037","cd":"nt","m":1,"l":"kt","q":"Theo Luật số 72/2025/QH15, cơ quan nào quyết định thành lập, giải thể, nhập, chia, điều chỉnh địa giới và đổi tên đơn vị hành chính cấp tỉnh?","a":["Quốc hội","Ủy ban Thường vụ Quốc hội","Chính phủ","Thủ tướng Chính phủ"],"why":"Khoản 1 Điều 9 Luật 72/2025: Quốc hội quyết định thành lập, giải thể, nhập, chia, điều chỉnh địa giới và đổi tên đơn vị hành chính cấp tỉnh. Với đơn vị hành chính cấp xã, thẩm quyền thuộc UBTVQH.","cc":"Khoản 1 Điều 9 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nt-050","cd":"nt","m":1,"l":"kt","q":"Luật Tổ chức chính quyền địa phương số 72/2025/QH15 được Quốc hội thông qua ngày 16/6/2025. Luật này có hiệu lực thi hành từ khi nào?","a":["Từ ngày được thông qua (16/6/2025)","Từ ngày 01/7/2025","Từ ngày 01/01/2026","Sau 45 ngày kể từ ngày được thông qua"],"why":"Khoản 1 Điều 51 Luật 72/2025: Luật có hiệu lực thi hành từ ngày được thông qua, tức 16/6/2025. Ngày 01/7/2025 là ngày chính quyền cấp huyện kết thúc hoạt động, không phải ngày Luật có hiệu lực.","cc":"Khoản 1 Điều 51 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nt-003","cd":"nt","m":2,"l":"th","q":"Một đại biểu HĐND xã A có nhiều biểu hiện không còn xứng đáng với sự tín nhiệm của Nhân dân. Theo Hiến pháp, đại biểu này có thể bị chủ thể nào bãi nhiệm?","a":["Cử tri hoặc HĐND xã A","UBTVQH hoặc Thường trực HĐND tỉnh","Ủy ban MTTQ Việt Nam hoặc UBND xã A","Chủ tịch HĐND hoặc Chủ tịch UBND xã A"],"why":"Khoản 2 Điều 7 Hiến pháp: đại biểu HĐND bị cử tri hoặc HĐND bãi nhiệm khi không còn xứng đáng với sự tín nhiệm của Nhân dân. Quyền bãi nhiệm thuộc về cử tri và cơ quan dân cử, không thuộc cơ quan hành chính hay MTTQ.","cc":"Khoản 2 Điều 7 Hiến pháp nước Cộng hòa xã hội chủ nghĩa Việt Nam năm 2013 (văn bản hợp nhất năm 2025)"},{"id":"nt-006","cd":"nt","m":2,"l":"kt","q":"Theo Điều 111 Hiến pháp, cấp chính quyền địa phương gồm HĐND và UBND được tổ chức ở đơn vị hành chính phù hợp với đặc điểm nông thôn, đô thị, hải đảo do cơ quan nào quy định?","a":["Quốc hội","Chính phủ","Ủy ban Thường vụ Quốc hội","HĐND cấp tỉnh"],"why":"Khoản 2 Điều 111 Hiến pháp: cấp chính quyền địa phương gồm có HĐND và UBND được tổ chức ở đơn vị hành chính phù hợp với đặc điểm nông thôn, đô thị, hải đảo do Quốc hội quy định, không phải do Chính phủ hay địa phương tự quy định.","cc":"Khoản 2 Điều 111 Hiến pháp nước Cộng hòa xã hội chủ nghĩa Việt Nam năm 2013 (văn bản hợp nhất năm 2025)"},{"id":"nt-007","cd":"nt","m":2,"l":"kt","q":"Theo Hiến pháp, chính quyền địa phương ở đơn vị hành chính - kinh tế đặc biệt được quy định như thế nào?","a":["Do Quốc hội quy định khi thành lập đơn vị hành chính - kinh tế đặc biệt đó","Do Chính phủ quy định sau khi Quốc hội thành lập đơn vị đó","Do UBTVQH quy định theo đề nghị của Chính phủ","Do HĐND cấp tỉnh nơi có đơn vị đó quy định"],"why":"Khoản 3 Điều 111 Hiến pháp: chính quyền địa phương ở đơn vị hành chính - kinh tế đặc biệt do Quốc hội quy định khi thành lập đơn vị đó. Đơn vị hành chính - kinh tế đặc biệt cũng do chính Quốc hội thành lập.","cc":"Khoản 3 Điều 111 Hiến pháp nước Cộng hòa xã hội chủ nghĩa Việt Nam năm 2013 (văn bản hợp nhất năm 2025)"},{"id":"nt-011","cd":"nt","m":2,"l":"th","q":"Một cơ quan nhà nước cấp trên dự kiến giao chính quyền xã A thực hiện một số nhiệm vụ thuộc trách nhiệm của mình. Theo Hiến pháp, việc giao nhiệm vụ này phải kèm theo điều gì?","a":["Các điều kiện bảo đảm thực hiện nhiệm vụ đó","Nghị quyết chấp thuận của HĐND xã A","Văn bản đồng ý của Ủy ban MTTQ Việt Nam xã A","Cam kết tự bố trí toàn bộ kinh phí của xã A"],"why":"Khoản 3 Điều 112 Hiến pháp: trong trường hợp cần thiết, chính quyền địa phương được giao thực hiện một số nhiệm vụ của cơ quan nhà nước cấp trên với các điều kiện bảo đảm thực hiện nhiệm vụ đó. Giao việc phải đi kèm điều kiện thực hiện.","cc":"Khoản 3 Điều 112 Hiến pháp nước Cộng hòa xã hội chủ nghĩa Việt Nam năm 2013 (văn bản hợp nhất năm 2025)"},{"id":"nt-012","cd":"nt","m":2,"l":"kt","q":"Theo Điều 115 Hiến pháp, người nào sau đây KHÔNG thuộc đối tượng mà đại biểu HĐND có quyền chất vấn?","a":["Chủ tịch Ủy ban MTTQ Việt Nam cùng cấp","Viện trưởng Viện kiểm sát nhân dân","Thủ trưởng cơ quan thuộc UBND","Thành viên khác của UBND (ngoài Chủ tịch)"],"why":"Khoản 2 Điều 115 Hiến pháp: đại biểu HĐND có quyền chất vấn Chủ tịch UBND, các thành viên khác của UBND, Chánh án Tòa án nhân dân, Viện trưởng Viện kiểm sát nhân dân và Thủ trưởng cơ quan thuộc UBND. Chủ tịch Ủy ban MTTQ không thuộc diện bị chất vấn.","cc":"Khoản 2 Điều 115 Hiến pháp nước Cộng hòa xã hội chủ nghĩa Việt Nam năm 2013 (văn bản hợp nhất năm 2025)"},{"id":"nt-013","cd":"nt","m":2,"l":"th","q":"Đại biểu HĐND xã A gửi kiến nghị đến một đơn vị đóng trên địa bàn về việc xả thải gây ô nhiễm. Theo Hiến pháp, người đứng đầu đơn vị này có trách nhiệm gì đối với kiến nghị của đại biểu?","a":["Tiếp đại biểu, xem xét, giải quyết kiến nghị của đại biểu","Chuyển kiến nghị đến Thường trực HĐND để trả lời thay","Chỉ giải quyết khi kiến nghị được HĐND biểu quyết thông qua","Báo cáo UBND xã A và chờ chỉ đạo rồi mới tiếp đại biểu"],"why":"Khoản 2 Điều 115 Hiến pháp: đại biểu HĐND có quyền kiến nghị với các cơ quan nhà nước, tổ chức, đơn vị ở địa phương; người đứng đầu cơ quan, tổ chức, đơn vị này có trách nhiệm tiếp đại biểu, xem xét, giải quyết kiến nghị của đại biểu.","cc":"Khoản 2 Điều 115 Hiến pháp nước Cộng hòa xã hội chủ nghĩa Việt Nam năm 2013 (văn bản hợp nhất năm 2025)"},{"id":"nt-015","cd":"nt","m":2,"l":"kt","q":"Theo Hiến pháp, Chủ tịch Ủy ban MTTQ Việt Nam ở địa phương được mời tham dự hội nghị UBND cùng cấp trong trường hợp nào?","a":["Khi hội nghị bàn các vấn đề có liên quan","Tại mọi hội nghị, với tư cách thành viên UBND","Chỉ khi được HĐND cùng cấp giới thiệu tham dự","Chỉ tại hội nghị tổng kết công tác hằng năm"],"why":"Khoản 2 Điều 116 Hiến pháp: Chủ tịch Ủy ban MTTQ Việt Nam và người đứng đầu tổ chức chính trị - xã hội ở địa phương được mời tham dự các kỳ họp HĐND và được mời tham dự hội nghị UBND cùng cấp khi bàn các vấn đề có liên quan.","cc":"Khoản 2 Điều 116 Hiến pháp nước Cộng hòa xã hội chủ nghĩa Việt Nam năm 2013 (văn bản hợp nhất năm 2025)"},{"id":"nt-024","cd":"nt","m":2,"l":"kt","q":"Theo Nghị quyết số 202/2025/QH15, tỉnh Ninh Bình mới (giáp tỉnh Thanh Hóa) được hình thành từ việc sắp xếp những tỉnh nào?","a":["Hà Nam, Nam Định và Ninh Bình","Thái Bình, Nam Định và Ninh Bình","Hòa Bình, Hà Nam và Ninh Bình","Hưng Yên, Thái Bình và Ninh Bình"],"why":"Khoản 8 Điều 1 Nghị quyết 202/2025/QH15: sắp xếp toàn bộ diện tích, dân số của ba tỉnh Hà Nam, Nam Định và Ninh Bình thành tỉnh Ninh Bình mới; tỉnh này giáp Hưng Yên, Phú Thọ, Thanh Hóa, Hà Nội và Biển Đông.","cc":"Khoản 8 Điều 1 Nghị quyết số 202/2025/QH15 của Quốc hội về việc sắp xếp đơn vị hành chính cấp tỉnh"},{"id":"nt-028","cd":"nt","m":2,"l":"kt","q":"Theo Luật số 72/2025/QH15, UBND cũng hoạt động theo chế độ tập thể, quyết định theo đa số như HĐND, nhưng có thêm yêu cầu nào?","a":["Đồng thời đề cao thẩm quyền và trách nhiệm của Chủ tịch UBND","Đồng thời phải được Thường trực HĐND cùng cấp phê duyệt","Đồng thời mọi quyết định phải được toàn thể thành viên nhất trí","Đồng thời đề cao vai trò quyết định của các cơ quan chuyên môn"],"why":"Khoản 1 Điều 4 Luật 72/2025: UBND hoạt động theo chế độ tập thể, quyết định theo đa số; đồng thời đề cao thẩm quyền và trách nhiệm của Chủ tịch UBND. Đây là điểm khác so với HĐND, vốn chỉ làm việc tập thể, quyết định theo đa số.","cc":"Khoản 1 Điều 4 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nt-029","cd":"nt","m":2,"l":"th","q":"Một công việc được pháp luật xác định rõ thuộc thẩm quyền của chính quyền xã A, nhưng UBND xã vẫn gửi văn bản xin tỉnh quyết định thay để \"cho chắc\". Theo nguyên tắc tại Luật số 72/2025/QH15, cách làm đúng là gì?","a":["Chính quyền xã A phải tự quyết định, tổ chức thực hiện và tự chịu trách nhiệm","Chuyển công việc lên chính quyền cấp tỉnh quyết định thay cho xã","Tạm dừng giải quyết cho đến khi có ý kiến của HĐND tỉnh","Xin ý kiến Ủy ban MTTQ xã A rồi mới được quyết định"],"why":"Khoản 5 Điều 4 Luật 72/2025: những công việc thuộc thẩm quyền của chính quyền địa phương phải do chính quyền địa phương quyết định và tổ chức thực hiện; phát huy vai trò tự chủ và tự chịu trách nhiệm. Không đùn đẩy việc của mình lên cấp trên.","cc":"Khoản 5 Điều 4 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nt-031","cd":"nt","m":2,"l":"kt","q":"Theo Luật số 72/2025/QH15, nhiệm kỳ 05 năm của mỗi khóa HĐND được tính từ thời điểm nào?","a":["Từ ngày khai mạc kỳ họp thứ nhất của HĐND khóa đó","Từ ngày bầu cử đại biểu HĐND khóa đó","Từ ngày công bố kết quả bầu cử đại biểu HĐND","Từ ngày HĐND khóa trước bế mạc kỳ họp cuối cùng"],"why":"Khoản 4 Điều 5 Luật 72/2025: nhiệm kỳ mỗi khóa HĐND là 05 năm kể từ ngày khai mạc kỳ họp thứ nhất của HĐND khóa đó đến ngày khai mạc kỳ họp thứ nhất của HĐND khóa mới, không tính từ ngày bầu cử.","cc":"Khoản 4 Điều 5 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nt-032","cd":"nt","m":2,"l":"kt","q":"Theo Luật số 72/2025/QH15, việc rút ngắn hoặc kéo dài nhiệm kỳ của HĐND do cơ quan nào quyết định?","a":["Quốc hội quyết định theo đề nghị của UBTVQH","UBTVQH quyết định theo đề nghị của Chính phủ","Chính phủ quyết định theo đề nghị của HĐND cấp tỉnh","HĐND cấp tỉnh tự quyết định khi có 2/3 đại biểu tán thành"],"why":"Khoản 4 Điều 5 Luật 72/2025: việc rút ngắn hoặc kéo dài nhiệm kỳ của HĐND do Quốc hội quyết định theo đề nghị của UBTVQH. HĐND không tự quyết định thay đổi nhiệm kỳ của mình.","cc":"Khoản 4 Điều 5 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nt-034","cd":"nt","m":2,"l":"th","q":"HĐND xã A khóa mới vừa khai mạc kỳ họp thứ nhất (HĐND khóa trước hết nhiệm kỳ) nhưng chưa bầu xong UBND khóa mới. Theo Luật số 72/2025/QH15, trong thời gian này UBND xã A khóa trước xử lý thế nào?","a":["Tiếp tục làm nhiệm vụ cho đến khi HĐND khóa mới bầu ra UBND khóa mới","Chấm dứt hoạt động ngay khi HĐND hết nhiệm kỳ","Chỉ Chủ tịch UBND tiếp tục làm việc, các thành viên khác nghỉ","Bàn giao toàn bộ công việc cho Thường trực HĐND điều hành"],"why":"Khoản 2 Điều 6 Luật 72/2025: nhiệm kỳ UBND theo nhiệm kỳ HĐND cùng cấp; khi HĐND hết nhiệm kỳ, UBND tiếp tục làm nhiệm vụ cho đến khi HĐND khóa mới bầu ra UBND khóa mới, bảo đảm quản lý hành chính không bị gián đoạn.","cc":"Khoản 2 Điều 6 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nt-035","cd":"nt","m":2,"l":"th","q":"Ủy ban MTTQ Việt Nam xã A tổng hợp ý kiến, kiến nghị của Nhân dân về một tuyến đường xuống cấp và chuyển đến chính quyền xã. Theo Luật số 72/2025/QH15, chính quyền xã A có trách nhiệm gì?","a":["Tiếp nhận, giải quyết và trả lời các ý kiến, kiến nghị đó","Tiếp nhận để tham khảo, không bắt buộc phải trả lời","Chuyển toàn bộ lên chính quyền cấp tỉnh giải quyết","Chỉ trả lời khi kiến nghị được nêu tại kỳ họp HĐND"],"why":"Khoản 4 Điều 7 Luật 72/2025: chính quyền địa phương có trách nhiệm tiếp nhận, giải quyết và trả lời các ý kiến, kiến nghị của Nhân dân địa phương do Ủy ban MTTQ Việt Nam tổng hợp và chuyển đến. Trả lời là nghĩa vụ, không phải tùy nghi.","cc":"Khoản 4 Điều 7 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nt-036","cd":"nt","m":2,"l":"kt","q":"Theo Luật số 72/2025/QH15, tiêu chuẩn của đơn vị hành chính làm căn cứ khi thành lập, nhập, chia đơn vị hành chính, điều chỉnh địa giới đơn vị hành chính do cơ quan nào quy định?","a":["Ủy ban Thường vụ Quốc hội","Chính phủ","Quốc hội","HĐND cấp tỉnh"],"why":"Điểm đ khoản 2 Điều 8 Luật 72/2025: phải căn cứ vào tiêu chuẩn của đơn vị hành chính theo quy định của UBTVQH. Dễ nhầm với tiêu chí phân loại đơn vị hành chính (Điều 3) – nội dung này thực hiện theo quy định của Chính phủ.","cc":"Điểm đ khoản 2 Điều 8 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nt-039","cd":"nt","m":2,"l":"kt","q":"Theo Luật số 72/2025/QH15, việc thành lập, giải thể, nhập, chia, điều chỉnh địa giới và đổi tên đơn vị hành chính phải được lấy ý kiến Nhân dân ở phạm vi nào?","a":["Ở những đơn vị hành chính cấp xã chịu ảnh hưởng trực tiếp","Ở mọi đơn vị hành chính cấp xã trong tỉnh","Ở các tỉnh, thành phố giáp ranh với địa phương đó","Chỉ ở đơn vị hành chính cấp xã có dân số đông nhất"],"why":"Khoản 3 Điều 10 Luật 72/2025: phải lấy ý kiến Nhân dân ở những đơn vị hành chính cấp xã chịu ảnh hưởng trực tiếp; UBND cấp tỉnh chịu trách nhiệm tổ chức lấy ý kiến bằng các hình thức phù hợp theo quy định của Chính phủ.","cc":"Khoản 3 Điều 10 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nt-041","cd":"nt","m":2,"l":"th","q":"Một điểm tập kết rác gây ô nhiễm ảnh hưởng đến cả xã A và xã B. Theo nguyên tắc phân định thẩm quyền tại Luật số 72/2025/QH15 (khi luật, nghị quyết của Quốc hội không quy định khác), vấn đề này thuộc thẩm quyền giải quyết của cấp nào?","a":["Chính quyền địa phương cấp tỉnh","Chính quyền xã nơi đặt điểm tập kết rác","Cơ quan nhà nước ở trung ương","Chính quyền xã có số dân bị ảnh hưởng nhiều hơn"],"why":"Điểm g khoản 2 Điều 11 Luật 72/2025: vấn đề liên quan đến phạm vi từ 02 đơn vị hành chính cấp xã trở lên thuộc thẩm quyền giải quyết của chính quyền cấp tỉnh; cấp tỉnh có thể giao chính quyền một trong các xã có liên quan chủ trì giải quyết.","cc":"Điểm g khoản 2 Điều 11 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nt-043","cd":"nt","m":2,"l":"kt","q":"Theo nguyên tắc tại Điều 12 Luật số 72/2025/QH15, việc phân quyền cho chính quyền địa phương các cấp phải được quy định trong loại văn bản nào?","a":["Luật, nghị quyết của Quốc hội","Nghị định của Chính phủ","Quyết định của Thủ tướng Chính phủ","Nghị quyết của HĐND cấp tỉnh"],"why":"Khoản 1 Điều 12 Luật 72/2025: việc phân quyền cho chính quyền địa phương các cấp phải được quy định trong luật, nghị quyết của Quốc hội. Riêng giai đoạn chuyển tiếp, khoản 1 Điều 54 giao Chính phủ ban hành văn bản phân định lại nhiệm vụ, quyền hạn để áp dụng tạm thời.","cc":"Khoản 1 Điều 12 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nt-045","cd":"nt","m":2,"l":"kt","q":"Theo Luật số 72/2025/QH15, HĐND cấp tỉnh được phân cấp nhiệm vụ, quyền hạn của mình cho những chủ thể nào?","a":["UBND cùng cấp hoặc HĐND cấp xã","Thường trực HĐND cấp tỉnh hoặc các Ban của HĐND cấp tỉnh","Chủ tịch UBND cấp tỉnh hoặc Chủ tịch UBND cấp xã","Cơ quan chuyên môn thuộc UBND cấp tỉnh hoặc UBND cấp xã"],"why":"Khoản 1 Điều 13 Luật 72/2025: HĐND cấp tỉnh phân cấp cho UBND cùng cấp hoặc HĐND cấp xã. Việc phân cấp cho cơ quan chuyên môn, UBND, Chủ tịch UBND cấp xã là thẩm quyền của UBND, Chủ tịch UBND cấp tỉnh.","cc":"Khoản 1 Điều 13 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nt-047","cd":"nt","m":2,"l":"th","q":"Sở X được UBND tỉnh phân cấp thực hiện một nhiệm vụ. Do thiếu người, Sở X muốn phân cấp tiếp nhiệm vụ này cho UBND các xã. Theo Luật số 72/2025/QH15, việc này có được phép không?","a":["Không, vì cơ quan được phân cấp không được phân cấp tiếp nhiệm vụ đó","Được, nếu UBND các xã đồng ý nhận bằng văn bản","Được, nếu Sở X bảo đảm kinh phí cho UBND các xã","Được, sau khi Sở X báo cáo Thường trực HĐND tỉnh"],"why":"Khoản 4 Điều 13 Luật 72/2025: cơ quan, tổ chức, đơn vị, cá nhân được phân cấp không được phân cấp tiếp nhiệm vụ, quyền hạn mà mình được phân cấp; nếu gặp khó khăn thì có quyền đề nghị cơ quan phân cấp điều chỉnh nội dung phân cấp.","cc":"Khoản 4 Điều 13 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nt-017","cd":"nt","m":3,"l":"th","q":"HĐND tỉnh ban hành một nghị quyết trái với luật. Theo Hiến pháp, thẩm quyền xử lý nghị quyết này được phân định như thế nào?","a":["Thủ tướng Chính phủ đình chỉ việc thi hành và đề nghị UBTVQH bãi bỏ","Thủ tướng Chính phủ trực tiếp ra quyết định bãi bỏ nghị quyết đó","Chính phủ đình chỉ việc thi hành và đề nghị Quốc hội bãi bỏ","Chủ tịch UBND tỉnh đình chỉ việc thi hành và đề nghị HĐND tỉnh bãi bỏ"],"why":"Khoản 4 Điều 98 Hiến pháp: Thủ tướng đình chỉ việc thi hành nghị quyết của HĐND cấp tỉnh trái Hiến pháp, luật, văn bản cấp trên, đồng thời đề nghị UBTVQH bãi bỏ. Riêng văn bản của UBND, Chủ tịch UBND cấp tỉnh thì Thủ tướng được trực tiếp bãi bỏ.","cc":"Khoản 4 Điều 98 Hiến pháp nước Cộng hòa xã hội chủ nghĩa Việt Nam năm 2013 (văn bản hợp nhất năm 2025)"},{"id":"nt-018","cd":"nt","m":3,"l":"kt","q":"Theo Hiến pháp, Hội đồng bầu cử quốc gia có vai trò gì đối với cuộc bầu cử đại biểu HĐND các cấp?","a":["Chỉ đạo và hướng dẫn công tác bầu cử đại biểu HĐND các cấp","Trực tiếp tổ chức bầu cử đại biểu HĐND các cấp","Phê chuẩn kết quả bầu cử đại biểu HĐND các cấp","Không có nhiệm vụ gì đối với bầu cử đại biểu HĐND"],"why":"Khoản 1 Điều 117 Hiến pháp: Hội đồng bầu cử quốc gia có nhiệm vụ tổ chức bầu cử đại biểu Quốc hội; còn với bầu cử đại biểu HĐND các cấp thì chỉ đạo và hướng dẫn công tác bầu cử, không trực tiếp tổ chức.","cc":"Khoản 1 Điều 117 Hiến pháp nước Cộng hòa xã hội chủ nghĩa Việt Nam năm 2013 (văn bản hợp nhất năm 2025)"},{"id":"nt-030","cd":"nt","m":3,"l":"th","q":"Bà M không cư trú tại xã A nhưng đang công tác tại một doanh nghiệp đóng trên địa bàn xã A. Xét riêng tiêu chuẩn về nơi cư trú, công tác của đại biểu HĐND theo Luật số 72/2025/QH15, bà M có đáp ứng để là đại biểu HĐND xã A không?","a":["Có, vì chỉ cần cư trú hoặc công tác tại đơn vị hành chính đó","Không, vì đại biểu bắt buộc phải cư trú tại xã A","Không, vì phải vừa cư trú vừa công tác tại xã A","Có, nhưng chỉ khi công tác tại cơ quan nhà nước của xã A"],"why":"Điểm đ khoản 3 Điều 5 Luật 72/2025: đại biểu HĐND phải cư trú hoặc công tác tại cơ quan, tổ chức, đơn vị, doanh nghiệp ở đơn vị hành chính mà mình là đại biểu. Chỉ cần một trong hai; nơi công tác có thể là doanh nghiệp, không chỉ cơ quan nhà nước.","cc":"Điểm đ khoản 3 Điều 5 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nt-033","cd":"nt","m":3,"l":"kt","q":"Theo Điều 5 Luật số 72/2025/QH15, Chính phủ có trách nhiệm nào sau đây đối với HĐND?","a":["Hướng dẫn, kiểm tra HĐND trong việc thực hiện văn bản của cơ quan nhà nước cấp trên","Giám sát, hướng dẫn hoạt động và ban hành Quy chế làm việc mẫu của HĐND","Lãnh đạo, hướng dẫn, kiểm tra, thanh tra tổ chức và hoạt động của HĐND","Quyết định rút ngắn hoặc kéo dài nhiệm kỳ của HĐND theo đề nghị của UBTVQH"],"why":"Khoản 5 Điều 5: UBTVQH giám sát, hướng dẫn hoạt động của HĐND và ban hành Quy chế làm việc mẫu; Chính phủ hướng dẫn, kiểm tra HĐND trong việc thực hiện văn bản của cơ quan nhà nước cấp trên. Chính phủ lãnh đạo, thanh tra UBND chứ không phải HĐND.","cc":"Khoản 5 Điều 5 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nt-038","cd":"nt","m":3,"l":"th","q":"Phường B muốn đổi tên để gắn với một địa danh lịch sử của địa phương; Nhân dân và HĐND phường đều đồng thuận. Theo Luật số 72/2025/QH15, cơ quan nào có thẩm quyền quyết định việc đổi tên phường B?","a":["Ủy ban Thường vụ Quốc hội","HĐND cấp tỉnh","Chính phủ","Quốc hội"],"why":"Khoản 2 Điều 9 Luật 72/2025: UBTVQH quyết định cả việc đổi tên đơn vị hành chính cấp xã, không chỉ thành lập, nhập, chia. Quốc hội quyết định đối với cấp tỉnh; HĐND cấp tỉnh, cấp xã chỉ xem xét, cho ý kiến về đề án.","cc":"Khoản 2 Điều 9 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nt-040","cd":"nt","m":3,"l":"th","q":"UBND tỉnh xây dựng đề án nhập xã A và xã B thành một xã mới. Sau khi có kết quả lấy ý kiến Nhân dân và hoàn thiện đề án, theo Luật số 72/2025/QH15, đề án phải được gửi đến HĐND nào để xem xét, cho ý kiến?","a":["HĐND cấp tỉnh và HĐND xã A, HĐND xã B","Chỉ HĐND cấp tỉnh","Chỉ HĐND xã A và HĐND xã B","HĐND của mọi xã, phường trong tỉnh"],"why":"Khoản 4 Điều 10 Luật 72/2025: đề án về đơn vị hành chính cấp xã phải gửi HĐND cấp tỉnh và HĐND cấp xã ở các đơn vị hành chính có liên quan trực tiếp để xem xét, cho ý kiến. Đề án về đơn vị hành chính cấp tỉnh thì gửi HĐND cấp tỉnh.","cc":"Khoản 4 Điều 10 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nt-042","cd":"nt","m":3,"l":"th","q":"UBND xã A để hồ sơ thủ tục hành chính của người dân, doanh nghiệp bị ùn tắc kéo dài dù việc này thuộc nhiệm vụ, quyền hạn của xã. Theo Luật số 72/2025/QH15, trong trường hợp cần thiết, Chủ tịch UBND tỉnh được làm gì?","a":["Trực tiếp chỉ đạo, điều hành việc giải quyết vấn đề thuộc nhiệm vụ của UBND xã A","Không được can thiệp vì việc thuộc thẩm quyền của cấp xã","Chỉ được kiến nghị HĐND xã A tổ chức giám sát việc giải quyết","Phải chờ HĐND tỉnh ra nghị quyết cho phép mới được chỉ đạo"],"why":"Khoản 3 Điều 11 Luật 72/2025: trường hợp cần thiết, UBND, Chủ tịch UBND cấp tỉnh trực tiếp chỉ đạo, điều hành việc giải quyết vấn đề thuộc nhiệm vụ, quyền hạn của UBND, Chủ tịch UBND cấp xã, không để thủ tục của người dân, doanh nghiệp bị đình trệ, ùn tắc.","cc":"Khoản 3 Điều 11 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nt-044","cd":"nt","m":3,"l":"kt","q":"Theo Luật số 72/2025/QH15, chính quyền địa phương có được phân cấp, ủy quyền tiếp các nhiệm vụ, quyền hạn mà mình được PHÂN QUYỀN hay không?","a":["Được, trừ khi luật, nghị quyết của Quốc hội quy định không được phân cấp, ủy quyền","Không, nhiệm vụ được phân quyền thì phải tự mình trực tiếp thực hiện","Được, nhưng phải có văn bản chấp thuận trước của Chính phủ","Chỉ được ủy quyền, không được phân cấp nhiệm vụ đã được phân quyền"],"why":"Khoản 2 Điều 12: nhiệm vụ được phân quyền có thể phân cấp, ủy quyền theo Điều 13, Điều 14, trừ khi luật, nghị quyết của Quốc hội quy định không được. Khác với nhiệm vụ nhận phân cấp, nhận ủy quyền: không được phân cấp tiếp, ủy quyền tiếp.","cc":"Khoản 2 Điều 12 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nt-046","cd":"nt","m":3,"l":"kt","q":"Theo Luật số 72/2025/QH15, đặc điểm nào sau đây là của ỦY QUYỀN, giúp phân biệt với phân cấp (vốn được thực hiện liên tục, thường xuyên)?","a":["Thực hiện trong khoảng thời gian xác định kèm theo các điều kiện cụ thể","Phải được quy định trong luật hoặc nghị quyết của Quốc hội","Phải được quy định trong văn bản quy phạm pháp luật của bên giao","Bên nhận được giao tiếp nhiệm vụ đó cho cơ quan, cá nhân khác"],"why":"Khoản 1 Điều 14: ủy quyền là giao thực hiện nhiệm vụ trong khoảng thời gian xác định kèm theo các điều kiện cụ thể, bằng văn bản ủy quyền. Phân cấp thì liên tục, thường xuyên và quy định trong văn bản quy phạm pháp luật; phân quyền do luật, nghị quyết của Quốc hội quy định.","cc":"Khoản 1 Điều 14 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nt-048","cd":"nt","m":3,"l":"th","q":"Chủ tịch UBND xã A ủy quyền bằng văn bản cho một công chức xã thực hiện một nhiệm vụ trong 03 tháng. Công chức này làm vượt quá phạm vi được ủy quyền, gây hậu quả. Theo Luật số 72/2025/QH15, trách nhiệm được xác định thế nào?","a":["Công chức nhận ủy quyền chịu trách nhiệm trước pháp luật; người ủy quyền không chịu trách nhiệm về việc làm sai đó","Chủ tịch UBND xã chịu toàn bộ trách nhiệm vì là người ủy quyền; công chức không phải chịu trách nhiệm","Chủ tịch UBND xã và công chức cùng chịu trách nhiệm ngang nhau trước pháp luật về hậu quả xảy ra","UBND xã chịu trách nhiệm tập thể; cả người ủy quyền và người nhận ủy quyền đều được miễn trách nhiệm"],"why":"Khoản 4 Điều 14 Luật 72/2025: bên nhận ủy quyền thực hiện không đúng nội dung, phạm vi, thời hạn đã được ủy quyền thì chịu trách nhiệm trước pháp luật về kết quả thực hiện; bên ủy quyền không phải chịu trách nhiệm về việc thực hiện không đúng đó.","cc":"Khoản 4 Điều 14 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nt-049","cd":"nt","m":3,"l":"kt","q":"Theo Luật số 72/2025/QH15, cơ quan nào quy định chi tiết phạm vi nhiệm vụ, quyền hạn mà Chủ tịch UBND cấp xã được ủy quyền cho công chức thuộc UBND cấp xã?","a":["HĐND cấp tỉnh","UBND cấp tỉnh","HĐND cấp xã","Chính phủ"],"why":"Khoản 8 Điều 14 Luật 72/2025: HĐND cấp tỉnh quy định chi tiết phạm vi nhiệm vụ, quyền hạn được ủy quyền cho công chức thuộc UBND cấp xã. Công chức được giao ký thừa ủy quyền thì được sử dụng con dấu của UBND cấp xã.","cc":"Khoản 8 Điều 14 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"bc-001","cd":"bc","m":1,"l":"kt","q":"Việc bầu cử đại biểu HĐND được tiến hành theo những nguyên tắc nào?","a":["Phổ thông, bình đẳng, trực tiếp và bỏ phiếu kín","Phổ thông, bình đẳng, gián tiếp và bỏ phiếu kín","Dân chủ, công khai, trực tiếp và biểu quyết giơ tay","Tập trung dân chủ, bình đẳng, trực tiếp và công khai"],"why":"Luật quy định bốn nguyên tắc bầu cử: phổ thông, bình đẳng, trực tiếp và bỏ phiếu kín, áp dụng chung cho bầu cử đại biểu Quốc hội và đại biểu HĐND.","cc":"Điều 1 Luật Bầu cử đại biểu Quốc hội và đại biểu HĐND (văn bản hợp nhất số 83/VBHN-VPQH năm 2026)"},{"id":"bc-002","cd":"bc","m":1,"l":"kt","q":"Tính đến ngày bầu cử được công bố, công dân Việt Nam đủ bao nhiêu tuổi trở lên thì có quyền ứng cử vào HĐND các cấp?","a":["Đủ hai mươi mốt tuổi","Đủ mười tám tuổi","Đủ hai mươi tuổi","Đủ hai mươi lăm tuổi"],"why":"Công dân đủ 18 tuổi trở lên có quyền bầu cử; còn quyền ứng cử vào Quốc hội, HĐND các cấp đòi hỏi đủ 21 tuổi trở lên, đều tính đến ngày bầu cử được công bố.","cc":"Điều 2 Luật Bầu cử đại biểu Quốc hội và đại biểu HĐND (văn bản hợp nhất số 83/VBHN-VPQH năm 2026)"},{"id":"bc-003","cd":"bc","m":1,"l":"kt","q":"Người ứng cử đại biểu HĐND phải đáp ứng các tiêu chuẩn của đại biểu HĐND được quy định tại luật nào?","a":["Luật Tổ chức chính quyền địa phương","Luật Tổ chức Quốc hội","Luật Cán bộ, công chức","Luật Mặt trận Tổ quốc Việt Nam"],"why":"Luật Bầu cử không tự đặt tiêu chuẩn riêng mà dẫn chiếu: người ứng cử đại biểu HĐND theo tiêu chuẩn tại Luật Tổ chức chính quyền địa phương, người ứng cử đại biểu Quốc hội theo Luật Tổ chức Quốc hội.","cc":"Khoản 2 Điều 3 Luật Bầu cử đại biểu Quốc hội và đại biểu HĐND (văn bản hợp nhất số 83/VBHN-VPQH năm 2026)"},{"id":"bc-004","cd":"bc","m":1,"l":"kt","q":"Theo Luật Bầu cử đại biểu Quốc hội và đại biểu HĐND, ngày bầu cử phải là ngày nào trong tuần?","a":["Ngày chủ nhật","Ngày thứ bảy","Ngày thứ bảy hoặc ngày chủ nhật","Bất kỳ ngày nào do Quốc hội quyết định"],"why":"Ngày bầu cử phải là ngày chủ nhật và được công bố chậm nhất là 115 ngày trước ngày bầu cử. Quốc hội quyết định ngày bầu cử toàn quốc nhưng vẫn phải chọn ngày chủ nhật.","cc":"Điều 5 Luật Bầu cử đại biểu Quốc hội và đại biểu HĐND (văn bản hợp nhất số 83/VBHN-VPQH năm 2026)"},{"id":"bc-006","cd":"bc","m":1,"l":"kt","q":"Mỗi đơn vị bầu cử đại biểu HĐND được bầu tối đa bao nhiêu đại biểu?","a":["Không quá năm đại biểu","Không quá ba đại biểu","Không quá bốn đại biểu","Không quá bảy đại biểu"],"why":"Mỗi đơn vị bầu cử đại biểu HĐND được bầu không quá năm đại biểu; mức không quá ba đại biểu là của đơn vị bầu cử đại biểu Quốc hội.","cc":"Khoản 4 Điều 10 Luật Bầu cử đại biểu Quốc hội và đại biểu HĐND (văn bản hợp nhất số 83/VBHN-VPQH năm 2026)"},{"id":"bc-008","cd":"bc","m":1,"l":"kt","q":"Theo quy định hiện hành (chính quyền địa phương 2 cấp), Ủy ban bầu cử ở địa phương được thành lập ở những đơn vị hành chính nào?","a":["Ở tỉnh, thành phố và ở xã, phường, đặc khu","Ở tỉnh, thành phố; ở huyện, quận; ở xã, phường, thị trấn","Chỉ ở tỉnh, thành phố","Ở tỉnh, thành phố và ở thôn, tổ dân phố"],"why":"Từ ngày 01/7/2025 không còn Ủy ban bầu cử ở huyện; các tổ chức phụ trách bầu cử ở địa phương gồm Ủy ban bầu cử ở tỉnh, thành phố, Ủy ban bầu cử ở xã, phường, đặc khu, các Ban bầu cử và Tổ bầu cử.","cc":"Khoản 1 Điều 21 Luật Bầu cử đại biểu Quốc hội và đại biểu HĐND (văn bản hợp nhất số 83/VBHN-VPQH năm 2026)"},{"id":"bc-016","cd":"bc","m":1,"l":"kt","q":"Ngoài trường hợp cử tri trong đơn vị vũ trang nhân dân, danh sách cử tri do cơ quan nào lập và lập theo phạm vi nào?","a":["UBND cấp xã lập theo từng khu vực bỏ phiếu","Ủy ban bầu cử ở xã lập theo từng đơn vị bầu cử","Tổ bầu cử lập theo từng thôn, tổ dân phố","Công an cấp xã lập theo từng khu vực bỏ phiếu"],"why":"Danh sách cử tri do UBND cấp xã lập theo từng khu vực bỏ phiếu; riêng danh sách cử tri trong đơn vị vũ trang nhân dân do chỉ huy đơn vị lập để đưa vào danh sách cử tri của khu vực bỏ phiếu nơi đóng quân.","cc":"Khoản 1 Điều 31 Luật Bầu cử đại biểu Quốc hội và đại biểu HĐND (văn bản hợp nhất số 83/VBHN-VPQH năm 2026)"},{"id":"bc-023","cd":"bc","m":1,"l":"kt","q":"Các hội nghị hiệp thương giới thiệu người ứng cử đại biểu HĐND ở mỗi cấp do cơ quan nào tổ chức?","a":["Ban Thường trực Ủy ban MTTQ Việt Nam cùng cấp","Thường trực HĐND cùng cấp","Ủy ban bầu cử cùng cấp","UBND cùng cấp"],"why":"Hội nghị hiệp thương ở mỗi cấp do Ban Thường trực Ủy ban MTTQ Việt Nam cùng cấp tổ chức; đại diện Ủy ban bầu cử, Thường trực HĐND, UBND cùng cấp được mời tham dự.","cc":"Khoản 1 Điều 50 Luật Bầu cử đại biểu Quốc hội và đại biểu HĐND (văn bản hợp nhất số 83/VBHN-VPQH năm 2026)"},{"id":"bc-029","cd":"bc","m":1,"l":"kt","q":"Thời gian vận động bầu cử bắt đầu và kết thúc khi nào?","a":["Từ ngày công bố danh sách chính thức người ứng cử đến trước thời điểm bắt đầu bỏ phiếu 24 giờ","Từ ngày nộp hồ sơ ứng cử đến trước thời điểm bắt đầu bỏ phiếu 24 giờ","Từ ngày công bố danh sách chính thức người ứng cử đến thời điểm bắt đầu bỏ phiếu","Từ ngày hiệp thương lần thứ ba đến trước thời điểm bắt đầu bỏ phiếu 48 giờ"],"why":"Vận động bầu cử chỉ được tiến hành từ ngày công bố danh sách chính thức những người ứng cử và phải kết thúc trước thời điểm bắt đầu bỏ phiếu 24 giờ.","cc":"Điều 64 Luật Bầu cử đại biểu Quốc hội và đại biểu HĐND (văn bản hợp nhất số 83/VBHN-VPQH năm 2026)"},{"id":"bc-030","cd":"bc","m":1,"l":"th","q":"Tại hội nghị tiếp xúc cử tri ở xã A, một người ứng cử đại biểu HĐND xã hứa nếu trúng cử sẽ tặng mỗi hộ trong thôn một phần quà bằng tiền của cá nhân mình. Hành vi này được đánh giá thế nào?","a":["Bị cấm, vì hứa tặng tiền, tài sản để lôi kéo, mua chuộc cử tri","Được phép, vì đó là một phần chương trình hành động","Được phép, nếu quà tặng lấy từ tài sản cá nhân hợp pháp","Được phép, nếu báo cáo trước với Ban Thường trực Ủy ban MTTQ cấp xã"],"why":"Sử dụng hoặc hứa tặng, cho, ủng hộ tiền, tài sản, lợi ích vật chất để lôi kéo, mua chuộc cử tri là hành vi bị cấm trong vận động bầu cử, bất kể nguồn tiền là của ai.","cc":"Khoản 4 Điều 68 Luật Bầu cử đại biểu Quốc hội và đại biểu HĐND (văn bản hợp nhất số 83/VBHN-VPQH năm 2026)"},{"id":"bc-031","cd":"bc","m":1,"l":"th","q":"Trong ngày bầu cử ở xã A, cụ M mắt kém nên không thể tự viết được phiếu bầu, nhưng vẫn đi lại được và đã đến phòng bỏ phiếu. Cách xử lý nào đúng luật?","a":["Cụ M nhờ người khác viết hộ nhưng phải tự mình bỏ phiếu vào hòm phiếu","Cụ M ủy quyền cho người thân viết phiếu và bỏ phiếu thay","Thành viên Tổ bầu cử viết phiếu và bỏ phiếu thay cụ M","Cụ M không tham gia bầu cử vì không tự viết được phiếu"],"why":"Cử tri không thể tự viết phiếu thì nhờ người khác viết hộ nhưng phải tự mình bỏ phiếu; người viết hộ phải giữ bí mật phiếu bầu. Chỉ khi vì khuyết tật không tự bỏ phiếu được mới nhờ người khác bỏ phiếu vào hòm phiếu.","cc":"Khoản 3 Điều 69 Luật Bầu cử đại biểu Quốc hội và đại biểu HĐND (văn bản hợp nhất số 83/VBHN-VPQH năm 2026)"},{"id":"bc-032","cd":"bc","m":1,"l":"th","q":"Bà H ở phường B đang ốm nặng, điều trị tại nhà và không thể đến phòng bỏ phiếu trong ngày bầu cử. Để bà H thực hiện quyền bầu cử, việc nào sau đây đúng luật?","a":["Tổ bầu cử mang hòm phiếu phụ và phiếu bầu đến chỗ ở để bà H tự bầu","Con của bà H mang thẻ cử tri đến phòng bỏ phiếu để bầu thay","Tổ bầu cử ghi nhận bà H vắng mặt vì lý do chính đáng","Bà H gửi phiếu bầu đã viết sẵn nhờ trưởng thôn, tổ trưởng tổ dân phố bỏ hộ"],"why":"Cử tri ốm đau, già yếu, khuyết tật không thể đến phòng bỏ phiếu thì Tổ bầu cử mang hòm phiếu phụ và phiếu bầu đến chỗ ở, chỗ điều trị để cử tri nhận phiếu và tự bầu; không được nhờ người khác bầu thay.","cc":"Khoản 4 Điều 69 Luật Bầu cử đại biểu Quốc hội và đại biểu HĐND (văn bản hợp nhất số 83/VBHN-VPQH năm 2026)"},{"id":"bc-033","cd":"bc","m":1,"l":"kt","q":"Theo quy định chung, việc bỏ phiếu trong ngày bầu cử diễn ra trong khoảng thời gian nào?","a":["Từ bảy giờ sáng đến bảy giờ tối cùng ngày","Từ sáu giờ sáng đến sáu giờ tối cùng ngày","Từ bảy giờ sáng đến năm giờ chiều cùng ngày","Từ tám giờ sáng đến tám giờ tối cùng ngày"],"why":"Việc bỏ phiếu bắt đầu từ 7 giờ sáng đến 7 giờ tối cùng ngày. Tùy tình hình địa phương, Tổ bầu cử có thể cho bắt đầu sớm hơn nhưng không trước 5 giờ sáng, hoặc kết thúc muộn hơn nhưng không quá 9 giờ tối.","cc":"Khoản 1 Điều 71 Luật Bầu cử đại biểu Quốc hội và đại biểu HĐND (văn bản hợp nhất số 83/VBHN-VPQH năm 2026)"},{"id":"bc-035","cd":"bc","m":1,"l":"kt","q":"Để trúng cử đại biểu HĐND, người ứng cử phải đạt số phiếu bầu tối thiểu như thế nào?","a":["Quá một nửa tổng số phiếu bầu hợp lệ","Quá một nửa tổng số cử tri trong danh sách cử tri","Ít nhất hai phần ba tổng số phiếu bầu hợp lệ","Quá một nửa tổng số phiếu thu vào"],"why":"Người trúng cử phải đạt quá một nửa tổng số phiếu bầu hợp lệ; nếu số người đạt mức này nhiều hơn số đại biểu được bầu thì người có số phiếu cao hơn trúng cử.","cc":"Khoản 2 Điều 78 Luật Bầu cử đại biểu Quốc hội và đại biểu HĐND (văn bản hợp nhất số 83/VBHN-VPQH năm 2026)"},{"id":"bc-041","cd":"bc","m":1,"l":"kt","q":"Người có trách nhiệm trong công tác bầu cử mà gian lận phiếu bầu để làm sai lệch kết quả bầu cử thì bị xử lý như thế nào?","a":["Tùy tính chất, mức độ mà bị kỷ luật, xử phạt hành chính hoặc truy cứu trách nhiệm hình sự","Chỉ bị xử lý kỷ luật theo quy định về cán bộ, công chức","Chỉ bị xóa tên khỏi danh sách thành viên tổ chức phụ trách bầu cử","Chỉ bị phê bình, rút kinh nghiệm trước Ủy ban bầu cử"],"why":"Hành vi giả mạo giấy tờ, gian lận phiếu bầu, làm sai lệch kết quả bầu cử tùy theo tính chất, mức độ vi phạm mà bị xử lý kỷ luật, xử phạt vi phạm hành chính hoặc truy cứu trách nhiệm hình sự.","cc":"Điều 95 Luật Bầu cử đại biểu Quốc hội và đại biểu HĐND (văn bản hợp nhất số 83/VBHN-VPQH năm 2026)"},{"id":"bc-045","cd":"bc","m":1,"l":"kt","q":"Theo Nghị quyết 107/2025/UBTVQH15, phụ nữ phải đạt tỷ lệ ít nhất bao nhiêu trong danh sách chính thức những người ứng cử đại biểu HĐND ở từng cấp nhiệm kỳ 2026–2031?","a":["Ít nhất 35%","Ít nhất 30%","Ít nhất 25%","Ít nhất 40%"],"why":"Phụ nữ phải đạt ít nhất 35% trong danh sách chính thức những người ứng cử ở từng cấp; con số khoảng 30% là mục tiêu phấn đấu về tỷ lệ trúng cử trên tổng số đại biểu HĐND ở từng cấp.","cc":"Điểm b khoản 3 Điều 2 Nghị quyết số 107/2025/UBTVQH15 của UBTVQH"},{"id":"bc-005","cd":"bc","m":2,"l":"kt","q":"Số đơn vị bầu cử, danh sách các đơn vị bầu cử đại biểu HĐND cấp xã và số đại biểu được bầu ở mỗi đơn vị bầu cử do cơ quan nào ấn định?","a":["Ủy ban bầu cử ở xã, theo đề nghị của UBND cấp xã","UBND cấp xã, theo đề nghị của Ủy ban bầu cử ở xã","Thường trực HĐND cấp xã, theo đề nghị của UBND cấp xã","Ủy ban bầu cử ở tỉnh, theo đề nghị của UBND cấp xã"],"why":"Đơn vị bầu cử đại biểu HĐND cấp nào do Ủy ban bầu cử ở cấp đó ấn định theo đề nghị của UBND cùng cấp và phải được công bố chậm nhất là 80 ngày trước ngày bầu cử.","cc":"Khoản 3 Điều 10 Luật Bầu cử đại biểu Quốc hội và đại biểu HĐND (văn bản hợp nhất số 83/VBHN-VPQH năm 2026)"},{"id":"bc-007","cd":"bc","m":2,"l":"kt","q":"Theo quy định chung, mỗi khu vực bỏ phiếu có bao nhiêu cử tri?","a":["Từ ba trăm đến bốn nghìn cử tri","Từ ba trăm đến hai nghìn cử tri","Từ năm trăm đến bốn nghìn cử tri","Từ một trăm đến ba nghìn cử tri"],"why":"Mỗi khu vực bỏ phiếu có từ 300 đến 4.000 cử tri; riêng ở miền núi, hải đảo và nơi dân cư không tập trung thì dù chưa đủ 300 cử tri vẫn được thành lập một khu vực bỏ phiếu.","cc":"Khoản 2 Điều 11 Luật Bầu cử đại biểu Quốc hội và đại biểu HĐND (văn bản hợp nhất số 83/VBHN-VPQH năm 2026)"},{"id":"bc-009","cd":"bc","m":2,"l":"kt","q":"Cơ quan nào quyết định thành lập Ủy ban bầu cử ở xã, phường, đặc khu?","a":["UBND cấp xã, sau khi thống nhất với Thường trực HĐND và Ban Thường trực Ủy ban MTTQ cùng cấp","Thường trực HĐND cấp xã, sau khi thống nhất với UBND và Ban Thường trực Ủy ban MTTQ cùng cấp","UBND cấp tỉnh, theo đề nghị của UBND cấp xã và Ban Thường trực Ủy ban MTTQ cấp xã","Ủy ban bầu cử ở tỉnh, theo đề nghị của Thường trực HĐND và UBND cấp xã"],"why":"Chậm nhất 105 ngày trước ngày bầu cử, UBND cấp xã sau khi thống nhất với Thường trực HĐND và Ban Thường trực Ủy ban MTTQ cùng cấp quyết định thành lập Ủy ban bầu cử ở xã (có từ 9 đến 17 thành viên).","cc":"Khoản 2 Điều 22 Luật Bầu cử đại biểu Quốc hội và đại biểu HĐND (văn bản hợp nhất số 83/VBHN-VPQH năm 2026)"},{"id":"bc-011","cd":"bc","m":2,"l":"kt","q":"Tổ bầu cử được thành lập ở đâu và chậm nhất bao nhiêu ngày trước ngày bầu cử?","a":["Ở mỗi khu vực bỏ phiếu, chậm nhất là 43 ngày trước ngày bầu cử","Ở mỗi đơn vị bầu cử, chậm nhất là 70 ngày trước ngày bầu cử","Ở mỗi khu vực bỏ phiếu, chậm nhất là 70 ngày trước ngày bầu cử","Ở mỗi thôn, tổ dân phố, chậm nhất là 43 ngày trước ngày bầu cử"],"why":"UBND cấp xã quyết định thành lập ở mỗi khu vực bỏ phiếu một Tổ bầu cử chậm nhất 43 ngày trước ngày bầu cử. Mốc 70 ngày và phạm vi đơn vị bầu cử là quy định về Ban bầu cử.","cc":"Khoản 1 Điều 25 Luật Bầu cử đại biểu Quốc hội và đại biểu HĐND (văn bản hợp nhất số 83/VBHN-VPQH năm 2026)"},{"id":"bc-013","cd":"bc","m":2,"l":"th","q":"Ông T là thành viên Tổ bầu cử ở một khu vực bỏ phiếu của xã A, đồng thời được giới thiệu ứng cử đại biểu HĐND xã tại chính đơn vị bầu cử đó. Theo luật, ông T phải làm gì?","a":["Xin rút khỏi Tổ bầu cử chậm nhất vào ngày công bố danh sách chính thức người ứng cử","Tiếp tục làm thành viên Tổ bầu cử nhưng không tham gia kiểm phiếu","Xin rút khỏi Tổ bầu cử chậm nhất 24 giờ trước thời điểm bắt đầu bỏ phiếu","Rút tên khỏi danh sách ứng cử vì đã là thành viên Tổ bầu cử"],"why":"Người ứng cử không được làm thành viên Ban bầu cử, Tổ bầu cử ở đơn vị bầu cử mình ứng cử; phải xin rút chậm nhất vào ngày công bố danh sách chính thức, nếu không thì cơ quan đã thành lập sẽ xóa tên và bổ sung người thay thế.","cc":"Điều 27 Luật Bầu cử đại biểu Quốc hội và đại biểu HĐND (văn bản hợp nhất số 83/VBHN-VPQH năm 2026)"},{"id":"bc-017","cd":"bc","m":2,"l":"kt","q":"Danh sách cử tri phải được niêm yết chậm nhất bao nhiêu ngày trước ngày bầu cử?","a":["40 ngày","30 ngày","35 ngày","43 ngày"],"why":"Chậm nhất 40 ngày trước ngày bầu cử, cơ quan lập danh sách cử tri phải niêm yết tại trụ sở UBND cấp xã và các địa điểm công cộng của khu vực bỏ phiếu, đồng thời thông báo rộng rãi để Nhân dân kiểm tra.","cc":"Điều 32 Luật Bầu cử đại biểu Quốc hội và đại biểu HĐND (văn bản hợp nhất số 83/VBHN-VPQH năm 2026)"},{"id":"bc-019","cd":"bc","m":2,"l":"kt","q":"Công dân ứng cử đại biểu HĐND phải nộp hồ sơ ứng cử chậm nhất bao nhiêu ngày trước ngày bầu cử?","a":["42 ngày","70 ngày","35 ngày","30 ngày"],"why":"Thời hạn nộp hồ sơ ứng cử là chậm nhất 42 ngày trước ngày bầu cử; mốc 70 ngày là quy định cũ, đã được thay thế từ ngày 01/7/2025.","cc":"Khoản 1 Điều 35 Luật Bầu cử đại biểu Quốc hội và đại biểu HĐND (văn bản hợp nhất số 83/VBHN-VPQH năm 2026)"},{"id":"bc-020","cd":"bc","m":2,"l":"th","q":"Ông V cư trú và làm việc thường xuyên tại xã A, không cư trú và cũng không công tác ở xã B. Vì xã B là quê gốc, ông muốn tự ứng cử đại biểu HĐND xã B. Theo luật, ông V có được ứng cử đại biểu HĐND xã B không?","a":["Không, vì ông không cư trú hoặc công tác thường xuyên ở xã B","Có, vì công dân được ứng cử HĐND ở bất kỳ địa phương nào","Có, nếu được hội nghị cử tri ở xã B tín nhiệm","Có, nếu được Ủy ban bầu cử ở xã A giới thiệu sang xã B"],"why":"Người tự ứng cử, người được giới thiệu ứng cử đại biểu HĐND của địa phương nào thì phải đang cư trú hoặc công tác thường xuyên ở địa phương đó; hồ sơ nộp tại Ủy ban bầu cử ở đơn vị hành chính mà mình ứng cử.","cc":"Khoản 2 Điều 36 Luật Bầu cử đại biểu Quốc hội và đại biểu HĐND (văn bản hợp nhất số 83/VBHN-VPQH năm 2026)"},{"id":"bc-022","cd":"bc","m":2,"l":"th","q":"Ông P ở xã A đã chấp hành xong bản án hình sự của Tòa án nhưng chưa được xóa án tích. Ông muốn tự ứng cử đại biểu HĐND xã. Trường hợp này được giải quyết thế nào?","a":["Ông P không được ứng cử vì chưa được xóa án tích","Ông P được ứng cử vì đã chấp hành xong bản án","Ông P được ứng cử nếu hội nghị cử tri nơi cư trú tín nhiệm","Ông P chỉ được ứng cử HĐND cấp xã, không được ứng cử cấp tỉnh"],"why":"Người đã chấp hành xong bản án, quyết định hình sự của Tòa án nhưng chưa được xóa án tích thuộc trường hợp không được ứng cử đại biểu Quốc hội và đại biểu HĐND ở bất kỳ cấp nào.","cc":"Khoản 4 Điều 37 Luật Bầu cử đại biểu Quốc hội và đại biểu HĐND (văn bản hợp nhất số 83/VBHN-VPQH năm 2026)"},{"id":"bc-024","cd":"bc","m":2,"l":"kt","q":"Ở thôn, tổ dân phố, chủ thể nào dự kiến người của thôn, tổ dân phố để giới thiệu ứng cử đại biểu HĐND cấp xã?","a":["Ban công tác Mặt trận ở thôn, tổ dân phố","Trưởng thôn, tổ trưởng tổ dân phố","Chi bộ thôn, tổ dân phố","Ban Thường trực Ủy ban MTTQ cấp xã"],"why":"Ban công tác Mặt trận ở thôn, tổ dân phố dự kiến người giới thiệu ứng cử và phối hợp với trưởng thôn, tổ trưởng tổ dân phố tổ chức hội nghị cử tri để thảo luận, giới thiệu người ứng cử đại biểu HĐND cấp xã.","cc":"Khoản 4 Điều 52 Luật Bầu cử đại biểu Quốc hội và đại biểu HĐND (văn bản hợp nhất số 83/VBHN-VPQH năm 2026)"},{"id":"bc-025","cd":"bc","m":2,"l":"kt","q":"Trong quy trình hiệp thương giới thiệu người ứng cử đại biểu HĐND, danh sách sơ bộ những người ứng cử được lập tại hội nghị nào?","a":["Hội nghị hiệp thương lần thứ hai","Hội nghị hiệp thương lần thứ nhất","Hội nghị hiệp thương lần thứ ba","Hội nghị cử tri nơi cư trú"],"why":"Hiệp thương lần thứ nhất thỏa thuận cơ cấu, thành phần, số lượng; lần thứ hai lập danh sách sơ bộ và gửi lấy ý kiến cử tri; lần thứ ba lựa chọn, lập danh sách những người đủ tiêu chuẩn ứng cử.","cc":"Khoản 2 Điều 53 Luật Bầu cử đại biểu Quốc hội và đại biểu HĐND (văn bản hợp nhất số 83/VBHN-VPQH năm 2026)"},{"id":"bc-026","cd":"bc","m":2,"l":"kt","q":"Danh sách chính thức những người ứng cử đại biểu HĐND theo từng đơn vị bầu cử do cơ quan nào lập, công bố và chậm nhất khi nào?","a":["Ủy ban bầu cử, chậm nhất là 17 ngày trước ngày bầu cử","Ban Thường trực Ủy ban MTTQ cùng cấp, chậm nhất là 21 ngày trước ngày bầu cử","Ban bầu cử, chậm nhất là 17 ngày trước ngày bầu cử","Tổ bầu cử, chậm nhất là 16 ngày trước ngày bầu cử"],"why":"Ủy ban bầu cử lập và công bố danh sách chính thức chậm nhất 17 ngày trước ngày bầu cử. Mốc 21 ngày là hạn MTTQ gửi danh sách sau hiệp thương lần thứ ba; mốc 16 ngày là hạn Tổ bầu cử niêm yết danh sách ở khu vực bỏ phiếu.","cc":"Khoản 2 Điều 58 Luật Bầu cử đại biểu Quốc hội và đại biểu HĐND (văn bản hợp nhất số 83/VBHN-VPQH năm 2026)"},{"id":"bc-034","cd":"bc","m":2,"l":"kt","q":"Trước khi mở hòm phiếu để kiểm phiếu, Tổ bầu cử phải mời ai chứng kiến việc kiểm phiếu?","a":["Hai cử tri không phải là người ứng cử","Hai người ứng cử có mặt tại phòng bỏ phiếu","Đại diện Ủy ban bầu cử và Ban bầu cử","Ba cử tri cao tuổi nhất của khu vực bỏ phiếu"],"why":"Trước khi mở hòm phiếu, Tổ bầu cử phải thống kê, lập biên bản, niêm phong số phiếu không sử dụng đến và mời hai cử tri không phải là người ứng cử chứng kiến. Người ứng cử, phóng viên báo chí cũng được chứng kiến việc kiểm phiếu.","cc":"Điều 73 Luật Bầu cử đại biểu Quốc hội và đại biểu HĐND (văn bản hợp nhất số 83/VBHN-VPQH năm 2026)"},{"id":"bc-036","cd":"bc","m":2,"l":"th","q":"Đơn vị bầu cử số 2 của xã A được bầu 3 đại biểu HĐND xã. Hai người có số phiếu cao nhất đã rõ; ông K (52 tuổi) và bà L (45 tuổi) cùng đạt quá nửa số phiếu hợp lệ và có số phiếu bằng nhau ở vị trí thứ ba. Ai trúng cử?","a":["Ông K, vì là người nhiều tuổi hơn","Bà L, vì ưu tiên người ứng cử là phụ nữ","Ông K và bà L cùng trúng cử, đơn vị có 4 đại biểu","Chưa ai trúng cử, phải bầu cử thêm giữa hai người"],"why":"Khi cuối danh sách trúng cử có nhiều người bằng phiếu nhau và nhiều hơn số đại biểu được bầu đã ấn định cho đơn vị bầu cử thì người nhiều tuổi hơn là người trúng cử.","cc":"Khoản 4 Điều 78 Luật Bầu cử đại biểu Quốc hội và đại biểu HĐND (văn bản hợp nhất số 83/VBHN-VPQH năm 2026)"},{"id":"bc-039","cd":"bc","m":2,"l":"kt","q":"Cơ quan nào xác nhận tư cách của người trúng cử đại biểu HĐND và cấp giấy chứng nhận đại biểu HĐND khóa mới cho người trúng cử?","a":["Ủy ban bầu cử chịu trách nhiệm tổ chức bầu cử HĐND cấp đó","Thường trực HĐND khóa trước ở cấp đó","Ban Thường trực Ủy ban MTTQ Việt Nam cùng cấp","Hội đồng Bầu cử quốc gia"],"why":"Ủy ban bầu cử xác nhận tư cách người trúng cử đại biểu HĐND cấp mình tổ chức bầu cử, cấp giấy chứng nhận đại biểu và báo cáo HĐND khóa mới tại kỳ họp đầu tiên. Hội đồng Bầu cử quốc gia xác nhận tư cách đại biểu Quốc hội.","cc":"Khoản 2 Điều 88 Luật Bầu cử đại biểu Quốc hội và đại biểu HĐND (văn bản hợp nhất số 83/VBHN-VPQH năm 2026)"},{"id":"bc-042","cd":"bc","m":2,"l":"kt","q":"Theo Nghị quyết 107/2025/UBTVQH15, dân số của từng đơn vị hành chính để xác định số lượng đại biểu HĐND được bầu nhiệm kỳ 2026–2031 được tính theo số liệu nào?","a":["Cơ sở dữ liệu quốc gia về dân cư tính đến ngày 31/8/2025","Kết quả tổng điều tra dân số và nhà ở gần nhất","Cơ sở dữ liệu quốc gia về dân cư tính đến ngày 31/12/2025","Số liệu của cơ quan thống kê cấp tỉnh tính đến ngày 01/7/2025"],"why":"Dân số làm căn cứ xác định số lượng đại biểu HĐND được bầu nhiệm kỳ 2026–2031 lấy theo số liệu thống kê dân số tại Cơ sở dữ liệu quốc gia về dân cư tính đến ngày 31/8/2025.","cc":"Điểm a khoản 1 Điều 1 Nghị quyết số 107/2025/UBTVQH15 của UBTVQH"},{"id":"bc-044","cd":"bc","m":2,"l":"th","q":"Thường trực HĐND xã A chuẩn bị dự kiến cơ cấu, thành phần, phân bổ số lượng người được giới thiệu ứng cử đại biểu HĐND xã nhiệm kỳ 2026–2031. Trước khi dự kiến, Thường trực HĐND xã phải thống nhất ý kiến với những cơ quan nào?","a":["Ban thường trực Ủy ban MTTQ Việt Nam và UBND cùng cấp","Ủy ban bầu cử ở xã và Ban Thường trực Ủy ban MTTQ cấp tỉnh","Thường trực HĐND cấp tỉnh và UBND cấp tỉnh","Ủy ban bầu cử ở xã và các Ban của HĐND xã"],"why":"Thường trực HĐND cấp xã dự kiến cụ thể cơ cấu, thành phần, phân bổ số lượng người được giới thiệu ứng cử đại biểu HĐND cấp mình sau khi thống nhất ý kiến với Ban thường trực Ủy ban MTTQ Việt Nam và UBND cùng cấp.","cc":"Khoản 2 Điều 2 Nghị quyết số 107/2025/UBTVQH15 của UBTVQH"},{"id":"bc-046","cd":"bc","m":2,"l":"kt","q":"Theo Nghị quyết 107/2025/UBTVQH15, người ứng cử là người trẻ tuổi (dưới 40 tuổi) được phấn đấu đạt tỷ lệ nào trong danh sách chính thức những người ứng cử đại biểu HĐND ở từng cấp?","a":["Không dưới 15%","Không dưới 10%","Không dưới 20%","Không dưới 30%"],"why":"Người trẻ tuổi (dưới 40 tuổi) phấn đấu đạt không dưới 15%. Mức không dưới 10% là của người ngoài Đảng; mức không dưới 30% là của đại biểu HĐND nhiệm kỳ 2021–2026 tái cử.","cc":"Điểm d khoản 3 Điều 2 Nghị quyết số 107/2025/UBTVQH15 của UBTVQH"},{"id":"bc-010","cd":"bc","m":3,"l":"kt","q":"Ban bầu cử đại biểu HĐND cấp xã có bao nhiêu thành viên?","a":["Từ chín đến mười lăm thành viên","Từ mười một đến mười lăm thành viên","Từ chín đến mười bảy thành viên","Từ mười một đến hai mươi mốt thành viên"],"why":"Ban bầu cử đại biểu HĐND cấp xã có 9–15 thành viên, cấp tỉnh có 11–15 thành viên. Dễ nhầm với Ủy ban bầu cử ở xã (9–17 thành viên) và Tổ bầu cử (11–21 thành viên).","cc":"Khoản 2 Điều 24 Luật Bầu cử đại biểu Quốc hội và đại biểu HĐND (văn bản hợp nhất số 83/VBHN-VPQH năm 2026)"},{"id":"bc-012","cd":"bc","m":3,"l":"th","q":"Tổ bầu cử ở một khu vực bỏ phiếu của phường B có 15 thành viên. Một cuộc họp của Tổ có 10 thành viên tham dự; khi biểu quyết một quyết định thì có 7 người tán thành. Kết luận nào đúng luật?","a":["Cuộc họp hợp lệ nhưng quyết định chưa được thông qua vì chưa quá nửa tổng số thành viên","Cuộc họp hợp lệ và quyết định được thông qua vì quá nửa số người dự họp tán thành","Cuộc họp không hợp lệ vì chưa đủ ba phần tư tổng số thành viên tham dự","Cuộc họp không hợp lệ vì phải có đủ toàn bộ thành viên Tổ bầu cử tham dự"],"why":"Cuộc họp được tiến hành khi có ít nhất 2/3 tổng số thành viên dự (10/15 là đủ). Quyết định chỉ được thông qua khi quá nửa TỔNG SỐ thành viên tán thành, tức ít nhất 8/15, nên 7 phiếu là chưa đủ.","cc":"Khoản 1 Điều 26 Luật Bầu cử đại biểu Quốc hội và đại biểu HĐND (văn bản hợp nhất số 83/VBHN-VPQH năm 2026)"},{"id":"bc-014","cd":"bc","m":3,"l":"th","q":"Chị L đăng ký tạm trú tại phường B mới được 6 tháng tính đến ngày bầu cử và được ghi tên vào danh sách cử tri ở phường B. Tại nơi tạm trú này, chị L được bầu những đại biểu nào?","a":["Đại biểu Quốc hội và đại biểu HĐND cấp tỉnh","Đại biểu Quốc hội, đại biểu HĐND cấp tỉnh và cấp xã","Chỉ đại biểu Quốc hội","Đại biểu HĐND cấp tỉnh và đại biểu HĐND cấp xã"],"why":"Cử tri tạm trú chưa đủ 12 tháng tại địa phương được ghi tên vào danh sách cử tri để bầu đại biểu Quốc hội và đại biểu HĐND cấp tỉnh ở nơi tạm trú, không bầu đại biểu HĐND cấp xã tại đó.","cc":"Khoản 3 Điều 29 Luật Bầu cử đại biểu Quốc hội và đại biểu HĐND (văn bản hợp nhất số 83/VBHN-VPQH năm 2026)"},{"id":"bc-015","cd":"bc","m":3,"l":"kt","q":"Người nào sau đây vẫn được ghi tên vào danh sách cử tri để bầu đại biểu Quốc hội và đại biểu HĐND cấp tỉnh?","a":["Người đang bị tạm giam","Người mất năng lực hành vi dân sự","Người bị kết án tử hình đang chờ thi hành án","Người đang chấp hành hình phạt tù không được hưởng án treo"],"why":"Người đang bị tạm giam, tạm giữ vẫn được ghi tên vào danh sách cử tri để bầu đại biểu Quốc hội và HĐND cấp tỉnh nơi đang bị tạm giam, tạm giữ. Ba trường hợp còn lại thuộc diện không được ghi tên vào danh sách cử tri.","cc":"Khoản 5 Điều 29 và khoản 1 Điều 30 Luật Bầu cử đại biểu Quốc hội và đại biểu HĐND (văn bản hợp nhất số 83/VBHN-VPQH năm 2026)"},{"id":"bc-018","cd":"bc","m":3,"l":"th","q":"Ông K ở xã A phát hiện danh sách cử tri niêm yết ghi sai thông tin của mình nên đã khiếu nại với UBND xã. UBND xã đã trả lời nhưng ông K không đồng ý với kết quả giải quyết. Ông K có quyền gì tiếp theo?","a":["Khởi kiện tại Tòa án nhân dân theo pháp luật về tố tụng hành chính","Khiếu nại tiếp đến Ủy ban bầu cử ở xã để ra quyết định cuối cùng","Khiếu nại lần hai đến Chủ tịch UBND cấp tỉnh","Gửi đơn đến Hội đồng Bầu cử quốc gia để xem xét, quyết định"],"why":"Khiếu nại về danh sách cử tri do cơ quan lập danh sách giải quyết trong 05 ngày. Nếu không đồng ý hoặc hết thời hạn mà không được giải quyết, người khiếu nại có quyền khởi kiện tại Tòa án nhân dân theo pháp luật tố tụng hành chính.","cc":"Điều 33 Luật Bầu cử đại biểu Quốc hội và đại biểu HĐND (văn bản hợp nhất số 83/VBHN-VPQH năm 2026)"},{"id":"bc-021","cd":"bc","m":3,"l":"th","q":"Bà N đã nộp hồ sơ ứng cử đại biểu Quốc hội. Trong cùng cuộc bầu cử, bà còn muốn ứng cử đại biểu HĐND. Bà N được nộp hồ sơ ứng cử đại biểu HĐND ở mấy cấp?","a":["Chỉ ở một cấp (cấp tỉnh hoặc cấp xã)","Ở hai cấp (cấp tỉnh và cấp xã)","Không được ứng cử đại biểu HĐND ở cấp nào","Chỉ riêng cấp tỉnh, không được chọn cấp xã"],"why":"Công dân được nộp hồ sơ ứng cử đại biểu HĐND tối đa ở hai cấp trong cùng một nhiệm kỳ; nhưng nếu đã nộp hồ sơ ứng cử đại biểu Quốc hội thì chỉ được nộp hồ sơ ứng cử đại biểu HĐND ở một cấp.","cc":"Khoản 3 Điều 36 Luật Bầu cử đại biểu Quốc hội và đại biểu HĐND (văn bản hợp nhất số 83/VBHN-VPQH năm 2026)"},{"id":"bc-027","cd":"bc","m":3,"l":"th","q":"Đơn vị bầu cử số 1 của xã A được ấn định bầu 5 đại biểu HĐND xã. Theo nguyên tắc số dư, danh sách chính thức những người ứng cử ở đơn vị bầu cử này phải có ít nhất bao nhiêu người?","a":["8 người","6 người","7 người","10 người"],"why":"Đơn vị bầu cử được bầu từ bốn đại biểu trở lên thì số người ứng cử phải nhiều hơn số đại biểu được bầu ít nhất là ba người: 5 + 3 = 8. Nếu đơn vị được bầu ba đại biểu thì số dư ít nhất là hai người.","cc":"Khoản 3 Điều 58 Luật Bầu cử đại biểu Quốc hội và đại biểu HĐND (văn bản hợp nhất số 83/VBHN-VPQH năm 2026)"},{"id":"bc-028","cd":"bc","m":3,"l":"th","q":"Sau khi danh sách chính thức người ứng cử đại biểu HĐND xã A được công bố và trước thời điểm bắt đầu bỏ phiếu, một người ứng cử bị khởi tố bị can. Việc xóa tên người này khỏi danh sách ứng cử do ai quyết định?","a":["Ủy ban bầu cử ở xã, sau khi thống nhất với Ban Thường trực Ủy ban MTTQ cấp xã","Ban bầu cử ở đơn vị bầu cử đó, sau khi báo cáo Ủy ban bầu cử ở xã","Hội đồng Bầu cử quốc gia, theo đề nghị của Ủy ban bầu cử ở tỉnh","Ban Thường trực Ủy ban MTTQ cấp xã, sau khi tổ chức hiệp thương lại"],"why":"Với người ứng cử đại biểu HĐND, Ủy ban bầu cử đã công bố danh sách quyết định xóa tên sau khi thống nhất ý kiến với Ban Thường trực Ủy ban MTTQ cùng cấp. Hội đồng Bầu cử quốc gia chỉ xóa tên người ứng cử đại biểu Quốc hội.","cc":"Khoản 2 Điều 60 Luật Bầu cử đại biểu Quốc hội và đại biểu HĐND (văn bản hợp nhất số 83/VBHN-VPQH năm 2026)"},{"id":"bc-037","cd":"bc","m":3,"l":"th","q":"Đơn vị bầu cử số 3 của xã A được ấn định bầu 3 đại biểu HĐND xã. Trong cuộc bầu cử đầu tiên, tỷ lệ cử tri đi bầu đạt 95% nhưng chỉ có 2 người trúng cử. Có phải tổ chức bầu cử thêm ở đơn vị bầu cử này không?","a":["Không, vì số người trúng cử đã đủ hai phần ba số đại biểu được bầu","Có, vì chưa bầu đủ số đại biểu đã ấn định cho đơn vị bầu cử","Có, nếu Hội đồng Bầu cử quốc gia xem xét và đồng ý","Không, vì luật không quy định bầu cử thêm đối với HĐND cấp xã"],"why":"Với đại biểu HĐND, chỉ bầu cử thêm khi số người trúng cử chưa đủ hai phần ba số đại biểu được bầu của đơn vị bầu cử. 2 trên 3 là vừa đủ hai phần ba nên không bầu cử thêm (khác với bầu cử đại biểu Quốc hội: thiếu là xem xét bầu thêm).","cc":"Khoản 2 Điều 79 Luật Bầu cử đại biểu Quốc hội và đại biểu HĐND (văn bản hợp nhất số 83/VBHN-VPQH năm 2026)"},{"id":"bc-038","cd":"bc","m":3,"l":"th","q":"Một đơn vị bầu cử đại biểu HĐND xã A phải bầu cử lại vì lần đầu chưa quá nửa số cử tri đi bầu. Trong cuộc bầu cử lại, số cử tri đi bầu vẫn chưa đạt quá một nửa tổng số cử tri trong danh sách. Xử lý thế nào?","a":["Công nhận kết quả bầu cử lại, không tổ chức bầu cử lại lần thứ hai","Tổ chức bầu cử lại lần thứ hai trong thời hạn 07 ngày","Hủy kết quả và chờ bầu cử bổ sung trong nhiệm kỳ","Trình Hội đồng Bầu cử quốc gia quyết định ngày bầu cử lại lần thứ hai"],"why":"Nếu bầu cử lại mà số cử tri đi bầu vẫn chưa đạt quá một nửa tổng số cử tri trong danh sách cử tri thì kết quả bầu cử lại vẫn được công nhận và không tổ chức bầu cử lại lần thứ hai.","cc":"Khoản 4 Điều 80 Luật Bầu cử đại biểu Quốc hội và đại biểu HĐND (văn bản hợp nhất số 83/VBHN-VPQH năm 2026)"},{"id":"bc-040","cd":"bc","m":3,"l":"kt","q":"Cơ quan nào quyết định và công bố ngày bầu cử bổ sung đại biểu HĐND cấp xã?","a":["Thường trực HĐND cấp tỉnh","Ủy ban Thường vụ Quốc hội","Thường trực HĐND cấp xã","UBND cấp tỉnh"],"why":"Ngày bầu cử bổ sung đại biểu HĐND cấp tỉnh do Ủy ban Thường vụ Quốc hội quyết định; với HĐND cấp xã thì do Thường trực HĐND cấp tỉnh quyết định và công bố. Ngày này phải là chủ nhật, công bố chậm nhất 30 ngày trước ngày bầu cử.","cc":"Khoản 3 Điều 89 Luật Bầu cử đại biểu Quốc hội và đại biểu HĐND (văn bản hợp nhất số 83/VBHN-VPQH năm 2026)"},{"id":"bc-043","cd":"bc","m":3,"l":"kt","q":"Để xác định số lượng đại biểu HĐND xã được bầu nhiệm kỳ 2026–2031, cơ quan nào chịu trách nhiệm xác định xã ở miền núi và cơ quan nào xác định xã ở hải đảo?","a":["Bộ Dân tộc và Tôn giáo xác định xã miền núi; Bộ Nội vụ xác định xã hải đảo","Bộ Nội vụ xác định xã miền núi; Bộ Dân tộc và Tôn giáo xác định xã hải đảo","Bộ Nội vụ xác định đồng thời xã miền núi và xã hải đảo","UBND cấp tỉnh xác định xã miền núi; Bộ Quốc phòng xác định xã hải đảo"],"why":"Bộ Dân tộc và Tôn giáo chịu trách nhiệm xác định xã ở miền núi, Bộ Nội vụ xác định xã ở hải đảo; kết quả được công bố trên Trang thông tin điện tử của Hội đồng Bầu cử quốc gia chậm nhất ngày 01/11/2025.","cc":"Điểm b khoản 1 Điều 1 Nghị quyết số 107/2025/UBTVQH15 của UBTVQH"},{"id":"tc-001","cd":"tc","m":1,"l":"kt","q":"Theo Luật Tổ chức chính quyền địa phương số 72/2025/QH15, cơ cấu tổ chức của HĐND gồm những thành phần nào?","a":["Thường trực HĐND, các Ban của HĐND, Tổ đại biểu HĐND và các đại biểu HĐND","Thường trực HĐND, các Ban của HĐND, Văn phòng HĐND và các đại biểu HĐND","Chủ tịch HĐND, các Phó Chủ tịch HĐND, các Ban của HĐND và Tổ đại biểu HĐND","Thường trực HĐND, UBND cùng cấp, các Ban của HĐND và các đại biểu HĐND"],"why":"Cơ cấu tổ chức của HĐND gồm 4 thành phần: Thường trực HĐND, các Ban của HĐND, Tổ đại biểu HĐND và các đại biểu HĐND. UBND là cơ quan chấp hành, không nằm trong cơ cấu tổ chức của HĐND.","cc":"Khoản 1 Điều 29 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"tc-002","cd":"tc","m":1,"l":"kt","q":"Theo Luật Tổ chức chính quyền địa phương số 72/2025/QH15, Thường trực HĐND gồm những thành viên nào?","a":["Chủ tịch HĐND, Phó Chủ tịch HĐND và các Ủy viên là Trưởng Ban của HĐND","Chủ tịch HĐND, Phó Chủ tịch HĐND và các Ủy viên là Tổ trưởng Tổ đại biểu HĐND","Chủ tịch HĐND, Phó Chủ tịch HĐND, Trưởng Ban và Phó Trưởng Ban của HĐND","Chủ tịch HĐND, Phó Chủ tịch HĐND và Chủ tịch UBND cùng cấp"],"why":"Thường trực HĐND gồm Chủ tịch HĐND, Phó Chủ tịch HĐND và các Ủy viên là Trưởng Ban của HĐND. Phó Trưởng Ban và Tổ trưởng Tổ đại biểu không phải là thành viên Thường trực HĐND.","cc":"Khoản 2 Điều 29 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"tc-004","cd":"tc","m":1,"l":"kt","q":"Theo Luật Tổ chức chính quyền địa phương số 72/2025/QH15, HĐND cấp xã thành lập những Ban nào?","a":["Ban Kinh tế - Ngân sách và Ban Văn hóa - Xã hội","Ban Pháp chế và Ban Kinh tế - Xã hội","Ban Pháp chế, Ban Kinh tế - Ngân sách và Ban Văn hóa - Xã hội","Ban Kinh tế - Ngân sách, Ban Văn hóa - Xã hội và Ban Đô thị"],"why":"HĐND cấp xã thành lập 2 Ban: Ban Kinh tế - Ngân sách và Ban Văn hóa - Xã hội. Ban Pháp chế được thành lập ở HĐND tỉnh, thành phố; Ban Đô thị được thành lập ở HĐND thành phố.","cc":"Điểm a khoản 3 Điều 29 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"tc-005","cd":"tc","m":1,"l":"kt","q":"Theo Luật Tổ chức chính quyền địa phương số 72/2025/QH15, Tổ đại biểu HĐND được hợp thành như thế nào?","a":["Gồm các đại biểu HĐND được bầu ở một hoặc nhiều đơn vị bầu cử","Gồm các đại biểu HĐND cùng công tác trong một cơ quan, đơn vị","Gồm các đại biểu HĐND là thành viên của cùng một Ban của HĐND","Gồm các đại biểu HĐND tự nguyện đăng ký sinh hoạt cùng nhau"],"why":"Các đại biểu HĐND được bầu ở một hoặc nhiều đơn vị bầu cử hợp thành Tổ đại biểu HĐND; số lượng Tổ đại biểu do Thường trực HĐND cùng cấp quyết định.","cc":"Khoản 4 Điều 29 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"tc-008","cd":"tc","m":1,"l":"kt","q":"Theo Điều 31 Luật Tổ chức chính quyền địa phương số 72/2025/QH15, triệu tập các kỳ họp của HĐND là nhiệm vụ, quyền hạn của chủ thể nào?","a":["Thường trực HĐND","Chủ tịch UBND cùng cấp","Các Ban của HĐND","Ban Thường trực Ủy ban MTTQ Việt Nam cùng cấp"],"why":"Thường trực HĐND triệu tập các kỳ họp của HĐND và phối hợp với UBND trong việc chuẩn bị kỳ họp của HĐND.","cc":"Khoản 2 Điều 31 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"tc-013","cd":"tc","m":1,"l":"th","q":"Một đại biểu HĐND xã A có việc gia đình đột xuất nên không thể tham dự một phiên họp của HĐND xã. Theo Luật Tổ chức chính quyền địa phương số 72/2025/QH15, đại biểu này phải làm gì?","a":["Phải có lý do và báo cáo trước với Chủ tọa kỳ họp, phiên họp","Gửi đơn xin phép đến Ủy ban MTTQ Việt Nam xã trước phiên họp","Ủy quyền bằng văn bản cho đại biểu khác biểu quyết thay mình","Không phải báo cáo, chỉ cần giải trình khi tiếp xúc cử tri"],"why":"Đại biểu HĐND có trách nhiệm tham dự đầy đủ các kỳ họp, phiên họp của HĐND; trường hợp không tham dự thì phải có lý do và phải báo cáo trước với Chủ tọa kỳ họp, phiên họp.","cc":"Khoản 2 Điều 33 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"tc-015","cd":"tc","m":1,"l":"kt","q":"Theo Luật Tổ chức chính quyền địa phương số 72/2025/QH15, đại biểu HĐND có quyền chất vấn người nào sau đây?","a":["Chủ tịch UBND cùng cấp","Chủ tịch Ủy ban MTTQ Việt Nam cùng cấp","Tổ trưởng Tổ đại biểu HĐND","Trưởng thôn, Tổ trưởng tổ dân phố"],"why":"Đại biểu HĐND có quyền chất vấn Chủ tịch UBND, các thành viên khác của UBND, người đứng đầu cơ quan thuộc UBND cùng cấp, Chánh án Tòa án nhân dân, Viện trưởng Viện kiểm sát nhân dân cùng cấp.","cc":"Khoản 7 Điều 33 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"tc-016","cd":"tc","m":1,"l":"kt","q":"Trong thời gian HĐND không họp, việc bắt, giam, giữ, khởi tố đại biểu HĐND, khám xét nơi ở và nơi làm việc của đại biểu HĐND phải có sự đồng ý của chủ thể nào?","a":["Thường trực HĐND","Chủ tịch UBND cùng cấp","Ủy ban MTTQ Việt Nam cùng cấp","Tổ đại biểu HĐND nơi đại biểu sinh hoạt"],"why":"Không được bắt, giam, giữ, khởi tố đại biểu HĐND, khám xét nơi ở và nơi làm việc của đại biểu nếu không có sự đồng ý của HĐND, hoặc của Thường trực HĐND trong thời gian HĐND không họp.","cc":"Khoản 10 Điều 33 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"tc-019","cd":"tc","m":1,"l":"kt","q":"Theo Luật Tổ chức chính quyền địa phương số 72/2025/QH15, HĐND họp mỗi năm ít nhất mấy kỳ?","a":["02 kỳ","01 kỳ","03 kỳ","04 kỳ"],"why":"HĐND họp mỗi năm ít nhất 02 kỳ; ngoài ra HĐND có thể họp kỳ họp chuyên đề hoặc kỳ họp để giải quyết công việc phát sinh đột xuất.","cc":"Khoản 2 Điều 34 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"tc-023","cd":"tc","m":1,"l":"kt","q":"Theo khoản 2 Điều 35 Luật Tổ chức chính quyền địa phương số 72/2025/QH15, nghị quyết của HĐND (trừ nghị quyết về bãi nhiệm đại biểu HĐND) được thông qua khi nào?","a":["Khi có quá nửa tổng số đại biểu HĐND biểu quyết tán thành","Khi có quá nửa số đại biểu HĐND có mặt biểu quyết tán thành","Khi có ít nhất hai phần ba tổng số đại biểu HĐND biểu quyết tán thành","Khi có ít nhất hai phần ba số đại biểu HĐND có mặt biểu quyết tán thành"],"why":"Nghị quyết của HĐND được thông qua khi có quá nửa TỔNG SỐ đại biểu HĐND (không phải số đại biểu có mặt) biểu quyết tán thành; riêng nghị quyết bãi nhiệm đại biểu HĐND cần ít nhất hai phần ba tổng số đại biểu.","cc":"Khoản 2 Điều 35 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"tc-025","cd":"tc","m":1,"l":"kt","q":"Theo Luật Tổ chức chính quyền địa phương số 72/2025/QH15, HĐND bầu Chủ tịch UBND cùng cấp theo giới thiệu của ai?","a":["Chủ tịch HĐND cùng cấp","Chủ tịch UBND cấp trên trực tiếp","Thường trực HĐND cấp trên trực tiếp","Ban Thường trực Ủy ban MTTQ Việt Nam cùng cấp"],"why":"HĐND bầu Chủ tịch UBND theo giới thiệu của Chủ tịch HĐND; bầu Phó Chủ tịch UBND, Ủy viên UBND theo giới thiệu của Chủ tịch UBND.","cc":"Khoản 2 Điều 36 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"tc-033","cd":"tc","m":1,"l":"kt","q":"Đại biểu HĐND không đáp ứng đủ các tiêu chuẩn của đại biểu HĐND và không còn xứng đáng với sự tín nhiệm của Nhân dân thì bị chủ thể nào bãi nhiệm?","a":["HĐND hoặc cử tri","Thường trực HĐND hoặc Chủ tịch HĐND","Ủy ban MTTQ Việt Nam cùng cấp","Thường trực HĐND cấp trên trực tiếp"],"why":"Đại biểu HĐND không đáp ứng đủ tiêu chuẩn và không còn xứng đáng với sự tín nhiệm của Nhân dân thì bị HĐND hoặc cử tri bãi nhiệm. Thường trực HĐND chỉ quyết định việc đưa ra HĐND hoặc đưa ra cử tri bãi nhiệm.","cc":"Khoản 5 Điều 38 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"tc-035","cd":"tc","m":1,"l":"kt","q":"Theo Luật Tổ chức chính quyền địa phương số 72/2025/QH15, UBND họp thường kỳ với tần suất nào?","a":["Mỗi tháng 01 lần","Mỗi tháng 02 lần","Mỗi quý 01 lần","06 tháng 01 lần"],"why":"UBND họp thường kỳ mỗi tháng 01 lần; ngoài ra UBND họp chuyên đề hoặc họp để giải quyết công việc phát sinh đột xuất trong các trường hợp luật định.","cc":"Khoản 1 Điều 40 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"tc-037","cd":"tc","m":1,"l":"kt","q":"Theo Luật Tổ chức chính quyền địa phương số 72/2025/QH15, chính quyền địa phương cấp xã tổ chức hội nghị đối thoại với Nhân dân với tần suất tối thiểu nào?","a":["Ít nhất mỗi năm một lần","Ít nhất mỗi năm hai lần","Ít nhất mỗi quý một lần","Ít nhất mỗi tháng một lần"],"why":"Chính quyền địa phương cấp xã tổ chức hội nghị đối thoại với Nhân dân ít nhất mỗi năm một lần, hoặc khi có ít nhất 10% tổng số cử tri của cấp xã yêu cầu, hoặc trong trường hợp cần thiết.","cc":"Khoản 1 Điều 43 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"tc-040","cd":"tc","m":1,"l":"kt","q":"Theo Luật Tổ chức chính quyền địa phương số 72/2025/QH15, HĐND bị giải tán trong trường hợp nào?","a":["Khi HĐND làm thiệt hại nghiêm trọng đến lợi ích của Nhân dân","Khi HĐND không tổ chức đủ 02 kỳ họp thường lệ trong một năm","Khi quá nửa tổng số đại biểu HĐND xin thôi làm nhiệm vụ đại biểu","Khi HĐND không thông qua được dự toán ngân sách địa phương"],"why":"Luật quy định HĐND làm thiệt hại nghiêm trọng đến lợi ích của Nhân dân thì bị giải tán. UBTVQH giải tán HĐND cấp tỉnh; HĐND cấp tỉnh giải tán HĐND cấp xã.","cc":"Khoản 1 Điều 50 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"tc-043","cd":"tc","m":1,"l":"kt","q":"Theo Luật Tổ chức chính quyền địa phương số 72/2025/QH15, HĐND, UBND huyện, quận, thị xã, thành phố thuộc tỉnh (cấp huyện) kết thúc hoạt động từ ngày nào?","a":["Ngày 01 tháng 7 năm 2025","Ngày 16 tháng 6 năm 2025","Ngày 01 tháng 01 năm 2026","Ngày 15 tháng 3 năm 2026"],"why":"Chính quyền địa phương cấp huyện kết thúc hoạt động từ ngày 01/7/2025; từ đó cả nước tổ chức chính quyền địa phương 2 cấp là cấp tỉnh và cấp xã.","cc":"Khoản 3 Điều 51 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"tc-044","cd":"tc","m":1,"l":"kt","q":"Nghị quyết số 106/2025/UBTVQH15 của UBTVQH quy định về nội dung nào?","a":["Số lượng Phó Chủ tịch HĐND, Phó Trưởng Ban của HĐND và bố trí đại biểu HĐND chuyên trách","Tiêu chuẩn, điều kiện thành lập Ban Dân tộc của HĐND cấp tỉnh","Số lượng đại biểu HĐND được bầu ở mỗi tỉnh, thành phố và xã, phường","Trình tự, thủ tục cử tri bãi nhiệm đại biểu HĐND cấp tỉnh, cấp xã"],"why":"Nghị quyết 106/2025/UBTVQH15 quy định số lượng Phó Chủ tịch HĐND, Phó Trưởng Ban của HĐND cấp tỉnh, cấp xã và việc bố trí đại biểu HĐND hoạt động chuyên trách. Tiêu chuẩn thành lập Ban Dân tộc thuộc Nghị quyết 108/2025/UBTVQH15.","cc":"Điều 1 Nghị quyết số 106/2025/UBTVQH15 của Ủy ban Thường vụ Quốc hội"},{"id":"tc-045","cd":"tc","m":1,"l":"kt","q":"Theo Nghị quyết số 106/2025/UBTVQH15, HĐND cấp xã có bao nhiêu Phó Chủ tịch HĐND?","a":["01 Phó Chủ tịch","02 Phó Chủ tịch","03 Phó Chủ tịch","Không có Phó Chủ tịch, chỉ có Chủ tịch HĐND"],"why":"HĐND cấp xã (xã, phường, đặc khu nơi tổ chức cấp chính quyền địa phương) có 01 Phó Chủ tịch HĐND.","cc":"Điều 5 Nghị quyết số 106/2025/UBTVQH15 của Ủy ban Thường vụ Quốc hội"},{"id":"tc-053","cd":"tc","m":1,"l":"kt","q":"Nghị quyết số 108/2025/UBTVQH15 quy định tiêu chuẩn, điều kiện thành lập Ban Dân tộc của HĐND ở cấp nào?","a":["Cấp tỉnh","Cấp xã","Cấp tỉnh và cấp xã","Cấp tỉnh và đặc khu"],"why":"Nghị quyết 108/2025/UBTVQH15 quy định tiêu chuẩn, điều kiện thành lập Ban Dân tộc của HĐND cấp tỉnh. HĐND cấp xã chỉ thành lập Ban Kinh tế - Ngân sách và Ban Văn hóa - Xã hội.","cc":"Điều 1 Nghị quyết số 108/2025/UBTVQH15 của Ủy ban Thường vụ Quốc hội"},{"id":"tc-003","cd":"tc","m":2,"l":"th","q":"Bà M là Trưởng Ban Kinh tế - Ngân sách của HĐND xã A, đồng thời là Ủy viên Thường trực HĐND xã. Chủ tịch UBND xã A dự kiến giới thiệu bà M để HĐND xã bầu giữ thêm chức Ủy viên UBND xã. Dự kiến này có đúng luật không?","a":["Không, vì thành viên Thường trực HĐND không thể đồng thời là thành viên UBND cùng cấp","Có, vì thành viên UBND không nhất thiết phải là đại biểu HĐND","Có, nếu kết quả bầu được Chủ tịch UBND tỉnh phê chuẩn","Có, nếu bà M chuyển sang hoạt động không chuyên trách tại Ban"],"why":"Trưởng Ban của HĐND là Ủy viên Thường trực HĐND. Luật quy định thành viên Thường trực HĐND không thể đồng thời là thành viên UBND cùng cấp, nên bà M không thể kiêm Ủy viên UBND xã.","cc":"Khoản 2 Điều 29 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"tc-009","cd":"tc","m":2,"l":"th","q":"Ban Văn hóa - Xã hội của HĐND xã A cần bổ sung một Phó Trưởng Ban trong số đại biểu HĐND xã. Theo Luật Tổ chức chính quyền địa phương số 72/2025/QH15, việc này được thực hiện như thế nào?","a":["Thường trực HĐND xã phê chuẩn theo đề nghị của Trưởng Ban","HĐND xã bầu theo giới thiệu của Thường trực HĐND xã","Chủ tịch HĐND xã bổ nhiệm theo đề nghị của Trưởng Ban","Thường trực HĐND tỉnh phê chuẩn theo đề nghị của HĐND xã"],"why":"Trong các chức danh của Ban, HĐND chỉ bầu Trưởng Ban. Danh sách Phó Trưởng Ban, Ủy viên của Ban do Thường trực HĐND cấp mình phê chuẩn trong số đại biểu HĐND theo đề nghị của Trưởng Ban.","cc":"Khoản 7 Điều 31 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"tc-011","cd":"tc","m":2,"l":"th","q":"Giữa nhiệm kỳ, Chủ tịch HĐND xã A chuyển công tác, HĐND xã chưa bầu được Chủ tịch mới; Phó Chủ tịch HĐND xã vẫn đang làm việc bình thường. Ai điều hành hoạt động của HĐND và Thường trực HĐND xã A cho đến khi bầu ra Chủ tịch HĐND mới?","a":["Phó Chủ tịch HĐND xã, theo phân công của Thường trực HĐND xã","Người do Thường trực HĐND tỉnh chỉ định trong số đại biểu HĐND xã","Chủ tịch UBND xã, theo phân công của Thường trực HĐND tỉnh","Trưởng Ban cao tuổi nhất của HĐND xã, theo đề cử của HĐND xã"],"why":"Khi khuyết Chủ tịch HĐND, Thường trực HĐND cùng cấp phân công 01 Phó Chủ tịch HĐND điều hành. Thường trực HĐND tỉnh chỉ chỉ định người điều hành khi HĐND xã khuyết cả Chủ tịch và Phó Chủ tịch.","cc":"Khoản 4 Điều 32 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"tc-014","cd":"tc","m":2,"l":"kt","q":"Đại biểu HĐND không tham dự các kỳ họp liên tục trong 01 năm mà không có lý do chính đáng thì bị xử lý thế nào?","a":["Thường trực HĐND phải báo cáo HĐND để bãi nhiệm đại biểu đó","Thường trực HĐND quyết định tạm đình chỉ nhiệm vụ của đại biểu đó","Đại biểu đó đương nhiên mất quyền đại biểu HĐND","Chủ tịch HĐND nhắc nhở và thông báo về nơi đại biểu đó công tác"],"why":"Không tham dự các kỳ họp liên tục trong 01 năm mà không có lý do chính đáng là căn cứ để Thường trực HĐND phải báo cáo HĐND bãi nhiệm đại biểu; đây không phải trường hợp tạm đình chỉ hay đương nhiên mất quyền đại biểu.","cc":"Khoản 2 Điều 33 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"tc-017","cd":"tc","m":2,"l":"th","q":"Một đại biểu HĐND xã A bị cơ quan công an tạm giữ vì phạm tội quả tang. Theo Luật Tổ chức chính quyền địa phương số 72/2025/QH15, cơ quan tạm giữ phải làm gì?","a":["Lập tức báo cáo để HĐND hoặc Thường trực HĐND xem xét, quyết định","Trả tự do ngay cho đại biểu và chờ ý kiến của HĐND","Báo cáo Thường trực HĐND trong thời hạn 05 ngày làm việc","Chỉ cần thông báo cho Chủ tịch UBND và Ủy ban MTTQ cùng cấp"],"why":"Phạm tội quả tang là trường hợp đại biểu có thể bị tạm giữ trước, nhưng cơ quan tạm giữ phải lập tức báo cáo để HĐND hoặc Thường trực HĐND xem xét, quyết định.","cc":"Khoản 10 Điều 33 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"tc-020","cd":"tc","m":2,"l":"kt","q":"Ngoài Thường trực HĐND và Chủ tịch UBND cùng cấp, phải có ít nhất bao nhiêu đại biểu HĐND yêu cầu thì HĐND họp kỳ họp chuyên đề hoặc kỳ họp để giải quyết công việc phát sinh đột xuất?","a":["Một phần ba tổng số đại biểu HĐND","Một phần tư tổng số đại biểu HĐND","Quá nửa tổng số đại biểu HĐND","Hai phần ba tổng số đại biểu HĐND"],"why":"HĐND họp kỳ họp chuyên đề hoặc kỳ họp giải quyết công việc phát sinh đột xuất khi Thường trực HĐND, Chủ tịch UBND cùng cấp hoặc ít nhất một phần ba tổng số đại biểu HĐND yêu cầu.","cc":"Khoản 3 Điều 34 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"tc-021","cd":"tc","m":2,"l":"th","q":"Xã A có 12.000 cử tri. Một đơn yêu cầu HĐND xã họp bàn về việc quản lý chợ của xã có chữ ký hợp lệ của 1.500 cử tri trong xã. Theo Luật Tổ chức chính quyền địa phương số 72/2025/QH15, Thường trực HĐND xã A phải xử lý thế nào?","a":["Tổ chức kỳ họp chuyên đề hoặc họp giải quyết việc đột xuất để bàn nội dung cử tri kiến nghị","Chuyển đơn đến UBND xã giải quyết vì chưa đủ một phần ba tổng số cử tri của xã","Ghi nhận và đưa nội dung vào kỳ họp thường lệ cuối năm của HĐND xã","Báo cáo Thường trực HĐND tỉnh xem xét, quyết định việc tổ chức kỳ họp"],"why":"Khi đơn yêu cầu có chữ ký của trên 10% tổng số cử tri của cấp xã (ở đây 1.500/12.000 = 12,5%), Thường trực HĐND cấp xã có trách nhiệm tổ chức kỳ họp chuyên đề hoặc họp giải quyết công việc đột xuất để bàn nội dung đó.","cc":"Khoản 4 Điều 34 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"tc-026","cd":"tc","m":2,"l":"kt","q":"Kết quả bầu Chủ tịch HĐND, Phó Chủ tịch HĐND cấp xã phải được chủ thể nào phê chuẩn?","a":["Thường trực HĐND cấp tỉnh","Chủ tịch UBND cấp tỉnh","HĐND cấp tỉnh tại kỳ họp gần nhất","Ủy ban Thường vụ Quốc hội"],"why":"Kết quả bầu Chủ tịch, Phó Chủ tịch HĐND cấp xã do Thường trực HĐND cấp tỉnh phê chuẩn. Chủ tịch UBND cấp tỉnh phê chuẩn kết quả bầu Chủ tịch, Phó Chủ tịch UBND cấp xã; UBTVQH phê chuẩn đối với Chủ tịch, Phó Chủ tịch HĐND cấp tỉnh.","cc":"Khoản 3 Điều 36 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"tc-027","cd":"tc","m":2,"l":"th","q":"Tại kỳ họp, HĐND xã A bầu ông H giữ chức Chủ tịch UBND xã. Kết quả bầu đang chờ Chủ tịch UBND tỉnh phê chuẩn. Theo Luật Tổ chức chính quyền địa phương số 72/2025/QH15, ông H thực hiện nhiệm vụ, quyền hạn của Chủ tịch UBND xã từ khi nào?","a":["Ngay sau khi được HĐND xã bầu","Từ ngày Chủ tịch UBND tỉnh phê chuẩn kết quả bầu","Sau 05 ngày làm việc kể từ ngày được bầu","Từ ngày Thường trực HĐND xã gửi kết quả bầu đi phê chuẩn"],"why":"Người giữ chức vụ do HĐND bầu thực hiện nhiệm vụ, quyền hạn của mình ngay sau khi được HĐND bầu, không phải chờ phê chuẩn. Nếu kết quả bầu không được phê chuẩn thì HĐND tổ chức bầu lại chức danh đó.","cc":"Khoản 6 Điều 36 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"tc-029","cd":"tc","m":2,"l":"th","q":"Một Trưởng Ban của HĐND tỉnh được cơ quan có thẩm quyền quyết định cho nghỉ hưu. Theo Luật Tổ chức chính quyền địa phương số 72/2025/QH15, thủ tục tại HĐND tỉnh đối với chức vụ Trưởng Ban của người này được thực hiện thế nào?","a":["Không phải làm thủ tục miễn nhiệm; Thường trực HĐND báo cáo HĐND tại kỳ họp gần nhất","HĐND tỉnh phải miễn nhiệm tại kỳ họp gần nhất theo đề nghị của Thường trực HĐND","Thường trực HĐND tỉnh ra nghị quyết miễn nhiệm rồi trình UBTVQH phê chuẩn","HĐND tỉnh phải bãi nhiệm với ít nhất hai phần ba tổng số đại biểu tán thành"],"why":"Người được HĐND bầu mà được cơ quan có thẩm quyền quyết định cho nghỉ hưu hoặc từ trần thì không phải thực hiện thủ tục miễn nhiệm tại HĐND; Thường trực HĐND báo cáo HĐND tại kỳ họp gần nhất.","cc":"Khoản 6 Điều 37 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"tc-031","cd":"tc","m":2,"l":"th","q":"Một đại biểu HĐND xã A vừa bị cơ quan có thẩm quyền khởi tố. Theo Luật Tổ chức chính quyền địa phương số 72/2025/QH15, việc thực hiện nhiệm vụ, quyền hạn đại biểu của người này được xử lý thế nào?","a":["Thường trực HĐND xã quyết định tạm đình chỉ việc thực hiện nhiệm vụ, quyền hạn đại biểu","Đại biểu đương nhiên mất quyền đại biểu HĐND kể từ ngày bị khởi tố","HĐND xã phải họp để bãi nhiệm đại biểu trong thời hạn 30 ngày","Đại biểu vẫn hoạt động bình thường cho đến khi có bản án của Tòa án"],"why":"Đại biểu HĐND bị khởi tố thì Thường trực HĐND quyết định tạm đình chỉ việc thực hiện nhiệm vụ, quyền hạn đại biểu. Chỉ khi bị kết tội bằng bản án, quyết định của Tòa án đã có hiệu lực thì mới đương nhiên mất quyền đại biểu.","cc":"Điểm a khoản 1 Điều 38 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"tc-034","cd":"tc","m":2,"l":"th","q":"Bà L là Trưởng Ban Văn hóa - Xã hội của HĐND xã A. Bà được chấp thuận cho thôi làm nhiệm vụ đại biểu HĐND xã vì lý do sức khỏe. Theo Luật Tổ chức chính quyền địa phương số 72/2025/QH15, chức vụ Trưởng Ban của bà L được giải quyết thế nào?","a":["Bà L đương nhiên thôi đảm nhiệm chức vụ Trưởng Ban","Bà L tiếp tục giữ chức vụ cho đến khi HĐND xã miễn nhiệm","Bà L tiếp tục giữ chức vụ cho đến khi hết nhiệm kỳ HĐND","Bà L giữ chức vụ đến khi Thường trực HĐND tỉnh phê chuẩn cho thôi"],"why":"Đại biểu HĐND đã thôi làm nhiệm vụ đại biểu, bị miễn nhiệm, bãi nhiệm hoặc bị mất quyền đại biểu thì đương nhiên thôi đảm nhiệm các chức vụ trong Thường trực HĐND, Ban của HĐND.","cc":"Khoản 7 Điều 38 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"tc-036","cd":"tc","m":2,"l":"kt","q":"Khi Chủ tịch UBND cấp xã có hành vi vi phạm pháp luật hoặc không thực hiện đúng chức trách, nhiệm vụ được giao, ai có thẩm quyền quyết định cách chức?","a":["Chủ tịch UBND cấp tỉnh","Thường trực HĐND cấp tỉnh","Thủ tướng Chính phủ","HĐND cấp xã, theo đề nghị của Chủ tịch HĐND cấp xã"],"why":"Chủ tịch UBND cấp tỉnh quyết định cách chức Chủ tịch, Phó Chủ tịch UBND cấp xã; Thủ tướng Chính phủ cách chức Chủ tịch, Phó Chủ tịch UBND cấp tỉnh. Khi đó HĐND không thực hiện thủ tục miễn nhiệm, bãi nhiệm.","cc":"Khoản 2 Điều 41 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"tc-038","cd":"tc","m":2,"l":"th","q":"Xã A và xã B được nhập thành một xã mới mang tên xã C (không trùng tên với xã nào trước đó). Theo Luật Tổ chức chính quyền địa phương số 72/2025/QH15, khóa của HĐND xã C được xác định thế nào?","a":["Tính lại từ đầu (khóa I) kể từ thời điểm thành lập xã C","Tiếp tục tính theo khóa của HĐND xã có dân số lớn hơn","Tiếp tục tính theo khóa của HĐND xã được thành lập sớm hơn","Do Thường trực HĐND tỉnh quyết định khi chỉ định triệu tập viên"],"why":"Đơn vị hành chính mới thay đổi tên gọi hoặc thay đổi loại đơn vị hành chính thì khóa HĐND được tính lại từ khóa I. Chỉ khi giữ nguyên tên gọi của một trong các đơn vị cũ thì mới tiếp tục tính theo khóa HĐND của đơn vị đó.","cc":"Điểm b khoản 1 Điều 49 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"tc-041","cd":"tc","m":2,"l":"kt","q":"Chủ thể nào có thẩm quyền giải tán HĐND cấp xã và nghị quyết giải tán phải được ai phê chuẩn?","a":["HĐND cấp tỉnh giải tán; UBTVQH phê chuẩn","Thường trực HĐND cấp tỉnh giải tán; HĐND cấp tỉnh phê chuẩn","UBND cấp tỉnh giải tán; Thủ tướng Chính phủ phê chuẩn","HĐND cấp tỉnh giải tán; Thủ tướng Chính phủ phê chuẩn"],"why":"HĐND cấp tỉnh giải tán HĐND cấp xã, nhưng nghị quyết giải tán phải trình UBTVQH phê chuẩn; HĐND cấp xã chấm dứt hoạt động kể từ ngày nghị quyết được phê chuẩn. UBTVQH trực tiếp giải tán HĐND cấp tỉnh.","cc":"Khoản 2 và khoản 3 Điều 50 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"tc-046","cd":"tc","m":2,"l":"kt","q":"Theo Nghị quyết số 106/2025/UBTVQH15, HĐND ở đơn vị hành chính cấp tỉnh không thuộc diện sắp xếp năm 2025 có tối đa bao nhiêu Phó Chủ tịch HĐND?","a":["Không quá 02 Phó Chủ tịch","Không quá 01 Phó Chủ tịch","Không quá 03 Phó Chủ tịch","Không quá 04 Phó Chủ tịch"],"why":"Đơn vị hành chính cấp tỉnh không thực hiện sắp xếp có không quá 02 Phó Chủ tịch HĐND; tỉnh hình thành sau sắp xếp có không quá 03; thành phố hình thành do sắp xếp 03 đơn vị hành chính cấp tỉnh có không quá 04.","cc":"Khoản 4 Điều 3 Nghị quyết số 106/2025/UBTVQH15 của Ủy ban Thường vụ Quốc hội"},{"id":"tc-047","cd":"tc","m":2,"l":"kt","q":"Theo Nghị quyết số 106/2025/UBTVQH15, mỗi Ban của HĐND cấp xã được tính bình quân bao nhiêu Phó Trưởng Ban?","a":["02 Phó Trưởng Ban","01 Phó Trưởng Ban","03 Phó Trưởng Ban","04 Phó Trưởng Ban"],"why":"Mỗi Ban của HĐND cấp xã được tính bình quân 02 Phó Trưởng Ban; số lượng cụ thể ở từng xã có thể khác nhau nhưng tổng số trong toàn tỉnh không được vượt quá tổng số tính theo khung bình quân này.","cc":"Khoản 1 Điều 6 Nghị quyết số 106/2025/UBTVQH15 của Ủy ban Thường vụ Quốc hội"},{"id":"tc-048","cd":"tc","m":2,"l":"kt","q":"Theo Nghị quyết số 106/2025/UBTVQH15, chủ thể nào quyết định cụ thể số lượng Phó Trưởng Ban của HĐND ở từng đơn vị hành chính cấp xã?","a":["Thường trực HĐND cấp tỉnh","Thường trực HĐND cấp xã","HĐND cấp xã","UBND cấp tỉnh"],"why":"Thường trực HĐND cấp tỉnh quyết định cụ thể số lượng Phó Trưởng Ban của HĐND ở từng xã, căn cứ quy mô diện tích, dân số, phân loại đơn vị hành chính, tình hình thực tiễn và định hướng của Ban Thường vụ tỉnh ủy, thành ủy.","cc":"Khoản 2 Điều 6 Nghị quyết số 106/2025/UBTVQH15 của Ủy ban Thường vụ Quốc hội"},{"id":"tc-049","cd":"tc","m":2,"l":"kt","q":"Theo Nghị quyết số 106/2025/UBTVQH15, mỗi Ban của HĐND cấp tỉnh được tính bình quân bao nhiêu Ủy viên là đại biểu HĐND hoạt động chuyên trách?","a":["01 Ủy viên","02 Ủy viên","03 Ủy viên","Không có, Ủy viên của Ban chỉ hoạt động kiêm nhiệm"],"why":"Mỗi Ban của HĐND cấp tỉnh được tính bình quân 01 Ủy viên là đại biểu HĐND hoạt động chuyên trách; số lượng cụ thể của từng Ban do Thường trực HĐND cấp tỉnh quyết định trong tổng số tính theo mức bình quân.","cc":"Khoản 1 Điều 8 Nghị quyết số 106/2025/UBTVQH15 của Ủy ban Thường vụ Quốc hội"},{"id":"tc-054","cd":"tc","m":2,"l":"kt","q":"Theo Nghị quyết số 108/2025/UBTVQH15, tiêu chuẩn về số người dân tộc thiểu số sinh sống tập trung thành cộng đồng làng, bản để thành lập Ban Dân tộc của HĐND cấp tỉnh là bao nhiêu?","a":["Trên 20.000 người","Trên 5.000 người","Trên 10.000 người","Trên 50.000 người"],"why":"Tiêu chuẩn thứ nhất là tỉnh, thành phố có trên 20.000 người dân tộc thiểu số sinh sống tập trung thành cộng đồng làng, bản. Mức trên 5.000 người áp dụng cho người dân tộc thiểu số đang cần Nhà nước tập trung giúp đỡ, hỗ trợ phát triển.","cc":"Khoản 1 Điều 1 Nghị quyết số 108/2025/UBTVQH15 của Ủy ban Thường vụ Quốc hội"},{"id":"tc-006","cd":"tc","m":3,"l":"th","q":"Tỉnh A (là tỉnh, không phải thành phố) có 1.700.000 dân. Theo nguyên tắc xác định số lượng đại biểu của Luật Tổ chức chính quyền địa phương số 72/2025/QH15, tỉnh A được bầu bao nhiêu đại biểu HĐND tỉnh?","a":["60 đại biểu","56 đại biểu","74 đại biểu","85 đại biểu"],"why":"Tỉnh có đến 1.000.000 dân được bầu 50 đại biểu; trên mức đó cứ thêm 70.000 dân được bầu thêm 01 đại biểu. 700.000 dân tăng thêm ứng với 10 đại biểu, tổng cộng 60 đại biểu (mức trần là 85).","cc":"Điểm a khoản 1 Điều 30 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"tc-007","cd":"tc","m":3,"l":"th","q":"Xã A là xã miền núi có 8.000 dân. Theo nguyên tắc xác định số lượng đại biểu của Luật Tổ chức chính quyền địa phương số 72/2025/QH15, HĐND xã A được bầu bao nhiêu đại biểu?","a":["18 đại biểu","15 đại biểu","23 đại biểu","30 đại biểu"],"why":"Xã miền núi có đến 5.000 dân được bầu 15 đại biểu; từ trên 5.000 đến 10.000 dân thì cứ thêm 1.000 dân được bầu thêm 01 đại biểu. 3.000 dân tăng thêm ứng với 3 đại biểu, tổng cộng 18 đại biểu.","cc":"Điểm a khoản 2 Điều 30 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"tc-010","cd":"tc","m":3,"l":"kt","q":"Trong thời gian HĐND không họp, chủ thể nào được quyết định chế độ chi ngân sách đối với một số nhiệm vụ chi thuộc trường hợp đột xuất, cấp bách theo chỉ đạo của cấp có thẩm quyền, rồi báo cáo HĐND tại kỳ họp gần nhất?","a":["Thường trực HĐND cấp tỉnh","Thường trực HĐND cấp xã","Chủ tịch UBND cấp tỉnh","Ban Kinh tế - Ngân sách của HĐND cấp tỉnh"],"why":"Thường trực HĐND các cấp được quyết định biện pháp giải quyết công việc đột xuất, khẩn cấp; riêng việc quyết định chế độ chi ngân sách cho nhiệm vụ chi đột xuất, cấp bách thì Luật chỉ trao cho Thường trực HĐND cấp tỉnh.","cc":"Điểm b khoản 14 Điều 31 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"tc-012","cd":"tc","m":3,"l":"th","q":"HĐND xã B khuyết cả Chủ tịch và Phó Chủ tịch HĐND. Theo Luật Tổ chức chính quyền địa phương số 72/2025/QH15, người điều hành hoạt động của HĐND, Thường trực HĐND xã B cho đến khi bầu ra Chủ tịch HĐND mới được xác định thế nào?","a":["Thường trực HĐND tỉnh chỉ định trong số đại biểu HĐND xã B","UBTVQH chỉ định trong số đại biểu HĐND xã B","Chủ tịch UBND tỉnh chỉ định trong số thành viên UBND xã B","Các Trưởng Ban của HĐND xã B tự phân công một người điều hành"],"why":"Khuyết cả Chủ tịch và Phó Chủ tịch HĐND cấp xã thì Thường trực HĐND cấp tỉnh chỉ định người điều hành trong số đại biểu HĐND cấp xã. UBTVQH chỉ định trong trường hợp tương tự ở HĐND cấp tỉnh.","cc":"Khoản 4 Điều 32 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"tc-022","cd":"tc","m":3,"l":"kt","q":"HĐND họp công khai. Trong trường hợp cần thiết, chủ thể nào quyết định việc HĐND họp kín?","a":["HĐND, theo đề nghị của Thường trực HĐND, Chủ tịch UBND hoặc yêu cầu của ít nhất 1/3 đại biểu","Thường trực HĐND, theo đề nghị của Chủ tịch UBND cùng cấp","Chủ tịch HĐND, theo yêu cầu của ít nhất 1/3 tổng số đại biểu HĐND","Chủ tọa kỳ họp, sau khi thống nhất với Chủ tịch UBND cùng cấp"],"why":"Thường trực HĐND, Chủ tịch UBND cùng cấp chỉ có quyền đề nghị, ít nhất một phần ba tổng số đại biểu HĐND có quyền yêu cầu; còn quyền quyết định họp kín thuộc về chính HĐND.","cc":"Khoản 5 Điều 34 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"tc-024","cd":"tc","m":3,"l":"th","q":"HĐND xã A có tổng số 24 đại biểu; tại kỳ họp có 21 đại biểu tham dự. HĐND xã biểu quyết nghị quyết bãi nhiệm một đại biểu HĐND xã. Nghị quyết này được thông qua khi có ít nhất bao nhiêu đại biểu biểu quyết tán thành?","a":["16 đại biểu","14 đại biểu","13 đại biểu","11 đại biểu"],"why":"Bãi nhiệm đại biểu HĐND cần ít nhất hai phần ba TỔNG SỐ đại biểu HĐND tán thành, tức 2/3 của 24 là 16; không tính trên số đại biểu có mặt (14) và không áp dụng mức quá nửa tổng số (13).","cc":"Khoản 2 Điều 35 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"tc-028","cd":"tc","m":3,"l":"th","q":"Tại một kỳ họp giữa nhiệm kỳ, khi HĐND xã A bầu Trưởng Ban Kinh tế - Ngân sách, một đại biểu tự ứng cử dù không có tên trong danh sách đề cử của Thường trực HĐND xã. Theo Luật Tổ chức chính quyền địa phương số 72/2025/QH15, trường hợp này được xử lý thế nào?","a":["Thường trực HĐND xã trình HĐND xã xem xét, quyết định","Không chấp nhận, vì chỉ được bầu theo danh sách đề cử của Thường trực HĐND","Đương nhiên bổ sung vào danh sách bầu, vì đại biểu có quyền ứng cử","Thường trực HĐND tỉnh xem xét, quyết định việc bổ sung danh sách"],"why":"Đại biểu HĐND có quyền ứng cử hoặc giới thiệu thêm người ngoài danh sách; khi đó Thường trực HĐND trình HĐND xem xét, quyết định. Riêng tại kỳ họp thứ nhất của mỗi khóa thì chủ tọa kỳ họp trình HĐND.","cc":"Khoản 5 Điều 36 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"tc-030","cd":"tc","m":3,"l":"th","q":"Phó Chủ tịch UBND xã A (được HĐND xã bầu theo giới thiệu của Chủ tịch UBND xã) muốn xin từ chức vì lý do sức khỏe. Theo Luật Tổ chức chính quyền địa phương số 72/2025/QH15, người này phải làm đơn và gửi đến ai?","a":["Chủ tịch UBND xã A, là người đã giới thiệu để HĐND xã bầu chức vụ đó","Chủ tịch UBND tỉnh, là người phê chuẩn kết quả bầu chức vụ đó","Chủ tịch HĐND xã A, là người chủ tọa kỳ họp bầu chức vụ đó","Thường trực HĐND tỉnh, là cơ quan giám sát hoạt động của HĐND xã"],"why":"Đơn xin thôi giữ chức vụ, xin từ chức phải gửi đến cơ quan hoặc người có thẩm quyền giới thiệu để HĐND bầu chức vụ đó. Phó Chủ tịch UBND do Chủ tịch UBND giới thiệu nên đơn gửi đến Chủ tịch UBND xã.","cc":"Khoản 2 Điều 37 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"tc-032","cd":"tc","m":3,"l":"th","q":"Ông K là đại biểu HĐND xã A. Ông chuyển công tác sang cơ quan ở tỉnh khác nhưng vẫn cư trú tại xã A và không đề nghị thôi làm nhiệm vụ đại biểu. Theo điểm a khoản 3 Điều 38 Luật Tổ chức chính quyền địa phương số 72/2025/QH15, ông K có thuộc diện được xem xét cho thôi làm nhiệm vụ đại biểu do không còn công tác, cư trú tại xã A không?","a":["Không, vì phải đồng thời không còn công tác và không cư trú tại xã A","Có, vì chỉ cần không còn công tác tại cơ quan, tổ chức ở xã A","Có, nhưng phải được hai phần ba tổng số đại biểu HĐND xã tán thành","Không, vì đại biểu HĐND chỉ thôi làm nhiệm vụ khi hết nhiệm kỳ"],"why":"Điểm a khoản 3 Điều 38 đòi hỏi đủ hai điều kiện: không còn công tác tại cơ quan, tổ chức, doanh nghiệp ở đơn vị hành chính đó VÀ không cư trú tại đó. Ông K vẫn cư trú tại xã A nên chưa thuộc trường hợp này.","cc":"Điểm a khoản 3 Điều 38 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"tc-039","cd":"tc","m":3,"l":"th","q":"Do nhiều đại biểu chuyển công tác, HĐND xã A không còn đủ hai phần ba tổng số đại biểu được bầu theo quy định, trong khi nhiệm kỳ còn lại đúng 18 tháng. Theo Luật Tổ chức chính quyền địa phương số 72/2025/QH15, có thực hiện bầu cử bổ sung đại biểu HĐND xã A không?","a":["Không, vì thời gian còn lại của nhiệm kỳ ít hơn hoặc bằng 18 tháng","Có, vì thời gian còn lại của nhiệm kỳ từ đủ 18 tháng trở lên","Có, vì không đủ hai phần ba tổng số đại biểu thì luôn phải bầu bổ sung","Không, vì chỉ bầu bổ sung khi còn dưới một phần ba tổng số đại biểu"],"why":"Chỉ bầu cử bổ sung khi thời gian còn lại của nhiệm kỳ NHIỀU HƠN 18 tháng. Nếu còn lại ít hơn hoặc bằng 18 tháng (kể cả đúng 18 tháng) thì không thực hiện bầu cử bổ sung đại biểu HĐND.","cc":"Điểm b khoản 2 Điều 49 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"tc-050","cd":"tc","m":3,"l":"th","q":"Theo quyết định của Thường trực HĐND tỉnh, Ban Kinh tế - Ngân sách của HĐND xã A có 02 Phó Trưởng Ban. Nay xã A bố trí Trưởng Ban này là đại biểu HĐND hoạt động chuyên trách. Theo Nghị quyết số 106/2025/UBTVQH15, số lượng Phó Trưởng Ban của Ban này thay đổi thế nào?","a":["Giảm tương ứng 01 người","Giữ nguyên như đã được quyết định","Tăng thêm 01 người hoạt động chuyên trách","Giảm tương ứng 02 người"],"why":"Khi bố trí Trưởng Ban của HĐND cấp tỉnh, cấp xã là đại biểu HĐND hoạt động chuyên trách thì số lượng Phó Trưởng Ban theo quy định giảm tương ứng 01 người.","cc":"Khoản 5 Điều 7 Nghị quyết số 106/2025/UBTVQH15 của Ủy ban Thường vụ Quốc hội"},{"id":"tc-051","cd":"tc","m":3,"l":"th","q":"HĐND xã A dự kiến bố trí một Ủy viên của Ban Văn hóa - Xã hội làm đại biểu HĐND hoạt động chuyên trách. Theo Nghị quyết số 106/2025/UBTVQH15, dự kiến này có phù hợp không?","a":["Không, vì ở cấp xã chức danh Ủy viên của Ban không thuộc diện bố trí chuyên trách","Có, vì mỗi Ban của HĐND cấp xã được tính bình quân 01 Ủy viên chuyên trách","Có, nếu Thường trực HĐND tỉnh quyết định trong tổng số được giao","Không, vì ở cấp xã chỉ Chủ tịch HĐND mới được hoạt động chuyên trách"],"why":"Ở cấp xã chỉ có thể bố trí chuyên trách đối với 4 chức danh: Chủ tịch HĐND, Phó Chủ tịch HĐND, Trưởng Ban và Phó Trưởng Ban của HĐND. Ủy viên của Ban hoạt động chuyên trách chỉ được bố trí ở HĐND cấp tỉnh.","cc":"Khoản 2 Điều 7 Nghị quyết số 106/2025/UBTVQH15 của Ủy ban Thường vụ Quốc hội"},{"id":"tc-052","cd":"tc","m":3,"l":"kt","q":"Theo Nghị quyết số 106/2025/UBTVQH15, đơn vị hành chính cấp tỉnh hình thành sau sắp xếp năm 2025 có số Phó Chủ tịch HĐND, Phó Trưởng Ban của HĐND cấp tỉnh nhiều hơn quy định thì phải giảm dần để thực hiện đúng quy định vào thời điểm nào?","a":["Đến tháng 7 năm 2030","Đến tháng 3 năm 2027","Đến tháng 7 năm 2026","Đến khi kết thúc nhiệm kỳ 2026 - 2031"],"why":"Đầu nhiệm kỳ 2026 - 2031 được giữ nguyên số lượng như cuối nhiệm kỳ 2021 - 2026, nhưng HĐND tỉnh, thành phố phải có lộ trình giảm dần để đến tháng 7 năm 2030 thực hiện đúng quy định, trừ trường hợp cấp có thẩm quyền có quy định khác.","cc":"Khoản 1 Điều 10 Nghị quyết số 106/2025/UBTVQH15 của Ủy ban Thường vụ Quốc hội"},{"id":"tc-055","cd":"tc","m":3,"l":"th","q":"Tỉnh A có 12.000 người dân tộc thiểu số sinh sống tập trung thành cộng đồng làng, bản; có 6.000 người dân tộc thiểu số đang cần Nhà nước tập trung giúp đỡ, hỗ trợ phát triển; có đồng bào dân tộc thiểu số sinh sống ở địa bàn xung yếu về an ninh, quốc phòng. Theo Nghị quyết số 108/2025/UBTVQH15, HĐND tỉnh A có đủ điều kiện thành lập Ban Dân tộc không?","a":["Có, vì đáp ứng 02 trong 03 tiêu chuẩn, điều kiện theo quy định","Không, vì phải đáp ứng đủ 03 tiêu chuẩn, điều kiện theo quy định","Không, vì chưa có trên 20.000 người sinh sống tập trung thành cộng đồng","Có, vì chỉ cần đáp ứng 01 trong 03 tiêu chuẩn, điều kiện theo quy định"],"why":"Ban Dân tộc được thành lập khi đáp ứng 02 trong 03 tiêu chuẩn. Tỉnh A không đạt mức trên 20.000 người sinh sống tập trung, nhưng đạt tiêu chuẩn trên 5.000 người cần giúp đỡ và tiêu chuẩn về địa bàn xung yếu an ninh, quốc phòng.","cc":"Điều 1 Nghị quyết số 108/2025/UBTVQH15 của Ủy ban Thường vụ Quốc hội"},{"id":"nv-001","cd":"nv","m":1,"l":"kt","q":"Nghị quyết của HĐND một xã bị phát hiện trái pháp luật. Ở cấp tỉnh, cơ quan nào có quyền bãi bỏ một phần hoặc toàn bộ nghị quyết đó?","a":["HĐND tỉnh","UBND tỉnh","Chủ tịch UBND tỉnh","Thường trực HĐND tỉnh"],"why":"Bãi bỏ văn bản trái pháp luật của HĐND cấp xã là quyền của HĐND tỉnh. Chủ tịch UBND tỉnh chỉ được đình chỉ thi hành rồi báo cáo UBND tỉnh để đề nghị HĐND tỉnh bãi bỏ.","cc":"Điểm đ khoản 1 Điều 15 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nv-007","cd":"nv","m":1,"l":"th","q":"Phường B vừa hoàn thành một tuyến phố mới và một quảng trường, cần đặt tên chính thức. Ở tỉnh, cơ quan nào có thẩm quyền quyết định đặt tên đường, phố, quảng trường này?","a":["HĐND tỉnh","HĐND phường B","UBND tỉnh","Chủ tịch UBND phường B"],"why":"Quyết định đặt tên, đổi tên đường, phố, quảng trường, công trình công cộng ở địa phương là nhiệm vụ, quyền hạn của HĐND tỉnh; HĐND phường không được giao việc này.","cc":"Điểm đ khoản 2 Điều 15 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nv-008","cd":"nv","m":1,"l":"th","q":"Xã A dự kiến tổ chức lại hai thôn ít dân thành một thôn mới và đặt tên cho thôn mới. Theo Luật Tổ chức chính quyền địa phương số 72/2025/QH15, cơ quan nào quyết định việc này?","a":["HĐND xã A","UBND xã A","HĐND tỉnh","UBND tỉnh"],"why":"Việc thành lập, tổ chức lại, giải thể, đặt tên, đổi tên thôn do HĐND xã quyết định theo quy định của pháp luật; UBND xã xây dựng, trình HĐND xã.","cc":"Điểm d khoản 2 Điều 21 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nv-009","cd":"nv","m":1,"l":"kt","q":"Ở phường, việc thành lập, tổ chức lại, giải thể, đặt tên, đổi tên tổ dân phố thuộc thẩm quyền quyết định của cơ quan nào?","a":["HĐND phường","UBND phường","Chủ tịch UBND phường","HĐND tỉnh"],"why":"HĐND phường quyết định thành lập, tổ chức lại, giải thể, đặt tên, đổi tên tổ dân phố (ở xã, HĐND xã quyết định các việc tương tự đối với thôn).","cc":"Khoản 3 Điều 24 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nv-011","cd":"nv","m":1,"l":"kt","q":"Chủ tịch, Phó Chủ tịch và Ủy viên UBND tỉnh do cơ quan nào bầu, miễn nhiệm, bãi nhiệm?","a":["HĐND tỉnh","Thường trực HĐND tỉnh","Thủ tướng Chính phủ","Cử tri trong tỉnh bầu trực tiếp"],"why":"HĐND bầu, miễn nhiệm, bãi nhiệm Chủ tịch, Phó Chủ tịch, Ủy viên UBND cùng cấp; UBND là cơ quan do HĐND cùng cấp bầu ra.","cc":"Điểm g khoản 2 Điều 15 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nv-013","cd":"nv","m":1,"l":"kt","q":"Kế hoạch phát triển kinh tế - xã hội cấp tỉnh 05 năm và hằng năm do cơ quan nào quyết định?","a":["HĐND tỉnh","UBND tỉnh","Chủ tịch UBND tỉnh","Thủ tướng Chính phủ"],"why":"HĐND tỉnh quyết định kế hoạch phát triển kinh tế - xã hội cấp tỉnh 05 năm và hằng năm; UBND tỉnh xây dựng, trình HĐND và tổ chức thực hiện nghị quyết.","cc":"Điểm a khoản 3 Điều 15 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nv-015","cd":"nv","m":1,"l":"th","q":"Kết thúc năm ngân sách, UBND xã A lập báo cáo quyết toán ngân sách xã. Theo Luật Tổ chức chính quyền địa phương số 72/2025/QH15, cơ quan nào phê chuẩn quyết toán ngân sách của xã A?","a":["HĐND xã A","HĐND tỉnh","UBND tỉnh","Chủ tịch UBND xã A"],"why":"HĐND xã quyết định dự toán, phân bổ dự toán và phê chuẩn quyết toán ngân sách cấp mình; HĐND tỉnh phê chuẩn quyết toán ngân sách địa phương ở cấp tỉnh.","cc":"Điểm b khoản 3 Điều 21 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nv-022","cd":"nv","m":1,"l":"th","q":"Xã A muốn huy động sự đóng góp của Nhân dân để làm đường giao thông và nhà văn hóa. Theo Luật Tổ chức chính quyền địa phương số 72/2025/QH15, cơ quan nào quyết định biện pháp huy động này?","a":["HĐND xã A","UBND xã A","Chủ tịch UBND xã A","Ủy ban MTTQ Việt Nam xã A"],"why":"HĐND xã quyết định biện pháp huy động sự đóng góp của Nhân dân để đầu tư xây dựng cơ sở hạ tầng, giao thông, công trình công cộng, phúc lợi trên địa bàn theo quy định của pháp luật.","cc":"Điểm c khoản 3 Điều 21 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nv-029","cd":"nv","m":1,"l":"kt","q":"Quy chế làm việc của HĐND, Thường trực HĐND, các Ban của HĐND, Tổ đại biểu HĐND và đại biểu HĐND xã do cơ quan nào ban hành?","a":["HĐND xã","Thường trực HĐND xã","HĐND tỉnh","Ủy ban Thường vụ Quốc hội"],"why":"HĐND mỗi cấp tự ban hành Quy chế làm việc của HĐND, Thường trực HĐND, các Ban, Tổ đại biểu và đại biểu HĐND cấp mình. Ủy ban Thường vụ Quốc hội chỉ ban hành Quy chế làm việc mẫu.","cc":"Điểm đ khoản 2 Điều 21 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nv-030","cd":"nv","m":1,"l":"kt","q":"Chính sách thu hút, trọng dụng, đãi ngộ người có tài năng và nguồn nhân lực chất lượng cao trong hoạt động công vụ tại địa phương do cơ quan nào quyết định?","a":["HĐND tỉnh","UBND tỉnh","Chủ tịch UBND tỉnh","HĐND xã"],"why":"HĐND tỉnh quyết định chính sách thu hút, trọng dụng, đãi ngộ người có tài năng, nguồn nhân lực chất lượng cao phù hợp với điều kiện, khả năng ngân sách của địa phương.","cc":"Điểm b khoản 2 Điều 15 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nv-032","cd":"nv","m":1,"l":"kt","q":"Theo Luật Tổ chức chính quyền địa phương số 72/2025/QH15, chính quyền địa phương ở đặc khu (chưa được công nhận loại đô thị) thực hiện các nhiệm vụ, quyền hạn tương ứng của chính quyền địa phương ở đâu?","a":["Ở xã","Ở phường","Ở tỉnh","Ở thành phố"],"why":"Chính quyền địa phương ở đặc khu thực hiện nhiệm vụ, quyền hạn tương ứng của chính quyền địa phương ở xã; chỉ khi đặc khu được công nhận loại đô thị mới thực hiện như ở phường.","cc":"Khoản 1 Điều 27 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nv-036","cd":"nv","m":1,"l":"kt","q":"Cơ quan nào ở xã có nhiệm vụ xây dựng, trình HĐND xã ban hành nghị quyết về các vấn đề như kế hoạch phát triển kinh tế - xã hội, ngân sách và tổ chức thực hiện nghị quyết của HĐND xã?","a":["UBND xã","Thường trực HĐND xã","Các Ban của HĐND xã","Ủy ban MTTQ Việt Nam xã"],"why":"UBND xã xây dựng, trình HĐND cùng cấp xem xét ban hành nghị quyết để thực hiện phần lớn nhiệm vụ, quyền hạn của HĐND xã và tổ chức thực hiện nghị quyết của HĐND.","cc":"Khoản 1 Điều 22 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nv-045","cd":"nv","m":1,"l":"kt","q":"Ở xã, ai chịu trách nhiệm cung ứng các dịch vụ công thiết yếu trên địa bàn như điện chiếu sáng, cấp nước, xử lý nước thải, rác thải, vệ sinh môi trường, phòng chống cháy nổ?","a":["Chủ tịch UBND xã","Chủ tịch HĐND xã","Chủ tịch UBND tỉnh","Trưởng thôn"],"why":"Luật giao Chủ tịch UBND xã chịu trách nhiệm cung ứng các dịch vụ công thiết yếu trên địa bàn: điện chiếu sáng, cấp nước, xử lý nước thải, rác thải, vệ sinh môi trường, phòng chống cháy nổ.","cc":"Khoản 12 Điều 23 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nv-046","cd":"nv","m":1,"l":"kt","q":"Theo Luật Tổ chức chính quyền địa phương số 72/2025/QH15, ai có nhiệm vụ hướng dẫn và kiểm tra hoạt động tự quản của thôn trên địa bàn xã?","a":["Chủ tịch UBND xã","Thường trực HĐND xã","HĐND xã","Chủ tịch Ủy ban MTTQ Việt Nam xã"],"why":"Hướng dẫn và kiểm tra hoạt động tự quản của thôn là nhiệm vụ của Chủ tịch UBND xã; ở phường, Chủ tịch UBND phường làm việc này đối với tổ dân phố.","cc":"Khoản 14 Điều 23 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nv-048","cd":"nv","m":1,"l":"kt","q":"Người đứng đầu cơ quan chuyên môn thuộc UBND tỉnh do ai quyết định bổ nhiệm?","a":["Chủ tịch UBND tỉnh","HĐND tỉnh","Thường trực HĐND tỉnh","Thủ tướng Chính phủ"],"why":"Chủ tịch UBND tỉnh quyết định bổ nhiệm, điều động, tạm đình chỉ, cách chức người đứng đầu cơ quan chuyên môn, tổ chức hành chính khác thuộc UBND tỉnh; HĐND tỉnh không bầu chức danh này.","cc":"Khoản 17 Điều 17 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nv-050","cd":"nv","m":1,"l":"kt","q":"Ai là người triệu tập và chủ tọa các phiên họp của UBND tỉnh?","a":["Chủ tịch UBND tỉnh","Chủ tịch HĐND tỉnh","Thường trực HĐND tỉnh","Chánh Văn phòng UBND tỉnh"],"why":"Chủ tịch UBND lãnh đạo, điều hành công việc của UBND, triệu tập và chủ tọa các phiên họp của UBND; đây là nhiệm vụ đầu tiên của Chủ tịch UBND ở cả cấp tỉnh và cấp xã.","cc":"Khoản 1 Điều 17 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nv-002","cd":"nv","m":2,"l":"th","q":"HĐND xã A có những việc làm gây thiệt hại nghiêm trọng đến lợi ích của Nhân dân. Theo Luật Tổ chức chính quyền địa phương số 72/2025/QH15, việc giải tán HĐND xã A được thực hiện thế nào?","a":["HĐND tỉnh giải tán và trình Ủy ban Thường vụ Quốc hội phê chuẩn","Ủy ban Thường vụ Quốc hội trực tiếp giải tán theo đề nghị của UBND tỉnh","HĐND tỉnh giải tán và trình Thủ tướng Chính phủ phê chuẩn","Chủ tịch UBND tỉnh quyết định giải tán và báo cáo HĐND tỉnh"],"why":"HĐND tỉnh là cơ quan giải tán HĐND cấp xã khi HĐND đó làm thiệt hại nghiêm trọng đến lợi ích của Nhân dân, nhưng phải trình Ủy ban Thường vụ Quốc hội phê chuẩn.","cc":"Điểm e khoản 1 Điều 15 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nv-003","cd":"nv","m":2,"l":"kt","q":"HĐND tỉnh được quyết định áp dụng thí điểm các chính sách đặc thù, đặc biệt, chưa được quy định trong pháp luật để thúc đẩy phát triển kinh tế - xã hội trên địa bàn với điều kiện nào về thủ tục?","a":["Sau khi đã báo cáo và được Thủ tướng Chính phủ cho phép","Sau khi được Ủy ban Thường vụ Quốc hội phê chuẩn","Sau khi Quốc hội ban hành nghị quyết cho phép thí điểm","Sau khi lấy ý kiến thống nhất của các bộ, ngành liên quan"],"why":"HĐND tỉnh căn cứ chủ trương của Đảng, quyết định thí điểm chính sách đặc thù phù hợp khả năng cân đối ngân sách địa phương, nhưng chỉ sau khi đã báo cáo và được Thủ tướng Chính phủ cho phép.","cc":"Điểm c khoản 1 Điều 15 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nv-004","cd":"nv","m":2,"l":"kt","q":"Ở tỉnh, tổng biên chế cán bộ, công chức của chính quyền địa phương cấp xã (theo chỉ tiêu biên chế được cấp có thẩm quyền giao) do cơ quan nào quyết định?","a":["HĐND tỉnh","UBND tỉnh","Chủ tịch UBND tỉnh","Thường trực HĐND tỉnh"],"why":"HĐND tỉnh quyết định biên chế của cấp mình và tổng biên chế cán bộ, công chức cấp xã. UBND tỉnh chỉ quản lý biên chế; HĐND xã quyết định cụ thể biên chế của xã mình theo chỉ tiêu được giao.","cc":"Điểm a khoản 2 Điều 15 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nv-005","cd":"nv","m":2,"l":"th","q":"Đầu năm, xã A cần xác định cụ thể biên chế cán bộ, công chức trong các cơ quan của chính quyền xã. Theo Luật Tổ chức chính quyền địa phương số 72/2025/QH15, việc này do ai quyết định và căn cứ vào đâu?","a":["HĐND xã quyết định, căn cứ chỉ tiêu được chính quyền cấp tỉnh giao","UBND xã quyết định, căn cứ chỉ tiêu được chính quyền cấp tỉnh giao","Chủ tịch UBND xã quyết định sau khi báo cáo Chủ tịch UBND tỉnh","HĐND xã tự quyết định theo nhu cầu, không phụ thuộc chỉ tiêu cấp trên"],"why":"HĐND xã quyết định cụ thể biên chế của chính quyền cấp mình trên cơ sở chỉ tiêu được chính quyền địa phương cấp tỉnh giao; UBND xã chỉ quản lý biên chế đó.","cc":"Điểm b khoản 2 Điều 21 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nv-010","cd":"nv","m":2,"l":"kt","q":"Trong các nhiệm vụ, quyền hạn mà Luật Tổ chức chính quyền địa phương số 72/2025/QH15 quy định, việc bầu, miễn nhiệm, bãi nhiệm Hội thẩm nhân dân được giao cho cơ quan nào?","a":["HĐND tỉnh","HĐND xã","Thường trực HĐND tỉnh","UBND tỉnh"],"why":"Điều 15 giao HĐND tỉnh bầu, miễn nhiệm, bãi nhiệm Hội thẩm nhân dân theo quy định của pháp luật; Điều 21 về HĐND xã không có nội dung này.","cc":"Điểm g khoản 2 Điều 15 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nv-014","cd":"nv","m":2,"l":"kt","q":"Việc phân cấp nguồn thu, nhiệm vụ chi giữa ngân sách cấp tỉnh và ngân sách cấp xã thuộc thẩm quyền quyết định của cơ quan nào?","a":["HĐND tỉnh","UBND tỉnh","Chủ tịch UBND tỉnh","HĐND xã đối với ngân sách của xã mình"],"why":"HĐND tỉnh quyết định phân cấp nguồn thu, nhiệm vụ chi giữa ngân sách cấp tỉnh và cấp xã; HĐND xã chỉ quyết định dự toán và phân bổ ngân sách cấp mình.","cc":"Điểm c khoản 3 Điều 15 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nv-017","cd":"nv","m":2,"l":"th","q":"UBND xã A đã lập xong quy hoạch, kế hoạch sử dụng đất của xã. Theo Luật Tổ chức chính quyền địa phương số 72/2025/QH15, bước tiếp theo đúng thẩm quyền là gì?","a":["HĐND xã thông qua trước khi trình UBND cấp tỉnh phê duyệt","HĐND xã quyết định phê duyệt rồi báo cáo UBND cấp tỉnh","UBND xã trình thẳng HĐND cấp tỉnh thông qua và phê duyệt","Chủ tịch UBND xã phê duyệt sau khi lấy ý kiến HĐND xã"],"why":"Với quy hoạch, kế hoạch sử dụng đất của cấp xã, HĐND xã chỉ thông qua; thẩm quyền phê duyệt thuộc UBND cấp tỉnh.","cc":"Điểm a khoản 5 Điều 21 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nv-021","cd":"nv","m":2,"l":"th","q":"Chủ tịch UBND xã A ban hành một quyết định trái pháp luật. Theo Luật Tổ chức chính quyền địa phương số 72/2025/QH15, HĐND xã A có quyền gì đối với quyết định này?","a":["Đình chỉ việc thi hành, bãi bỏ một phần hoặc toàn bộ quyết định đó","Chỉ được đình chỉ thi hành rồi đề nghị HĐND tỉnh bãi bỏ","Chỉ được kiến nghị Chủ tịch UBND tỉnh xem xét, bãi bỏ","Chỉ được chất vấn, không có quyền đình chỉ hay bãi bỏ"],"why":"HĐND xã có quyền đình chỉ việc thi hành, bãi bỏ một phần hoặc toàn bộ văn bản trái pháp luật của UBND, Chủ tịch UBND cùng cấp.","cc":"Điểm d khoản 1 Điều 21 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nv-023","cd":"nv","m":2,"l":"kt","q":"HĐND xã quyết định biện pháp phát triển sự nghiệp giáo dục trên địa bàn đối với những bậc học nào?","a":["Mầm non, tiểu học, trung học cơ sở","Mầm non và tiểu học","Tiểu học, trung học cơ sở, trung học phổ thông","Từ mầm non đến trung học phổ thông"],"why":"HĐND xã quyết định biện pháp phát triển sự nghiệp giáo dục mầm non, tiểu học, trung học cơ sở; trung học phổ thông không thuộc phạm vi này.","cc":"Điểm a khoản 6 Điều 21 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nv-027","cd":"nv","m":2,"l":"th","q":"Xã A muốn có chương trình, biện pháp hỗ trợ phát triển kinh tế hộ gia đình và các cơ sở sản xuất, kinh doanh trên địa bàn xã. Theo Luật Tổ chức chính quyền địa phương số 72/2025/QH15, cơ quan nào của xã quyết định?","a":["HĐND xã A","UBND xã A","Chủ tịch UBND xã A","Thường trực HĐND xã A"],"why":"Quyết định chương trình, biện pháp hỗ trợ phát triển kinh tế hộ gia đình, các cơ sở sản xuất, kinh doanh trên địa bàn là nhiệm vụ của HĐND xã; UBND xã xây dựng, trình và tổ chức thực hiện.","cc":"Điểm đ khoản 3 Điều 21 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nv-028","cd":"nv","m":2,"l":"kt","q":"Đối với việc thành lập, giải thể, nhập, chia, điều chỉnh địa giới và đổi tên đơn vị hành chính cấp xã ở địa phương, HĐND tỉnh có nhiệm vụ, quyền hạn gì?","a":["Xem xét, cho ý kiến về các việc này","Quyết định các việc này bằng nghị quyết","Phê chuẩn đề án do UBND tỉnh xây dựng","Không tham gia, chỉ HĐND cấp xã cho ý kiến"],"why":"HĐND tỉnh chỉ xem xét, cho ý kiến về việc thành lập, giải thể, nhập, chia, điều chỉnh địa giới, đổi tên đơn vị hành chính cấp mình và cấp xã; HĐND tỉnh không phải là cơ quan quyết định.","cc":"Điểm d khoản 2 Điều 15 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nv-031","cd":"nv","m":2,"l":"kt","q":"Nhiệm vụ, quyền hạn nào sau đây thuộc HĐND tỉnh chứ không thuộc UBND tỉnh?","a":["Quyết định cơ chế, chính sách, biện pháp về phí, lệ phí của địa phương","Quyết định số lượng Phó Chủ tịch UBND của từng đơn vị hành chính cấp xã","Quy định chức năng, nhiệm vụ của cơ quan chuyên môn thuộc UBND tỉnh","Quản lý biên chế cán bộ, công chức trong các cơ quan hành chính"],"why":"HĐND tỉnh quyết định cơ chế, chính sách, biện pháp về tài chính, ngân sách, đầu tư, phí, lệ phí. Ba việc còn lại là nhiệm vụ, quyền hạn của UBND tỉnh theo Điều 16.","cc":"Điểm b khoản 3 Điều 15 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nv-033","cd":"nv","m":2,"l":"th","q":"Đặc khu C vừa được công nhận loại đô thị theo quy định của pháp luật. Khi đó, HĐND đặc khu C thực hiện các nhiệm vụ, quyền hạn tương ứng của cơ quan nào?","a":["HĐND phường","HĐND xã","HĐND thành phố","HĐND tỉnh"],"why":"Đặc khu được công nhận loại đô thị thì chính quyền địa phương ở đặc khu thực hiện nhiệm vụ, quyền hạn tương ứng của chính quyền địa phương ở phường (Mục 4 Chương IV).","cc":"Khoản 1 Điều 27 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nv-034","cd":"nv","m":2,"l":"kt","q":"Tại đặc khu có dân số thường trú dưới 1.000 người, việc tổ chức chính quyền địa phương được quy định thế nào?","a":["Không tổ chức cấp chính quyền địa phương; UBND đặc khu do UBND cấp tỉnh thành lập","Vẫn tổ chức HĐND và UBND như ở xã nhưng giảm số lượng đại biểu HĐND","Chỉ tổ chức HĐND đặc khu, không tổ chức UBND đặc khu","Không tổ chức cấp chính quyền địa phương; UBND đặc khu do Thủ tướng thành lập"],"why":"Đặc khu dưới 1.000 dân thường trú không tổ chức cấp chính quyền địa phương (không có HĐND); UBND đặc khu là cơ quan hành chính nhà nước do UBND cấp tỉnh quyết định thành lập.","cc":"Khoản 1 Điều 28 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nv-037","cd":"nv","m":2,"l":"th","q":"Tỉnh cần xác định xã A, phường B mỗi nơi có bao nhiêu Phó Chủ tịch UBND. Theo Luật Tổ chức chính quyền địa phương số 72/2025/QH15, cơ quan nào quyết định số lượng Phó Chủ tịch UBND của từng đơn vị hành chính cấp xã?","a":["UBND tỉnh, trong tổng số tính theo khung của Chính phủ","HĐND tỉnh, trong tổng số tính theo khung của Chính phủ","HĐND của từng xã, phường tự quyết định khi bầu","Thường trực HĐND tỉnh, theo đề nghị của UBND tỉnh"],"why":"UBND tỉnh quyết định số lượng Phó Chủ tịch UBND của từng xã, phường, bảo đảm tổng số Phó Chủ tịch UBND cấp xã của địa phương không vượt quá tổng số tính theo khung quy định của Chính phủ.","cc":"Khoản 8 Điều 16 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nv-038","cd":"nv","m":2,"l":"th","q":"Tỉnh cần thành lập một đơn vị sự nghiệp công lập thuộc UBND tỉnh. Theo Luật Tổ chức chính quyền địa phương số 72/2025/QH15, cơ quan nào quyết định thành lập đơn vị này?","a":["UBND tỉnh","HĐND tỉnh","Thường trực HĐND tỉnh","Thủ tướng Chính phủ"],"why":"Chỗ dễ nhầm: cơ quan chuyên môn thuộc UBND do HĐND cùng cấp quyết định thành lập, còn đơn vị sự nghiệp công lập thuộc UBND thì do chính UBND cấp đó quyết định thành lập, tổ chức lại, giải thể.","cc":"Khoản 6 Điều 16 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nv-039","cd":"nv","m":2,"l":"th","q":"HĐND xã A vừa bầu Chủ tịch UBND xã. Theo Luật Tổ chức chính quyền địa phương số 72/2025/QH15, kết quả bầu này phải được ai phê chuẩn?","a":["Chủ tịch UBND tỉnh","Thường trực HĐND tỉnh","HĐND tỉnh","Chủ tịch HĐND tỉnh"],"why":"Chủ tịch UBND tỉnh phê chuẩn kết quả bầu, miễn nhiệm, bãi nhiệm Chủ tịch, Phó Chủ tịch UBND cấp xã. Thường trực HĐND tỉnh phê chuẩn đối với Chủ tịch, Phó Chủ tịch HĐND cấp xã.","cc":"Khoản 17 Điều 17 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nv-042","cd":"nv","m":2,"l":"th","q":"Xã A đang khuyết Chủ tịch UBND, HĐND xã chưa kịp bầu người mới. Theo Luật Tổ chức chính quyền địa phương số 72/2025/QH15, ai có thẩm quyền giao quyền Chủ tịch UBND xã A?","a":["Chủ tịch UBND tỉnh","Thường trực HĐND xã A","Thường trực HĐND tỉnh","Chủ tịch HĐND xã A"],"why":"Giao quyền Chủ tịch UBND cấp xã là nhiệm vụ, quyền hạn của Chủ tịch UBND tỉnh; Thường trực HĐND xã không tự giao quyền.","cc":"Khoản 17 Điều 17 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nv-044","cd":"nv","m":2,"l":"kt","q":"Khi Chủ tịch UBND xã thay mặt UBND xã quyết định một vấn đề thuộc thẩm quyền của UBND (không thuộc các nội dung UBND phải thảo luận tập thể), Chủ tịch UBND xã có trách nhiệm gì?","a":["Báo cáo UBND tại phiên họp gần nhất","Báo cáo HĐND xã tại kỳ họp gần nhất","Báo cáo Chủ tịch UBND tỉnh trước khi quyết định","Lấy phiếu ý kiến các Ủy viên UBND trước khi ký"],"why":"Chủ tịch UBND được thay mặt UBND cấp mình quyết định những vấn đề thuộc thẩm quyền của UBND, trừ các nội dung UBND phải thảo luận tập thể, và phải báo cáo UBND tại phiên họp gần nhất.","cc":"Khoản 16 Điều 23 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nv-006","cd":"nv","m":3,"l":"kt","q":"Về người hoạt động không chuyên trách hưởng phụ cấp từ ngân sách nhà nước, thẩm quyền được phân định thế nào giữa HĐND tỉnh và HĐND xã?","a":["HĐND tỉnh quyết định mức phụ cấp và tổng số lượng; HĐND xã quyết định cụ thể số lượng trên địa bàn","HĐND tỉnh quyết định tổng số lượng; HĐND xã quyết định mức phụ cấp và số lượng cụ thể trên địa bàn","HĐND xã quyết định cả mức phụ cấp và số lượng trên địa bàn; HĐND tỉnh chỉ giám sát thực hiện","HĐND tỉnh quyết định mức phụ cấp và tổng số lượng; UBND xã quyết định cụ thể số lượng trên địa bàn"],"why":"Mức phụ cấp và tổng số lượng người hoạt động không chuyên trách của địa phương do HĐND tỉnh quyết định; HĐND xã quyết định cụ thể số lượng trên địa bàn mình theo quy định của chính quyền cấp tỉnh.","cc":"Điểm b khoản 2 Điều 15 và điểm d khoản 2 Điều 21 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nv-018","cd":"nv","m":3,"l":"kt","q":"HĐND thành phố thông qua kế hoạch sử dụng đất của thành phố trước khi trình cơ quan có thẩm quyền phê duyệt trong trường hợp nào?","a":["Khi thành phố không phải lập quy hoạch sử dụng đất cấp tỉnh","Khi quy hoạch sử dụng đất cấp tỉnh đã hết thời hạn","Khi được Thủ tướng Chính phủ cho phép thí điểm","Trong mọi trường hợp, cùng với quy hoạch sử dụng đất cấp tỉnh"],"why":"Đây là nhiệm vụ riêng của HĐND thành phố: thông qua kế hoạch sử dụng đất của thành phố đối với trường hợp không phải lập quy hoạch sử dụng đất cấp tỉnh.","cc":"Khoản 3 Điều 18 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nv-019","cd":"nv","m":3,"l":"kt","q":"Ngoài các nhiệm vụ, quyền hạn như HĐND tỉnh, HĐND thành phố còn được Luật Tổ chức chính quyền địa phương số 72/2025/QH15 giao thêm nhiệm vụ, quyền hạn nào sau đây?","a":["Quyết định biện pháp quản lý dân cư ở thành phố và tổ chức đời sống dân cư đô thị","Quyết định bảng giá đất theo quy định của pháp luật về đất đai","Quyết định đặt tên, đổi tên đường, phố, quảng trường, công trình công cộng","Bãi bỏ một phần hoặc toàn bộ văn bản trái pháp luật của HĐND cấp xã"],"why":"Quản lý dân cư và tổ chức đời sống dân cư đô thị là nhiệm vụ riêng có thêm của HĐND thành phố (Điều 18). Ba việc còn lại HĐND tỉnh cũng có theo Điều 15.","cc":"Khoản 4 Điều 18 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nv-020","cd":"nv","m":3,"l":"kt","q":"So với HĐND xã, quy định về đối tượng chịu sự giám sát của HĐND tỉnh nêu thêm những cơ quan nào?","a":["Tòa án nhân dân và Viện kiểm sát nhân dân","Thường trực HĐND và các Ban của HĐND cấp mình","UBND cùng cấp và cơ quan khác ở địa phương","Ủy ban MTTQ Việt Nam và các tổ chức chính trị - xã hội"],"why":"HĐND tỉnh và HĐND xã đều giám sát Thường trực HĐND, các Ban của HĐND cấp mình, UBND cùng cấp và cơ quan khác ở địa phương; riêng HĐND tỉnh còn giám sát Tòa án nhân dân, Viện kiểm sát nhân dân.","cc":"Khoản 9 Điều 15 và khoản 8 Điều 21 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nv-024","cd":"nv","m":3,"l":"kt","q":"So với HĐND xã, HĐND phường có thêm nhiệm vụ, quyền hạn nào sau đây?","a":["Quyết định biện pháp để thực hiện quy hoạch đô thị, phát triển hạ tầng kỹ thuật và hạ tầng xã hội","Thông qua quy hoạch, kế hoạch sử dụng đất của cấp mình trước khi trình UBND cấp tỉnh phê duyệt","Quyết định biện pháp huy động sự đóng góp của Nhân dân để xây dựng công trình công cộng","Quyết định dự toán thu, chi ngân sách địa phương và phân bổ dự toán ngân sách cấp mình"],"why":"Điều 24 giao thêm cho HĐND phường việc quyết định biện pháp thực hiện quy hoạch đô thị, phát triển hạ tầng kỹ thuật, hạ tầng xã hội. Ba việc còn lại HĐND xã và HĐND phường đều có.","cc":"Khoản 1 Điều 24 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nv-025","cd":"nv","m":3,"l":"th","q":"Phường B muốn đề ra các biện pháp khuyến khích phát triển kinh tế đô thị, thương mại, dịch vụ, công nghệ cao phù hợp với đặc điểm đô thị. Theo Luật Tổ chức chính quyền địa phương số 72/2025/QH15, phân công nào đúng?","a":["HĐND phường quyết định các biện pháp; UBND phường tổ chức thực hiện","UBND phường quyết định các biện pháp; HĐND phường giám sát thực hiện","Chủ tịch UBND phường quyết định các biện pháp; UBND phường thực hiện","UBND phường quyết định các biện pháp sau khi xin ý kiến UBND tỉnh"],"why":"Quyết định các biện pháp khuyến khích phát triển kinh tế đô thị là quyền của HĐND phường; UBND phường xây dựng, trình HĐND và tổ chức thực hiện các chính sách khuyến khích đó.","cc":"Khoản 2 Điều 24 và khoản 1, khoản 4 Điều 25 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nv-026","cd":"nv","m":3,"l":"th","q":"Tỉnh dự kiến tổ chức lại hai cơ quan chuyên môn thuộc UBND tỉnh thành một cơ quan mới. Theo Luật Tổ chức chính quyền địa phương số 72/2025/QH15, thẩm quyền được phân định thế nào?","a":["HĐND tỉnh quyết định tổ chức lại; UBND tỉnh quy định chức năng, nhiệm vụ, cơ cấu tổ chức","UBND tỉnh quyết định tổ chức lại; HĐND tỉnh quy định chức năng, nhiệm vụ, cơ cấu tổ chức","Chủ tịch UBND tỉnh quyết định tổ chức lại; UBND tỉnh quy định chức năng, nhiệm vụ","HĐND tỉnh quyết định tổ chức lại và quy định luôn chức năng, nhiệm vụ, cơ cấu tổ chức"],"why":"Thành lập, tổ chức lại, đổi tên, giải thể cơ quan chuyên môn thuộc UBND do HĐND cùng cấp quyết định; còn chức năng, nhiệm vụ, quyền hạn, cơ cấu tổ chức của cơ quan đó do UBND tỉnh quy định.","cc":"Điểm c khoản 2 Điều 15 và khoản 6 Điều 16 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nv-035","cd":"nv","m":3,"l":"kt","q":"Cơ chế, chính sách đặc thù cho chính quyền địa phương ở từng đặc khu để phát triển kinh tế - xã hội, bảo đảm quốc phòng, an ninh do cơ quan nào xem xét, quyết định?","a":["Quốc hội, do chính quyền cấp tỉnh trình Chính phủ để trình","HĐND cấp tỉnh, sau khi được Thủ tướng Chính phủ cho phép","Chính phủ, theo đề nghị của chính quyền cấp tỉnh","Ủy ban Thường vụ Quốc hội, theo đề nghị của HĐND cấp tỉnh"],"why":"Cơ chế, chính sách đặc thù cho từng đặc khu do Quốc hội xem xét, quyết định; chính quyền địa phương cấp tỉnh trình Chính phủ để Chính phủ trình Quốc hội.","cc":"Khoản 4 Điều 27 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nv-040","cd":"nv","m":3,"l":"th","q":"Chủ tịch UBND xã A có vi phạm nghiêm trọng. Có ý kiến đề nghị bãi nhiệm, có ý kiến đề nghị cách chức. Theo Luật Tổ chức chính quyền địa phương số 72/2025/QH15, thẩm quyền đối với hai hình thức này thế nào?","a":["HĐND xã bãi nhiệm; Chủ tịch UBND tỉnh quyết định cách chức","HĐND xã bãi nhiệm và cũng là cơ quan quyết định cách chức","Chủ tịch UBND tỉnh bãi nhiệm; HĐND xã quyết định cách chức","HĐND tỉnh bãi nhiệm; UBND tỉnh quyết định cách chức"],"why":"Bãi nhiệm Chủ tịch UBND xã là quyền của HĐND xã (Chủ tịch UBND tỉnh phê chuẩn kết quả); còn điều động, cách chức Chủ tịch, Phó Chủ tịch UBND cấp xã do Chủ tịch UBND tỉnh quyết định.","cc":"Điểm e khoản 2 Điều 21 và khoản 17 Điều 17 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nv-041","cd":"nv","m":3,"l":"th","q":"Một Phó Chủ tịch UBND xã A cần bị tạm đình chỉ công tác để phục vụ việc xem xét vi phạm. Theo Luật Tổ chức chính quyền địa phương số 72/2025/QH15, ai quyết định tạm đình chỉ công tác đối với người này?","a":["Chủ tịch UBND xã A","Chủ tịch UBND tỉnh","HĐND xã A","Thường trực HĐND xã A"],"why":"Chủ tịch UBND xã quyết định tạm đình chỉ công tác đối với Phó Chủ tịch UBND cấp mình. Chủ tịch UBND tỉnh tạm đình chỉ Phó Chủ tịch UBND tỉnh và Chủ tịch UBND cấp xã.","cc":"Khoản 10 Điều 23 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nv-043","cd":"nv","m":3,"l":"th","q":"Mưa lũ lớn đe dọa tính mạng người dân, Chủ tịch UBND tỉnh quyết định áp dụng một biện pháp cấp bách vượt thẩm quyền. Theo Luật Tổ chức chính quyền địa phương số 72/2025/QH15, sau đó Chủ tịch UBND tỉnh phải làm gì?","a":["Báo cáo cơ quan có thẩm quyền của Đảng và Thủ tướng Chính phủ trong thời gian sớm nhất","Báo cáo HĐND tỉnh tại kỳ họp gần nhất để HĐND tỉnh phê chuẩn","Báo cáo UBND tỉnh tại phiên họp gần nhất để biểu quyết thông qua","Xin ý kiến Thường trực HĐND tỉnh để hợp thức hóa quyết định"],"why":"Trong trường hợp thật cần thiết, Chủ tịch UBND tỉnh được áp dụng biện pháp cấp bách khác quy định của pháp luật hoặc vượt thẩm quyền, sau đó phải báo cáo cơ quan có thẩm quyền của Đảng và Thủ tướng Chính phủ sớm nhất.","cc":"Khoản 14 Điều 17 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nv-047","cd":"nv","m":3,"l":"th","q":"Chủ tịch UBND tỉnh phát hiện một nghị quyết của HĐND xã A trái pháp luật. Theo Luật Tổ chức chính quyền địa phương số 72/2025/QH15, Chủ tịch UBND tỉnh xử lý thế nào?","a":["Đình chỉ thi hành, báo cáo UBND tỉnh để đề nghị HĐND tỉnh bãi bỏ","Đình chỉ thi hành và trực tiếp bãi bỏ một phần hoặc toàn bộ nghị quyết","Đình chỉ thi hành, báo cáo Thủ tướng Chính phủ để đề nghị bãi bỏ","Không được đình chỉ, chỉ kiến nghị HĐND xã A tự sửa đổi, bãi bỏ"],"why":"Với văn bản trái pháp luật của HĐND cấp xã, Chủ tịch UBND tỉnh chỉ được đình chỉ thi hành và báo cáo UBND tỉnh để đề nghị HĐND tỉnh bãi bỏ. Quyền trực tiếp đình chỉ, bãi bỏ (khoản 19 Điều 17) áp dụng với văn bản của cơ quan chuyên môn thuộc UBND tỉnh và của UBND, Chủ tịch UBND cấp xã.","cc":"Khoản 20 Điều 17 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"nv-049","cd":"nv","m":3,"l":"kt","q":"Ngoài các nhiệm vụ, quyền hạn như Chủ tịch UBND tỉnh, Chủ tịch UBND thành phố còn có thêm nhiệm vụ, quyền hạn nào sau đây?","a":["Chỉ đạo việc tổ chức thực hiện chính sách dân cư, quản lý nhập cư trên địa bàn thành phố","Phê chuẩn kết quả bầu, miễn nhiệm, bãi nhiệm Chủ tịch, Phó Chủ tịch UBND cấp xã","Chỉ đạo, tổ chức thực hiện các nhiệm vụ về đối ngoại theo quy định của pháp luật","Quản lý các khu công nghiệp, khu kinh tế của địa phương theo quy định của pháp luật"],"why":"Điều 20 giao thêm cho Chủ tịch UBND thành phố việc chỉ đạo thực hiện chính sách dân cư, quản lý nhập cư, quản lý lao động trên địa bàn thành phố. Ba việc còn lại Chủ tịch UBND tỉnh cũng có theo Điều 17.","cc":"Khoản 3 Điều 20 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"kht-001","cd":"kh","m":1,"l":"kt","q":"Theo Quy chế làm việc mẫu, HĐND cấp tỉnh họp mỗi năm ít nhất mấy kỳ?","a":["02 kỳ","01 kỳ","03 kỳ","04 kỳ"],"why":"HĐND cấp tỉnh họp mỗi năm ít nhất 02 kỳ; ngoài ra có thể họp chuyên đề hoặc họp để giải quyết công việc phát sinh đột xuất khi có yêu cầu.","cc":"Khoản 1 Điều 4 Quy chế làm việc mẫu của HĐND cấp tỉnh (kèm Nghị quyết 103/2025/UBTVQH15)"},{"id":"kht-005","cd":"kh","m":1,"l":"kt","q":"Kỳ họp thứ nhất của HĐND cấp tỉnh khóa mới phải được tổ chức chậm nhất bao nhiêu ngày kể từ ngày bầu cử đại biểu HĐND?","a":["45 ngày","30 ngày","60 ngày","90 ngày"],"why":"Kỳ họp thứ nhất của HĐND khóa mới được tổ chức chậm nhất là 45 ngày kể từ ngày bầu cử đại biểu HĐND.","cc":"Khoản 1 Điều 6 Quy chế làm việc mẫu của HĐND cấp tỉnh (kèm Nghị quyết 103/2025/UBTVQH15)"},{"id":"kht-008","cd":"kh","m":1,"l":"kt","q":"Kỳ họp thứ nhất của mỗi khóa HĐND cấp tỉnh do ai triệu tập (khi không khuyết Thường trực HĐND)?","a":["Thường trực HĐND khóa trước","Ủy ban bầu cử cấp tỉnh","Chủ tịch UBND cấp tỉnh khóa trước","Ban Thường trực Ủy ban MTTQ Việt Nam cấp tỉnh"],"why":"Kỳ họp thứ nhất của mỗi khóa HĐND do Thường trực HĐND khóa trước triệu tập; chỉ khi khuyết Thường trực HĐND mới có triệu tập viên được chỉ định.","cc":"Khoản 2 Điều 6 Quy chế làm việc mẫu của HĐND cấp tỉnh (kèm Nghị quyết 103/2025/UBTVQH15)"},{"id":"kht-011","cd":"kh","m":1,"l":"kt","q":"Chương trình kỳ họp HĐND cấp tỉnh (do Thường trực HĐND dự kiến và trình) được thông qua bằng cách nào?","a":["HĐND biểu quyết thông qua tại kỳ họp","Thường trực HĐND quyết định trước ngày khai mạc","Chủ tọa kỳ họp quyết định sau khi nghe thảo luận","Chủ tịch HĐND thống nhất với Chủ tịch UBND rồi ban hành"],"why":"Thường trực HĐND chỉ trình dự kiến chương trình; sau khi đại biểu thảo luận và Chủ tọa kết luận, HĐND biểu quyết thông qua chương trình kỳ họp.","cc":"Khoản 4 Điều 7 Quy chế làm việc mẫu của HĐND cấp tỉnh (kèm Nghị quyết 103/2025/UBTVQH15)"},{"id":"kht-015","cd":"kh","m":1,"l":"kt","q":"Khi thực hiện nhiệm vụ, quyền hạn với tư cách đại biểu HĐND cấp tỉnh, Quy chế làm việc mẫu yêu cầu đại biểu thế nào về huy hiệu và trang phục?","a":["Đeo huy hiệu, mặc trang phục lịch sự, trang trọng","Mặc lễ phục thống nhất do HĐND cấp phát","Đeo thẻ công chức, mặc đồng phục cơ quan công tác","Không quy định, tùy đại biểu lựa chọn"],"why":"Đại biểu HĐND cấp tỉnh có trách nhiệm đeo huy hiệu, mặc trang phục lịch sự, trang trọng khi thực hiện nhiệm vụ, quyền hạn với tư cách đại biểu.","cc":"Khoản 3 Điều 9 Quy chế làm việc mẫu của HĐND cấp tỉnh (kèm Nghị quyết 103/2025/UBTVQH15)"},{"id":"kht-017","cd":"kh","m":1,"l":"kt","q":"Công tác thư ký kỳ họp HĐND cấp tỉnh do cơ quan, bộ phận nào tổ chức thực hiện?","a":["Văn phòng Đoàn ĐBQH và HĐND hoặc bộ phận được Thường trực HĐND phân công","Văn phòng UBND cấp tỉnh hoặc bộ phận được Chủ tịch UBND phân công","Ban Pháp chế của HĐND hoặc bộ phận được Trưởng Ban phân công","Đoàn thư ký kỳ họp do HĐND bầu tại phiên khai mạc"],"why":"Văn phòng Đoàn ĐBQH và HĐND hoặc bộ phận được Thường trực HĐND phân công tổ chức công tác thư ký: lập danh sách đại biểu có mặt, ghi biên bản, tổng hợp ý kiến, giúp Chủ tọa về quy trình.","cc":"Điều 11 Quy chế làm việc mẫu của HĐND cấp tỉnh (kèm Nghị quyết 103/2025/UBTVQH15)"},{"id":"kht-021","cd":"kh","m":1,"l":"kt","q":"Trước phiên khai mạc, HĐND cấp tỉnh có thể tổ chức phiên họp nào để xem xét, thông qua chương trình kỳ họp và một số nội dung khác theo đề nghị của Thường trực HĐND?","a":["Phiên trù bị","Phiên họp Tổ thảo luận","Phiên họp Thường trực HĐND mở rộng","Phiên họp toàn thể các Ban của HĐND"],"why":"Trước phiên khai mạc, HĐND tổ chức họp phiên trù bị (nếu có) để xem xét, thông qua chương trình kỳ họp và một số nội dung khác theo đề nghị của Thường trực HĐND.","cc":"Khoản 2 Điều 14 Quy chế làm việc mẫu của HĐND cấp tỉnh (kèm Nghị quyết 103/2025/UBTVQH15)"},{"id":"kht-023","cd":"kh","m":1,"l":"kt","q":"HĐND cấp tỉnh bầu Chủ tịch HĐND, Phó Chủ tịch HĐND, Trưởng Ban của HĐND bằng hình thức nào?","a":["Bỏ phiếu kín","Biểu quyết giơ tay","Biểu quyết công khai bằng hệ thống điện tử","Lấy ý kiến đại biểu bằng văn bản"],"why":"HĐND bầu Chủ tịch HĐND, Phó Chủ tịch HĐND, Trưởng Ban của HĐND bằng hình thức bỏ phiếu kín; Ban kiểm phiếu báo cáo kết quả kiểm phiếu.","cc":"Điểm e khoản 1 Điều 16 Quy chế làm việc mẫu của HĐND cấp tỉnh (kèm Nghị quyết 103/2025/UBTVQH15)"},{"id":"kht-025","cd":"kh","m":1,"l":"kt","q":"Theo Quy chế làm việc mẫu, ai giới thiệu nhân sự dự kiến giữ chức vụ Chủ tịch UBND để HĐND cấp tỉnh bầu?","a":["Chủ tịch HĐND","Chủ tịch UBND đương nhiệm","Ban Thường trực Ủy ban MTTQ Việt Nam cấp tỉnh","Trưởng Ban Pháp chế của HĐND"],"why":"Nhân sự dự kiến giữ chức vụ Chủ tịch UBND do Chủ tịch HĐND giới thiệu để HĐND bầu (thống nhất với khoản 2 Điều 36 Luật 72/2025/QH15); các chức danh của HĐND do Thường trực HĐND giới thiệu. Lưu ý: theo Luật, Phó Chủ tịch UBND, Ủy viên UBND do Chủ tịch UBND giới thiệu.","cc":"Điểm a khoản 2 Điều 16 Quy chế làm việc mẫu của HĐND cấp tỉnh (kèm Nghị quyết 103/2025/UBTVQH15); khoản 2 Điều 36 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"kht-026","cd":"kh","m":1,"l":"kt","q":"Cơ quan nào trình danh sách để HĐND cấp tỉnh bầu Hội thẩm nhân dân?","a":["Ủy ban MTTQ Việt Nam","Tòa án nhân dân cấp tỉnh","Viện kiểm sát nhân dân cấp tỉnh","Ban Pháp chế của HĐND"],"why":"Danh sách để HĐND bầu Hội thẩm nhân dân do Ủy ban MTTQ Việt Nam trình, không phải Tòa án hay Viện kiểm sát; việc bầu thực hiện tương tự bầu các chức danh của HĐND.","cc":"Điểm a khoản 3 Điều 16 Quy chế làm việc mẫu của HĐND cấp tỉnh (kèm Nghị quyết 103/2025/UBTVQH15)"},{"id":"kht-034","cd":"kh","m":1,"l":"kt","q":"Theo Quy chế làm việc mẫu, các phiên họp của HĐND cấp tỉnh (trừ trường hợp do HĐND quyết định) được thông tin đến Nhân dân bằng cách nào?","a":["Phát thanh, truyền hình trực tiếp theo chương trình kỳ họp đã thông qua","Chỉ đăng biên bản trên trang thông tin điện tử sau kỳ họp","Chỉ thông báo kết quả tại hội nghị tiếp xúc cử tri sau kỳ họp","Chỉ phát lại bản ghi hình sau khi Thường trực HĐND duyệt"],"why":"Các phiên họp của HĐND được phát thanh, truyền hình trực tiếp theo chương trình kỳ họp đã được HĐND thông qua, trừ trường hợp do HĐND quyết định.","cc":"Khoản 3 Điều 19 Quy chế làm việc mẫu của HĐND cấp tỉnh (kèm Nghị quyết 103/2025/UBTVQH15)"},{"id":"kht-035","cd":"kh","m":1,"l":"kt","q":"Theo Quy chế làm việc mẫu, Thường trực HĐND cấp tỉnh họp thường kỳ bao lâu một lần?","a":["Mỗi tháng 01 lần","Mỗi tuần 01 lần","Mỗi quý 01 lần","Hai tháng 01 lần"],"why":"Thường trực HĐND họp thường kỳ mỗi tháng 01 lần; khi cần thiết thì họp đột xuất theo đề nghị của Chủ tịch HĐND.","cc":"Khoản 1 Điều 20 Quy chế làm việc mẫu của HĐND cấp tỉnh (kèm Nghị quyết 103/2025/UBTVQH15)"},{"id":"kht-039","cd":"kh","m":1,"l":"kt","q":"Ai quyết định thời gian, chương trình, nội dung, thành phần, triệu tập và chủ tọa phiên họp Thường trực HĐND cấp tỉnh?","a":["Chủ tịch HĐND","Chủ tịch UBND cấp tỉnh","Chánh Văn phòng Đoàn ĐBQH và HĐND","Trưởng Ban Pháp chế của HĐND"],"why":"Chủ tịch HĐND quyết định về thời gian, chương trình, nội dung, hình thức họp, thành phần họp, triệu tập và chủ tọa phiên họp Thường trực HĐND.","cc":"Khoản 1 Điều 21 Quy chế làm việc mẫu của HĐND cấp tỉnh (kèm Nghị quyết 103/2025/UBTVQH15)"},{"id":"kht-044","cd":"kh","m":1,"l":"kt","q":"Theo Quy chế làm việc mẫu, tổ chức nào của HĐND cấp tỉnh có trách nhiệm tổ chức cho đại biểu HĐND tiếp xúc cử tri, tổng hợp ý kiến, kiến nghị của cử tri trước kỳ họp HĐND?","a":["Tổ đại biểu HĐND","Tổ thảo luận tại kỳ họp","Ban Pháp chế của HĐND","Bộ phận thư ký kỳ họp"],"why":"Tổ đại biểu HĐND có trách nhiệm tổ chức cho đại biểu tiếp xúc cử tri, tổng hợp ý kiến, kiến nghị của cử tri trước kỳ họp; Tổ thảo luận chỉ được lập để thảo luận tại kỳ họp.","cc":"Khoản 3 Điều 31 Quy chế làm việc mẫu của HĐND cấp tỉnh (kèm Nghị quyết 103/2025/UBTVQH15)"},{"id":"kht-045","cd":"kh","m":1,"l":"kt","q":"Theo Nghị quyết 103/2025/UBTVQH15, trên cơ sở Quy chế làm việc mẫu, HĐND cấp tỉnh phải làm gì?","a":["Ban hành Quy chế làm việc của cấp mình phù hợp với Quy chế mẫu và thực tế địa phương","Áp dụng nguyên văn Quy chế mẫu, không được ban hành quy chế riêng","Đề nghị UBND cấp tỉnh ban hành Quy chế làm việc của HĐND","Trình Ủy ban Thường vụ Quốc hội phê chuẩn quy chế riêng trước khi áp dụng"],"why":"HĐND cấp tỉnh tự ban hành Quy chế làm việc của cấp mình, phù hợp với Quy chế mẫu, quy định pháp luật có liên quan và điều kiện thực tế của địa phương.","cc":"Điều 2 Nghị quyết 103/2025/UBTVQH15"},{"id":"khx-001","cd":"kh","m":1,"l":"kt","q":"Quy chế làm việc mẫu ban hành kèm theo Nghị quyết 104/2025/UBTVQH15 áp dụng cho HĐND ở những đơn vị hành chính nào (gọi chung là cấp xã)?","a":["Xã, phường, đặc khu","Xã, phường, thị trấn","Xã, phường, thị xã","Huyện, quận, xã, phường"],"why":"Quy chế mẫu kèm Nghị quyết 104/2025/UBTVQH15 áp dụng cho HĐND xã, phường, đặc khu (gọi chung là cấp xã); thị trấn, thị xã, huyện, quận không thuộc phạm vi này.","cc":"Điều 1 Nghị quyết 104/2025/UBTVQH15"},{"id":"khx-002","cd":"kh","m":1,"l":"kt","q":"Theo Quy chế làm việc mẫu, HĐND cấp xã hoạt động theo chế độ nào?","a":["Chế độ tập thể, quyết định theo đa số","Chế độ thủ trưởng, Chủ tịch HĐND quyết định","Chế độ tập thể, quyết định khi mọi đại biểu đều đồng thuận","Chế độ hội nghị, Thường trực HĐND quyết định"],"why":"HĐND hoạt động theo chế độ tập thể, quyết định theo đa số; các đại biểu bình đẳng trong thảo luận và quyết định các vấn đề thuộc nhiệm vụ, quyền hạn của HĐND.","cc":"Khoản 2 Điều 2 Quy chế làm việc mẫu của HĐND cấp xã (kèm Nghị quyết 104/2025/UBTVQH15)"},{"id":"khx-003","cd":"kh","m":1,"l":"kt","q":"Theo Quy chế làm việc mẫu, HĐND cấp xã họp mỗi năm ít nhất bao nhiêu kỳ?","a":["02 kỳ","01 kỳ","03 kỳ","04 kỳ"],"why":"HĐND cấp xã họp mỗi năm ít nhất 02 kỳ; ngoài ra có thể họp chuyên đề hoặc họp để giải quyết công việc phát sinh đột xuất khi có yêu cầu.","cc":"Khoản 1 Điều 4 Quy chế làm việc mẫu của HĐND cấp xã (kèm Nghị quyết 104/2025/UBTVQH15)"},{"id":"khx-007","cd":"kh","m":1,"l":"kt","q":"Khi chuẩn bị kỳ họp HĐND cấp xã, ai phân công các Ban của HĐND thẩm tra các nội dung trình kỳ họp?","a":["Thường trực HĐND cấp xã","Chủ tịch UBND cấp xã","Chánh Văn phòng HĐND và UBND","Thường trực HĐND cấp tỉnh"],"why":"Thường trực HĐND ban hành thông báo dự kiến thời gian, nội dung, chương trình kỳ họp, kế hoạch tiếp xúc cử tri và phân công các Ban thẩm tra nội dung trình kỳ họp theo lĩnh vực phụ trách.","cc":"Khoản 4 Điều 5 Quy chế làm việc mẫu của HĐND cấp xã (kèm Nghị quyết 104/2025/UBTVQH15)"},{"id":"khx-011","cd":"kh","m":1,"l":"kt","q":"Trong trường hợp thông thường, kỳ họp thứ nhất của mỗi khóa HĐND cấp xã do ai triệu tập?","a":["Thường trực HĐND cấp xã khóa trước","Chủ tịch UBND cấp xã khóa trước","Ủy ban bầu cử ở cấp xã","Thường trực HĐND cấp tỉnh"],"why":"Kỳ họp thứ nhất của mỗi khóa HĐND do Thường trực HĐND khóa trước triệu tập; chỉ khi khuyết Thường trực HĐND cấp xã thì Thường trực HĐND cấp tỉnh mới chỉ định triệu tập viên.","cc":"Khoản 2 Điều 6 Quy chế làm việc mẫu của HĐND cấp xã (kèm Nghị quyết 104/2025/UBTVQH15)"},{"id":"khx-016","cd":"kh","m":1,"l":"kt","q":"Theo Quy chế làm việc mẫu, khi thực hiện nhiệm vụ, quyền hạn với tư cách đại biểu, đại biểu HĐND cấp xã có trách nhiệm gì về huy hiệu và trang phục?","a":["Đeo huy hiệu, mặc trang phục lịch sự, trang trọng","Đeo thẻ công chức, mặc đồng phục công sở","Mặc lễ phục thống nhất do HĐND cấp tỉnh quy định","Chỉ đeo huy hiệu tại phiên khai mạc và phiên bế mạc"],"why":"Đại biểu HĐND có trách nhiệm đeo huy hiệu, mặc trang phục lịch sự, trang trọng khi thực hiện nhiệm vụ, quyền hạn với tư cách là đại biểu HĐND, không chỉ riêng tại phiên khai mạc, bế mạc.","cc":"Khoản 3 Điều 9 Quy chế làm việc mẫu của HĐND cấp xã (kèm Nghị quyết 104/2025/UBTVQH15)"},{"id":"khx-017","cd":"kh","m":1,"l":"kt","q":"Theo Quy chế làm việc mẫu, cơ quan nào có trách nhiệm tổ chức thực hiện công tác thư ký kỳ họp HĐND cấp xã (lập danh sách đại biểu có mặt, vắng mặt, ghi biên bản kỳ họp...)?","a":["Văn phòng HĐND và UBND","Ban Văn hóa - Xã hội của HĐND","Đoàn thư ký do HĐND bầu tại kỳ họp","Tổ thảo luận do Thường trực HĐND thành lập"],"why":"Văn phòng HĐND và UBND cấp xã tổ chức thực hiện công tác thư ký kỳ họp: lập danh sách đại biểu có mặt, vắng mặt, ghi biên bản, tổng hợp ý kiến đại biểu, giúp Chủ tọa về quy trình, thủ tục.","cc":"Điều 11 Quy chế làm việc mẫu của HĐND cấp xã (kèm Nghị quyết 104/2025/UBTVQH15)"},{"id":"khx-021","cd":"kh","m":1,"l":"kt","q":"Tại kỳ họp thứ nhất của mỗi khóa HĐND cấp xã, ai chủ tọa các phiên họp cho đến khi HĐND bầu được Chủ tịch HĐND khóa mới?","a":["Chủ tịch HĐND khóa trước hoặc triệu tập viên","Chủ tịch UBND cấp xã khóa trước","Đại biểu HĐND cao tuổi nhất có mặt","Chủ tịch Ủy ban bầu cử ở cấp xã"],"why":"Tại kỳ họp thứ nhất của mỗi khóa, Chủ tịch HĐND khóa trước hoặc triệu tập viên chủ tọa các phiên họp cho đến khi HĐND bầu được Chủ tịch HĐND khóa mới.","cc":"Khoản 1 Điều 14 Quy chế làm việc mẫu của HĐND cấp xã (kèm Nghị quyết 104/2025/UBTVQH15)"},{"id":"khx-023","cd":"kh","m":1,"l":"kt","q":"HĐND cấp xã bầu Chủ tịch HĐND, Phó Chủ tịch HĐND, Trưởng Ban của HĐND bằng hình thức nào?","a":["Bỏ phiếu kín","Biểu quyết giơ tay công khai","Biểu quyết công khai bằng hệ thống điện tử","Lấy ý kiến đại biểu bằng văn bản"],"why":"Các chức danh Chủ tịch HĐND, Phó Chủ tịch HĐND, Trưởng Ban của HĐND được bầu bằng hình thức bỏ phiếu kín; HĐND bầu Ban kiểm phiếu để thực hiện việc kiểm phiếu.","cc":"Điểm e khoản 1 Điều 16 Quy chế làm việc mẫu của HĐND cấp xã (kèm Nghị quyết 104/2025/UBTVQH15)"},{"id":"khx-028","cd":"kh","m":1,"l":"kt","q":"Theo Quy chế làm việc mẫu, Thường trực HĐND cấp xã họp thường kỳ với tần suất nào?","a":["Mỗi tháng 01 lần","Mỗi quý 01 lần","Mỗi tháng 02 lần","Mỗi tuần 01 lần"],"why":"Thường trực HĐND cấp xã họp thường kỳ mỗi tháng 01 lần; khi cần thiết có thể họp đột xuất theo đề nghị của Chủ tịch HĐND.","cc":"Khoản 1 Điều 19 Quy chế làm việc mẫu của HĐND cấp xã (kèm Nghị quyết 104/2025/UBTVQH15)"},{"id":"khx-038","cd":"kh","m":1,"l":"kt","q":"Theo Quy chế làm việc mẫu, nhiệm vụ nào sau đây thuộc trách nhiệm của Tổ đại biểu HĐND cấp xã?","a":["Tổ chức cho đại biểu tiếp xúc cử tri, tổng hợp ý kiến, kiến nghị cử tri trước kỳ họp","Trực tiếp giải quyết khiếu nại, tố cáo của cử tri thay UBND cấp xã","Thẩm tra dự thảo nghị quyết, đề án, báo cáo trước khi trình HĐND tại kỳ họp","Quyết định triệu tập kỳ họp chuyên đề của HĐND khi cử tri có kiến nghị"],"why":"Tổ đại biểu HĐND tổ chức cho đại biểu tiếp xúc cử tri, tổng hợp ý kiến, kiến nghị của cử tri trước kỳ họp. Thẩm tra là việc của các Ban; quyết định tổ chức kỳ họp chuyên đề thuộc Thường trực HĐND.","cc":"Khoản 3 Điều 30 Quy chế làm việc mẫu của HĐND cấp xã (kèm Nghị quyết 104/2025/UBTVQH15)"},{"id":"kht-002","cd":"kh","m":2,"l":"kt","q":"Ở các năm tiếp theo của nhiệm kỳ (không phải năm bắt đầu nhiệm kỳ), HĐND cấp tỉnh quyết định kế hoạch tổ chức các kỳ họp thường lệ vào thời điểm nào?","a":["Tại kỳ họp cuối cùng của năm trước đó","Tại kỳ họp thường lệ đầu tiên của chính năm đó","Tại kỳ họp giữa năm của năm trước đó","Tại phiên họp Thường trực HĐND đầu năm"],"why":"Năm bắt đầu nhiệm kỳ thì quyết định tại kỳ họp thứ nhất; các năm tiếp theo thì quyết định tại kỳ họp cuối cùng của năm trước đó, theo đề nghị của Thường trực HĐND.","cc":"Khoản 1 Điều 4 Quy chế làm việc mẫu của HĐND cấp tỉnh (kèm Nghị quyết 103/2025/UBTVQH15)"},{"id":"kht-004","cd":"kh","m":2,"l":"th","q":"Giữa hai kỳ họp thường lệ, Chủ tịch UBND tỉnh có văn bản yêu cầu HĐND tỉnh họp để giải quyết công việc phát sinh đột xuất về điều chỉnh kế hoạch đầu tư công. Theo Quy chế làm việc mẫu của HĐND cấp tỉnh, ai quyết định việc tổ chức kỳ họp này?","a":["Thường trực HĐND tỉnh","Chủ tịch UBND tỉnh","Ban Kinh tế - Ngân sách của HĐND tỉnh","Chánh Văn phòng Đoàn ĐBQH và HĐND tỉnh"],"why":"Chủ tịch UBND cùng cấp có quyền yêu cầu HĐND họp chuyên đề hoặc họp giải quyết công việc đột xuất, nhưng việc tổ chức kỳ họp này do Thường trực HĐND quyết định.","cc":"Khoản 2 Điều 4 và khoản 1 Điều 6 Quy chế làm việc mẫu của HĐND cấp tỉnh (kèm Nghị quyết 103/2025/UBTVQH15)"},{"id":"kht-006","cd":"kh","m":2,"l":"th","q":"Bầu cử đại biểu HĐND tỉnh diễn ra ngày 15/3. Do một số đơn vị bầu cử chưa bầu đủ số đại biểu, tỉnh tổ chức bầu cử thêm vào ngày 29/3. Theo Quy chế làm việc mẫu của HĐND cấp tỉnh, thời hạn tổ chức kỳ họp thứ nhất của HĐND tỉnh khóa mới được tính từ ngày nào?","a":["Từ ngày bầu cử thêm (29/3)","Từ ngày bầu cử đầu tiên (15/3)","Từ ngày công bố kết quả bầu cử thêm","Từ ngày xác nhận tư cách đại biểu HĐND"],"why":"Địa phương có bầu cử lại, bầu cử thêm hoặc lùi ngày bầu cử thì thời hạn tổ chức kỳ họp thứ nhất (chậm nhất 45 ngày) được tính từ ngày bầu cử lại, bầu cử thêm hoặc ngày bầu cử mới.","cc":"Khoản 1 Điều 6 Quy chế làm việc mẫu của HĐND cấp tỉnh (kèm Nghị quyết 103/2025/UBTVQH15)"},{"id":"kht-007","cd":"kh","m":2,"l":"kt","q":"Trong nhiệm kỳ, Thường trực HĐND cấp tỉnh phải quyết định tổ chức kỳ họp thường lệ chậm nhất bao nhiêu ngày trước ngày khai mạc kỳ họp?","a":["20 ngày","10 ngày","15 ngày","30 ngày"],"why":"Quyết định tổ chức kỳ họp thường lệ phải có chậm nhất 20 ngày trước ngày khai mạc; đừng nhầm với hạn 15 ngày gửi tài liệu kỳ họp đến đại biểu.","cc":"Khoản 1 Điều 6 Quy chế làm việc mẫu của HĐND cấp tỉnh (kèm Nghị quyết 103/2025/UBTVQH15)"},{"id":"kht-009","cd":"kh","m":2,"l":"kt","q":"Trường hợp khuyết Thường trực HĐND cấp tỉnh, cơ quan nào chỉ định triệu tập viên để triệu tập và chủ tọa kỳ họp thứ nhất của HĐND cấp tỉnh khóa mới?","a":["Ủy ban Thường vụ Quốc hội","Thủ tướng Chính phủ","Hội đồng bầu cử quốc gia","Ủy ban bầu cử cấp tỉnh"],"why":"Với HĐND cấp tỉnh, khi khuyết Thường trực HĐND thì Ủy ban Thường vụ Quốc hội chỉ định triệu tập viên để triệu tập và chủ tọa kỳ họp.","cc":"Khoản 2 Điều 6 Quy chế làm việc mẫu của HĐND cấp tỉnh (kèm Nghị quyết 103/2025/UBTVQH15)"},{"id":"kht-010","cd":"kh","m":2,"l":"kt","q":"Dự kiến chương trình kỳ họp HĐND cấp tỉnh được gửi đến đại biểu HĐND cùng với văn bản nào?","a":["Quyết định triệu tập kỳ họp","Báo cáo thẩm tra của các Ban của HĐND","Thông báo kết luận phiên họp Thường trực HĐND","Kế hoạch tiếp xúc cử tri trước kỳ họp"],"why":"Dự kiến chương trình kỳ họp được gửi đến đại biểu HĐND cùng với quyết định triệu tập kỳ họp để đại biểu chủ động nghiên cứu, sắp xếp công việc.","cc":"Khoản 3 Điều 6 Quy chế làm việc mẫu của HĐND cấp tỉnh (kèm Nghị quyết 103/2025/UBTVQH15)"},{"id":"kht-012","cd":"kh","m":2,"l":"th","q":"Chủ tịch HĐND tỉnh được điều động nhận công tác khác; HĐND tỉnh chưa bầu được Chủ tịch mới thì đến kỳ họp thường lệ. Thường trực HĐND tỉnh vẫn còn các Phó Chủ tịch và Ủy viên. Theo Quy chế làm việc mẫu của HĐND cấp tỉnh, ai chủ tọa kỳ họp?","a":["Một Phó Chủ tịch HĐND do Thường trực HĐND phân công","Phó Chủ tịch HĐND cao tuổi nhất, không cần phân công","Triệu tập viên do Ủy ban Thường vụ Quốc hội chỉ định","Trưởng Ban Pháp chế của HĐND tỉnh"],"why":"Khuyết Chủ tịch HĐND thì Thường trực HĐND phân công một Phó Chủ tịch HĐND chủ tọa kỳ họp; chỉ khi khuyết cả Thường trực HĐND thì Ủy ban Thường vụ Quốc hội mới chỉ định Chủ tọa.","cc":"Khoản 1 Điều 8 Quy chế làm việc mẫu của HĐND cấp tỉnh (kèm Nghị quyết 103/2025/UBTVQH15)"},{"id":"kht-013","cd":"kh","m":2,"l":"kt","q":"Tại kỳ họp thứ nhất của mỗi khóa HĐND cấp tỉnh, Chủ tịch HĐND khóa trước hoặc triệu tập viên làm Chủ tọa các phiên họp cho đến khi nào?","a":["Đến khi HĐND bầu được Chủ tịch HĐND khóa mới","Đến khi bế mạc kỳ họp thứ nhất","Đến khi HĐND bầu xong Chủ tịch UBND khóa mới","Đến khi HĐND thông qua chương trình kỳ họp"],"why":"Chủ tịch HĐND khóa trước hoặc triệu tập viên chỉ chủ tọa cho đến khi HĐND bầu được Chủ tịch HĐND khóa mới; sau đó Chủ tịch mới điều hành.","cc":"Khoản 1 Điều 14 Quy chế làm việc mẫu của HĐND cấp tỉnh (kèm Nghị quyết 103/2025/UBTVQH15)"},{"id":"kht-014","cd":"kh","m":2,"l":"th","q":"Một đại biểu HĐND tỉnh có lịch công tác trùng với một phiên họp của kỳ họp HĐND tỉnh nên không thể tham dự (không thuộc trường hợp bất khả kháng). Theo Quy chế làm việc mẫu của HĐND cấp tỉnh, đại biểu phải làm gì?","a":["Báo cáo trước với Chủ tọa, đồng thời thông tin cho Văn phòng Đoàn ĐBQH và HĐND","Báo cáo trước với Tổ trưởng Tổ đại biểu, đồng thời thông tin cho Ban Pháp chế","Gửi đơn xin phép đến Chủ tịch UBND tỉnh trước ngày khai mạc kỳ họp","Giải trình bằng văn bản với Thường trực HĐND sau khi kỳ họp bế mạc"],"why":"Đại biểu vắng mặt phải có lý do và báo cáo trước với Chủ tọa kỳ họp, phiên họp, đồng thời thông tin cho Văn phòng Đoàn ĐBQH và HĐND, trừ trường hợp bất khả kháng.","cc":"Khoản 1 Điều 9 Quy chế làm việc mẫu của HĐND cấp tỉnh (kèm Nghị quyết 103/2025/UBTVQH15)"},{"id":"kht-018","cd":"kh","m":2,"l":"kt","q":"Tài liệu phục vụ kỳ họp thường lệ (gửi qua Văn phòng Đoàn ĐBQH và HĐND) phải đến đại biểu HĐND cấp tỉnh chậm nhất bao nhiêu ngày trước ngày khai mạc kỳ họp?","a":["15 ngày","05 ngày","07 ngày","10 ngày"],"why":"Tài liệu kỳ họp thường lệ được gửi qua Văn phòng Đoàn ĐBQH và HĐND để đến đại biểu HĐND cấp tỉnh chậm nhất là 15 ngày trước ngày khai mạc kỳ họp.","cc":"Khoản 1 Điều 12 Quy chế làm việc mẫu của HĐND cấp tỉnh (kèm Nghị quyết 103/2025/UBTVQH15)"},{"id":"kht-020","cd":"kh","m":2,"l":"kt","q":"Ai quyết định tổ chức kỳ họp HĐND cấp tỉnh theo hình thức trực tiếp, trực tuyến hoặc kết hợp giữa họp trực tiếp với trực tuyến?","a":["HĐND quyết định, theo đề nghị của Thường trực HĐND","Thường trực HĐND quyết định, theo đề nghị của UBND cấp tỉnh","Chủ tịch HĐND quyết định, sau khi thống nhất với Chủ tịch UBND","Chủ tọa kỳ họp quyết định, theo đề nghị của bộ phận thư ký"],"why":"Hình thức tiến hành kỳ họp (trực tiếp, kể cả họp kín; trực tuyến; hoặc kết hợp) do chính HĐND xem xét, quyết định theo đề nghị của Thường trực HĐND.","cc":"Điều 13 Quy chế làm việc mẫu của HĐND cấp tỉnh (kèm Nghị quyết 103/2025/UBTVQH15)"},{"id":"kht-024","cd":"kh","m":2,"l":"kt","q":"Ban kiểm phiếu thực hiện nhiệm vụ kiểm phiếu tại kỳ họp HĐND cấp tỉnh (khi bầu các chức danh) được hình thành như thế nào?","a":["HĐND bầu theo sự giới thiệu của Chủ tọa kỳ họp","Thường trực HĐND chỉ định trước kỳ họp","Chủ tọa kỳ họp chỉ định, không cần HĐND bầu","HĐND bầu theo sự giới thiệu của Ban Pháp chế"],"why":"Ban kiểm phiếu do HĐND bầu theo sự giới thiệu của Chủ tọa kỳ họp, thực hiện kiểm phiếu theo quy định của pháp luật và hướng dẫn của Ủy ban Thường vụ Quốc hội.","cc":"Điểm đ khoản 1 Điều 16 Quy chế làm việc mẫu của HĐND cấp tỉnh (kèm Nghị quyết 103/2025/UBTVQH15)"},{"id":"kht-033","cd":"kh","m":2,"l":"kt","q":"Chậm nhất bao nhiêu ngày kể từ ngày nghị quyết được thông qua, Văn phòng Đoàn ĐBQH và HĐND phải đăng tải công khai nghị quyết của HĐND cấp tỉnh trên trang thông tin điện tử của HĐND (trừ trường hợp pháp luật có quy định khác)?","a":["10 ngày","05 ngày","15 ngày","30 ngày"],"why":"Chậm nhất là 10 ngày kể từ ngày nghị quyết được thông qua, Văn phòng Đoàn ĐBQH và HĐND đăng tải công khai nghị quyết trên trang thông tin điện tử của HĐND, trừ trường hợp pháp luật có quy định khác.","cc":"Khoản 2 Điều 19 Quy chế làm việc mẫu của HĐND cấp tỉnh (kèm Nghị quyết 103/2025/UBTVQH15)"},{"id":"kht-036","cd":"kh","m":2,"l":"kt","q":"Phiên họp Thường trực HĐND cấp tỉnh phải bảo đảm có ít nhất bao nhiêu thành viên Thường trực HĐND tham dự?","a":["Ít nhất hai phần ba tổng số thành viên","Quá nửa tổng số thành viên","Ít nhất ba phần tư tổng số thành viên","Toàn bộ thành viên"],"why":"Phiên họp phải có ít nhất hai phần ba tổng số thành viên Thường trực HĐND tham dự; đừng nhầm với tỷ lệ quá nửa tổng số thành viên cần có để thông qua quyết định.","cc":"Khoản 1 Điều 20 Quy chế làm việc mẫu của HĐND cấp tỉnh (kèm Nghị quyết 103/2025/UBTVQH15)"},{"id":"kht-037","cd":"kh","m":2,"l":"kt","q":"Quyết định của Thường trực HĐND cấp tỉnh phải được bao nhiêu thành viên biểu quyết tán thành?","a":["Quá nửa tổng số thành viên Thường trực HĐND","Quá nửa số thành viên có mặt tại phiên họp","Ít nhất hai phần ba tổng số thành viên Thường trực HĐND","Toàn bộ thành viên Thường trực HĐND"],"why":"Thường trực HĐND thảo luận tập thể, quyết định theo đa số; quyết định phải được quá nửa tổng số thành viên (không phải quá nửa số người có mặt) biểu quyết tán thành.","cc":"Khoản 2 Điều 20 Quy chế làm việc mẫu của HĐND cấp tỉnh (kèm Nghị quyết 103/2025/UBTVQH15)"},{"id":"kht-041","cd":"kh","m":2,"l":"th","q":"Kỳ họp HĐND tỉnh dự kiến khai mạc ngày 20/7. Ngày 12/7, UBND tỉnh mới gửi hồ sơ một dự thảo nghị quyết đến Ban Kinh tế - Ngân sách (được phân công thẩm tra). Đối chiếu Quy chế làm việc mẫu của HĐND cấp tỉnh, nhận định nào đúng?","a":["Chậm hạn, vì phải gửi chậm nhất 15 ngày trước ngày khai mạc kỳ họp","Đúng hạn, vì chỉ cần gửi chậm nhất 07 ngày trước ngày khai mạc kỳ họp","Đúng hạn, vì chỉ cần gửi chậm nhất 05 ngày làm việc trước ngày khai mạc","Chậm hạn, vì phải gửi chậm nhất 30 ngày trước ngày khai mạc kỳ họp"],"why":"Cơ quan trình phải gửi hồ sơ dự thảo nghị quyết, đề án, báo cáo đến Ban được phân công thẩm tra chậm nhất là 15 ngày trước ngày khai mạc kỳ họp; gửi trước 8 ngày là chậm hạn.","cc":"Khoản 1 Điều 28 Quy chế làm việc mẫu của HĐND cấp tỉnh (kèm Nghị quyết 103/2025/UBTVQH15)"},{"id":"kht-042","cd":"kh","m":2,"l":"kt","q":"Báo cáo thẩm tra của Ban của HĐND cấp tỉnh phải được gửi đến Thường trực HĐND chậm nhất khi nào?","a":["05 ngày làm việc trước ngày khai mạc kỳ họp","03 ngày làm việc trước ngày khai mạc kỳ họp","07 ngày làm việc trước ngày khai mạc kỳ họp","15 ngày trước ngày khai mạc kỳ họp"],"why":"Báo cáo thẩm tra gửi Thường trực HĐND chậm nhất 05 ngày làm việc trước ngày khai mạc, đồng thời gửi cơ quan trình; hạn 15 ngày là hạn cơ quan trình gửi hồ sơ đến Ban thẩm tra.","cc":"Khoản 3 Điều 28 Quy chế làm việc mẫu của HĐND cấp tỉnh (kèm Nghị quyết 103/2025/UBTVQH15)"},{"id":"kht-043","cd":"kh","m":2,"l":"th","q":"Do bão lũ, Ban Văn hóa - Xã hội của HĐND tỉnh không thể tổ chức phiên họp toàn thể để thẩm tra một dự thảo nghị quyết. Theo Quy chế làm việc mẫu của HĐND cấp tỉnh, ai xem xét, quyết định việc xin ý kiến thành viên Ban bằng văn bản?","a":["Trưởng Ban Văn hóa - Xã hội","Chủ tịch HĐND tỉnh","Thường trực HĐND tỉnh","Chánh Văn phòng Đoàn ĐBQH và HĐND tỉnh"],"why":"Khi không tổ chức được phiên họp toàn thể Ban (do thiên tai, dịch bệnh, tình trạng khẩn cấp khác) hoặc tùy tính chất, nội dung, Trưởng Ban xem xét, quyết định việc xin ý kiến bằng văn bản.","cc":"Khoản 4 Điều 29 Quy chế làm việc mẫu của HĐND cấp tỉnh (kèm Nghị quyết 103/2025/UBTVQH15)"},{"id":"khx-004","cd":"kh","m":2,"l":"th","q":"Năm 2027 (không phải năm bắt đầu nhiệm kỳ), HĐND xã A cần quyết định kế hoạch tổ chức các kỳ họp thường lệ của năm 2028. Theo Quy chế làm việc mẫu của HĐND cấp xã, việc này được quyết định vào lúc nào?","a":["Tại kỳ họp cuối cùng của năm 2027, theo đề nghị của Thường trực HĐND","Tại kỳ họp đầu tiên của năm 2028, theo đề nghị của Thường trực HĐND","Tại phiên họp Thường trực HĐND tháng 12/2027, không cần trình HĐND","Tại kỳ họp thứ nhất của nhiệm kỳ, quyết định một lần cho cả 5 năm"],"why":"Với các năm tiếp theo của nhiệm kỳ, HĐND quyết định kế hoạch tổ chức các kỳ họp thường lệ vào kỳ họp cuối cùng của năm trước đó; chỉ năm bắt đầu nhiệm kỳ mới quyết định tại kỳ họp thứ nhất.","cc":"Khoản 1 Điều 4 Quy chế làm việc mẫu của HĐND cấp xã (kèm Nghị quyết 104/2025/UBTVQH15)"},{"id":"khx-005","cd":"kh","m":2,"l":"th","q":"HĐND phường B có 24 đại biểu. Một số đại biểu muốn yêu cầu HĐND phường họp chuyên đề về vệ sinh môi trường. Theo Quy chế làm việc mẫu của HĐND cấp xã, cần ít nhất bao nhiêu đại biểu cùng yêu cầu?","a":["8 đại biểu (một phần ba tổng số)","6 đại biểu (một phần tư tổng số)","13 đại biểu (quá nửa tổng số)","16 đại biểu (hai phần ba tổng số)"],"why":"HĐND họp chuyên đề hoặc họp giải quyết công việc đột xuất khi Thường trực HĐND, Chủ tịch UBND cùng cấp hoặc ít nhất một phần ba tổng số đại biểu HĐND yêu cầu; một phần ba của 24 là 8.","cc":"Khoản 2 Điều 4 Quy chế làm việc mẫu của HĐND cấp xã (kèm Nghị quyết 104/2025/UBTVQH15)"},{"id":"khx-006","cd":"kh","m":2,"l":"th","q":"Sau một đợt sạt lở, Chủ tịch UBND xã A yêu cầu HĐND xã họp để giải quyết công việc phát sinh đột xuất. Theo Quy chế làm việc mẫu của HĐND cấp xã, ai quyết định việc tổ chức kỳ họp này?","a":["Thường trực HĐND xã","Chủ tịch UBND xã, vì là người yêu cầu","Thường trực HĐND cấp tỉnh","Tập thể UBND xã biểu quyết"],"why":"Chủ tịch UBND cùng cấp có quyền yêu cầu HĐND họp chuyên đề, họp đột xuất, nhưng việc tổ chức kỳ họp chuyên đề hoặc họp để giải quyết công việc phát sinh đột xuất do Thường trực HĐND quyết định.","cc":"Khoản 1 Điều 6 Quy chế làm việc mẫu của HĐND cấp xã (kèm Nghị quyết 104/2025/UBTVQH15)"},{"id":"khx-009","cd":"kh","m":2,"l":"th","q":"Sau ngày bầu cử chung, xã A phải tổ chức bầu cử thêm đại biểu HĐND xã. Theo Quy chế làm việc mẫu của HĐND cấp xã, thời hạn 45 ngày để tổ chức kỳ họp thứ nhất của HĐND xã A được tính từ ngày nào?","a":["Từ ngày bầu cử thêm","Từ ngày bầu cử chung lần đầu","Từ ngày công bố kết quả bầu cử thêm","Từ ngày xác nhận tư cách đại biểu trúng cử"],"why":"Địa phương có bầu cử lại, bầu cử thêm hoặc lùi ngày bầu cử thì thời hạn tổ chức kỳ họp thứ nhất được tính từ ngày bầu cử lại, bầu cử thêm hoặc ngày bầu cử mới, không tính từ ngày bầu cử chung.","cc":"Khoản 1 Điều 6 Quy chế làm việc mẫu của HĐND cấp xã (kèm Nghị quyết 104/2025/UBTVQH15)"},{"id":"khx-012","cd":"kh","m":2,"l":"th","q":"Sau bầu cử, xã A khuyết Thường trực HĐND nên chưa có chủ thể triệu tập kỳ họp thứ nhất của HĐND xã khóa mới. Theo Quy chế làm việc mẫu của HĐND cấp xã, ai chỉ định triệu tập viên để triệu tập và chủ tọa kỳ họp?","a":["Thường trực HĐND cấp tỉnh","Chủ tịch UBND cấp tỉnh","Ủy ban Thường vụ Quốc hội","Ban Thường trực Ủy ban MTTQ Việt Nam xã A"],"why":"Khi khuyết Thường trực HĐND cấp xã, Thường trực HĐND cấp tỉnh chỉ định triệu tập viên để triệu tập và chủ tọa kỳ họp HĐND cấp xã.","cc":"Khoản 2 Điều 6 Quy chế làm việc mẫu của HĐND cấp xã (kèm Nghị quyết 104/2025/UBTVQH15)"},{"id":"khx-015","cd":"kh","m":2,"l":"th","q":"Đại biểu HĐND xã A biết trước mình không thể dự phiên họp ngày mai của kỳ họp HĐND xã vì việc gia đình (không phải trường hợp bất khả kháng). Theo Quy chế làm việc mẫu của HĐND cấp xã, đại biểu phải làm gì?","a":["Báo cáo trước với Chủ tọa, đồng thời thông tin cho Văn phòng HĐND và UBND","Gửi đơn xin phép Chủ tịch UBND xã và chờ văn bản đồng ý","Báo cáo Tổ trưởng Tổ đại biểu sau khi phiên họp kết thúc","Ủy quyền bằng văn bản cho đại biểu khác biểu quyết thay"],"why":"Đại biểu không dự phiên họp, kỳ họp thì phải có lý do và báo cáo trước với Chủ tọa kỳ họp, phiên họp, đồng thời thông tin cho Văn phòng HĐND và UBND, trừ trường hợp bất khả kháng.","cc":"Khoản 1 Điều 9 Quy chế làm việc mẫu của HĐND cấp xã (kèm Nghị quyết 104/2025/UBTVQH15)"},{"id":"khx-018","cd":"kh","m":2,"l":"kt","q":"Tài liệu phục vụ kỳ họp thường lệ của HĐND cấp xã phải được gửi đến đại biểu HĐND chậm nhất là bao nhiêu ngày trước ngày khai mạc kỳ họp?","a":["15 ngày","20 ngày","10 ngày","07 ngày"],"why":"Tài liệu kỳ họp được gửi qua Văn phòng HĐND và UBND để đến đại biểu chậm nhất là 15 ngày trước ngày khai mạc kỳ họp thường lệ. Mốc 20 ngày là thời hạn Thường trực HĐND quyết định tổ chức kỳ họp.","cc":"Khoản 1 Điều 12 Quy chế làm việc mẫu của HĐND cấp xã (kèm Nghị quyết 104/2025/UBTVQH15)"},{"id":"khx-020","cd":"kh","m":2,"l":"th","q":"Do mưa lũ chia cắt một số thôn, Thường trực HĐND xã A đề nghị tổ chức kỳ họp theo hình thức kết hợp họp trực tiếp với trực tuyến. Theo Quy chế làm việc mẫu của HĐND cấp xã, ai xem xét, quyết định hình thức tổ chức kỳ họp?","a":["HĐND xã, theo đề nghị của Thường trực HĐND xã","Chủ tịch HĐND xã, sau khi thống nhất với Chủ tịch UBND xã","Thường trực HĐND cấp tỉnh, theo đề nghị của HĐND xã","Chủ tịch UBND xã, theo đề nghị của Văn phòng HĐND và UBND"],"why":"HĐND xem xét, quyết định tổ chức kỳ họp theo hình thức trực tiếp (bao gồm cả họp kín), trực tuyến hoặc kết hợp họp trực tiếp với trực tuyến, theo đề nghị của Thường trực HĐND.","cc":"Điều 13 Quy chế làm việc mẫu của HĐND cấp xã (kèm Nghị quyết 104/2025/UBTVQH15)"},{"id":"khx-029","cd":"kh","m":2,"l":"th","q":"Thường trực HĐND phường B có 4 thành viên. Phiên họp thường kỳ tháng này chỉ có 2 thành viên dự được. Theo Quy chế làm việc mẫu của HĐND cấp xã, phiên họp có bảo đảm điều kiện về số thành viên tham dự không?","a":["Không, vì phải có ít nhất hai phần ba tổng số thành viên tham dự","Có, vì chỉ cần một nửa tổng số thành viên tham dự","Có, miễn là Chủ tịch HĐND có mặt và chủ tọa phiên họp","Không, vì phải có đủ toàn bộ thành viên Thường trực tham dự"],"why":"Phiên họp Thường trực HĐND phải bảo đảm có ít nhất hai phần ba tổng số thành viên tham dự; với 4 thành viên thì cần ít nhất 3 người, nên 2 người là chưa đủ.","cc":"Khoản 1 Điều 19 Quy chế làm việc mẫu của HĐND cấp xã (kèm Nghị quyết 104/2025/UBTVQH15)"},{"id":"khx-035","cd":"kh","m":2,"l":"th","q":"HĐND xã A phân công lĩnh vực phụ trách của hai Ban theo đúng hướng gợi ý trong Quy chế làm việc mẫu của HĐND cấp xã. Khi đó, lĩnh vực quốc phòng, an ninh ở địa phương thuộc phạm vi phụ trách của chủ thể nào?","a":["Ban Văn hóa - Xã hội của HĐND xã","Ban Kinh tế - Ngân sách của HĐND xã","Thường trực HĐND xã trực tiếp phụ trách","Các Tổ đại biểu HĐND xã theo địa bàn"],"why":"Theo hướng gợi ý của Quy chế mẫu, Ban Văn hóa - Xã hội phụ trách cả thi hành pháp luật, xây dựng chính quyền, giáo dục, y tế, quốc phòng, an ninh, dân tộc, tôn giáo; Ban Kinh tế - Ngân sách phụ trách quy hoạch, tài chính, ngân sách, đất đai...","cc":"Khoản 2 Điều 26 Quy chế làm việc mẫu của HĐND cấp xã (kèm Nghị quyết 104/2025/UBTVQH15)"},{"id":"khx-036","cd":"kh","m":2,"l":"kt","q":"Cơ quan, tổ chức, cá nhân trình dự thảo nghị quyết, đề án, báo cáo phải gửi hồ sơ đến Ban của HĐND cấp xã được phân công thẩm tra chậm nhất là bao lâu trước ngày khai mạc kỳ họp HĐND?","a":["15 ngày","05 ngày làm việc","10 ngày","20 ngày"],"why":"Hồ sơ phải gửi đến Ban được phân công thẩm tra chậm nhất là 15 ngày trước ngày khai mạc kỳ họp; còn 05 ngày làm việc là thời hạn Ban gửi báo cáo thẩm tra đến Thường trực HĐND.","cc":"Khoản 1 Điều 27 Quy chế làm việc mẫu của HĐND cấp xã (kèm Nghị quyết 104/2025/UBTVQH15)"},{"id":"khx-037","cd":"kh","m":2,"l":"kt","q":"Báo cáo thẩm tra của Ban của HĐND cấp xã phải được gửi đến Thường trực HĐND chậm nhất là bao lâu trước ngày khai mạc kỳ họp HĐND?","a":["05 ngày làm việc","03 ngày làm việc","07 ngày","15 ngày"],"why":"Báo cáo thẩm tra được gửi đến Thường trực HĐND chậm nhất là 05 ngày làm việc trước ngày khai mạc kỳ họp, đồng thời gửi cơ quan trình. Mốc 15 ngày là hạn cơ quan trình gửi hồ sơ cho Ban thẩm tra.","cc":"Khoản 3 Điều 27 Quy chế làm việc mẫu của HĐND cấp xã (kèm Nghị quyết 104/2025/UBTVQH15)"},{"id":"kht-016","cd":"kh","m":3,"l":"th","q":"Tại phiên thảo luận tổ về dự thảo nghị quyết quy định giá dịch vụ, nhiều đại biểu HĐND tỉnh muốn cơ quan chuyên môn trực tiếp làm rõ một số số liệu. Theo Quy chế làm việc mẫu của HĐND cấp tỉnh, Tổ trưởng Tổ thảo luận xử lý thế nào là đúng?","a":["Đề nghị Thường trực HĐND mời đại diện cơ quan liên quan dự phiên thảo luận của Tổ","Tự ký giấy triệu tập Giám đốc Sở đến giải trình trước Tổ thảo luận","Đề nghị Chủ tịch UBND tỉnh cử người đến dự phiên thảo luận của Tổ","Dừng thảo luận, chuyển nội dung sang Ban của HĐND thẩm tra lại"],"why":"Khi cần thiết, Tổ trưởng Tổ thảo luận có thể đề nghị Thường trực HĐND mời đại diện các cơ quan có liên quan dự phiên thảo luận của Tổ để làm rõ vấn đề đại biểu quan tâm; Tổ trưởng không tự triệu tập.","cc":"Khoản 2 Điều 10 Quy chế làm việc mẫu của HĐND cấp tỉnh (kèm Nghị quyết 103/2025/UBTVQH15)"},{"id":"kht-019","cd":"kh","m":3,"l":"kt","q":"Theo Quy chế làm việc mẫu của HĐND cấp tỉnh, ai quyết định các tài liệu được lưu hành tại kỳ họp HĐND và phải thực hiện thủ tục gì trước khi quyết định?","a":["Chánh Văn phòng Đoàn ĐBQH và HĐND, sau khi báo cáo và xin ý kiến Chủ tịch HĐND","Chủ tịch HĐND, sau khi lấy ý kiến Chánh Văn phòng UBND cấp tỉnh","Chủ tọa kỳ họp, sau khi HĐND biểu quyết thông qua danh mục tài liệu","Trưởng Ban Pháp chế, sau khi báo cáo và xin ý kiến Thường trực HĐND"],"why":"Người quyết định tài liệu lưu hành tại kỳ họp là Chánh Văn phòng Đoàn ĐBQH và HĐND, nhưng chỉ sau khi đã báo cáo và xin ý kiến Chủ tịch HĐND.","cc":"Khoản 1 Điều 12 Quy chế làm việc mẫu của HĐND cấp tỉnh (kèm Nghị quyết 103/2025/UBTVQH15)"},{"id":"kht-022","cd":"kh","m":3,"l":"th","q":"Tại kỳ họp HĐND tỉnh, dự thảo nghị quyết về một đề án quan trọng còn nhiều ý kiến khác nhau, cần thêm thời gian nghiên cứu, tiếp thu, chỉnh lý. Theo Quy chế làm việc mẫu của HĐND cấp tỉnh, hướng xử lý nào đúng?","a":["HĐND quyết định lùi thời điểm trình HĐND thông qua dự thảo","Thường trực HĐND thông qua thay HĐND sau khi kỳ họp bế mạc","Chủ tọa cho biểu quyết ngay, phần còn khác ý kiến giao UBND quy định","Ban thẩm tra quyết định rút dự thảo khỏi chương trình kỳ họp"],"why":"Dự thảo có nội dung quan trọng, phức tạp hoặc còn ý kiến khác nhau, cần thêm thời gian thì HĐND tự quyết định hoặc quyết định theo đề nghị của cơ quan trình việc lùi thời điểm trình HĐND thông qua.","cc":"Điểm b khoản 5 Điều 15 Quy chế làm việc mẫu của HĐND cấp tỉnh (kèm Nghị quyết 103/2025/UBTVQH15)"},{"id":"kht-027","cd":"kh","m":3,"l":"th","q":"Tại kỳ họp bầu Phó Chủ tịch HĐND tỉnh, một đại biểu tự ứng cử ngoài danh sách do Thường trực HĐND giới thiệu. Theo Quy chế làm việc mẫu của HĐND cấp tỉnh, trường hợp này được xử lý thế nào?","a":["Thường trực HĐND trình HĐND xem xét, quyết định","Chủ tọa kỳ họp bác ngay vì ngoài danh sách giới thiệu","Ban kiểm phiếu tự bổ sung tên người ứng cử vào phiếu bầu","Đại biểu tự ghi thêm tên người ứng cử vào phiếu bầu"],"why":"Người tự ứng cử hoặc được đại biểu đề cử ngoài danh sách giới thiệu thì Thường trực HĐND (hoặc Chủ tọa kỳ họp nếu khuyết Thường trực HĐND) trình HĐND xem xét, quyết định.","cc":"Điểm a khoản 1 Điều 16 Quy chế làm việc mẫu của HĐND cấp tỉnh (kèm Nghị quyết 103/2025/UBTVQH15)"},{"id":"kht-028","cd":"kh","m":3,"l":"th","q":"HĐND tỉnh xem xét cho từ chức đối với một Phó Chủ tịch UBND tỉnh theo đơn của người này. Theo Quy chế làm việc mẫu của HĐND cấp tỉnh, HĐND biểu quyết theo cách nào?","a":["Biểu quyết công khai và không bầu Ban kiểm phiếu","Bỏ phiếu kín và phải bầu Ban kiểm phiếu","Bỏ phiếu kín nhưng không cần bầu Ban kiểm phiếu","Thường trực HĐND lấy ý kiến đại biểu bằng văn bản"],"why":"Cho thôi giữ chức vụ, cho từ chức, miễn nhiệm thì HĐND biểu quyết công khai và không bầu Ban kiểm phiếu; chỉ trường hợp bãi nhiệm mới bỏ phiếu kín.","cc":"Điểm b khoản 4 Điều 16 Quy chế làm việc mẫu của HĐND cấp tỉnh (kèm Nghị quyết 103/2025/UBTVQH15)"},{"id":"kht-029","cd":"kh","m":3,"l":"th","q":"HĐND tỉnh chuẩn bị xem xét miễn nhiệm Chủ tịch UBND tỉnh (không thuộc trường hợp được điều động, bị cách chức, nghỉ hưu hoặc xin thôi giữ chức vụ). Theo Quy chế làm việc mẫu của HĐND cấp tỉnh, ai có thẩm quyền trình HĐND việc miễn nhiệm này?","a":["Chủ tịch HĐND tỉnh, vì là người có thẩm quyền trình HĐND bầu chức danh này","Ban Pháp chế của HĐND tỉnh, vì là Ban phụ trách xây dựng chính quyền","Ban Thường trực Ủy ban MTTQ Việt Nam tỉnh, vì đại diện cho cử tri","Giám đốc Sở Nội vụ tỉnh, vì là cơ quan tham mưu công tác cán bộ"],"why":"Ai có thẩm quyền trình HĐND bầu thì cũng trình việc miễn nhiệm, bãi nhiệm; Chủ tịch UBND do Chủ tịch HĐND giới thiệu nên Chủ tịch HĐND trình. Nếu Chủ tịch UBND tỉnh được Thủ tướng điều động hoặc cách chức thì HĐND không làm thủ tục miễn nhiệm, bãi nhiệm.","cc":"Điểm a khoản 4 Điều 16 Quy chế làm việc mẫu của HĐND cấp tỉnh (kèm Nghị quyết 103/2025/UBTVQH15); khoản 4 Điều 37 Luật Tổ chức chính quyền địa phương số 72/2025/QH15"},{"id":"kht-030","cd":"kh","m":3,"l":"th","q":"Giữa hai kỳ họp, một đại biểu HĐND tỉnh có đơn xin thôi làm nhiệm vụ đại biểu vì lý do sức khỏe. Theo Quy chế làm việc mẫu của HĐND cấp tỉnh, việc này được giải quyết thế nào?","a":["Thường trực HĐND xem xét, quyết định và báo cáo HĐND tại kỳ họp gần nhất","Phải chờ kỳ họp gần nhất để HĐND biểu quyết, không ai được quyết định trước","Chủ tịch HĐND quyết định và thông báo cho Tổ đại biểu nơi đại biểu sinh hoạt","Thường trực HĐND trình Ủy ban Thường vụ Quốc hội xem xét, quyết định"],"why":"Trong thời gian HĐND không họp, việc cho thôi làm nhiệm vụ đại biểu do Thường trực HĐND xem xét, quyết định và báo cáo HĐND tại kỳ họp gần nhất; khi HĐND đang họp thì Thường trực trình HĐND quyết định.","cc":"Điểm a khoản 5 Điều 16 Quy chế làm việc mẫu của HĐND cấp tỉnh (kèm Nghị quyết 103/2025/UBTVQH15)"},{"id":"kht-031","cd":"kh","m":3,"l":"kt","q":"Khi HĐND cấp tỉnh xem xét cho thôi làm nhiệm vụ đại biểu HĐND tại kỳ họp, hình thức biểu quyết được xác định thế nào?","a":["HĐND quyết định hình thức; nếu biểu quyết công khai thì không bầu Ban kiểm phiếu","Bắt buộc bỏ phiếu kín và phải bầu Ban kiểm phiếu như khi bầu chức danh","Bắt buộc biểu quyết công khai, không được bỏ phiếu kín","Chủ tọa kỳ họp quyết định hình thức sau khi hỏi ý kiến Ban Pháp chế"],"why":"Với việc cho thôi làm nhiệm vụ đại biểu, Quy chế mẫu không ấn định sẵn hình thức mà để HĐND quyết định; trường hợp biểu quyết công khai thì không bầu Ban kiểm phiếu.","cc":"Điểm b khoản 5 Điều 16 Quy chế làm việc mẫu của HĐND cấp tỉnh (kèm Nghị quyết 103/2025/UBTVQH15)"},{"id":"kht-032","cd":"kh","m":3,"l":"th","q":"Sau khi HĐND tỉnh thảo luận tại tổ và tại hội trường về dự thảo nghị quyết do UBND tỉnh trình, ai có trách nhiệm chủ động xây dựng báo cáo giải trình, tiếp thu để báo cáo HĐND tại phiên họp toàn thể theo Quy chế làm việc mẫu của HĐND cấp tỉnh?","a":["Cơ quan trình dự thảo, phối hợp với cơ quan chủ trì thẩm tra và bộ phận thư ký kỳ họp","Ban chủ trì thẩm tra, phối hợp với Văn phòng UBND tỉnh và Sở Tư pháp","Bộ phận thư ký kỳ họp, phối hợp với Ban Pháp chế của HĐND tỉnh","Thường trực HĐND tỉnh, phối hợp với các Tổ trưởng Tổ thảo luận"],"why":"Trách nhiệm giải trình, tiếp thu thuộc cơ quan, tổ chức, người trình dự thảo; cơ quan này chủ động phối hợp với cơ quan chủ trì thẩm tra và bộ phận thư ký kỳ họp để xây dựng báo cáo.","cc":"Khoản 4 Điều 15 Quy chế làm việc mẫu của HĐND cấp tỉnh (kèm Nghị quyết 103/2025/UBTVQH15)"},{"id":"kht-038","cd":"kh","m":3,"l":"th","q":"Thường trực HĐND tỉnh có 6 thành viên được xin ý kiến bằng văn bản về một nội dung thuộc thẩm quyền. Kết quả: 3 thành viên tán thành (trong đó có Chủ tịch HĐND), 3 thành viên không tán thành. Theo Quy chế làm việc mẫu của HĐND cấp tỉnh, xử lý thế nào?","a":["Thực hiện theo ý kiến mà Chủ tịch HĐND đã biểu quyết","Nội dung không được thông qua vì chưa quá nửa tán thành","Phải tổ chức phiên họp trực tiếp để biểu quyết lại","Trình HĐND xem xét, quyết định tại kỳ họp gần nhất"],"why":"Trường hợp biểu quyết ngang nhau thì thực hiện theo ý kiến mà Chủ tịch HĐND đã biểu quyết, kể cả khi xin ý kiến bằng văn bản.","cc":"Khoản 2 Điều 20 Quy chế làm việc mẫu của HĐND cấp tỉnh (kèm Nghị quyết 103/2025/UBTVQH15)"},{"id":"kht-040","cd":"kh","m":3,"l":"th","q":"Một phiên họp Thường trực HĐND tỉnh do Phó Chủ tịch HĐND làm Chủ tọa. Sau phiên họp, Văn phòng Đoàn ĐBQH và HĐND xây dựng dự thảo thông báo kết luận. Theo Quy chế làm việc mẫu của HĐND cấp tỉnh, dự thảo này được trình thế nào?","a":["Trình Phó Chủ tịch chủ tọa cho ý kiến, sau đó trình Chủ tịch HĐND quyết định","Trình Phó Chủ tịch chủ tọa phiên họp quyết định và ký ban hành ngay","Trình tập thể Thường trực HĐND biểu quyết tại phiên họp kế tiếp","Chánh Văn phòng quyết định sau khi lấy ý kiến Ban chủ trì thẩm tra"],"why":"Nếu Chủ tọa phiên họp là Phó Chủ tịch HĐND thì dự thảo thông báo kết luận được trình Chủ tọa xem xét, cho ý kiến trước khi trình Chủ tịch HĐND xem xét, quyết định.","cc":"Khoản 1 Điều 22 Quy chế làm việc mẫu của HĐND cấp tỉnh (kèm Nghị quyết 103/2025/UBTVQH15)"},{"id":"khx-014","cd":"kh","m":3,"l":"th","q":"Trước kỳ họp thường lệ, phường B khuyết Chủ tịch HĐND, còn các thành viên khác của Thường trực HĐND phường vẫn đủ. Theo Quy chế làm việc mẫu của HĐND cấp xã, ai chủ tọa kỳ họp?","a":["Phó Chủ tịch HĐND phường, theo phân công của Thường trực HĐND phường","Người do Thường trực HĐND cấp tỉnh chỉ định làm Chủ tọa kỳ họp","Chủ tịch UBND phường, theo đề nghị của Thường trực HĐND phường","Một Trưởng Ban của HĐND phường do các đại biểu bầu tại kỳ họp"],"why":"Khuyết Chủ tịch HĐND thì Thường trực HĐND phân công Phó Chủ tịch HĐND chủ tọa kỳ họp. Chỉ khi khuyết cả Thường trực HĐND thì Thường trực HĐND cấp tỉnh mới chỉ định Chủ tọa kỳ họp.","cc":"Khoản 1 Điều 8 Quy chế làm việc mẫu của HĐND cấp xã (kèm Nghị quyết 104/2025/UBTVQH15)"},{"id":"khx-019","cd":"kh","m":3,"l":"kt","q":"Theo Quy chế làm việc mẫu của HĐND cấp xã, ai quyết định các tài liệu được lưu hành tại kỳ họp HĐND?","a":["Chánh Văn phòng HĐND và UBND, sau khi báo cáo và xin ý kiến Chủ tịch HĐND","Thường trực HĐND, sau khi thống nhất với Chủ tịch UBND cùng cấp","Chủ tọa kỳ họp, sau khi lấy biểu quyết của các đại biểu HĐND","Trưởng Ban được phân công thẩm tra, sau khi báo cáo Thường trực HĐND"],"why":"Chánh Văn phòng HĐND và UBND quyết định tài liệu lưu hành tại kỳ họp sau khi báo cáo, xin ý kiến Chủ tịch HĐND. Còn Thường trực HĐND quyết định chế độ quản lý và việc đăng tải tài liệu kỳ họp.","cc":"Khoản 1 Điều 12 Quy chế làm việc mẫu của HĐND cấp xã (kèm Nghị quyết 104/2025/UBTVQH15)"},{"id":"khx-022","cd":"kh","m":3,"l":"th","q":"Tại kỳ họp HĐND xã A, một dự thảo nghị quyết có nội dung quan trọng, phức tạp còn nhiều ý kiến khác nhau, cần thêm thời gian nghiên cứu, tiếp thu, chỉnh lý. Theo Quy chế làm việc mẫu của HĐND cấp xã, cách xử lý nào đúng?","a":["HĐND quyết định lùi thời điểm thông qua, tự mình hoặc theo đề nghị của cơ quan trình","Chủ tọa kỳ họp tự quyết định rút dự thảo khỏi chương trình kỳ họp","Thường trực HĐND thông qua dự thảo bằng văn bản sau khi kỳ họp bế mạc","Bắt buộc biểu quyết ngay vì chương trình kỳ họp đã được thông qua"],"why":"Dự thảo có nội dung quan trọng, phức tạp hoặc còn ý kiến khác nhau, cần thêm thời gian thì HĐND quyết định, hoặc theo đề nghị của cơ quan, tổ chức, người có thẩm quyền trình quyết định, lùi thời điểm trình HĐND thông qua.","cc":"Điểm b khoản 5 Điều 15 Quy chế làm việc mẫu của HĐND cấp xã (kèm Nghị quyết 104/2025/UBTVQH15)"},{"id":"khx-024","cd":"kh","m":3,"l":"th","q":"Tại kỳ họp thứ nhất của HĐND xã A khóa mới, do khuyết Thường trực HĐND nên kỳ họp do người được chỉ định làm Chủ tọa điều hành. Theo Quy chế làm việc mẫu của HĐND cấp xã, ai giới thiệu danh sách nhân sự để HĐND bầu Chủ tịch HĐND, Phó Chủ tịch HĐND, Trưởng Ban của HĐND?","a":["Chủ tọa kỳ họp","Thường trực HĐND cấp tỉnh","Chủ tịch UBND xã A","Ban Thường trực Ủy ban MTTQ Việt Nam xã A"],"why":"Thông thường Thường trực HĐND giới thiệu nhân sự Chủ tịch HĐND, Phó Chủ tịch HĐND, Trưởng Ban; khi khuyết Thường trực HĐND thì Chủ tọa kỳ họp giới thiệu. Thường trực HĐND cấp tỉnh là chủ thể chỉ định Chủ tọa kỳ họp.","cc":"Điểm a khoản 1 Điều 16 Quy chế làm việc mẫu của HĐND cấp xã (kèm Nghị quyết 104/2025/UBTVQH15)"},{"id":"khx-025","cd":"kh","m":3,"l":"th","q":"Tại một kỳ họp giữa nhiệm kỳ (không phải kỳ họp thứ nhất) của HĐND phường B, khi thảo luận về nhân sự bầu Trưởng Ban của HĐND, một đại biểu đề cử thêm một đại biểu khác ngoài danh sách do Thường trực HĐND phường giới thiệu. Theo Quy chế làm việc mẫu của HĐND cấp xã, việc này được xử lý thế nào?","a":["Thường trực HĐND trình HĐND xem xét, quyết định","Chủ tọa kỳ họp bác đề cử vì ngoài danh sách giới thiệu","Người được đề cử đương nhiên được ghi vào phiếu bầu","Ban kiểm phiếu xem xét, quyết định trước khi phát phiếu"],"why":"Người tự ứng cử hoặc được đề cử ngoài danh sách thì Thường trực HĐND trình HĐND xem xét, quyết định; không bị bác ngay, cũng không đương nhiên vào danh sách bầu. Riêng kỳ họp thứ nhất của mỗi khóa, Luật 72/2025/QH15 (khoản 5 Điều 36) giao chủ tọa kỳ họp trình.","cc":"Điểm a khoản 1 Điều 16 Quy chế làm việc mẫu của HĐND cấp xã (kèm Nghị quyết 104/2025/UBTVQH15)"},{"id":"khx-026","cd":"kh","m":3,"l":"th","q":"HĐND xã A xem xét cho Trưởng Ban Kinh tế - Ngân sách của HĐND xã từ chức theo đơn của người này. Theo Quy chế làm việc mẫu của HĐND cấp xã, HĐND biểu quyết việc cho từ chức này theo cách nào?","a":["Biểu quyết công khai và không bầu Ban kiểm phiếu","Bỏ phiếu kín và phải bầu Ban kiểm phiếu","Biểu quyết công khai nhưng vẫn phải bầu Ban kiểm phiếu","Lấy ý kiến bằng văn bản do Thường trực HĐND tổng hợp"],"why":"Khi cho thôi giữ chức vụ, từ chức, miễn nhiệm người giữ chức vụ do HĐND bầu thì HĐND biểu quyết công khai và không bầu Ban kiểm phiếu; riêng trường hợp bãi nhiệm thì bỏ phiếu kín.","cc":"Điểm b khoản 3 Điều 16 Quy chế làm việc mẫu của HĐND cấp xã (kèm Nghị quyết 104/2025/UBTVQH15)"},{"id":"khx-027","cd":"kh","m":3,"l":"th","q":"Giữa hai kỳ họp, một đại biểu HĐND phường B có đơn xin thôi làm nhiệm vụ đại biểu vì lý do sức khỏe. Theo Quy chế làm việc mẫu của HĐND cấp xã, trong thời gian HĐND không họp, việc này được giải quyết thế nào?","a":["Thường trực HĐND xem xét, quyết định và báo cáo HĐND tại kỳ họp gần nhất","Chủ tịch HĐND quyết định và thông báo cho Tổ đại biểu nơi đại biểu sinh hoạt","Phải chờ đến kỳ họp gần nhất để HĐND biểu quyết bằng bỏ phiếu kín","Thường trực HĐND cấp tỉnh xem xét, quyết định theo đề nghị của phường"],"why":"Căn cứ đơn của đại biểu, Thường trực HĐND trình HĐND quyết định cho thôi làm nhiệm vụ đại biểu; trong thời gian HĐND không họp thì Thường trực HĐND xem xét, quyết định và báo cáo HĐND tại kỳ họp gần nhất.","cc":"Điểm a khoản 4 Điều 16 Quy chế làm việc mẫu của HĐND cấp xã (kèm Nghị quyết 104/2025/UBTVQH15)"},{"id":"khx-031","cd":"kh","m":3,"l":"th","q":"Thường trực HĐND xã A (4 thành viên) xin ý kiến bằng văn bản về một nội dung; kết quả 2 phiếu tán thành, 2 phiếu không tán thành, trong đó Chủ tịch HĐND xã tán thành. Theo Quy chế làm việc mẫu của HĐND cấp xã, kết quả được xác định thế nào?","a":["Thực hiện theo ý kiến mà Chủ tịch HĐND đã biểu quyết, tức là tán thành","Không thông qua, vì quy tắc ngang phiếu không áp dụng khi xin ý kiến bằng văn bản","Phải tổ chức phiên họp trực tiếp để biểu quyết lại cho đến khi quá nửa","Chuyển nội dung lên HĐND xã quyết định tại kỳ họp gần nhất"],"why":"Khi biểu quyết ngang nhau, Thường trực HĐND thực hiện theo ý kiến mà Chủ tịch HĐND đã biểu quyết, kể cả trường hợp xin ý kiến bằng văn bản.","cc":"Khoản 2 Điều 19 Quy chế làm việc mẫu của HĐND cấp xã (kèm Nghị quyết 104/2025/UBTVQH15)"},{"id":"khx-033","cd":"kh","m":3,"l":"th","q":"Một phiên họp Thường trực HĐND xã A do Phó Chủ tịch HĐND xã làm Chủ tọa. Sau phiên họp, Văn phòng HĐND và UBND xã xây dựng dự thảo thông báo kết luận. Theo Quy chế làm việc mẫu của HĐND cấp xã, dự thảo này được trình thế nào?","a":["Trình Phó Chủ tịch HĐND cho ý kiến, rồi trình Chủ tịch HĐND xem xét, quyết định","Trình Phó Chủ tịch HĐND chủ tọa quyết định, không cần trình Chủ tịch HĐND","Trình tập thể Thường trực HĐND biểu quyết thông qua tại phiên họp kế tiếp","Trình Trưởng Ban chủ trì thẩm tra quyết định, rồi báo cáo Chủ tịch HĐND"],"why":"Nếu Chủ tọa là Chủ tịch HĐND thì Chủ tọa xem xét, quyết định dự thảo thông báo kết luận; nếu Chủ tọa là Phó Chủ tịch HĐND thì Phó Chủ tịch cho ý kiến trước khi trình Chủ tịch HĐND xem xét, quyết định.","cc":"Khoản 1 Điều 21 Quy chế làm việc mẫu của HĐND cấp xã (kèm Nghị quyết 104/2025/UBTVQH15)"},{"id":"khx-034","cd":"kh","m":3,"l":"kt","q":"Tại kỳ họp, khi HĐND cấp xã xem xét cho thôi làm nhiệm vụ đại biểu HĐND theo đơn của đại biểu, hình thức biểu quyết được xác định thế nào?","a":["HĐND quyết định hình thức biểu quyết; nếu công khai thì không bầu Ban kiểm phiếu","Bắt buộc bỏ phiếu kín và phải bầu Ban kiểm phiếu","Bắt buộc biểu quyết công khai, do Chủ tọa kỳ họp kiểm đếm","Thường trực HĐND quyết định hình thức; luôn phải bầu Ban kiểm phiếu"],"why":"Với việc cho thôi làm nhiệm vụ đại biểu tại kỳ họp, HĐND tự quyết định hình thức biểu quyết; nếu biểu quyết công khai thì không bầu Ban kiểm phiếu. Khác với bãi nhiệm người giữ chức vụ do HĐND bầu là phải bỏ phiếu kín.","cc":"Điểm b khoản 4 Điều 16 Quy chế làm việc mẫu của HĐND cấp xã (kèm Nghị quyết 104/2025/UBTVQH15)"},{"id":"gsh-001","cd":"gs","m":1,"l":"kt","q":"Nghị quyết số 114/2025/UBTVQH15 quy định chi tiết và hướng dẫn về hoạt động giám sát của HĐND có hiệu lực thi hành từ ngày nào?","a":["Ngày 01 tháng 3 năm 2026","Ngày 01 tháng 01 năm 2026","Ngày 24 tháng 12 năm 2025","Ngày 01 tháng 7 năm 2026"],"why":"Nghị quyết được UBTVQH thông qua ngày 24/12/2025 nhưng có hiệu lực thi hành từ ngày 01/3/2026; dễ nhầm ngày thông qua với ngày có hiệu lực.","cc":"Khoản 1 Điều 63 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-002","cd":"gs","m":1,"l":"kt","q":"Theo Nghị quyết số 114/2025/UBTVQH15, “cơ quan giúp việc của HĐND” ở cấp xã là cơ quan nào?","a":["Văn phòng HĐND và UBND cấp xã","Văn phòng Đoàn đại biểu Quốc hội và HĐND cấp tỉnh","Ban của HĐND cấp xã","Tổ đại biểu HĐND cấp xã"],"why":"Cơ quan giúp việc của HĐND gồm Văn phòng Đoàn đại biểu Quốc hội và HĐND cấp tỉnh (ở cấp tỉnh) và Văn phòng HĐND và UBND cấp xã (ở cấp xã). Đây là đầu mối tổng hợp, tham mưu trong hầu hết các thủ tục giám sát.","cc":"Khoản 1 Điều 2 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-005","cd":"gs","m":1,"l":"kt","q":"Theo Nghị quyết số 114/2025/UBTVQH15, HĐND quyết định chương trình giám sát năm sau của mình tại kỳ họp nào?","a":["Kỳ họp thường lệ cuối năm","Kỳ họp thường lệ giữa năm","Kỳ họp thường lệ đầu tiên của năm sau","Kỳ họp chuyên đề do Thường trực HĐND triệu tập"],"why":"HĐND quyết định chương trình giám sát năm sau tại kỳ họp thường lệ cuối năm; còn báo cáo kết quả thực hiện chương trình giám sát năm trước được trình tại kỳ họp thường lệ đầu tiên của năm sau.","cc":"Khoản 1 Điều 8 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-016","cd":"gs","m":1,"l":"kt","q":"Phiên chất vấn tại kỳ họp của HĐND cấp tỉnh được thông tin đến cử tri theo cách nào?","a":["Được phát thanh, truyền hình trực tiếp, trừ trường hợp do HĐND cấp tỉnh quyết định","Chỉ được đưa tin sau khi HĐND thông qua nghị quyết về chất vấn","Được ghi hình và phát lại sau khi Thường trực HĐND cấp tỉnh duyệt nội dung","Bắt buộc phát thanh, truyền hình trực tiếp, không có ngoại lệ"],"why":"Phiên chất vấn của HĐND cấp tỉnh được phát thanh, truyền hình trực tiếp để cử tri theo dõi; ngoại lệ chỉ do chính HĐND cấp tỉnh quyết định.","cc":"Khoản 4 Điều 22 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-017","cd":"gs","m":1,"l":"kt","q":"Theo Nghị quyết số 114/2025/UBTVQH15, ai điều hành phiên chất vấn tại kỳ họp HĐND?","a":["Chủ tịch HĐND; nếu vắng mặt thì phân công một Phó Chủ tịch HĐND","Trưởng Ban của HĐND phụ trách lĩnh vực được chất vấn","Chủ tịch UBND cùng cấp hoặc người được ủy quyền","Thư ký kỳ họp theo phân công của Thường trực HĐND"],"why":"Chủ tịch HĐND điều hành phiên chất vấn; trường hợp Chủ tịch HĐND vắng mặt thì phân công một Phó Chủ tịch HĐND điều hành.","cc":"Khoản 1 Điều 23 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-022","cd":"gs","m":1,"l":"kt","q":"Sau phiên chất vấn tại kỳ họp, HĐND ban hành văn bản nào về chất vấn?","a":["Nghị quyết về chất vấn","Kết luận về chất vấn","Thông báo kết quả phiên chất vấn","Biên bản phiên chất vấn"],"why":"Sau phiên chất vấn tại kỳ họp, HĐND ban hành nghị quyết về chất vấn; còn sau phiên chất vấn tại phiên họp Thường trực HĐND thì Thường trực HĐND thông qua kết luận về chất vấn.","cc":"Khoản 1 Điều 24 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-024","cd":"gs","m":1,"l":"kt","q":"Đại biểu HĐND có thể tham dự phiên chất vấn tại phiên họp Thường trực HĐND theo hình thức nào?","a":["Tham dự trực tiếp hoặc có thể tham dự theo hình thức trực tuyến","Chỉ được tham dự trực tiếp tại nơi tổ chức phiên họp","Chỉ được gửi câu hỏi bằng văn bản, không dự phiên họp","Chỉ đại biểu là thành viên Thường trực HĐND mới được tham dự"],"why":"Đại biểu HĐND tham dự trực tiếp phiên chất vấn tại phiên họp Thường trực HĐND hoặc có thể tham dự theo hình thức trực tuyến.","cc":"Khoản 6 Điều 30 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-025","cd":"gs","m":1,"l":"kt","q":"Theo Nghị quyết số 114/2025/UBTVQH15, nội dung chất vấn của đại biểu HĐND phải đáp ứng yêu cầu nào?","a":["Cụ thể, rõ ràng, có căn cứ và liên quan đến nhiệm vụ, quyền hạn, trách nhiệm của người bị chất vấn","Phải được Tổ đại biểu HĐND biểu quyết thông qua trước khi nêu tại phiên chất vấn","Phải được người bị chất vấn đồng ý trước về phạm vi và nội dung câu hỏi","Chỉ được nêu vấn đề đã có kết luận của cơ quan thanh tra, kiểm tra"],"why":"Nội dung chất vấn phải cụ thể, rõ ràng, có căn cứ và phải liên quan đến nhiệm vụ, quyền hạn, trách nhiệm của người bị chất vấn; không cần sự đồng ý trước của người bị chất vấn hay của Tổ đại biểu.","cc":"Khoản 2 Điều 33 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-026","cd":"gs","m":1,"l":"kt","q":"Tại phiên chất vấn, người bị chất vấn có trách nhiệm gì đối với vấn đề mà đại biểu HĐND đã chất vấn?","a":["Trả lời trực tiếp, đầy đủ; xác định rõ trách nhiệm, biện pháp, thời hạn khắc phục hạn chế","Trả lời khái quát tại phiên họp, phần chi tiết gửi bằng văn bản sau kỳ họp","Chuyển câu hỏi cho cấp dưới trực tiếp phụ trách lĩnh vực trả lời thay","Chỉ trả lời những câu hỏi đã được đại biểu gửi trước bằng văn bản"],"why":"Người bị chất vấn phải trả lời trực tiếp, đầy đủ vấn đề đại biểu đã chất vấn và xác định rõ trách nhiệm, biện pháp, thời hạn khắc phục hạn chế, bất cập (nếu có).","cc":"Điểm b khoản 3 Điều 22 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-027","cd":"gs","m":1,"l":"kt","q":"Phiên giải trình tại phiên họp Thường trực HĐND được tổ chức theo nguyên tắc nào về tính công khai?","a":["Tổ chức công khai, trừ trường hợp do Thường trực HĐND quyết định","Tổ chức kín, trừ trường hợp HĐND quyết định tổ chức công khai","Tổ chức kín, chỉ công bố kết luận sau phiên giải trình","Công khai hay kín do người được yêu cầu giải trình đề nghị"],"why":"Phiên giải trình của Thường trực HĐND được tổ chức công khai, trừ trường hợp do Thường trực HĐND quyết định; mức độ công khai được nêu trong kế hoạch tổ chức phiên giải trình.","cc":"Khoản 1 Điều 37 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-030","cd":"gs","m":1,"l":"kt","q":"Để tiến hành giám sát chuyên đề của HĐND, Đoàn giám sát của HĐND được thành lập bằng văn bản nào?","a":["Nghị quyết của HĐND, do Thường trực HĐND trình","Quyết định của Chủ tịch HĐND","Quyết định của Ban của HĐND phụ trách lĩnh vực","Kế hoạch của cơ quan giúp việc của HĐND"],"why":"Căn cứ chương trình giám sát của HĐND, Thường trực HĐND trình HĐND xem xét, thông qua nghị quyết thành lập Đoàn giám sát; Ban của HĐND phụ trách lĩnh vực chủ trì xây dựng dự thảo nghị quyết này.","cc":"Khoản 1 Điều 40 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-031","cd":"gs","m":1,"l":"kt","q":"Theo Nghị quyết số 114/2025/UBTVQH15, Trưởng Đoàn giám sát chuyên đề của HĐND là ai?","a":["Chủ tịch hoặc Phó Chủ tịch HĐND","Trưởng Ban hoặc Phó Trưởng Ban của HĐND","Tổ trưởng Tổ đại biểu HĐND nơi tiến hành giám sát","Chủ tịch Ủy ban MTTQ Việt Nam cùng cấp"],"why":"Trưởng Đoàn giám sát của HĐND là Chủ tịch hoặc Phó Chủ tịch HĐND. Đoàn giám sát của Ban của HĐND mới do Trưởng Ban hoặc Phó Trưởng Ban làm Trưởng Đoàn; đại diện Ủy ban MTTQ Việt Nam cùng cấp chỉ có thể được mời tham gia Đoàn.","cc":"Khoản 2 Điều 40 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-037","cd":"gs","m":1,"l":"kt","q":"Theo Nghị quyết số 114/2025/UBTVQH15, Tổ đại biểu HĐND tổ chức hoạt động giám sát trong trường hợp nào?","a":["Khi được HĐND hoặc Thường trực HĐND cùng cấp giao","Khi có đề nghị bằng văn bản của UBND cùng cấp","Khi có quá nửa số đại biểu trong Tổ biểu quyết yêu cầu","Khi được Ủy ban MTTQ Việt Nam cùng cấp đề nghị"],"why":"Tổ đại biểu HĐND tổ chức hoạt động giám sát khi được HĐND hoặc Thường trực HĐND cùng cấp giao; căn cứ nội dung được giao, Tổ xây dựng kế hoạch giám sát và đề cương báo cáo.","cc":"Khoản 1 Điều 48 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-038","cd":"gs","m":1,"l":"kt","q":"Khi tiến hành các hoạt động giám sát, Tổ đại biểu HĐND được sử dụng con dấu nào?","a":["Con dấu của HĐND cùng cấp","Con dấu của UBND cùng cấp","Con dấu riêng của Tổ đại biểu HĐND","Con dấu của Ủy ban MTTQ Việt Nam cùng cấp"],"why":"Tổ đại biểu HĐND không có con dấu riêng nhưng được sử dụng con dấu của HĐND cùng cấp khi tiến hành các hoạt động giám sát.","cc":"Khoản 4 Điều 48 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-040","cd":"gs","m":1,"l":"kt","q":"Đại biểu HĐND quyết định lựa chọn vấn đề giám sát việc thi hành pháp luật trên địa bàn nào?","a":["Địa bàn nơi đại biểu HĐND ứng cử","Địa bàn nơi đại biểu HĐND cư trú","Địa bàn nơi đại biểu HĐND công tác","Địa bàn do Ban của HĐND phân công"],"why":"Căn cứ tình hình địa phương, ý kiến, kiến nghị của cử tri và thực tiễn đời sống Nhân dân, đại biểu HĐND quyết định lựa chọn vấn đề giám sát việc thi hành pháp luật trên địa bàn nơi mình ứng cử.","cc":"Khoản 1 Điều 49 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-042","cd":"gs","m":1,"l":"kt","q":"Theo Nghị quyết số 114/2025/UBTVQH15, cơ quan nào có trách nhiệm giám sát việc giải quyết, trả lời kiến nghị của cử tri và báo cáo HĐND về kết quả giám sát?","a":["Thường trực HĐND","UBND cùng cấp","Ủy ban MTTQ Việt Nam cùng cấp","Cơ quan giúp việc của HĐND"],"why":"Thường trực HĐND có trách nhiệm giám sát việc giải quyết, trả lời kiến nghị của cử tri, xem xét báo cáo của UBND và cơ quan có thẩm quyền, rồi báo cáo HĐND; các Ban, Tổ đại biểu giúp Thường trực khi được phân công.","cc":"Khoản 1 Điều 50 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-049","cd":"gs","m":1,"l":"th","q":"Hai Ban của HĐND tỉnh cùng lên kế hoạch giám sát tại một sở trong cùng một tuần với nội dung gần giống nhau. Theo Nghị quyết số 114/2025/UBTVQH15, cơ quan nào có thẩm quyền yêu cầu các Ban điều chỉnh kế hoạch, phối hợp để tránh trùng lặp?","a":["Thường trực HĐND tỉnh","Chủ tịch UBND tỉnh","Sở chịu sự giám sát","Cơ quan thanh tra cấp tỉnh"],"why":"Thường trực HĐND chỉ đạo, điều hòa, phối hợp hoạt động giám sát của các Ban, Tổ đại biểu, đại biểu HĐND, trong đó có việc yêu cầu điều chỉnh chương trình, kế hoạch để tránh trùng lặp về nội dung, thời gian, địa điểm giám sát.","cc":"Điều 61 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-050","cd":"gs","m":1,"l":"kt","q":"Theo Nghị quyết số 96/2023/QH15, HĐND cấp tỉnh tổ chức lấy phiếu tín nhiệm đối với người giữ chức vụ do HĐND bầu vào thời điểm nào?","a":["Một lần trong mỗi nhiệm kỳ, vào kỳ họp cuối năm thứ ba của nhiệm kỳ","Mỗi năm một lần, vào kỳ họp thường lệ cuối năm","Hai lần trong mỗi nhiệm kỳ, vào năm thứ hai và năm thứ tư","Một lần trong mỗi nhiệm kỳ, vào kỳ họp đầu tiên của năm cuối nhiệm kỳ"],"why":"Việc lấy phiếu tín nhiệm được tổ chức một lần trong mỗi nhiệm kỳ, vào kỳ họp cuối năm thứ ba của nhiệm kỳ.","cc":"Điều 9 Nghị quyết số 96/2023/QH15"},{"id":"gsh-051","cd":"gs","m":1,"l":"kt","q":"Khi HĐND lấy phiếu tín nhiệm theo Nghị quyết số 96/2023/QH15, trên phiếu ghi những mức độ tín nhiệm nào?","a":["“Tín nhiệm cao”, “tín nhiệm”, “tín nhiệm thấp”","“Tín nhiệm”, “không tín nhiệm”","“Tín nhiệm cao”, “tín nhiệm”, “không tín nhiệm”","“Tín nhiệm cao”, “tín nhiệm thấp”, “không tín nhiệm”"],"why":"Lấy phiếu tín nhiệm có ba mức: tín nhiệm cao, tín nhiệm, tín nhiệm thấp và được thực hiện bằng bỏ phiếu kín. Hai mức “tín nhiệm”, “không tín nhiệm” là của bỏ phiếu tín nhiệm.","cc":"Điểm đ khoản 8 Điều 11 Nghị quyết số 96/2023/QH15"},{"id":"gsl-001","cd":"gs","m":1,"l":"kt","q":"Theo Luật Hoạt động giám sát của Quốc hội và HĐND số 121/2025/QH15, chủ thể nào sau đây là chủ thể giám sát của HĐND?","a":["Tổ đại biểu HĐND","Văn phòng HĐND và UBND cấp xã","Ủy ban MTTQ Việt Nam cùng cấp","Cơ quan thanh tra ở địa phương"],"why":"Chủ thể giám sát của HĐND gồm 5 chủ thể: HĐND, Thường trực HĐND, Ban của HĐND, Tổ đại biểu HĐND và đại biểu HĐND. MTTQ, cơ quan thanh tra chỉ phối hợp hoặc tham gia giám sát.","cc":"Khoản 3 Điều 2 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsl-002","cd":"gs","m":1,"l":"kt","q":"Theo Luật số 121/2025/QH15, “chất vấn” được hiểu là gì?","a":["Đại biểu nêu vấn đề thuộc trách nhiệm của người bị chất vấn và yêu cầu người đó trả lời về trách nhiệm của mình","Cơ quan, cá nhân giải thích, làm rõ trách nhiệm của mình theo yêu cầu của chủ thể giám sát","Đại biểu yêu cầu cơ quan chịu sự giám sát cung cấp thông tin, tài liệu về nội dung giám sát","Đại biểu chuyển kiến nghị của cử tri đến cơ quan có thẩm quyền và theo dõi việc trả lời"],"why":"Chất vấn gắn với trách nhiệm của chính người bị chất vấn và do đại biểu nêu ra. Việc cơ quan, tổ chức, cá nhân giải thích, làm rõ trách nhiệm theo yêu cầu của chủ thể giám sát là giải trình.","cc":"Khoản 7 Điều 2 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsl-003","cd":"gs","m":1,"l":"kt","q":"Theo Luật số 121/2025/QH15, “giải trình” trong hoạt động giám sát là gì?","a":["Cơ quan, tổ chức, cá nhân giải thích, làm rõ trách nhiệm của mình trong thực hiện nhiệm vụ theo yêu cầu của chủ thể giám sát","Đại biểu nêu vấn đề và yêu cầu người đứng đầu cơ quan trả lời về trách nhiệm tại kỳ họp HĐND","Chủ thể giám sát giải thích lý do tiến hành giám sát cho cơ quan chịu sự giám sát","Cơ quan chịu sự giám sát gửi báo cáo công tác định kỳ đến HĐND cùng cấp"],"why":"Giải trình là việc cơ quan, tổ chức, cá nhân giải thích, làm rõ trách nhiệm trong thực hiện nhiệm vụ, quyền hạn được giao theo yêu cầu của chủ thể giám sát; khác với chất vấn do đại biểu nêu vấn đề.","cc":"Khoản 8 Điều 2 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsl-005","cd":"gs","m":1,"l":"kt","q":"Nội dung nào sau đây là một nguyên tắc hoạt động giám sát theo Luật số 121/2025/QH15?","a":["Không làm cản trở hoạt động bình thường của cơ quan, tổ chức, cá nhân chịu sự giám sát","Chỉ tiến hành giám sát khi có đơn khiếu nại, tố cáo của công dân","Giữ kín kết quả giám sát cho đến khi kết thúc nhiệm kỳ HĐND","Giám sát dàn đều các lĩnh vực, không xác định trọng tâm, trọng điểm"],"why":"Luật nêu 6 nguyên tắc, trong đó có: khách quan, công khai, minh bạch, hiệu quả; giám sát toàn diện nhưng có trọng tâm, trọng điểm; không làm cản trở hoạt động bình thường của đối tượng chịu sự giám sát.","cc":"Khoản 6 Điều 3 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsl-008","cd":"gs","m":1,"l":"kt","q":"Theo Luật số 121/2025/QH15, cơ quan, tổ chức, cá nhân chịu sự giám sát có quyền nào sau đây?","a":["Được thông báo trước về kế hoạch, nội dung, yêu cầu giám sát, nội dung yêu cầu báo cáo","Được hoãn thực hiện kết luận giám sát khi chưa đồng ý với kết luận đó","Được từ chối báo cáo nếu chưa có ý kiến của cơ quan cấp trên trực tiếp","Được cử cấp phó giải trình thay mà không cần chủ thể giám sát đồng ý"],"why":"Cơ quan chịu sự giám sát được thông báo trước, được giải trình, bảo vệ tính đúng đắn việc làm của mình và được đề nghị xem xét lại kết luận, kiến nghị giám sát; nhưng vẫn phải báo cáo đầy đủ và thực hiện nghiêm kết luận.","cc":"Khoản 1 Điều 6 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsl-012","cd":"gs","m":1,"l":"kt","q":"Điều 8 Luật số 121/2025/QH15 nêu những tổ chức, cá nhân nào có thể được mời tham gia hoạt động giám sát?","a":["Ủy ban MTTQ Việt Nam và các chuyên gia có chuyên môn, kinh nghiệm về lĩnh vực giám sát","Ban Thanh tra nhân dân và Ban Giám sát đầu tư của cộng đồng","Hội Luật gia và Đoàn Luật sư ở địa phương","Trưởng thôn, tổ trưởng tổ dân phố nơi diễn ra cuộc giám sát"],"why":"Điều 8 nêu Ủy ban MTTQ Việt Nam và các chuyên gia có kiến thức chuyên môn, kinh nghiệm về vấn đề, lĩnh vực giám sát có thể được mời tham gia hoạt động giám sát.","cc":"Khoản 1 Điều 8 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsl-013","cd":"gs","m":1,"l":"kt","q":"Theo Luật số 121/2025/QH15, kết luận, kiến nghị giám sát và văn bản trả lời chất vấn ở HĐND phải được công khai bằng cách nào?","a":["Đăng trên cổng, trang thông tin điện tử của HĐND, phương tiện thông tin đại chúng hoặc hình thức công khai khác theo luật","Chỉ gửi đến cơ quan chịu sự giám sát và lưu hồ sơ tại cơ quan giúp việc của HĐND","Chỉ thông báo tại kỳ họp HĐND gần nhất, không đăng tải rộng rãi","Chỉ cung cấp cho cử tri khi có yêu cầu bằng văn bản gửi Thường trực HĐND"],"why":"Chương trình, kế hoạch, báo cáo kết quả, nghị quyết, kết luận, kiến nghị giám sát, văn bản trả lời chất vấn, trả lời kiến nghị cử tri phải được đăng tải, công khai, trừ trường hợp pháp luật có quy định khác.","cc":"Khoản 1 Điều 10 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsl-014","cd":"gs","m":1,"l":"kt","q":"HĐND báo cáo cử tri địa phương về hoạt động giám sát của mình thông qua hình thức nào?","a":["Phương tiện thông tin đại chúng và hoạt động tiếp xúc cử tri của đại biểu HĐND","Báo cáo bằng văn bản gửi đến từng hộ gia đình mỗi năm một lần","Hội nghị nhân dân do Ủy ban MTTQ Việt Nam cùng cấp triệu tập hằng quý","Niêm yết tại trụ sở UBND và nhà văn hóa thôn, tổ dân phố"],"why":"HĐND báo cáo cử tri địa phương về hoạt động giám sát của mình thông qua phương tiện thông tin đại chúng và hoạt động tiếp xúc cử tri của đại biểu HĐND.","cc":"Khoản 6 Điều 12 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsl-017","cd":"gs","m":1,"l":"kt","q":"Để tiến hành giám sát chuyên đề, HĐND thực hiện theo cách thức nào?","a":["Tổ chức Đoàn giám sát và xem xét báo cáo kết quả giám sát của Đoàn giám sát","Giao UBND cùng cấp tự kiểm tra rồi báo cáo kết quả tại kỳ họp","Tổ chức phiên chất vấn riêng đối với người đứng đầu lĩnh vực đó","Lấy ý kiến cử tri bằng phiếu rồi tổng hợp thành báo cáo giám sát"],"why":"HĐND (cũng như Thường trực HĐND, Ban của HĐND) giám sát chuyên đề bằng cách tổ chức Đoàn giám sát và xem xét báo cáo kết quả giám sát của Đoàn giám sát.","cc":"Điểm d khoản 1 và điểm d khoản 2 Điều 28 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsl-018","cd":"gs","m":1,"l":"kt","q":"Theo Luật số 121/2025/QH15, HĐND lấy phiếu tín nhiệm, bỏ phiếu tín nhiệm đối với đối tượng nào?","a":["Người giữ chức vụ do HĐND bầu","Mọi cán bộ, công chức làm việc tại UBND cùng cấp","Người đứng đầu cơ quan trung ương đóng trên địa bàn","Đại biểu HĐND không giữ chức vụ trong HĐND, UBND"],"why":"HĐND lấy phiếu tín nhiệm, bỏ phiếu tín nhiệm đối với người giữ chức vụ do HĐND bầu, theo quy định của Quốc hội về lấy phiếu tín nhiệm, bỏ phiếu tín nhiệm.","cc":"Khoản 3 Điều 28 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsl-019","cd":"gs","m":1,"l":"kt","q":"Chương trình giám sát hằng năm của HĐND do chủ thể nào quyết định và trên cơ sở nào?","a":["HĐND quyết định, trên cơ sở đề nghị của Thường trực HĐND","Thường trực HĐND quyết định, trên cơ sở đề nghị của các Ban của HĐND","HĐND quyết định, trên cơ sở đề nghị của UBND cùng cấp","Chủ tịch HĐND quyết định, trên cơ sở đề nghị của các Tổ đại biểu HĐND"],"why":"HĐND quyết định chương trình giám sát hằng năm của mình trên cơ sở đề nghị của Thường trực HĐND, rồi giao Thường trực HĐND ban hành kế hoạch và tổ chức thực hiện chương trình.","cc":"Khoản 4 Điều 28 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsl-032","cd":"gs","m":1,"l":"kt","q":"Đối với báo cáo công tác của UBND cùng cấp thuộc lĩnh vực mình phụ trách, Ban của HĐND thực hiện hoạt động giám sát nào?","a":["Thẩm tra báo cáo công tác đó","Phê chuẩn báo cáo công tác đó","Biểu quyết thông qua báo cáo công tác đó","Ra nghị quyết về báo cáo công tác đó"],"why":"Ban của HĐND thẩm tra báo cáo công tác của UBND và các báo cáo khác thuộc lĩnh vực phụ trách hoặc theo phân công của Thường trực HĐND; việc xem xét báo cáo tại kỳ họp thuộc về HĐND.","cc":"Điểm a khoản 2 và điểm a khoản 3 Điều 34 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsl-036","cd":"gs","m":1,"l":"kt","q":"Theo Luật số 121/2025/QH15, đại biểu HĐND cấp xã có quyền chất vấn những ai?","a":["Chủ tịch UBND, thành viên khác của UBND, người đứng đầu cơ quan thuộc UBND cấp xã","Chủ tịch HĐND, Phó Chủ tịch HĐND và Trưởng Ban của HĐND cấp xã","Chủ tịch UBND cấp xã, Chánh án Tòa án nhân dân, Viện trưởng Viện kiểm sát nhân dân khu vực","Chủ tịch UBND cấp xã, Chủ tịch Ủy ban MTTQ Việt Nam cấp xã và các trưởng thôn"],"why":"Đại biểu HĐND cấp xã chất vấn Chủ tịch UBND, thành viên khác của UBND, người đứng đầu cơ quan thuộc UBND cấp xã. Chánh án TAND, Viện trưởng VKSND cấp tỉnh thuộc diện chất vấn của đại biểu HĐND cấp tỉnh.","cc":"Điểm a khoản 2 Điều 36 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsl-039","cd":"gs","m":1,"l":"kt","q":"Theo Luật số 121/2025/QH15, cơ quan nào có trách nhiệm tổ chức để đại biểu HĐND thực hiện giám sát?","a":["Thường trực HĐND","UBND cùng cấp","Ủy ban MTTQ Việt Nam cùng cấp","Ban của HĐND mà đại biểu là thành viên"],"why":"Thường trực HĐND có trách nhiệm tổ chức để đại biểu HĐND thực hiện giám sát; đại biểu báo cáo Thường trực HĐND về chương trình giám sát của mình (nếu có) thông qua Tổ đại biểu HĐND.","cc":"Khoản 3 Điều 36 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsl-040","cd":"gs","m":1,"l":"kt","q":"Tổ đại biểu HĐND giám sát việc thi hành pháp luật ở địa phương trong trường hợp nào?","a":["Khi được HĐND hoặc Thường trực HĐND cùng cấp giao","Khi có ít nhất một phần ba số đại biểu trong Tổ đề nghị","Khi được Ủy ban MTTQ Việt Nam cùng cấp đề nghị phối hợp","Khi Tổ trưởng Tổ đại biểu HĐND xét thấy cần thiết"],"why":"Tổ đại biểu HĐND giám sát việc thi hành pháp luật ở địa phương khi được HĐND hoặc Thường trực HĐND cùng cấp giao và báo cáo kết quả để HĐND, Thường trực HĐND xem xét, quyết định.","cc":"Điều 37 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsl-043","cd":"gs","m":1,"l":"kt","q":"Nghị quyết giám sát của HĐND có giá trị như thế nào đối với cơ quan, tổ chức, cá nhân chịu sự giám sát?","a":["Có giá trị pháp lý bắt buộc thực hiện","Có giá trị tham khảo khi cơ quan chịu sự giám sát xây dựng kế hoạch","Chỉ có giá trị khuyến nghị, thực hiện tùy điều kiện thực tế","Chỉ bắt buộc thực hiện sau khi được UBND cùng cấp phê duyệt"],"why":"Nghị quyết giám sát của HĐND có giá trị pháp lý bắt buộc thực hiện; kết luận, kiến nghị giám sát của Thường trực HĐND, Ban của HĐND và đại biểu HĐND phải được thực hiện nghiêm chỉnh.","cc":"Khoản 1 Điều 40 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsl-048","cd":"gs","m":1,"l":"kt","q":"Luật Hoạt động giám sát của Quốc hội và HĐND số 121/2025/QH15 có hiệu lực thi hành từ ngày nào?","a":["Ngày 01 tháng 3 năm 2026","Ngày 01 tháng 01 năm 2026","Ngày 01 tháng 7 năm 2026","Ngày 10 tháng 12 năm 2025"],"why":"Luật số 121/2025/QH15 được Quốc hội khóa XV thông qua ngày 10/12/2025 và có hiệu lực thi hành từ ngày 01/3/2026, thay thế Luật số 87/2015/QH13.","cc":"Khoản 1 Điều 44 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsh-003","cd":"gs","m":2,"l":"th","q":"Một Ban của HĐND xã A dự định giám sát một đơn vị sự nghiệp công lập thuộc UBND xã. Theo Nghị quyết số 114/2025/UBTVQH15, đơn vị này có thuộc đối tượng giám sát của Ban không?","a":["Có, vì đơn vị sự nghiệp công lập thuộc UBND cấp xã là đối tượng giám sát của Ban","Không, vì Ban của HĐND cấp xã chỉ được giám sát UBND cấp xã","Không, vì chỉ Thường trực HĐND cấp xã mới được giám sát đơn vị này","Chỉ khi được HĐND cấp tỉnh giao nhiệm vụ bằng nghị quyết"],"why":"Thường trực HĐND và Ban của HĐND cấp xã giám sát UBND cấp xã, cơ quan chuyên môn, tổ chức hành chính khác và đơn vị sự nghiệp công lập thuộc UBND cấp xã, cùng cơ quan nhà nước khác ở địa phương.","cc":"Điểm b khoản 2 Điều 3 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-004","cd":"gs","m":2,"l":"kt","q":"Ban của HĐND, Tổ đại biểu, đại biểu HĐND và Ủy ban MTTQ Việt Nam cùng cấp gửi đề xuất nội dung đưa vào chương trình giám sát năm sau đến Thường trực HĐND chậm nhất khi nào?","a":["30 ngày trước ngày khai mạc kỳ họp thường lệ cuối năm trước","15 ngày trước ngày khai mạc kỳ họp thường lệ cuối năm trước","07 ngày trước ngày khai mạc kỳ họp thường lệ cuối năm trước","Ngày 20 tháng 12 của năm trước"],"why":"Đề xuất phải gửi chậm nhất 30 ngày trước ngày khai mạc kỳ họp thường lệ cuối năm trước, nêu rõ sự cần thiết, nội dung, phạm vi, đối tượng và thời gian giám sát để cơ quan giúp việc kịp tổng hợp.","cc":"Khoản 1 Điều 5 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-007","cd":"gs","m":2,"l":"th","q":"Giữa hai kỳ họp, do yêu cầu của thực tiễn, cần điều chỉnh một nội dung trong chương trình giám sát năm của HĐND tỉnh. Theo Nghị quyết số 114/2025/UBTVQH15, việc này được xử lý thế nào?","a":["Thường trực HĐND quyết định điều chỉnh và báo cáo HĐND tại kỳ họp gần nhất","Phải chờ đến kỳ họp để HĐND quyết định, Thường trực HĐND không được điều chỉnh","Chủ tịch HĐND quyết định điều chỉnh sau khi xin ý kiến UBND cùng cấp","Thường trực HĐND quyết định điều chỉnh và không phải báo cáo lại HĐND"],"why":"Trong thời gian HĐND không họp, Thường trực HĐND được quyết định điều chỉnh chương trình giám sát của HĐND nhưng phải báo cáo HĐND tại kỳ họp gần nhất.","cc":"Khoản 2 Điều 10 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-008","cd":"gs","m":2,"l":"kt","q":"Ban của HĐND xem xét, thông qua chương trình giám sát năm sau của Ban chậm nhất vào ngày nào?","a":["Ngày 20 tháng 12 của năm trước","Ngày 30 tháng 12 của năm trước","Ngày 15 tháng 12 của năm trước","Ngày 25 tháng 12 của năm trước"],"why":"Ban của HĐND thông qua chương trình giám sát năm sau chậm nhất ngày 20/12 của năm trước và báo cáo Thường trực HĐND cùng cấp; mốc 30/12 là hạn đại biểu HĐND báo cáo chương trình giám sát của mình (nếu có).","cc":"Khoản 1 Điều 13 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-010","cd":"gs","m":2,"l":"kt","q":"Khi HĐND xem xét tại kỳ họp một báo cáo có yêu cầu thẩm tra, ngay sau khi người đứng đầu cơ quan có báo cáo trình bày báo cáo thì bước tiếp theo là gì?","a":["Trưởng Ban của HĐND trình bày báo cáo thẩm tra","HĐND thảo luận về nội dung báo cáo","Người đứng đầu cơ quan có báo cáo giải trình các vấn đề liên quan","HĐND xem xét, quyết định việc ban hành nghị quyết"],"why":"Trình tự: người đứng đầu cơ quan trình bày báo cáo; Trưởng Ban của HĐND trình bày báo cáo thẩm tra; HĐND thảo luận; người đứng đầu cơ quan giải trình; HĐND xem xét, quyết định việc ban hành nghị quyết.","cc":"Khoản 2 Điều 16 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-011","cd":"gs","m":2,"l":"th","q":"Giữa hai kỳ họp, Thường trực HĐND xã A được HĐND xã giao xem xét báo cáo công tác của UBND xã. Sau khi thảo luận và nghe giải trình, Thường trực HĐND kết thúc việc xem xét bằng hình thức nào?","a":["Kết luận về công tác của cơ quan có báo cáo và báo cáo HĐND về kết quả xem xét","Thay mặt HĐND ban hành nghị quyết về công tác của cơ quan có báo cáo","Ra quyết định xử lý trách nhiệm người đứng đầu cơ quan có báo cáo","Lập biên bản phiên họp và gửi UBND cấp tỉnh xem xét, quyết định"],"why":"HĐND xem xét báo cáo tại kỳ họp thì quyết định việc ban hành nghị quyết; còn Thường trực HĐND xem xét báo cáo giữa hai kỳ họp thì kết luận về công tác của cơ quan có báo cáo và báo cáo HĐND về kết quả xem xét.","cc":"Điểm e khoản 1 và khoản 3 Điều 17 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-014","cd":"gs","m":2,"l":"th","q":"HĐND tỉnh đã lựa chọn Giám đốc Sở X trả lời chất vấn tại kỳ họp. Báo cáo bằng văn bản của Giám đốc Sở về nội dung thuộc nhóm vấn đề chất vấn phải được gửi đến đại biểu HĐND chậm nhất khi nào?","a":["05 ngày trước ngày tổ chức phiên chất vấn","03 ngày trước ngày tổ chức phiên chất vấn","10 ngày trước ngày khai mạc kỳ họp HĐND","Ngay tại phiên chất vấn, trước khi đại biểu nêu câu hỏi"],"why":"Báo cáo của người bị chất vấn phải gửi đến đại biểu HĐND chậm nhất 05 ngày trước ngày tổ chức phiên chất vấn; mốc 03 ngày là hạn thông báo dự kiến chương trình phiên chất vấn.","cc":"Điểm a khoản 1 Điều 22 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-015","cd":"gs","m":2,"l":"th","q":"Chủ tịch UBND xã A là người bị chất vấn tại kỳ họp HĐND xã nhưng có lịch công tác đột xuất nên muốn ủy quyền cho một Phó Chủ tịch UBND xã trả lời thay. Theo Nghị quyết số 114/2025/UBTVQH15, cách xử lý nào đúng?","a":["Không được ủy quyền; gửi văn bản nêu rõ lý do đến Thường trực HĐND để báo cáo HĐND quyết định","Được ủy quyền cho cấp phó nếu Chủ tịch HĐND đồng ý bằng văn bản","Được ủy quyền cho cấp phó nhưng phải chịu trách nhiệm về nội dung trả lời","Không cần báo cáo; nội dung chất vấn tự động chuyển sang trả lời bằng văn bản"],"why":"Người bị chất vấn không được ủy quyền cho người khác trả lời thay, trừ trường hợp luật có quy định khác; nếu không thể trực tiếp tham dự thì gửi văn bản nêu rõ lý do đến Thường trực HĐND để báo cáo HĐND xem xét, quyết định.","cc":"Khoản 2 Điều 22 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-019","cd":"gs","m":2,"l":"th","q":"Tại phiên chất vấn của HĐND xã B, một đại biểu chất vấn đúng nhóm vấn đề đã chọn, nhưng nội dung cần được điều tra, xác minh mới trả lời được. Theo Nghị quyết số 114/2025/UBTVQH15, HĐND xử lý thế nào?","a":["Cho người bị chất vấn trả lời chất vấn đó bằng văn bản","Buộc người bị chất vấn trả lời ngay tại phiên chất vấn","Chuyển chất vấn đó cho cơ quan thanh tra trả lời thay người bị chất vấn","Hủy chất vấn đó vì không đủ điều kiện trả lời tại kỳ họp"],"why":"HĐND cho trả lời bằng văn bản khi chất vấn không thuộc nhóm vấn đề chất vấn; thuộc nhóm vấn đề nhưng cần điều tra, xác minh; hoặc thuộc nhóm vấn đề nhưng chưa được trả lời tại phiên chất vấn.","cc":"Điểm b khoản 1 Điều 25 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-020","cd":"gs","m":2,"l":"kt","q":"Người bị chất vấn phải trả lời bằng văn bản cho đại biểu HĐND đã chất vấn chậm nhất bao nhiêu ngày kể từ ngày nhận được văn bản của cơ quan giúp việc của HĐND?","a":["20 ngày","10 ngày","15 ngày","30 ngày"],"why":"Thời hạn trả lời là 20 ngày kể từ ngày nhận văn bản của cơ quan giúp việc của HĐND; mốc 30 ngày là thời hạn để đại biểu kiến nghị nếu không đồng ý với nội dung trả lời.","cc":"Khoản 2 Điều 25 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-023","cd":"gs","m":2,"l":"kt","q":"Kết thúc phiên chất vấn tại phiên họp Thường trực HĐND, kết luận về chất vấn được thông qua khi nào?","a":["Khi có quá nửa tổng số thành viên Thường trực HĐND biểu quyết tán thành","Khi có ít nhất hai phần ba tổng số thành viên Thường trực HĐND biểu quyết tán thành","Khi có quá nửa số đại biểu HĐND dự phiên chất vấn biểu quyết tán thành","Khi Chủ tịch HĐND ký ban hành, không cần biểu quyết"],"why":"Kết thúc phiên chất vấn, Thường trực HĐND thông qua kết luận về chất vấn; kết luận được thông qua khi có quá nửa tổng số thành viên Thường trực HĐND biểu quyết tán thành.","cc":"Khoản 7 Điều 30 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-033","cd":"gs","m":2,"l":"kt","q":"Nghị quyết của HĐND thành lập Đoàn giám sát chuyên đề xác định Trưởng Đoàn, Phó Trưởng Đoàn và cơ cấu thành viên khác. Sau đó, ai quyết định thành viên cụ thể tham gia Đoàn giám sát?","a":["Thường trực HĐND","Trưởng Đoàn giám sát","Ban của HĐND phụ trách lĩnh vực","Cơ quan giúp việc của HĐND"],"why":"Căn cứ nghị quyết của HĐND, Thường trực HĐND quyết định thành viên cụ thể tham gia Đoàn giám sát và điều chỉnh thành phần Đoàn khi cần thiết theo đề nghị của Trưởng Đoàn giám sát.","cc":"Điểm a khoản 3 Điều 40 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-035","cd":"gs","m":2,"l":"th","q":"Đoàn giám sát chuyên đề của HĐND xã A ban hành kế hoạch giám sát và yêu cầu UBND xã gửi báo cáo sau 10 ngày. Theo Nghị quyết số 114/2025/UBTVQH15, yêu cầu về thời gian này có đúng không?","a":["Không đúng, vì thời gian xây dựng và gửi báo cáo không được ít hơn 20 ngày kể từ ngày ban hành kế hoạch","Đúng, vì thời gian gửi báo cáo hoàn toàn do Đoàn giám sát quyết định, không có mức tối thiểu","Không đúng, vì thời gian tối thiểu là 30 ngày kể từ ngày ban hành kế hoạch giám sát","Đúng, vì quy định chỉ yêu cầu tối thiểu 07 ngày kể từ ngày ban hành kế hoạch giám sát"],"why":"Thời gian để cơ quan chịu sự giám sát xây dựng và gửi báo cáo do Đoàn giám sát quyết định nhưng không ít hơn 20 ngày kể từ ngày ban hành kế hoạch, nhằm bảo đảm đủ thời gian chuẩn bị báo cáo có chất lượng.","cc":"Điểm a khoản 4 Điều 40 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-041","cd":"gs","m":2,"l":"th","q":"Đại biểu HĐND xã B đã quyết định nội dung, kế hoạch giám sát việc thi hành pháp luật tại một đơn vị và báo cáo Thường trực HĐND xã. Ai có trách nhiệm thông báo nội dung, kế hoạch này đến đơn vị chịu sự giám sát và trong thời hạn nào?","a":["Thường trực HĐND, cơ quan giúp việc của HĐND; chậm nhất 10 ngày trước ngày giám sát","Chính đại biểu HĐND tiến hành giám sát; chậm nhất 03 ngày trước ngày giám sát","Tổ trưởng Tổ đại biểu HĐND; chậm nhất 05 ngày trước ngày giám sát","UBND cùng cấp; chậm nhất 15 ngày trước ngày giám sát"],"why":"Thường trực HĐND và cơ quan giúp việc của HĐND có trách nhiệm tổ chức để đại biểu tiến hành giám sát, thông báo nội dung, kế hoạch giám sát đến đối tượng chậm nhất 10 ngày trước ngày tiến hành và hỗ trợ theo dõi, đôn đốc sau giám sát.","cc":"Khoản 5 Điều 49 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-044","cd":"gs","m":2,"l":"th","q":"Đại biểu HĐND xã A nhận thấy văn bản trả lời của cơ quan chức năng đối với một kiến nghị mà mình tiếp nhận khi tiếp xúc cử tri là chưa thỏa đáng. Theo Nghị quyết số 114/2025/UBTVQH15, kết quả xem xét, đánh giá của đại biểu được gửi đến đâu?","a":["Thường trực HĐND, thông qua Tổ đại biểu HĐND, để tổng hợp và phối hợp giám sát","Trực tiếp đến Chủ tịch UBND cùng cấp để yêu cầu trả lời lại cử tri","Ủy ban MTTQ Việt Nam cùng cấp để tổ chức đối thoại với cử tri","Cơ quan thanh tra cấp tỉnh để tiến hành thanh tra việc trả lời"],"why":"Đại biểu HĐND xem xét, đánh giá kết quả giải quyết, trả lời đối với kiến nghị mình nhận được qua tiếp xúc cử tri và gửi kết quả đến Thường trực HĐND qua Tổ đại biểu HĐND để tổng hợp và phối hợp giám sát.","cc":"Điểm a khoản 1 Điều 55 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-045","cd":"gs","m":2,"l":"th","q":"Một Ban của HĐND tỉnh đã ban hành kết luận giám sát nhưng cơ quan chịu sự giám sát không thực hiện. Theo Nghị quyết số 114/2025/UBTVQH15, Ban có quyền gì?","a":["Kiến nghị với Thường trực HĐND để báo cáo HĐND xem xét, quyết định","Ra quyết định xử phạt người đứng đầu cơ quan chịu sự giám sát","Đề nghị UBND cùng cấp cưỡng chế thi hành kết luận giám sát","Tự tổ chức bỏ phiếu tín nhiệm đối với người đứng đầu cơ quan đó"],"why":"Khi đối tượng không thực hiện hoặc thực hiện không đầy đủ kết luận, kiến nghị giám sát, Ban của HĐND và đại biểu HĐND có quyền kiến nghị với Thường trực HĐND để báo cáo HĐND xem xét, quyết định bằng nghị quyết.","cc":"Khoản 1 Điều 59 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-047","cd":"gs","m":2,"l":"kt","q":"Ban của HĐND, Tổ đại biểu HĐND báo cáo bằng văn bản đến Thường trực HĐND về kết quả sơ bộ các hoạt động giám sát trong tháng (nếu có) và dự kiến kế hoạch của tháng tiếp theo chậm nhất vào ngày nào?","a":["Ngày 25 hằng tháng","Ngày 20 hằng tháng","Ngày 15 hằng tháng","Ngày cuối cùng của tháng"],"why":"Chậm nhất ngày 25 hằng tháng, Ban và Tổ đại biểu báo cáo bằng văn bản đến Thường trực HĐND, nêu rõ nội dung, thời gian, thành phần, địa điểm làm việc để Thường trực điều hòa, tránh trùng lặp; đại biểu HĐND báo cáo qua Tổ đại biểu.","cc":"Khoản 2 Điều 62 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-048","cd":"gs","m":2,"l":"th","q":"Do yêu cầu của thực tiễn, một đại biểu HĐND tỉnh cần lùi thời gian một cuộc giám sát trong kế hoạch giám sát của mình. Theo Nghị quyết số 114/2025/UBTVQH15, đại biểu phải làm gì?","a":["Báo cáo trước đến Thường trực HĐND, thông qua Tổ đại biểu HĐND","Tự điều chỉnh, chỉ cần thông báo cho cơ quan chịu sự giám sát","Xin ý kiến chấp thuận của Chủ tịch UBND cùng cấp trước khi điều chỉnh","Chỉ cần nêu trong báo cáo tháng sau khi đã thực hiện xong việc điều chỉnh"],"why":"Khi phải điều chỉnh kế hoạch giám sát, Ban, Tổ đại biểu và đại biểu HĐND có trách nhiệm báo cáo trước đến Thường trực HĐND để chỉ đạo, điều hòa, phối hợp; đại biểu HĐND báo cáo qua Tổ đại biểu HĐND.","cc":"Khoản 1 Điều 62 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-053","cd":"gs","m":2,"l":"kt","q":"Theo Nghị quyết số 96/2023/QH15, Thường trực HĐND trình HĐND bỏ phiếu tín nhiệm đối với người giữ chức vụ do HĐND bầu khi có kiến nghị của ít nhất bao nhiêu đại biểu HĐND?","a":["Một phần ba tổng số đại biểu HĐND","20% tổng số đại biểu HĐND","Quá nửa tổng số đại biểu HĐND","Hai phần ba tổng số đại biểu HĐND"],"why":"Ở HĐND, cần kiến nghị của ít nhất một phần ba tổng số đại biểu (hoặc kiến nghị của Ủy ban MTTQ Việt Nam cùng cấp); tỷ lệ 20% là quy định đối với kiến nghị của đại biểu Quốc hội.","cc":"Điểm a khoản 2 Điều 13 Nghị quyết số 96/2023/QH15"},{"id":"gsh-054","cd":"gs","m":2,"l":"kt","q":"Theo Nghị quyết số 96/2023/QH15, người được HĐND bỏ phiếu tín nhiệm sẽ bị trình HĐND xem xét, quyết định việc miễn nhiệm khi số phiếu đánh giá “không tín nhiệm” đạt tỷ lệ nào?","a":["Quá nửa tổng số phiếu","Từ hai phần ba tổng số phiếu trở lên","Từ một phần ba tổng số phiếu trở lên","Từ 20% tổng số phiếu trở lên"],"why":"Người được bỏ phiếu tín nhiệm có quá nửa tổng số phiếu “không tín nhiệm” thì cơ quan, người đã giới thiệu để HĐND bầu có trách nhiệm trình HĐND xem xét, quyết định việc miễn nhiệm tại kỳ họp đó hoặc kỳ họp gần nhất.","cc":"Điều 17 Nghị quyết số 96/2023/QH15"},{"id":"gsh-055","cd":"gs","m":2,"l":"th","q":"Tháng 3 của năm HĐND tỉnh tổ chức lấy phiếu tín nhiệm, ông K được HĐND tỉnh bầu làm Trưởng Ban của HĐND tỉnh. Theo Nghị quyết số 96/2023/QH15, tại kỳ họp cuối năm đó, ông K có thuộc diện được lấy phiếu tín nhiệm không?","a":["Không, vì không lấy phiếu tín nhiệm đối với người được bầu trong năm lấy phiếu tín nhiệm","Có, vì Trưởng Ban của HĐND là chức vụ thuộc diện được lấy phiếu tín nhiệm","Có, nếu đã giữ chức vụ đủ 06 tháng tính đến ngày khai mạc kỳ họp","Không, vì chỉ lấy phiếu tín nhiệm đối với các chức vụ thuộc UBND"],"why":"Trưởng Ban của HĐND cấp tỉnh thuộc diện lấy phiếu tín nhiệm, nhưng không lấy phiếu đối với người đã có thông báo nghỉ công tác chờ nghỉ hưu hoặc được bầu, bổ nhiệm trong năm lấy phiếu tín nhiệm.","cc":"Khoản 5 Điều 2 Nghị quyết số 96/2023/QH15"},{"id":"gsl-004","cd":"gs","m":2,"l":"kt","q":"Theo Luật số 121/2025/QH15, “giám sát chuyên đề” là gì?","a":["Giám sát về vấn đề hoặc lĩnh vực hoạt động của cơ quan, tổ chức, cá nhân chịu sự giám sát trong việc tuân theo pháp luật","Giám sát về tính hợp hiến, tính hợp pháp, tính thống nhất của văn bản quy phạm pháp luật","Giám sát do HĐND thực hiện tại kỳ họp đối với báo cáo công tác của các cơ quan","Giám sát việc giải quyết một vụ việc khiếu nại, tố cáo cụ thể của công dân"],"why":"Giám sát chuyên đề hướng vào một vấn đề hoặc lĩnh vực hoạt động của đối tượng chịu sự giám sát. Việc xem xét tính hợp hiến, hợp pháp, thống nhất của văn bản là giám sát văn bản quy phạm pháp luật.","cc":"Khoản 5 Điều 2 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsl-006","cd":"gs","m":2,"l":"kt","q":"Khi chủ thể giám sát yêu cầu áp dụng biện pháp cần thiết để kịp thời chấm dứt hành vi vi phạm pháp luật, cơ quan, tổ chức, cá nhân có thẩm quyền phải giải quyết và trả lời trong thời hạn nào?","a":["15 ngày kể từ ngày nhận được yêu cầu","05 ngày làm việc kể từ ngày nhận được yêu cầu","10 ngày kể từ ngày nhận được yêu cầu","30 ngày kể từ ngày nhận được yêu cầu"],"why":"Thời hạn giải quyết và trả lời là 15 ngày kể từ ngày nhận được yêu cầu. Thời hạn 30 ngày chỉ áp dụng cho người đứng đầu cơ quan, tổ chức cấp trên khi vụ việc được chuyển lên do quá hạn không trả lời.","cc":"Khoản 4 Điều 4 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsl-009","cd":"gs","m":2,"l":"kt","q":"Trong trường hợp thông thường, cơ quan chịu sự giám sát phải cung cấp thông tin, tài liệu theo yêu cầu của chủ thể giám sát trong thời hạn nào?","a":["05 ngày làm việc kể từ ngày nhận được yêu cầu","03 ngày làm việc kể từ ngày nhận được yêu cầu","07 ngày làm việc kể từ ngày nhận được yêu cầu","15 ngày kể từ ngày nhận được yêu cầu"],"why":"Thông tin, tài liệu phải được cung cấp trong 05 ngày làm việc kể từ ngày nhận được yêu cầu; chỉ khi phức tạp, cần thời gian tổng hợp thì thời hạn mới có thể dài hơn nhưng không quá 15 ngày.","cc":"Khoản 2 Điều 7 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsl-010","cd":"gs","m":2,"l":"th","q":"Đoàn giám sát của Thường trực HĐND tỉnh yêu cầu Giám đốc một sở trực tiếp báo cáo, giải trình. Giám đốc sở không thể trực tiếp tham dự và muốn để Phó Giám đốc báo cáo thay. Theo Luật số 121/2025/QH15, việc này được thực hiện với điều kiện nào?","a":["Giám đốc sở ủy quyền cho cấp phó và phải được sự đồng ý của chủ thể giám sát","Giám đốc sở chỉ cần có văn bản ủy quyền, không cần ý kiến của chủ thể giám sát","Phải được Chủ tịch UBND tỉnh đồng ý bằng văn bản trước khi ủy quyền","Không thể thực hiện vì luật cấm ủy quyền trong mọi hoạt động giám sát"],"why":"Người đứng đầu có trách nhiệm trực tiếp báo cáo, giải trình; nếu không thể thì ủy quyền cho cấp phó khi được chủ thể giám sát đồng ý. Riêng chất vấn thì không được ủy quyền, trừ khi luật khác quy định khác.","cc":"Khoản 3 Điều 7 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsl-011","cd":"gs","m":2,"l":"th","q":"Tại kỳ họp HĐND xã B, Chủ tịch UBND xã bị chất vấn về tiến độ một công trình. Ông đề nghị để một Phó Chủ tịch UBND xã trả lời thay. Theo Luật số 121/2025/QH15, đề nghị này được xử lý thế nào?","a":["Không được; người bị chất vấn không được ủy quyền trả lời thay, trừ khi luật khác có quy định khác","Được, nếu Phó Chủ tịch là người trực tiếp phụ trách lĩnh vực bị chất vấn","Được, nếu được chủ tọa kỳ họp HĐND xã đồng ý ngay tại phiên chất vấn","Được, nếu có văn bản ủy quyền gửi trước cho Thường trực HĐND xã"],"why":"Với báo cáo, giải trình thì có thể ủy quyền cho cấp phó nếu chủ thể giám sát đồng ý; nhưng với chất vấn, người bị chất vấn không được ủy quyền cho người khác trả lời thay, trừ trường hợp luật khác có quy định khác.","cc":"Khoản 3 Điều 7 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsl-015","cd":"gs","m":2,"l":"kt","q":"Đại biểu HĐND báo cáo kết quả thực hiện chương trình giám sát của mình với cơ quan nào và bằng cách nào?","a":["Báo cáo Thường trực HĐND thông qua Tổ đại biểu HĐND","Báo cáo trực tiếp HĐND tại kỳ họp thường lệ cuối năm","Báo cáo Ban của HĐND mà đại biểu là thành viên","Báo cáo Chủ tịch HĐND thông qua cơ quan giúp việc của HĐND"],"why":"Đại biểu HĐND báo cáo Thường trực HĐND về kết quả thực hiện chương trình giám sát của mình thông qua Tổ đại biểu HĐND; đồng thời báo cáo cử tri địa phương qua hoạt động tiếp xúc cử tri.","cc":"Khoản 10 Điều 12 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsl-016","cd":"gs","m":2,"l":"th","q":"HĐND tỉnh nhận thấy cần giám sát việc tuân theo pháp luật của một số cơ quan, tổ chức ở xã C do yêu cầu của thực tiễn. Theo Luật số 121/2025/QH15, HĐND tỉnh có được tiến hành giám sát các cơ quan, tổ chức ở cấp xã này không?","a":["Có, trong trường hợp cần thiết do yêu cầu của thực tiễn","Không, việc giám sát ở cấp xã chỉ thuộc thẩm quyền của HĐND cấp xã","Có, nhưng phải được UBTVQH chấp thuận trước bằng văn bản","Có, nhưng chỉ khi HĐND xã C có văn bản đề nghị HĐND tỉnh giám sát"],"why":"Ngoài các đối tượng ở cấp tỉnh, trường hợp cần thiết do yêu cầu của thực tiễn, HĐND cấp tỉnh tiến hành giám sát hoạt động của cơ quan, tổ chức, cá nhân khác ở cấp xã trong việc tuân theo Hiến pháp và pháp luật.","cc":"Khoản 1 Điều 27 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsl-021","cd":"gs","m":2,"l":"kt","q":"Khi xem xét kết quả giám sát, đối với văn bản quy phạm pháp luật thuộc đối tượng giám sát của mình mà trái với Hiến pháp, văn bản của cơ quan nhà nước cấp trên, nghị quyết của mình, HĐND cấp xã có thẩm quyền gì?","a":["Đình chỉ việc thi hành, bãi bỏ một phần hoặc toàn bộ văn bản đó","Chỉ kiến nghị HĐND cấp tỉnh xem xét bãi bỏ văn bản đó","Chỉ đình chỉ việc thi hành và đề nghị Chủ tịch UBND cấp tỉnh bãi bỏ","Chỉ yêu cầu cơ quan ban hành tự sửa đổi trong thời hạn 30 ngày"],"why":"HĐND cấp xã có quyền đình chỉ việc thi hành, bãi bỏ một phần hoặc toàn bộ văn bản quy phạm pháp luật (loại quy định tại khoản 15 Điều 4 Luật Ban hành văn bản quy phạm pháp luật) trái Hiến pháp, văn bản cấp trên, nghị quyết của HĐND cấp xã.","cc":"Khoản 1 Điều 29 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsl-023","cd":"gs","m":2,"l":"kt","q":"HĐND cấp tỉnh giải tán HĐND cấp xã trong trường hợp nào và phải trình cơ quan nào phê chuẩn?","a":["Khi HĐND cấp xã làm thiệt hại nghiêm trọng đến lợi ích của Nhân dân; trình UBTVQH phê chuẩn","Khi HĐND cấp xã không họp đủ số kỳ họp trong năm; trình Chính phủ phê chuẩn","Khi HĐND cấp xã ban hành nghị quyết trái pháp luật; trình Thủ tướng Chính phủ phê chuẩn","Khi HĐND cấp xã làm thiệt hại nghiêm trọng đến lợi ích của Nhân dân; trình Quốc hội phê chuẩn"],"why":"HĐND cấp tỉnh giải tán HĐND cấp xã khi HĐND đó làm thiệt hại nghiêm trọng đến lợi ích của Nhân dân và trình Ủy ban Thường vụ Quốc hội phê chuẩn.","cc":"Khoản 3 Điều 29 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsl-025","cd":"gs","m":2,"l":"kt","q":"Hoạt động nào sau đây là hoạt động giám sát của Thường trực HĐND (ở cấp tỉnh và cấp xã) theo Điều 31 Luật số 121/2025/QH15?","a":["Giám sát việc giải quyết, trả lời kiến nghị của cử tri","Thẩm tra báo cáo công tác của UBND cùng cấp","Lấy phiếu tín nhiệm đối với người giữ chức vụ do HĐND bầu","Bãi bỏ văn bản quy phạm pháp luật trái với nghị quyết của HĐND"],"why":"Thường trực HĐND giám sát việc giải quyết, trả lời kiến nghị của cử tri. Thẩm tra báo cáo là hoạt động của Ban; lấy phiếu tín nhiệm, bãi bỏ văn bản trái pháp luật là thẩm quyền của HĐND.","cc":"Điểm d khoản 1 Điều 31 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsl-026","cd":"gs","m":2,"l":"kt","q":"Thường trực HĐND cấp xã tổ chức hoạt động giải trình tại phiên họp Thường trực HĐND để yêu cầu ai giải trình?","a":["Thành viên của UBND cấp xã; cá nhân có liên quan tham gia giải trình","Chủ tịch HĐND, Trưởng Ban của HĐND cấp xã và cá nhân có liên quan","Chánh án Tòa án nhân dân, Viện trưởng Viện kiểm sát nhân dân khu vực","Chủ tịch Ủy ban MTTQ Việt Nam cấp xã và người đứng đầu các đoàn thể"],"why":"Ở cấp xã, Thường trực HĐND yêu cầu thành viên UBND cấp xã giải trình, cá nhân có liên quan tham gia giải trình. Chánh án, Viện trưởng khu vực thuộc diện giải trình trước Thường trực HĐND cấp tỉnh.","cc":"Điểm d khoản 3 Điều 31 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsl-029","cd":"gs","m":2,"l":"th","q":"Thường trực HĐND xã H kiến nghị UBND xã giải quyết vướng mắc trong thực hiện một chính sách hỗ trợ ở địa phương (không phải kiến nghị về văn bản quy phạm pháp luật). Theo Luật số 121/2025/QH15, UBND xã phải xem xét và trả lời trong thời hạn nào?","a":["15 ngày; bất khả kháng hoặc nội dung phức tạp thì có thể dài hơn nhưng không quá 30 ngày","05 ngày làm việc; nội dung phức tạp thì có thể dài hơn nhưng không quá 15 ngày","30 ngày; bất khả kháng hoặc nội dung phức tạp thì có thể dài hơn nhưng không quá 60 ngày","10 ngày; bất khả kháng hoặc nội dung phức tạp thì có thể dài hơn nhưng không quá 20 ngày"],"why":"Kiến nghị giải quyết vấn đề về thực hiện chủ trương, chính sách, pháp luật: trả lời trong 15 ngày, tối đa 30 ngày nếu bất khả kháng hoặc phức tạp. Kiến nghị xử lý văn bản quy phạm pháp luật trái pháp luật: 30 ngày.","cc":"Khoản 2 Điều 32 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsl-030","cd":"gs","m":2,"l":"th","q":"Qua giám sát, Thường trực HĐND xã K thấy một Phó Chủ tịch UBND xã có vi phạm đến mức cần xem xét bãi nhiệm. Theo Luật số 121/2025/QH15, Thường trực HĐND xã có thẩm quyền gì?","a":["Kiến nghị HĐND xã miễn nhiệm, bãi nhiệm Phó Chủ tịch UBND xã","Tự quyết định bãi nhiệm rồi báo cáo HĐND xã tại kỳ họp gần nhất","Đình chỉ công tác Phó Chủ tịch UBND xã trong thời gian chờ xử lý","Kiến nghị Thường trực HĐND cấp tỉnh quyết định miễn nhiệm, bãi nhiệm"],"why":"Miễn nhiệm, bãi nhiệm Chủ tịch, Phó Chủ tịch, Ủy viên UBND cấp xã thuộc thẩm quyền của HĐND cấp xã; Thường trực HĐND cấp xã chỉ có quyền kiến nghị HĐND cấp xã xem xét.","cc":"Khoản 3 Điều 32 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsl-033","cd":"gs","m":2,"l":"kt","q":"Ban của HĐND giám sát việc giải quyết, trả lời kiến nghị của cử tri trên cơ sở nào?","a":["Theo phân công của Thường trực HĐND cùng cấp","Theo đề nghị của Ủy ban MTTQ Việt Nam cùng cấp","Theo yêu cầu của Chủ tịch UBND cùng cấp","Theo nghị quyết riêng của HĐND tại mỗi kỳ họp"],"why":"Thường trực HĐND trực tiếp giám sát việc giải quyết, trả lời kiến nghị của cử tri; còn Ban của HĐND thực hiện hoạt động này theo phân công của Thường trực HĐND cùng cấp.","cc":"Điểm c khoản 1 Điều 34 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsl-034","cd":"gs","m":2,"l":"kt","q":"Chương trình giám sát hằng năm của Ban của HĐND được quyết định như thế nào?","a":["Ban tự quyết định, tổ chức thực hiện và báo cáo Thường trực HĐND về chương trình","Thường trực HĐND quyết định và giao Ban tổ chức thực hiện","HĐND quyết định tại kỳ họp theo đề nghị của Trưởng Ban","Ban xây dựng, trình Chủ tịch HĐND phê duyệt trước khi thực hiện"],"why":"Ban của HĐND quyết định và tổ chức thực hiện chương trình giám sát hằng năm của mình, có thể điều chỉnh khi cần thiết, và có trách nhiệm báo cáo Thường trực HĐND về chương trình giám sát đó.","cc":"Khoản 4 Điều 34 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsl-035","cd":"gs","m":2,"l":"th","q":"Qua giám sát, một Ban của HĐND tỉnh phát hiện một văn bản quy phạm pháp luật ở địa phương có dấu hiệu trái với nghị quyết của HĐND tỉnh và kiến nghị cơ quan có thẩm quyền ở địa phương bãi bỏ. Cơ quan nhận kiến nghị phải xem xét, trả lời trong thời hạn nào?","a":["30 ngày kể từ ngày nhận được kiến nghị","15 ngày kể từ ngày nhận được kiến nghị","05 ngày làm việc kể từ ngày nhận được kiến nghị","60 ngày kể từ ngày nhận được kiến nghị"],"why":"Với kiến nghị sửa đổi, bổ sung, thay thế, tạm ngưng hiệu lực, đình chỉ thi hành, bãi bỏ văn bản quy phạm pháp luật, thời hạn trả lời là 30 ngày. Thời hạn 15 ngày áp dụng cho kiến nghị giải quyết vấn đề về thực hiện chính sách, pháp luật.","cc":"Khoản 1 Điều 35 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsl-044","cd":"gs","m":2,"l":"th","q":"UBND xã P không đồng ý với một kết luận giám sát của Ban của HĐND xã liên quan đến hoạt động của mình và có văn bản đề nghị Ban xem xét lại. Theo Luật số 121/2025/QH15, Ban của HĐND xã phải xem xét và trả lời trong thời hạn nào?","a":["15 ngày kể từ ngày nhận được đề nghị; trường hợp bất khả kháng hoặc phức tạp thì không quá 30 ngày","05 ngày làm việc kể từ ngày nhận được đề nghị; trường hợp phức tạp thì không quá 15 ngày","30 ngày kể từ ngày nhận được đề nghị; trường hợp bất khả kháng hoặc phức tạp thì không quá 45 ngày","Chậm nhất tại kỳ họp HĐND xã gần nhất sau ngày nhận được đề nghị"],"why":"Cơ quan chịu sự giám sát có quyền đề nghị xem xét lại kết luận, kiến nghị giám sát. Chủ thể giám sát phải xem xét, trả lời trong 15 ngày; bất khả kháng hoặc có nhiều nội dung phức tạp thì không quá 30 ngày.","cc":"Khoản 2 Điều 40 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsl-046","cd":"gs","m":2,"l":"th","q":"Một sở không thực hiện kết luận giám sát của Ban của HĐND tỉnh. Theo Luật số 121/2025/QH15, trước khi quyết định xử lý theo thẩm quyền hoặc kiến nghị xử lý, Ban của HĐND tỉnh thực hiện bước nào?","a":["Yêu cầu sở đó báo cáo giải trình; sở phải giải trình trong 15 ngày kể từ ngày nhận được yêu cầu","Đề nghị HĐND tỉnh bỏ phiếu tín nhiệm ngay đối với Giám đốc sở đó","Chuyển hồ sơ cho cơ quan thanh tra để tiến hành thanh tra toàn diện sở đó","Ban hành kết luận giám sát lần hai thay thế cho kết luận trước"],"why":"Khi cơ quan chịu sự giám sát không thực hiện hoặc thực hiện không đúng kết luận, chủ thể giám sát yêu cầu báo cáo giải trình trong 15 ngày (phức tạp không quá 30 ngày); quá hạn hoặc không tán thành nội dung giải trình thì xử lý hoặc kiến nghị xử lý.","cc":"Khoản 3 Điều 40 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsl-047","cd":"gs","m":2,"l":"kt","q":"Ở cấp xã, cơ quan nào có trách nhiệm tổ chức phục vụ hoạt động giám sát của HĐND trong phạm vi nhiệm vụ, quyền hạn của mình?","a":["Văn phòng HĐND và UBND cấp xã","Văn phòng Đoàn đại biểu Quốc hội và HĐND cấp tỉnh","Trung tâm phục vụ hành chính công cấp xã","Ủy ban MTTQ Việt Nam cấp xã"],"why":"Văn phòng HĐND và UBND cấp xã tổ chức phục vụ hoạt động giám sát của HĐND cấp xã; ở cấp tỉnh là Văn phòng Đoàn đại biểu Quốc hội và HĐND cấp tỉnh.","cc":"Khoản 1 Điều 42 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsl-049","cd":"gs","m":2,"l":"th","q":"Tháng 01/2026, Thường trực HĐND xã Q quyết định thành lập Đoàn giám sát chuyên đề, nhưng đến ngày 15/3/2026 Đoàn mới bắt đầu triển khai giám sát. Theo điều khoản chuyển tiếp, cuộc giám sát này áp dụng quy định của luật nào?","a":["Luật Hoạt động giám sát của Quốc hội và HĐND số 121/2025/QH15","Luật Hoạt động giám sát của Quốc hội và HĐND số 87/2015/QH13","Luật số 87/2015/QH13 về trình tự, Luật số 121/2025/QH15 về thẩm quyền","Một trong hai luật, do Thường trực HĐND xã Q lựa chọn áp dụng"],"why":"Hoạt động giám sát đã được quyết định trước ngày Luật có hiệu lực nhưng từ ngày 01/3/2026 mới triển khai thực hiện thì áp dụng Luật số 121/2025/QH15.","cc":"Khoản 1 Điều 45 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsh-006","cd":"gs","m":3,"l":"kt","q":"Xếp đúng trình tự: (1) HĐND thông qua nghị quyết chương trình giám sát năm; (2) Thường trực HĐND ban hành kế hoạch thực hiện; (3) Thường trực HĐND thông qua nghị quyết chương trình giám sát của mình; (4) Thường trực HĐND cho ý kiến về dự kiến chương trình.","a":["(4) → (1) → (3) → (2)","(4) → (3) → (1) → (2)","(1) → (4) → (3) → (2)","(4) → (1) → (2) → (3)"],"why":"Thường trực HĐND cho ý kiến trước kỳ họp cuối năm; HĐND thông qua nghị quyết; trong 07 ngày Thường trực thông qua nghị quyết chương trình của mình; trong 07 ngày tiếp theo cơ quan giúp việc trình Thường trực ban hành kế hoạch thực hiện.","cc":"Khoản 1 Điều 7, khoản 1 Điều 9 và khoản 1 Điều 10 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-009","cd":"gs","m":3,"l":"th","q":"Đại biểu HĐND xã B tự xây dựng chương trình giám sát năm sau của mình. Theo Nghị quyết số 114/2025/UBTVQH15, đại biểu phải báo cáo chương trình này như thế nào?","a":["Báo cáo Thường trực HĐND qua Tổ đại biểu, chậm nhất ngày 30 tháng 12 của năm trước","Báo cáo trực tiếp Chủ tịch HĐND, chậm nhất ngày 20 tháng 12 của năm trước","Trình Thường trực HĐND phê duyệt, chậm nhất ngày 20 tháng 12 của năm trước","Báo cáo Ban của HĐND theo lĩnh vực, chậm nhất ngày 30 tháng 12 của năm trước"],"why":"Đại biểu HĐND tự quyết định chương trình giám sát năm sau của mình (nếu có), không phải trình phê duyệt, và báo cáo Thường trực HĐND qua Tổ đại biểu chậm nhất ngày 30/12 của năm trước.","cc":"Khoản 2 Điều 13 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-012","cd":"gs","m":3,"l":"kt","q":"Theo Nghị quyết số 114/2025/UBTVQH15, báo cáo công tác 06 tháng, hằng năm của UBND cùng cấp được Ban của HĐND thẩm tra trong trường hợp nào?","a":["Khi có phân công của Thường trực HĐND cùng cấp","Đương nhiên, theo lĩnh vực phụ trách của từng Ban","Khi có yêu cầu của ít nhất một phần ba tổng số đại biểu HĐND","Khi Chủ tịch UBND cùng cấp có văn bản đề nghị"],"why":"Báo cáo kinh tế - xã hội, ngân sách, phòng chống tham nhũng... được Ban thẩm tra theo lĩnh vực phụ trách; còn báo cáo công tác 06 tháng, hằng năm, nhiệm kỳ của UBND (điểm b khoản 1 Điều 15) chỉ thẩm tra khi Thường trực HĐND cùng cấp phân công.","cc":"Điểm b khoản 1 Điều 18 và điểm b khoản 1 Điều 15 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-013","cd":"gs","m":3,"l":"kt","q":"Xếp đúng trình tự chuẩn bị chất vấn tại kỳ họp HĐND: (1) Thường trực HĐND xem xét, lựa chọn nhóm vấn đề chất vấn; (2) cơ quan giúp việc tổng hợp các đề xuất; (3) gửi xin ý kiến đại biểu HĐND; (4) cơ quan giúp việc dự kiến nhóm vấn đề, lấy ý kiến các Ban.","a":["(2) → (4) → (1) → (3)","(4) → (2) → (1) → (3)","(2) → (1) → (4) → (3)","(2) → (4) → (3) → (1)"],"why":"Chậm nhất 20 ngày trước kỳ họp: tổng hợp đề xuất; 15 ngày: dự kiến nhóm vấn đề, lấy ý kiến các Ban; 10 ngày: Thường trực HĐND xem xét, lựa chọn; sau đó gửi xin ý kiến đại biểu để trình HĐND quyết định.","cc":"Khoản 2 Điều 19, khoản 1 và khoản 2 Điều 21 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-018","cd":"gs","m":3,"l":"th","q":"Tại phiên chất vấn của HĐND tỉnh, một đại biểu đăng ký tranh luận nhưng khi phát biểu lại nêu một câu hỏi chất vấn mới và phản bác ý kiến của đại biểu đã chất vấn trước đó. Theo Nghị quyết số 114/2025/UBTVQH15, việc làm này đúng hay sai?","a":["Sai, vì không được dùng quyền tranh luận để chất vấn mới hoặc tranh luận với đại biểu đã chất vấn","Đúng, vì đại biểu có quyền tranh luận với bất kỳ người nào phát biểu tại phiên chất vấn","Đúng, nếu câu hỏi mới vẫn thuộc nhóm vấn đề đang được chất vấn tại phiên họp","Sai, vì chỉ đại biểu đã nêu chất vấn về vấn đề đó mới có quyền tranh luận"],"why":"Đại biểu được tranh luận với người bị chất vấn để làm rõ vấn đề đang chất vấn, nhưng không được dùng quyền tranh luận để nêu câu hỏi chất vấn hoặc tranh luận với đại biểu đã chất vấn trước. Đại biểu đã nêu chất vấn chỉ được ưu tiên tranh luận trước, không độc quyền.","cc":"Khoản 3 Điều 23 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-021","cd":"gs","m":3,"l":"th","q":"Đại biểu HĐND tỉnh nhận được văn bản trả lời chất vấn nhưng không đồng ý với nội dung trả lời. Theo Nghị quyết số 114/2025/UBTVQH15, chậm nhất 30 ngày kể từ ngày nhận được văn bản đó, đại biểu có quyền gì?","a":["Kiến nghị đưa ra thảo luận tại kỳ họp gần nhất hoặc kiến nghị HĐND xem xét trách nhiệm người bị chất vấn","Yêu cầu Chủ tịch UBND cùng cấp tạm đình chỉ công tác người bị chất vấn để làm rõ trách nhiệm","Tự mình tổ chức phiên chất vấn lại người bị chất vấn tại cuộc họp của Tổ đại biểu HĐND","Kiến nghị Ủy ban MTTQ Việt Nam cùng cấp tổ chức lấy phiếu tín nhiệm người bị chất vấn"],"why":"Nếu không đồng ý với nội dung trả lời bằng văn bản, trong 30 ngày đại biểu có quyền kiến nghị Thường trực HĐND đưa ra thảo luận tại kỳ họp HĐND gần nhất hoặc kiến nghị HĐND xem xét trách nhiệm đối với người bị chất vấn.","cc":"Khoản 4 Điều 25 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-028","cd":"gs","m":3,"l":"th","q":"Thường trực HĐND tỉnh yêu cầu một thành viên UBND tỉnh giải trình tại phiên họp Thường trực. Do không thể trực tiếp tham dự, người này muốn cử cấp phó của mình dự và trả lời thay. Theo Nghị quyết số 114/2025/UBTVQH15, điều này có được không?","a":["Được, nếu gửi văn bản nêu rõ lý do và được Thường trực HĐND đồng ý","Không, vì giải trình cũng như chất vấn đều không được cử người trả lời thay","Được, chỉ cần thông báo cho cơ quan giúp việc của HĐND trước phiên họp","Được, nếu được Chủ tịch UBND cùng cấp đồng ý bằng văn bản"],"why":"Khác với chất vấn (không được ủy quyền trả lời thay), người được yêu cầu giải trình nếu không thể trực tiếp tham dự thì gửi văn bản nêu rõ lý do và cử cấp phó tham dự, trả lời thay khi được Thường trực HĐND đồng ý.","cc":"Khoản 3 Điều 36 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-029","cd":"gs","m":3,"l":"th","q":"Thường trực HĐND xã A tổ chức phiên giải trình về một vấn đề do HĐND xã giao. Theo Nghị quyết số 114/2025/UBTVQH15, sau phiên giải trình, Thường trực HĐND xã phải làm gì?","a":["Hoàn thiện báo cáo kết quả phiên giải trình, trình HĐND xem xét, quyết định","Tự thông qua kết luận vấn đề giải trình khi quá nửa thành viên tán thành","Chuyển hồ sơ để UBND cùng cấp ban hành quyết định xử lý","Giao Ban của HĐND ban hành kết luận vấn đề giải trình"],"why":"Vấn đề giải trình do HĐND giao thì Thường trực HĐND hoàn thiện báo cáo kết quả phiên giải trình, trình HĐND xem xét, quyết định; chỉ khi phiên giải trình do Thường trực HĐND tự quyết định thì Thường trực mới thông qua kết luận.","cc":"Điểm g khoản 2 Điều 37 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-032","cd":"gs","m":3,"l":"th","q":"Thường trực HĐND tỉnh quyết định thành lập Đoàn giám sát chuyên đề của Thường trực HĐND. Theo Nghị quyết số 114/2025/UBTVQH15, người nào sau đây có thể được cử làm Trưởng Đoàn giám sát?","a":["Một Ủy viên của Thường trực HĐND tỉnh","Một Phó Trưởng Ban của HĐND tỉnh không phải là Ủy viên Thường trực HĐND","Đại diện Ủy ban MTTQ Việt Nam tỉnh được mời tham gia Đoàn giám sát","Một chuyên gia có kinh nghiệm được mời tham gia Đoàn giám sát"],"why":"Đoàn giám sát của Thường trực HĐND do một Phó Chủ tịch HĐND hoặc Ủy viên của Thường trực HĐND làm Trưởng Đoàn. Đại diện Ủy ban MTTQ Việt Nam, chuyên gia chỉ có thể được mời tham gia Đoàn.","cc":"Khoản 2 Điều 43 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-034","cd":"gs","m":3,"l":"th","q":"Thường trực HĐND tỉnh vừa ban hành nghị quyết thành lập Đoàn giám sát chuyên đề của Thường trực HĐND. Đoàn giám sát phải xây dựng và thông báo kế hoạch giám sát, các đề cương báo cáo trong thời hạn nào?","a":["15 ngày kể từ ngày Thường trực HĐND ban hành nghị quyết thành lập Đoàn","30 ngày kể từ ngày Thường trực HĐND ban hành nghị quyết thành lập Đoàn","20 ngày kể từ ngày Thường trực HĐND ban hành nghị quyết thành lập Đoàn","10 ngày kể từ ngày Thường trực HĐND ban hành nghị quyết thành lập Đoàn"],"why":"Đoàn giám sát của Thường trực HĐND (và của Ban của HĐND) có 15 ngày kể từ ngày ban hành nghị quyết (quyết định) thành lập Đoàn; thời hạn 30 ngày chỉ áp dụng cho Đoàn giám sát của HĐND.","cc":"Điểm a khoản 4 Điều 43 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-036","cd":"gs","m":3,"l":"th","q":"Năm trước, HĐND xã A đã giám sát chuyên đề về quản lý đất công ích; UBND xã thực hiện không đầy đủ nghị quyết giám sát. Nay có đề xuất HĐND xã giám sát lại nội dung này dù chưa đủ 24 tháng. Xét theo tiêu chí không trùng lặp chuyên đề giám sát, đề xuất này thế nào?","a":["Phù hợp, vì thuộc ngoại lệ giám sát lại do đối tượng thực hiện không đầy đủ nghị quyết giám sát","Không phù hợp, vì mọi nội dung đã giám sát đều phải đủ 24 tháng mới được chọn lại","Không phù hợp, vì nội dung đã giám sát chỉ được chọn lại ở nhiệm kỳ sau","Phù hợp, vì thời gian tính trùng lặp chỉ là 12 tháng kể từ khi giám sát"],"why":"Chuyên đề giám sát không trùng lặp với chuyên đề đã giám sát trong 24 tháng tính đến thời điểm đề xuất, trừ trường hợp giám sát lại do đối tượng không thực hiện hoặc thực hiện không đầy đủ nghị quyết, kết luận, kiến nghị về giám sát.","cc":"Điểm e khoản 1 Điều 39 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-039","cd":"gs","m":3,"l":"th","q":"Tổ đại biểu HĐND xã A vừa hoàn thành giám sát một vấn đề do Thường trực HĐND xã giao. Theo Nghị quyết số 114/2025/UBTVQH15, bước tiếp theo đúng là gì?","a":["Hoàn thiện báo cáo kết quả giám sát, dự thảo kết luận để trình Thường trực HĐND xem xét","Tổ đại biểu tự ban hành kết luận giám sát và gửi cơ quan chịu sự giám sát thực hiện","Tổ trưởng Tổ đại biểu ký quyết định xử lý các vi phạm đã phát hiện qua giám sát","Chuyển toàn bộ hồ sơ cho UBND cùng cấp để ban hành kết luận giám sát"],"why":"Tổ đại biểu không tự ban hành kết luận mà hoàn thiện báo cáo kết quả giám sát, dự thảo nghị quyết của HĐND hoặc kết luận của Thường trực HĐND để trình cơ quan đã giao xem xét. Riêng đại biểu HĐND tự giám sát thì được tự ban hành kết luận.","cc":"Khoản 3 Điều 48 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-046","cd":"gs","m":3,"l":"kt","q":"Xếp đúng trình tự HĐND xem xét báo cáo của Thường trực HĐND về kiến nghị giám sát: (1) HĐND thảo luận; (2) cơ quan chịu sự giám sát giải trình bổ sung; (3) Ban hoặc đại biểu có kiến nghị bổ sung ý kiến; (4) đại diện Thường trực HĐND trình bày báo cáo.","a":["(4) → (3) → (2) → (1)","(4) → (1) → (3) → (2)","(4) → (2) → (3) → (1)","(3) → (4) → (1) → (2)"],"why":"Ở thủ tục này, HĐND chỉ thảo luận sau khi đã nghe đại diện Thường trực HĐND trình bày, ý kiến bổ sung của Ban hoặc đại biểu có kiến nghị và phần giải trình bổ sung của cơ quan chịu sự giám sát; sau đó mới thông qua nghị quyết về vấn đề được kiến nghị.","cc":"Khoản 5 Điều 59 Nghị quyết số 114/2025/UBTVQH15"},{"id":"gsh-052","cd":"gs","m":3,"l":"th","q":"Tại kỳ họp HĐND tỉnh, một Phó Chủ tịch UBND tỉnh có số phiếu đánh giá “tín nhiệm thấp” chiếm 55% tổng số phiếu và người này không xin từ chức. Theo Nghị quyết số 96/2023/QH15, bước xử lý tiếp theo là gì?","a":["Thường trực HĐND trình HĐND bỏ phiếu tín nhiệm tại kỳ họp đó hoặc kỳ họp gần nhất","Chủ tịch UBND tỉnh trình HĐND miễn nhiệm người đó ngay tại kỳ họp đó","HĐND tổ chức lấy phiếu tín nhiệm lại đối với người đó vào kỳ họp cuối năm sau","Không phải xử lý gì vì chưa đến hai phần ba số phiếu đánh giá “tín nhiệm thấp”"],"why":"Quá nửa đến dưới 2/3 tổng số phiếu “tín nhiệm thấp”: có thể xin từ chức; nếu không thì Thường trực HĐND trình HĐND bỏ phiếu tín nhiệm tại kỳ họp đó hoặc kỳ họp gần nhất. Từ 2/3 trở lên mới trình miễn nhiệm.","cc":"Khoản 2 Điều 12 Nghị quyết số 96/2023/QH15"},{"id":"gsl-007","cd":"gs","m":3,"l":"th","q":"Qua giám sát, Ban của HĐND xã A yêu cầu một cơ quan có thẩm quyền áp dụng biện pháp chấm dứt hành vi vi phạm pháp luật. Hết thời hạn trả lời theo luật định, Ban vẫn không nhận được trả lời. Theo Luật số 121/2025/QH15, bước xử lý tiếp theo của Ban là gì?","a":["Yêu cầu người đứng đầu cơ quan, tổ chức cấp trên xem xét, giải quyết và trả lời trong 30 ngày","Gửi lại yêu cầu lần hai và chờ thêm 15 ngày trước khi báo cáo HĐND xã","Tự áp dụng biện pháp buộc chấm dứt hành vi vi phạm thay cho cơ quan đó","Chuyển hồ sơ sang cơ quan thanh tra để xử lý trong thời hạn 30 ngày"],"why":"Quá 15 ngày mà không nhận được trả lời, chủ thể giám sát yêu cầu người đứng đầu cơ quan, tổ chức cấp trên xem xét, giải quyết; người này phải giải quyết và trả lời trong 30 ngày kể từ ngày nhận được yêu cầu.","cc":"Khoản 4 Điều 4 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsl-020","cd":"gs","m":3,"l":"th","q":"Giữa hai kỳ họp, do yêu cầu của thực tiễn, cần thay đổi một chuyên đề trong chương trình giám sát năm của HĐND xã D. Theo Luật số 121/2025/QH15, việc điều chỉnh được thực hiện thế nào?","a":["Thường trực HĐND xã quyết định điều chỉnh và báo cáo HĐND xã tại kỳ họp gần nhất","Phải triệu tập kỳ họp chuyên đề để HĐND xã biểu quyết việc điều chỉnh","Chủ tịch HĐND xã quyết định điều chỉnh sau khi thống nhất với UBND xã","Thường trực HĐND xã điều chỉnh sau khi được Thường trực HĐND tỉnh phê duyệt"],"why":"Trường hợp cần thiết do yêu cầu của thực tiễn, trong thời gian HĐND không họp, Thường trực HĐND quyết định điều chỉnh chương trình giám sát của HĐND và báo cáo HĐND tại kỳ họp gần nhất.","cc":"Khoản 4 Điều 28 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsl-022","cd":"gs","m":3,"l":"kt","q":"Trong việc xem xét kết quả giám sát, thẩm quyền nào sau đây Luật số 121/2025/QH15 chỉ quy định cho HĐND cấp tỉnh mà không quy định cho HĐND cấp xã?","a":["Miễn nhiệm, bãi nhiệm Hội thẩm nhân dân theo quy định của pháp luật","Miễn nhiệm, bãi nhiệm Trưởng Ban của HĐND cùng cấp","Miễn nhiệm, bãi nhiệm Ủy viên UBND cùng cấp","Bỏ phiếu tín nhiệm đối với người giữ chức vụ do HĐND bầu"],"why":"HĐND hai cấp đều miễn nhiệm, bãi nhiệm Chủ tịch, Phó Chủ tịch HĐND, Trưởng Ban, Chủ tịch, Phó Chủ tịch và Ủy viên UBND cùng cấp; riêng HĐND cấp tỉnh còn miễn nhiệm, bãi nhiệm Hội thẩm nhân dân và giải tán HĐND cấp xã.","cc":"Khoản 2 Điều 29 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsl-024","cd":"gs","m":3,"l":"th","q":"Qua giám sát, HĐND xã E thấy một thông tư của bộ có quy định trái luật, gây vướng mắc ở địa phương và quyết định kiến nghị cơ quan có thẩm quyền ở trung ương sửa đổi. Theo Luật số 121/2025/QH15, HĐND xã E gửi kiến nghị này đến đâu?","a":["Thường trực HĐND cấp tỉnh để xem xét, tổng hợp gửi cơ quan có thẩm quyền ở trung ương","Gửi trực tiếp đến bộ đã ban hành thông tư, đồng thời gửi UBTVQH","UBND cấp tỉnh để tổng hợp, báo cáo Chính phủ xem xét sửa đổi","Đoàn đại biểu Quốc hội của tỉnh để chuyển đến Ủy ban của Quốc hội"],"why":"HĐND cấp xã gửi kiến nghị đến Thường trực HĐND cấp tỉnh để xem xét, tổng hợp gửi cơ quan có thẩm quyền ở trung ương. Chỉ HĐND cấp tỉnh gửi trực tiếp, đồng thời gửi UBTVQH, Hội đồng Dân tộc, Ủy ban của Quốc hội.","cc":"Khoản 4 Điều 29 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsl-027","cd":"gs","m":3,"l":"th","q":"Thường trực HĐND tỉnh muốn làm rõ trách nhiệm trong công tác xét xử trên địa bàn và dự kiến yêu cầu Chánh án Tòa án nhân dân khu vực giải trình tại phiên họp Thường trực HĐND tỉnh. Theo Luật số 121/2025/QH15, yêu cầu này có đúng thẩm quyền không?","a":["Có; Chánh án Tòa án nhân dân khu vực thuộc diện Thường trực HĐND tỉnh yêu cầu giải trình","Không; Thường trực HĐND tỉnh chỉ được yêu cầu Chánh án Tòa án nhân dân cấp tỉnh giải trình","Không; Tòa án chỉ báo cáo công tác tại kỳ họp HĐND, không thuộc diện giải trình","Có, nhưng phải được Chánh án Tòa án nhân dân cấp tỉnh đồng ý trước"],"why":"Thường trực HĐND cấp tỉnh được yêu cầu giải trình: thành viên UBND, Chánh án TAND, Viện trưởng VKSND, Trưởng Thi hành án dân sự cấp tỉnh, Chánh án TAND và Viện trưởng VKSND khu vực, Chủ tịch UBND đặc khu nơi không tổ chức cấp chính quyền địa phương.","cc":"Điểm d khoản 2 Điều 31 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsl-028","cd":"gs","m":3,"l":"th","q":"Ủy ban MTTQ Việt Nam xã G phát hiện một văn bản quy phạm pháp luật thuộc đối tượng giám sát của HĐND xã (loại quy định tại khoản 15 Điều 4 Luật Ban hành văn bản quy phạm pháp luật) có dấu hiệu trái văn bản của cơ quan nhà nước cấp trên và gửi đề nghị xem xét. Theo Luật số 121/2025/QH15, đề nghị của Ủy ban MTTQ cùng cấp là căn cứ để chủ thể nào xem xét văn bản đó?","a":["Thường trực HĐND xã G","Tổ đại biểu HĐND xã G","Thường trực HĐND cấp tỉnh","Ban của HĐND cấp tỉnh"],"why":"Thường trực HĐND cấp xã xem xét văn bản có dấu hiệu trái pháp luật khi tự mình phát hiện hoặc theo đề nghị của UBND, Ủy ban MTTQ cùng cấp, đại biểu Quốc hội, kiến nghị của Ban, đại biểu HĐND cùng cấp; HĐND thì xem xét theo đề nghị của Thường trực HĐND.","cc":"Điểm b khoản 3 Điều 31 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsl-031","cd":"gs","m":3,"l":"th","q":"Qua giám sát, Thường trực HĐND tỉnh xác định HĐND xã L đã làm thiệt hại nghiêm trọng đến lợi ích của Nhân dân. Theo Luật số 121/2025/QH15, Thường trực HĐND tỉnh có thẩm quyền gì?","a":["Kiến nghị HĐND cấp tỉnh giải tán HĐND xã L","Quyết định giải tán HĐND xã L rồi báo cáo HĐND tỉnh tại kỳ họp gần nhất","Trình UBTVQH trực tiếp quyết định giải tán HĐND xã L","Kiến nghị Chủ tịch UBND cấp tỉnh quyết định giải tán HĐND xã L"],"why":"Thường trực HĐND cấp tỉnh chỉ kiến nghị; HĐND cấp tỉnh mới có quyền giải tán HĐND cấp xã làm thiệt hại nghiêm trọng đến lợi ích của Nhân dân và phải trình UBTVQH phê chuẩn.","cc":"Khoản 4 Điều 32 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsl-037","cd":"gs","m":3,"l":"kt","q":"Theo điểm a khoản 1 Điều 36 Luật số 121/2025/QH15, người nào sau đây KHÔNG có trong danh sách những người mà đại biểu HĐND cấp tỉnh có quyền chất vấn?","a":["Trưởng Thi hành án dân sự cấp tỉnh","Viện trưởng Viện kiểm sát nhân dân cấp tỉnh","Chánh án Tòa án nhân dân cấp tỉnh","Người đứng đầu cơ quan thuộc UBND cấp tỉnh"],"why":"Đại biểu HĐND cấp tỉnh chất vấn Chủ tịch, thành viên khác của UBND, người đứng đầu cơ quan thuộc UBND, Chánh án TAND, Viện trưởng VKSND cấp tỉnh. Trưởng Thi hành án dân sự cấp tỉnh thuộc diện giải trình trước Thường trực HĐND tỉnh.","cc":"Điểm a khoản 1 Điều 36 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsl-038","cd":"gs","m":3,"l":"kt","q":"Theo Điều 36 Luật số 121/2025/QH15, ngoài hoạt động giám sát của HĐND, Thường trực HĐND, Ban, Tổ đại biểu HĐND cùng cấp, đại biểu HĐND cấp tỉnh còn tham gia hoạt động giám sát của chủ thể nào khi có yêu cầu, đề nghị?","a":["Đoàn đại biểu Quốc hội địa phương","Ủy ban MTTQ Việt Nam cấp tỉnh","Cơ quan thanh tra, kiểm toán ở địa phương","HĐND cấp xã nơi đại biểu cư trú"],"why":"Đại biểu HĐND cấp tỉnh tham gia hoạt động giám sát của HĐND, Thường trực HĐND, Ban, Tổ đại biểu HĐND cấp tỉnh và của Đoàn đại biểu Quốc hội địa phương khi có yêu cầu, đề nghị; quy định đối với đại biểu HĐND cấp xã không nêu Đoàn đại biểu Quốc hội.","cc":"Điểm đ khoản 1 Điều 36 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsl-041","cd":"gs","m":3,"l":"th","q":"Qua giám sát, một đại biểu HĐND xã M cho rằng cần đưa việc bỏ phiếu tín nhiệm đối với một người giữ chức vụ do HĐND xã bầu ra HĐND xem xét. Theo Điều 38 Luật số 121/2025/QH15, đại biểu thực hiện thẩm quyền nào?","a":["Kiến nghị Thường trực HĐND xem xét trình HĐND bỏ phiếu tín nhiệm","Trực tiếp trình HĐND bỏ phiếu tín nhiệm ngay tại kỳ họp đang diễn ra","Kiến nghị Chủ tịch UBND cấp tỉnh xem xét tổ chức bỏ phiếu tín nhiệm","Kiến nghị Tổ đại biểu HĐND lấy ý kiến cử tri về việc bỏ phiếu tín nhiệm"],"why":"Đại biểu HĐND kiến nghị Thường trực HĐND xem xét trình HĐND bỏ phiếu tín nhiệm đối với người giữ chức vụ do HĐND bầu, theo quy định của Quốc hội về bỏ phiếu tín nhiệm; đại biểu không tự mình trình HĐND.","cc":"Khoản 3 Điều 38 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsl-042","cd":"gs","m":3,"l":"th","q":"Thường trực HĐND tỉnh nhận thấy kế hoạch giám sát của Thường trực HĐND xã N trùng nội dung, thời gian với một đoàn giám sát của tỉnh tại cùng địa bàn. Theo Luật số 121/2025/QH15, Thường trực HĐND tỉnh có thẩm quyền gì?","a":["Yêu cầu Thường trực HĐND xã N điều chỉnh chương trình, kế hoạch, phối hợp giám sát để tránh trùng lặp","Hủy bỏ chương trình giám sát năm của Thường trực HĐND xã N","Chỉ được trao đổi, góp ý; việc điều chỉnh do Thường trực HĐND xã N tự quyết định","Đề nghị UBND tỉnh chỉ đạo UBND xã N không làm việc với đoàn giám sát của xã"],"why":"Trong chỉ đạo, điều hòa, phối hợp giám sát, Thường trực HĐND cấp tỉnh có quyền yêu cầu Ban, Tổ đại biểu HĐND cấp tỉnh và Thường trực HĐND cấp xã điều chỉnh chương trình, kế hoạch, phối hợp thực hiện để tránh trùng lặp.","cc":"Điểm c khoản 2 Điều 39 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsl-045","cd":"gs","m":3,"l":"th","q":"Một cơ quan thuộc UBND tỉnh đã đề nghị Thường trực HĐND tỉnh xem xét lại kết luận giám sát nhưng vẫn không tán thành với kết quả trả lời của Thường trực HĐND tỉnh. Theo Luật số 121/2025/QH15, cơ quan này có thể làm gì tiếp theo?","a":["Tự mình hoặc báo cáo người đứng đầu cơ quan có thẩm quyền để đề nghị HĐND xem xét kết luận đó","Khởi kiện kết luận giám sát ra Tòa án nhân dân có thẩm quyền","Tạm dừng thực hiện kết luận cho đến khi có ý kiến của Chính phủ","Đề nghị Ủy ban MTTQ Việt Nam cấp tỉnh tổ chức đối thoại để hủy kết luận"],"why":"Nếu không tán thành với kết quả trả lời của chủ thể giám sát, cơ quan chịu sự giám sát tự mình hoặc báo cáo với người đứng đầu cơ quan, tổ chức có thẩm quyền để đề nghị HĐND xem xét kết luận, kiến nghị giám sát đó.","cc":"Khoản 2 Điều 40 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"gsl-050","cd":"gs","m":3,"l":"th","q":"Đoàn giám sát chuyên đề của HĐND tỉnh được thành lập và đã triển khai giám sát từ tháng 12/2025, đến tháng 4/2026 mới kết thúc. Theo Luật số 121/2025/QH15, cuộc giám sát đang triển khai trước ngày 01/3/2026 này áp dụng quy định nào?","a":["Tiếp tục áp dụng quy định của Luật số 87/2015/QH13","Chuyển sang áp dụng Luật số 121/2025/QH15 kể từ ngày 01/3/2026","Dừng cuộc giám sát để quyết định lại theo Luật số 121/2025/QH15","Áp dụng quy định nào thuận lợi hơn cho cơ quan chịu sự giám sát"],"why":"Hoạt động giám sát đang được triển khai thực hiện trước ngày 01/3/2026 thì tiếp tục áp dụng Luật số 87/2015/QH13; đây là ngoại lệ của việc Luật số 87/2015/QH13 hết hiệu lực từ ngày Luật mới có hiệu lực.","cc":"Khoản 2 Điều 45 Luật Hoạt động giám sát của Quốc hội và Hội đồng nhân dân số 121/2025/QH15"},{"id":"ctd-001","cd":"ct","m":1,"l":"kt","q":"Theo Nghị quyết 116/2025/UBTVQH15, Thường trực HĐND cấp tỉnh tiếp công dân tại đâu?","a":["Tại Trụ sở tiếp công dân cấp tỉnh","Tại phòng họp của Thường trực HĐND cấp tỉnh","Tại trụ sở Ủy ban MTTQ Việt Nam cấp tỉnh","Tại trụ sở sở, ngành có liên quan đến vụ việc"],"why":"Thường trực HĐND cấp tỉnh tiếp công dân tại Trụ sở tiếp công dân cấp tỉnh; còn Thường trực HĐND cấp xã tiếp công dân tại địa điểm tiếp công dân cấp xã.","cc":"Khoản 1 Điều 8 Nghị quyết số 116/2025/UBTVQH15"},{"id":"ctd-003","cd":"ct","m":1,"l":"kt","q":"Theo Nghị quyết 116/2025/UBTVQH15, khi Thường trực HĐND, đại biểu HĐND tiếp công dân trực tuyến thì việc tiếp công dân trực tuyến được thực hiện theo quy định của cơ quan nào?","a":["Chính phủ","Ủy ban Thường vụ Quốc hội","HĐND cấp tỉnh","Thanh tra Chính phủ"],"why":"Trường hợp cần thiết, Thường trực HĐND, đại biểu HĐND có thể tiếp công dân trực tuyến; việc tiếp công dân trực tuyến thực hiện theo quy định của Chính phủ.","cc":"Khoản 4 Điều 8 Nghị quyết số 116/2025/UBTVQH15"},{"id":"ctd-007","cd":"ct","m":1,"l":"kt","q":"Theo Nghị quyết 116/2025/UBTVQH15, chủ thể nào có trách nhiệm sắp xếp lịch tiếp công dân của đại biểu HĐND cùng cấp?","a":["Thường trực HĐND","Chủ tịch UBND cùng cấp","Ban tiếp công dân cấp tỉnh","Tổ trưởng Tổ đại biểu HĐND"],"why":"Thường trực HĐND sắp xếp lịch tiếp công dân của đại biểu HĐND cùng cấp, niêm yết lịch tại địa điểm tiếp công dân, công bố trên phương tiện thông tin đại chúng ở địa phương và bố trí nơi tiếp.","cc":"Khoản 1 Điều 11 Nghị quyết số 116/2025/UBTVQH15"},{"id":"ctd-008","cd":"ct","m":1,"l":"kt","q":"Điều 12 Nghị quyết 116/2025/UBTVQH15 nêu cụ thể hoạt động nào của đại biểu HĐND, bên cạnh hoạt động tiếp công dân, là một nguồn tiếp nhận đơn?","a":["Hoạt động tiếp xúc cử tri","Hoạt động chất vấn tại kỳ họp","Hoạt động thẩm tra của các Ban","Hoạt động biểu quyết tại kỳ họp"],"why":"Đơn được tiếp nhận qua dịch vụ bưu chính, hoạt động tiếp công dân, hoạt động tiếp xúc cử tri của đại biểu, do cơ quan, tổ chức, cá nhân có thẩm quyền chuyển đến và nguồn khác theo quy định của pháp luật.","cc":"Khoản 3 Điều 12 Nghị quyết số 116/2025/UBTVQH15"},{"id":"ctd-009","cd":"ct","m":1,"l":"th","q":"Thường trực HĐND xã A nhận được một lá đơn kiến nghị không viết bằng tiếng Việt. Theo Nghị quyết 116/2025/UBTVQH15, để được coi là đơn đủ điều kiện xử lý thì lá đơn này cần đáp ứng yêu cầu nào về ngôn ngữ?","a":["Phải kèm theo bản dịch bằng tiếng Việt","Phải được UBND cấp xã nơi người viết đơn cư trú xác nhận","Phải viết lại bằng tiếng Việt, không chấp nhận bản dịch","Không cần gì thêm vì đơn viết bằng ngôn ngữ nào cũng được"],"why":"Đơn đủ điều kiện xử lý là đơn dùng chữ viết tiếng Việt; nếu không dùng chữ viết tiếng Việt thì phải kèm bản dịch bằng tiếng Việt.","cc":"Khoản 2 Điều 13 Nghị quyết số 116/2025/UBTVQH15"},{"id":"ctd-012","cd":"ct","m":1,"l":"kt","q":"Theo Nghị quyết 116/2025/UBTVQH15, thời hạn lưu đơn đối với các trường hợp đơn được lưu (như đơn không đủ điều kiện xử lý) là bao lâu?","a":["01 năm","06 tháng","02 năm","05 năm"],"why":"Thời hạn lưu đơn là 01 năm; việc tiêu hủy đơn sau đó được thực hiện theo quy định của pháp luật.","cc":"Khoản 2 Điều 19 Nghị quyết số 116/2025/UBTVQH15"},{"id":"ctd-020","cd":"ct","m":1,"l":"kt","q":"Theo Nghị quyết 116/2025/UBTVQH15, sau khi chuyển đơn khiếu nại, tố cáo, kiến nghị, phản ánh đến cơ quan, tổ chức, cá nhân có thẩm quyền giải quyết, đại biểu HĐND có trách nhiệm gì?","a":["Theo dõi, đôn đốc việc giải quyết","Tự mình giải quyết vụ việc thay cơ quan đó","Không còn trách nhiệm gì đối với đơn đã chuyển","Công khai toàn văn đơn tại kỳ họp HĐND"],"why":"Chuyển đơn chưa phải là hết trách nhiệm: sau khi chuyển đơn đến nơi có thẩm quyền giải quyết, đại biểu HĐND có trách nhiệm theo dõi, đôn đốc việc giải quyết.","cc":"Khoản 1 Điều 31 Nghị quyết số 116/2025/UBTVQH15"},{"id":"ctd-025","cd":"ct","m":1,"l":"kt","q":"Theo Luật Tiếp công dân, hành vi nào sau đây bị nghiêm cấm?","a":["Lôi kéo, mua chuộc người khác tập trung đông người tại nơi tiếp công dân","Khiếu nại, tố cáo hành vi vi phạm pháp luật của người tiếp công dân","Sử dụng người phiên dịch khi không thông thạo tiếng Việt","Cử người đại diện khi nhiều người cùng khiếu nại về một nội dung"],"why":"Luật nghiêm cấm kích động, cưỡng ép, dụ dỗ, lôi kéo, mua chuộc người khác tập trung đông người tại nơi tiếp công dân. Ba phương án còn lại là quyền hoặc nghĩa vụ hợp pháp của người đến khiếu nại, tố cáo, kiến nghị, phản ánh.","cc":"Khoản 7 Điều 6 Luật Tiếp công dân số 42/2013/QH13"},{"id":"ctd-026","cd":"ct","m":1,"l":"th","q":"Một công dân đến địa điểm tiếp công dân cấp xã để phản ánh với đại biểu HĐND xã nhưng không sử dụng thông thạo tiếng Việt. Theo Luật Tiếp công dân, người này có quyền gì?","a":["Có quyền sử dụng người phiên dịch","Chỉ được nộp đơn, không được trình bày trực tiếp","Phải nhờ người khác đứng tên phản ánh thay mình","Phải chờ đến khi tự trình bày được bằng tiếng Việt"],"why":"Người khiếu nại, tố cáo, kiến nghị, phản ánh không sử dụng thông thạo tiếng Việt thì có quyền sử dụng người phiên dịch khi đến nơi tiếp công dân.","cc":"Điểm đ khoản 1 Điều 7 Luật Tiếp công dân số 42/2013/QH13"},{"id":"ctd-027","cd":"ct","m":1,"l":"th","q":"Bà N được người khiếu nại ủy quyền đến nơi tiếp công dân để trình bày khiếu nại với đại biểu HĐND. Theo Luật Tiếp công dân (sửa đổi bởi Luật số 136/2025/QH15), ngoài việc nêu rõ họ tên, địa chỉ và thông tin về giấy tờ căn cước, bà N phải có giấy tờ gì?","a":["Văn bản ủy quyền hợp pháp","Giấy giới thiệu của UBND cấp xã nơi cư trú","Giấy xác nhận quan hệ nhân thân với người khiếu nại","Thẻ luật sư hoặc thẻ trợ giúp viên pháp lý"],"why":"Người đến nơi tiếp công dân phải nêu rõ họ tên, địa chỉ, số căn cước hoặc giấy chứng nhận căn cước, số định danh cá nhân hoặc số hộ chiếu; nếu được người khiếu nại ủy quyền thì phải có văn bản ủy quyền hợp pháp.","cc":"Điểm a khoản 2 Điều 7 Luật Tiếp công dân số 42/2013/QH13 (sửa đổi, bổ sung bởi khoản 3 Điều 1 Luật số 136/2025/QH15)"},{"id":"ctx-001","cd":"ct","m":1,"l":"th","q":"Tại hội nghị tiếp xúc cử tri ở phường B, một đại biểu HĐND kêu gọi cử tri và doanh nghiệp dự hội nghị quyên góp, tài trợ cho cơ quan nơi mình công tác. Theo Nghị quyết liên tịch 72/2025, việc làm này được đánh giá thế nào?","a":["Vi phạm nguyên tắc: không lợi dụng tiếp xúc cử tri để vận động tài trợ, quyên góp cho cơ quan mình","Được phép, nếu đã báo cáo trước bằng văn bản với Thường trực HĐND cùng cấp","Được phép, nếu việc quyên góp là tự nguyện và công khai ngay tại hội nghị","Chỉ vi phạm nếu đại biểu trực tiếp nhận tiền, hiện vật ngay tại hội nghị"],"why":"Nguyên tắc tiếp xúc cử tri: không lợi dụng hoạt động này để vận động tài trợ, quyên góp cho cơ quan, tổ chức, cá nhân mình. Không có ngoại lệ “tự nguyện” hay “đã báo cáo”; bản thân việc vận động đã trái nguyên tắc, dù có trực tiếp nhận tiền hay không.","cc":"Khoản 6 Điều 3 Nghị quyết liên tịch 72/2025/NQLT/UBTVQH15-CP-ĐCTUBTWMTTQVN (đã sửa đổi, bổ sung năm 2025)"},{"id":"ctx-002","cd":"ct","m":1,"l":"kt","q":"Theo Nghị quyết liên tịch 72/2025, đại biểu HĐND có quyền từ chối tiếp xúc cử tri trong trường hợp nào sau đây?","a":["Khi không bảo đảm an ninh, an toàn cho đại biểu","Khi số cử tri đến dự ít hơn so với dự kiến","Khi cử tri góp ý, phê bình hoạt động của đại biểu","Khi kiến nghị của cử tri không thuộc thẩm quyền HĐND"],"why":"Đại biểu có quyền từ chối tiếp xúc cử tri nếu không bảo đảm an ninh, an toàn cho đại biểu hoặc không bảo đảm một số nguyên tắc tiếp xúc cử tri. Ít cử tri dự hay bị góp ý, phê bình không phải là căn cứ để từ chối.","cc":"Khoản 2 Điều 4 Nghị quyết liên tịch 72/2025/NQLT/UBTVQH15-CP-ĐCTUBTWMTTQVN (đã sửa đổi, bổ sung năm 2025)"},{"id":"ctx-003","cd":"ct","m":1,"l":"kt","q":"Theo Nghị quyết liên tịch 72/2025 (đã sửa đổi năm 2025), đại biểu HĐND có trách nhiệm thực hiện việc tiếp xúc cử tri theo kế hoạch của chủ thể nào?","a":["Tổ đại biểu HĐND cùng cấp","UBND cùng cấp","Các Ban của HĐND cùng cấp","Ban Thường trực Ủy ban MTTQ cùng cấp"],"why":"Đại biểu HĐND thực hiện tiếp xúc cử tri theo kế hoạch của Tổ đại biểu HĐND cùng cấp; Tổ xây dựng kế hoạch của mình trên cơ sở kế hoạch tiếp xúc cử tri của Thường trực HĐND và tình hình thực tế ở địa phương.","cc":"Khoản 5 Điều 4 Nghị quyết liên tịch 72/2025/NQLT/UBTVQH15-CP-ĐCTUBTWMTTQVN (đã sửa đổi, bổ sung năm 2025)"},{"id":"ctx-004","cd":"ct","m":1,"l":"kt","q":"Theo Nghị quyết liên tịch 72/2025, cử tri có quyền nào sau đây đối với hoạt động tiếp xúc cử tri của đại biểu HĐND?","a":["Được thông tin về thời gian, địa điểm, hình thức, nội dung tiếp xúc cử tri","Được quyết định thời gian, địa điểm tổ chức hội nghị tiếp xúc cử tri","Được chủ trì, điều hành hội nghị tiếp xúc cử tri tại nơi mình cư trú","Được biểu quyết thông qua biên bản và kết luận hội nghị tiếp xúc cử tri"],"why":"Cử tri có quyền được thông tin về thời gian, địa điểm, hình thức, nội dung và dự tiếp xúc cử tri; nêu ý kiến, kiến nghị; có thể góp ý về việc thực hiện nhiệm vụ đại biểu. Việc chủ trì hội nghị thuộc về Ban Thường trực Ủy ban MTTQ.","cc":"Khoản 1 Điều 5 Nghị quyết liên tịch 72/2025/NQLT/UBTVQH15-CP-ĐCTUBTWMTTQVN (đã sửa đổi, bổ sung năm 2025)"},{"id":"ctx-013","cd":"ct","m":1,"l":"kt","q":"Tại hội nghị tiếp xúc cử tri trước kỳ họp thường lệ của HĐND, sau khi đại diện Thường trực HĐND, UBND và cơ quan liên quan trả lời kiến nghị của cử tri, đại biểu HĐND thực hiện nội dung nào?","a":["Phát biểu ý kiến ghi nhận, giải trình, tiếp thu ý kiến, kiến nghị của cử tri","Tuyên bố kết thúc hội nghị và thông qua biên bản tiếp xúc cử tri","Ra văn bản yêu cầu UBND giải quyết ngay các kiến nghị tại hội nghị","Giới thiệu thành phần tham dự và chương trình, nội dung hội nghị"],"why":"Trình tự hội nghị: MTTQ chủ trì, giới thiệu; đại biểu báo cáo; cử tri phát biểu; cơ quan có thẩm quyền trả lời; đại biểu phát biểu ghi nhận, giải trình, tiếp thu; đại diện Ban Thường trực Ủy ban MTTQ tuyên bố kết thúc.","cc":"Điểm đ khoản 1 Điều 24 Nghị quyết liên tịch 72/2025/NQLT/UBTVQH15-CP-ĐCTUBTWMTTQVN (đã sửa đổi, bổ sung năm 2025)"},{"id":"ctx-016","cd":"ct","m":1,"l":"kt","q":"Trường hợp tổ chức tiếp xúc cử tri sau kỳ họp HĐND, đại biểu HĐND tiếp xúc cử tri để thực hiện những nội dung nào?","a":["Báo cáo kết quả kỳ họp, phổ biến nghị quyết của HĐND và vận động Nhân dân thực hiện","Báo cáo dự kiến nội dung, chương trình kỳ họp và lấy ý kiến cử tri về kỳ họp đó","Lấy phiếu tín nhiệm của cử tri đối với người giữ chức vụ do HĐND bầu","Trực tiếp giải quyết khiếu nại, tố cáo của cử tri ngay tại hội nghị"],"why":"Sau ngày bế mạc kỳ họp, đại biểu HĐND tiếp xúc cử tri để báo cáo kết quả kỳ họp, phổ biến nghị quyết của HĐND và vận động Nhân dân thực hiện nghị quyết đó. Việc thu thập ý kiến về chương trình kỳ họp là nội dung tiếp xúc trước kỳ họp.","cc":"Khoản 3 Điều 26 Nghị quyết liên tịch 72/2025/NQLT/UBTVQH15-CP-ĐCTUBTWMTTQVN (đã sửa đổi, bổ sung năm 2025)"},{"id":"ctx-018","cd":"ct","m":1,"l":"kt","q":"Khi đại biểu HĐND tiếp xúc cử tri nơi cư trú, cơ quan nào có trách nhiệm bố trí địa điểm, tạo điều kiện thuận lợi và bảo đảm an ninh, trật tự, an toàn cho hoạt động này?","a":["UBND cấp xã nơi đại biểu cư trú","Thường trực HĐND cấp tỉnh","Ban Thường trực Ủy ban MTTQ cấp tỉnh","Tổ đại biểu HĐND nơi đại biểu sinh hoạt"],"why":"UBND cấp xã nơi đại biểu cư trú bố trí địa điểm, tạo điều kiện thuận lợi và bảo đảm an ninh, trật tự, an toàn. Ban Thường trực Ủy ban MTTQ cấp xã thì phối hợp tổ chức, thông báo và vận động cử tri tham dự.","cc":"Khoản 4 Điều 27 Nghị quyết liên tịch 72/2025/NQLT/UBTVQH15-CP-ĐCTUBTWMTTQVN (đã sửa đổi, bổ sung năm 2025)"},{"id":"ctx-023","cd":"ct","m":1,"l":"th","q":"Xã A có nhiều thôn vùng cao, mùa mưa đi lại khó khăn. Tổ đại biểu HĐND xã muốn tổ chức tiếp xúc cử tri trực tiếp kết hợp với trực tuyến. Theo Nghị quyết liên tịch 72/2025 (đã sửa đổi năm 2025), việc này có được phép không?","a":["Được; Tổ đại biểu HĐND cấp xã có thể tổ chức, căn cứ vào điều kiện thực tế","Không; chỉ Tổ đại biểu HĐND cấp tỉnh mới được tổ chức tiếp xúc trực tuyến","Không; đại biểu HĐND cấp xã chỉ được tiếp xúc cử tri theo phương thức trực tiếp","Được; nhưng phải được Đoàn đại biểu Quốc hội tỉnh chấp thuận trước"],"why":"Căn cứ điều kiện thực tế, Tổ đại biểu HĐND cấp tỉnh, cấp xã đều có thể tổ chức tiếp xúc cử tri trực tuyến hoặc trực tiếp kết hợp trực tuyến, với điều kiện bảo đảm kỹ thuật, an toàn thông tin mạng, an ninh mạng.","cc":"Khoản 1 Điều 35 Nghị quyết liên tịch 72/2025/NQLT/UBTVQH15-CP-ĐCTUBTWMTTQVN (đã sửa đổi, bổ sung năm 2025)"},{"id":"ctx-024","cd":"ct","m":1,"l":"kt","q":"Theo Nghị quyết liên tịch 72/2025, việc tiếp xúc cử tri trực tuyến chỉ được thực hiện khi bảo đảm điều kiện nào?","a":["Các điều kiện kỹ thuật, an toàn thông tin mạng, an ninh mạng","Có ít nhất một nửa số cử tri đăng ký tham dự trực tuyến","Được UBND cấp tỉnh chấp thuận bằng văn bản","Được truyền hình trực tiếp trên báo, đài địa phương"],"why":"Tiếp xúc cử tri trực tuyến chỉ được thực hiện khi bảo đảm các điều kiện kỹ thuật, an toàn thông tin mạng, an ninh mạng; không có yêu cầu về tỷ lệ cử tri đăng ký hay phải được UBND cấp tỉnh chấp thuận.","cc":"Khoản 4 Điều 35 Nghị quyết liên tịch 72/2025/NQLT/UBTVQH15-CP-ĐCTUBTWMTTQVN (đã sửa đổi, bổ sung năm 2025)"},{"id":"ctx-025","cd":"ct","m":1,"l":"th","q":"Trước kỳ họp HĐND, địa phương xảy ra bão lũ nghiêm trọng. Theo Nghị quyết liên tịch 72/2025, căn cứ tình hình và điều kiện thực tế, ai quyết định tổ chức hoặc không tổ chức tiếp xúc cử tri của đại biểu HĐND?","a":["Thường trực HĐND","Chủ tịch UBND cùng cấp","Ban Thường trực Ủy ban MTTQ cùng cấp","Từng Tổ đại biểu HĐND tự quyết định"],"why":"Khi xảy ra thiên tai, dịch bệnh hoặc sự kiện bất khả kháng, Thường trực HĐND quyết định tổ chức hoặc không tổ chức tiếp xúc cử tri của đại biểu HĐND, căn cứ tình hình và điều kiện thực tế tại địa phương.","cc":"Khoản 1 Điều 36 Nghị quyết liên tịch 72/2025/NQLT/UBTVQH15-CP-ĐCTUBTWMTTQVN (đã sửa đổi, bổ sung năm 2025)"},{"id":"ctx-026","cd":"ct","m":1,"l":"kt","q":"Thông qua tiếp xúc cử tri, đại biểu HĐND tập hợp ý kiến, kiến nghị của cử tri và gửi bằng văn bản đến đâu để tổng hợp, báo cáo Thường trực HĐND?","a":["Tổ đại biểu HĐND","UBND cùng cấp","Ban của HĐND phụ trách lĩnh vực","Ban Thường trực Ủy ban MTTQ cùng cấp"],"why":"Đại biểu HĐND gửi ý kiến, kiến nghị của cử tri bằng văn bản đến Tổ đại biểu HĐND; Tổ tổng hợp, báo cáo Thường trực HĐND để chuyển đến cơ quan, tổ chức, cá nhân có thẩm quyền xem xét giải quyết.","cc":"Khoản 1 Điều 41 Nghị quyết liên tịch 72/2025/NQLT/UBTVQH15-CP-ĐCTUBTWMTTQVN (đã sửa đổi, bổ sung năm 2025)"},{"id":"ctx-030","cd":"ct","m":1,"l":"kt","q":"Đối với kiến nghị của cử tri qua tiếp xúc cử tri của đại biểu HĐND, cơ quan, tổ chức, cá nhân có thẩm quyền phải giải quyết và trả lời cử tri chậm nhất sau bao lâu kể từ ngày nhận được kiến nghị?","a":["30 ngày","15 ngày","45 ngày","60 ngày"],"why":"Với tiếp xúc cử tri của đại biểu HĐND, thời hạn giải quyết, trả lời là chậm nhất sau 30 ngày kể từ ngày nhận được kiến nghị. Mốc 60 ngày áp dụng cho kiến nghị qua tiếp xúc cử tri của đại biểu Quốc hội.","cc":"Khoản 1 Điều 50 Nghị quyết liên tịch 72/2025/NQLT/UBTVQH15-CP-ĐCTUBTWMTTQVN (đã sửa đổi, bổ sung năm 2025)"},{"id":"ctx-036","cd":"ct","m":1,"l":"kt","q":"Kinh phí tổ chức tiếp xúc cử tri của đại biểu HĐND các cấp do nguồn nào bảo đảm?","a":["Ngân sách nhà nước, theo quy định của pháp luật","Đại biểu HĐND tự chi trả từ thu nhập cá nhân","Đóng góp tự nguyện của cử tri và doanh nghiệp","Quỹ của Ủy ban MTTQ cấp tổ chức hội nghị"],"why":"Kinh phí tổ chức tiếp xúc cử tri của đại biểu Quốc hội, đại biểu HĐND các cấp do ngân sách nhà nước bảo đảm theo quy định của pháp luật; không huy động đóng góp của cử tri hay doanh nghiệp.","cc":"Điều 57 Nghị quyết liên tịch 72/2025/NQLT/UBTVQH15-CP-ĐCTUBTWMTTQVN (đã sửa đổi, bổ sung năm 2025)"},{"id":"ctd-002","cd":"ct","m":2,"l":"th","q":"Ông H là đại biểu HĐND tỉnh, ứng cử tại xã A. Sau đó ông chuyển sinh hoạt đến xã B trong cùng tỉnh. Theo Nghị quyết 116/2025/UBTVQH15, ông H thực hiện việc tiếp công dân tại địa phương ở đâu?","a":["Ở nơi chuyển đến là xã B","Vẫn chỉ ở xã A, nơi ông đã ứng cử","Ở cả xã A và xã B, luân phiên hằng tháng","Ở bất kỳ xã nào trong tỉnh do ông tự chọn"],"why":"Đại biểu HĐND cấp tỉnh chuyển sinh hoạt đến địa phương khác trong cùng đơn vị hành chính cấp tỉnh thì thực hiện việc tiếp công dân ở nơi chuyển đến, không tiếp tục gắn với nơi ứng cử ban đầu.","cc":"Khoản 2 Điều 8 Nghị quyết số 116/2025/UBTVQH15"},{"id":"ctd-004","cd":"ct","m":2,"l":"th","q":"Một công dân đề nghị được gặp bà M, đại biểu HĐND xã A, để trình bày khiếu nại. Bà M có lý do chính đáng nên chưa thể tiếp. Theo Nghị quyết 116/2025/UBTVQH15, bà M cần làm gì?","a":["Báo cáo Thường trực HĐND cử người nhận đơn hoặc hẹn tiếp vào thời gian thích hợp","Từ chối tiếp và đề nghị công dân gửi đơn qua dịch vụ bưu chính","Đề nghị Chủ tịch UBND xã A tiếp thay và trả lời công dân","Giao Tổ trưởng Tổ đại biểu HĐND tiếp thay và tự xử lý đơn"],"why":"Đại biểu HĐND tiếp công dân theo đề nghị của công dân; nếu bất khả kháng hoặc có lý do chính đáng thì báo cáo Thường trực HĐND cử người nhận đơn hoặc hẹn tiếp vào thời gian thích hợp, không được bỏ mặc đề nghị.","cc":"Điểm c khoản 1 Điều 10 Nghị quyết số 116/2025/UBTVQH15"},{"id":"ctd-005","cd":"ct","m":2,"l":"kt","q":"Theo Nghị quyết 116/2025/UBTVQH15, lịch tiếp công dân định kỳ theo sự phân công của Thường trực HĐND phải được thông báo đến đại biểu HĐND chậm nhất là bao lâu trước ngày có lịch tiếp?","a":["10 ngày","05 ngày làm việc","07 ngày làm việc","15 ngày"],"why":"Lịch tiếp công dân định kỳ được thông báo đến đại biểu HĐND chậm nhất 10 ngày trước ngày có lịch tiếp. Dễ nhầm với mốc 05 ngày làm việc, là hạn đại biểu báo cáo khi không thể tiếp theo lịch.","cc":"Khoản 2 Điều 10 Nghị quyết số 116/2025/UBTVQH15"},{"id":"ctd-006","cd":"ct","m":2,"l":"th","q":"Ông K, đại biểu HĐND tỉnh, đã có lịch tiếp công dân được thông báo nhưng vì lý do công tác không thể tiếp đúng lịch. Theo Nghị quyết 116/2025/UBTVQH15, ông K phải dự kiến thời gian thay đổi cụ thể và báo cáo Thường trực HĐND chậm nhất khi nào?","a":["05 ngày làm việc trước ngày có lịch đã thông báo","10 ngày trước ngày có lịch đã thông báo","03 ngày làm việc trước ngày có lịch đã thông báo","01 ngày trước ngày có lịch đã thông báo"],"why":"Khi không thể tiếp theo lịch đã thông báo, đại biểu HĐND dự kiến thời gian thay đổi cụ thể và báo cáo Thường trực HĐND chậm nhất 05 ngày làm việc trước ngày có lịch, để kịp thông báo đến cơ quan, tổ chức, cá nhân có liên quan.","cc":"Khoản 3 Điều 10 Nghị quyết số 116/2025/UBTVQH15"},{"id":"ctd-015","cd":"ct","m":2,"l":"th","q":"Một Ban của HĐND tỉnh nhận được đơn kiến nghị có nội dung liên quan đến lĩnh vực phụ trách của nhiều Ban của HĐND tỉnh. Theo Nghị quyết 116/2025/UBTVQH15, Ban này xử lý lá đơn đó như thế nào?","a":["Chuyển đến Thường trực HĐND để xử lý theo thẩm quyền","Tự xử lý toàn bộ vì là nơi nhận đơn đầu tiên","Chuyển đến UBND tỉnh để phân công cơ quan xử lý","Trả lại đơn, hướng dẫn người gửi tách thành nhiều đơn"],"why":"Đơn liên quan đến lĩnh vực phụ trách của nhiều Ban thuộc trách nhiệm xử lý của Thường trực HĐND, nên Ban nhận được đơn chuyển đến Thường trực HĐND. Nếu đơn chỉ thuộc lĩnh vực của một Ban khác thì chuyển đến Ban đó.","cc":"Khoản 5 Điều 21 và điểm d khoản 1 Điều 20 Nghị quyết số 116/2025/UBTVQH15"},{"id":"ctd-017","cd":"ct","m":2,"l":"kt","q":"Theo Nghị quyết 116/2025/UBTVQH15, đối với kiến nghị, phản ánh do đại biểu HĐND chuyển đến, cơ quan, tổ chức, cá nhân có thẩm quyền phải thông báo việc giải quyết đến đại biểu HĐND trong thời hạn nào?","a":["05 ngày kể từ ngày có kết quả giải quyết","07 ngày làm việc kể từ ngày nhận được đơn","10 ngày kể từ ngày có kết quả giải quyết","15 ngày kể từ ngày nhận được đơn"],"why":"Với kiến nghị, phản ánh, cơ quan có thẩm quyền phải thông báo việc giải quyết đến đại biểu HĐND trong 05 ngày kể từ ngày có kết quả giải quyết; còn với khiếu nại, tố cáo thì thông báo theo pháp luật về khiếu nại, tố cáo.","cc":"Khoản 5 Điều 22 Nghị quyết số 116/2025/UBTVQH15"},{"id":"ctd-019","cd":"ct","m":2,"l":"kt","q":"Theo Nghị quyết 116/2025/UBTVQH15, khi cơ quan có thẩm quyền không giải quyết, không trả lời đơn đã chuyển, trường hợp cần thiết Thường trực HĐND có thể tổ chức Đoàn giám sát hoặc giao chủ thể nào giám sát việc giải quyết?","a":["Ban của HĐND cùng cấp","Tổ đại biểu HĐND nơi phát sinh vụ việc","Ủy ban MTTQ Việt Nam cùng cấp","Chủ tịch UBND cùng cấp"],"why":"Trường hợp cần thiết, Thường trực HĐND tổ chức Đoàn giám sát hoặc giao Ban của HĐND cùng cấp giám sát việc giải quyết khiếu nại, tố cáo, kiến nghị, phản ánh.","cc":"Điểm c khoản 2 Điều 29 Nghị quyết số 116/2025/UBTVQH15"},{"id":"ctd-024","cd":"ct","m":2,"l":"kt","q":"Các quy định tại Chương IV của Nghị quyết 116/2025/UBTVQH15 (về giám sát việc giải quyết khiếu nại, tố cáo, kiến nghị, phản ánh của Quốc hội và HĐND) có hiệu lực thi hành từ ngày nào?","a":["Ngày 01 tháng 3 năm 2026","Ngày 01 tháng 7 năm 2026","Ngày 01 tháng 01 năm 2026","Ngày 24 tháng 12 năm 2025"],"why":"Chương IV về giám sát có hiệu lực từ ngày 01/3/2026, sớm hơn phần còn lại của Nghị quyết (01/7/2026). Ngày 24/12/2025 là ngày Nghị quyết được thông qua.","cc":"Khoản 2 Điều 38 Nghị quyết số 116/2025/UBTVQH15"},{"id":"ctd-028","cd":"ct","m":2,"l":"th","q":"Ông P khiếu nại một vụ việc đã được giải quyết đúng chính sách, pháp luật, đã được cơ quan nhà nước có thẩm quyền kiểm tra, rà soát, thông báo bằng văn bản và đã được tiếp, giải thích, hướng dẫn, nhưng vẫn cố tình khiếu nại kéo dài. Theo Luật Tiếp công dân, khi ông P tiếp tục đến nơi tiếp công dân thì người tiếp công dân được làm gì?","a":["Được từ chối tiếp ông P","Vẫn bắt buộc phải tiếp và thụ lý lại từ đầu","Phải lập biên bản xử phạt hành chính ông P","Phải chuyển vụ việc sang cơ quan công an xử lý"],"why":"Người tiếp công dân được từ chối tiếp người khiếu nại, tố cáo về vụ việc đã giải quyết đúng chính sách, pháp luật, đã được kiểm tra, rà soát, thông báo bằng văn bản và đã được tiếp, giải thích, hướng dẫn nhưng vẫn cố tình khiếu nại, tố cáo kéo dài.","cc":"Khoản 3 Điều 9 Luật Tiếp công dân số 42/2013/QH13"},{"id":"ctd-029","cd":"ct","m":2,"l":"kt","q":"Theo Luật Tiếp công dân (sửa đổi bởi Luật số 136/2025/QH15), việc tiếp công dân của HĐND xã, phường, đặc khu được thực hiện tại trụ sở UBND cấp xã hoặc tại địa điểm tiếp công dân do ai quyết định?","a":["Chủ tịch UBND cấp xã","Chủ tịch HĐND cấp xã","Thường trực HĐND cấp xã","Chủ tịch UBND cấp tỉnh"],"why":"Việc tiếp công dân của cấp ủy, HĐND, UBND cấp xã thực hiện tại trụ sở UBND cấp xã hoặc địa điểm do Chủ tịch UBND cấp xã quyết định (gọi là địa điểm tiếp công dân cấp xã). Chủ tịch UBND cấp xã trực tiếp phụ trách công tác tiếp công dân ở cấp xã.","cc":"Khoản 1 Điều 15 Luật Tiếp công dân số 42/2013/QH13 (sửa đổi, bổ sung bởi khoản 7 Điều 1 Luật số 136/2025/QH15)"},{"id":"ctd-030","cd":"ct","m":2,"l":"kt","q":"Theo Luật Tiếp công dân (sửa đổi bởi Luật số 136/2025/QH15), Chủ tịch UBND cấp xã phải trực tiếp tiếp công dân tại địa điểm tiếp công dân ít nhất bao nhiêu ngày?","a":["02 ngày trong 01 tháng","01 ngày trong 01 tuần","01 ngày trong 01 tháng","01 ngày trong 01 quý"],"why":"Quy định sửa đổi năm 2025 yêu cầu Chủ tịch UBND cấp xã trực tiếp tiếp công dân ít nhất 02 ngày trong 01 tháng, thay cho mức 01 ngày trong 01 tuần của Luật năm 2013; ngoài ra còn phải tiếp công dân đột xuất trong các trường hợp luật định.","cc":"Điểm c khoản 2 Điều 15 Luật Tiếp công dân số 42/2013/QH13 (sửa đổi, bổ sung bởi khoản 7 Điều 1 Luật số 136/2025/QH15)"},{"id":"ctd-031","cd":"ct","m":2,"l":"kt","q":"Theo Điều 22 Luật Tiếp công dân (sửa đổi bởi Luật số 136/2025/QH15), trong trường hợp cần thiết, đại biểu HĐND chuyển đơn của công dân đến cơ quan, tổ chức, đơn vị có thẩm quyền giải quyết bằng cách nào?","a":["Trực tiếp hoặc thông qua Thường trực HĐND cùng cấp","Chỉ được thông qua Chủ tịch HĐND cùng cấp","Thông qua Ban tiếp công dân cấp tỉnh","Thông qua Chủ tịch UBND cùng cấp"],"why":"Đại biểu HĐND trước hết nghiên cứu, hướng dẫn công dân gửi đến đúng nơi có thẩm quyền; trường hợp cần thiết thì trực tiếp hoặc thông qua Thường trực HĐND cùng cấp chuyển đơn và theo dõi, đôn đốc việc giải quyết.","cc":"Khoản 3 Điều 22 Luật Tiếp công dân số 42/2013/QH13 (sửa đổi, bổ sung bởi khoản 9 Điều 1 Luật số 136/2025/QH15)"},{"id":"ctd-032","cd":"ct","m":2,"l":"th","q":"12 người dân ở xã A cùng đến địa điểm tiếp công dân cấp xã để kiến nghị về một nội dung. Theo Luật Tiếp công dân, những người này được cử tối đa bao nhiêu người đại diện để trình bày với người tiếp công dân?","a":["Không quá 05 người","Không quá 02 người","Không quá 03 người","Không quá 10 người"],"why":"Từ năm đến mười người thì cử một hoặc hai người đại diện; trên mười người thì có thể cử thêm nhưng không quá năm người. Người đại diện phải là người trong số những người khiếu nại, tố cáo, kiến nghị, phản ánh.","cc":"Điều 29 Luật Tiếp công dân số 42/2013/QH13"},{"id":"ctx-005","cd":"ct","m":2,"l":"kt","q":"Đối với hội nghị tiếp xúc cử tri định kỳ của đại biểu HĐND trước kỳ họp thường lệ, chủ thể nào có trách nhiệm tổ chức, chủ trì và cử người ghi biên bản hội nghị?","a":["Ban Thường trực Ủy ban MTTQ cấp đại biểu tiếp xúc cử tri","Thường trực HĐND cấp đại biểu tiếp xúc cử tri","UBND tại nơi đại biểu tiếp xúc cử tri","Tổ đại biểu HĐND nơi đại biểu sinh hoạt"],"why":"Ban Thường trực Ủy ban MTTQ cấp đại biểu tiếp xúc cử tri tổ chức, chủ trì và cử người ghi biên bản hội nghị, đồng thời tuyên truyền, thông báo rộng rãi để cử tri tham dự. Thường trực HĐND, UBND cử đại diện tham dự chứ không chủ trì.","cc":"Điểm b khoản 1 Điều 11 Nghị quyết liên tịch 72/2025/NQLT/UBTVQH15-CP-ĐCTUBTWMTTQVN (đã sửa đổi, bổ sung năm 2025)"},{"id":"ctx-006","cd":"ct","m":2,"l":"kt","q":"Chậm nhất bao lâu trước ngày tiếp xúc cử tri của đại biểu HĐND, Ban Thường trực Ủy ban MTTQ phải gửi kế hoạch tiếp xúc cử tri đến các cơ quan báo chí ở địa phương để thông báo rộng rãi?","a":["05 ngày làm việc","03 ngày làm việc","07 ngày làm việc","10 ngày làm việc"],"why":"Thời hạn là chậm nhất 05 ngày làm việc trước ngày tiếp xúc cử tri của đại biểu HĐND. Mốc 07 ngày làm việc là quy định đối với kế hoạch tiếp xúc cử tri của đại biểu Quốc hội do Đoàn đại biểu Quốc hội gửi.","cc":"Điểm b khoản 2 Điều 11 Nghị quyết liên tịch 72/2025/NQLT/UBTVQH15-CP-ĐCTUBTWMTTQVN (đã sửa đổi, bổ sung năm 2025)"},{"id":"ctx-007","cd":"ct","m":2,"l":"th","q":"Đại biểu HĐND tỉnh tiếp xúc cử tri tại xã A. Nhiều cử tri kiến nghị sửa chữa đường liên thôn thuộc thẩm quyền giải quyết của xã. Theo Nghị quyết liên tịch 72/2025, UBND xã A có trách nhiệm gì đối với hội nghị này?","a":["Cử đại diện lãnh đạo UBND xã tham dự để xem xét giải quyết, trả lời kiến nghị thuộc thẩm quyền cấp mình","Không phải tham dự, vì đây là hội nghị tiếp xúc cử tri của đại biểu HĐND cấp tỉnh","Chỉ bảo đảm an ninh, trật tự; việc trả lời kiến nghị do UBND tỉnh thực hiện","Chủ trì, điều hành hội nghị thay cho Ban Thường trực Ủy ban MTTQ"],"why":"UBND tại đơn vị hành chính nơi đại biểu tiếp xúc cử tri phải cử đại diện lãnh đạo tham dự để xem xét giải quyết, trả lời kiến nghị thuộc thẩm quyền của cấp mình, đồng thời phối hợp tổ chức và bảo đảm an ninh, trật tự.","cc":"Điểm b khoản 2 Điều 13 Nghị quyết liên tịch 72/2025/NQLT/UBTVQH15-CP-ĐCTUBTWMTTQVN (đã sửa đổi, bổ sung năm 2025)"},{"id":"ctx-008","cd":"ct","m":2,"l":"th","q":"Bà M là đại biểu HĐND tỉnh, công tác tại một bệnh viện có tổ chức công đoàn. Bà đề nghị được tiếp xúc cử tri tại nơi làm việc. Theo Nghị quyết liên tịch 72/2025, ai có trách nhiệm chủ trì tổ chức và tổ chức ghi biên bản hội nghị tiếp xúc cử tri này?","a":["Thủ trưởng bệnh viện, phối hợp với Chủ tịch Công đoàn bệnh viện","Ban Thường trực Ủy ban MTTQ cấp xã nơi bệnh viện đặt trụ sở","Thường trực HĐND tỉnh, phối hợp với UBND cấp xã sở tại","Tổ đại biểu HĐND tỉnh nơi bà M sinh hoạt"],"why":"Khi đại biểu đề nghị tiếp xúc cử tri nơi làm việc, Thủ trưởng cơ quan, tổ chức chủ trì, phối hợp với Chủ tịch Công đoàn (nếu có) tổ chức, bố trí thời gian, địa điểm và tổ chức ghi biên bản hội nghị; không phải Ban Thường trực Ủy ban MTTQ.","cc":"Điều 14 Nghị quyết liên tịch 72/2025/NQLT/UBTVQH15-CP-ĐCTUBTWMTTQVN (đã sửa đổi, bổ sung năm 2025)"},{"id":"ctx-011","cd":"ct","m":2,"l":"kt","q":"Theo Nghị quyết liên tịch 72/2025 (đã sửa đổi năm 2025), việc đại biểu HĐND cấp tỉnh và đại biểu HĐND cấp xã cùng tiếp xúc cử tri do ai xem xét, quyết định?","a":["Thường trực HĐND cấp tỉnh trao đổi với Thường trực HĐND cấp xã để xem xét, quyết định","Ban Thường trực Ủy ban MTTQ cấp tỉnh thống nhất với UBND cấp xã để quyết định","Tổ đại biểu HĐND cấp tỉnh tự quyết định và thông báo cho HĐND cấp xã","UBND cấp tỉnh trao đổi với Thường trực HĐND cấp xã để xem xét, quyết định"],"why":"Đại biểu HĐND hai cấp có thể cùng tiếp xúc cử tri; Thường trực HĐND cấp tỉnh trao đổi với Thường trực HĐND cấp xã để xem xét, quyết định, rồi chủ trì xây dựng kế hoạch tiếp xúc cử tri của đại biểu HĐND hai cấp.","cc":"Khoản 2 Điều 22 Nghị quyết liên tịch 72/2025/NQLT/UBTVQH15-CP-ĐCTUBTWMTTQVN (đã sửa đổi, bổ sung năm 2025)"},{"id":"ctx-014","cd":"ct","m":2,"l":"th","q":"Tại hội nghị ở xã A, đại biểu Quốc hội, đại biểu HĐND tỉnh và đại biểu HĐND xã cùng tiếp xúc cử tri. Theo Nghị quyết liên tịch 72/2025 (đã sửa đổi năm 2025), việc giới thiệu đại biểu, trình bày báo cáo được thực hiện theo thứ tự nào?","a":["Nội dung của đại biểu Quốc hội trước, rồi đại biểu HĐND cấp tỉnh, sau đó đại biểu HĐND cấp xã","Nội dung của đại biểu HĐND cấp xã trước, rồi đại biểu HĐND cấp tỉnh, sau đó đại biểu Quốc hội","Nội dung của đại biểu HĐND cấp tỉnh trước, rồi đại biểu Quốc hội, sau đó đại biểu HĐND cấp xã","Theo thứ tự do đại diện Ban Thường trực Ủy ban MTTQ chủ trì hội nghị tự quyết định"],"why":"Khi các đại biểu cùng tiếp xúc cử tri, nội dung liên quan đến đại biểu Quốc hội được tiến hành trước nội dung của đại biểu HĐND cấp tỉnh; nội dung của đại biểu HĐND cấp tỉnh tiến hành trước nội dung của đại biểu HĐND cấp xã.","cc":"Khoản 3 Điều 24 Nghị quyết liên tịch 72/2025/NQLT/UBTVQH15-CP-ĐCTUBTWMTTQVN (đã sửa đổi, bổ sung năm 2025)"},{"id":"ctx-015","cd":"ct","m":2,"l":"kt","q":"Sau đợt tiếp xúc cử tri trước kỳ họp HĐND, Tổ trưởng Tổ đại biểu HĐND cấp tỉnh, cấp xã phải báo cáo kết quả tiếp xúc cử tri với Thường trực HĐND cùng cấp bằng hình thức nào và vào thời điểm nào?","a":["Bằng văn bản, trước ngày khai mạc kỳ họp","Bằng văn bản, trong 07 ngày làm việc sau ngày bế mạc kỳ họp","Báo cáo trực tiếp tại phiên khai mạc kỳ họp HĐND","Bằng văn bản, trong 30 ngày kể từ ngày tiếp xúc cử tri"],"why":"Trước ngày khai mạc kỳ họp, Tổ trưởng Tổ đại biểu HĐND cấp tỉnh, cấp xã có trách nhiệm báo cáo kết quả tiếp xúc cử tri bằng văn bản với Thường trực HĐND cùng cấp, để kịp tổng hợp ý kiến, kiến nghị của cử tri phục vụ kỳ họp.","cc":"Khoản 2 Điều 26 Nghị quyết liên tịch 72/2025/NQLT/UBTVQH15-CP-ĐCTUBTWMTTQVN (đã sửa đổi, bổ sung năm 2025)"},{"id":"ctx-017","cd":"ct","m":2,"l":"th","q":"Ông K là đại biểu HĐND tỉnh, cư trú tại phường B và muốn tiếp xúc cử tri nơi cư trú. Theo Nghị quyết liên tịch 72/2025 (đã sửa đổi năm 2025), ông trực tiếp hoặc thông qua Thường trực HĐND tỉnh liên hệ với cơ quan nào để tổ chức tiếp xúc cử tri?","a":["Ban Thường trực Ủy ban MTTQ phường B","Ban Thường trực Ủy ban MTTQ cấp tỉnh","Văn phòng Đoàn ĐBQH và HĐND tỉnh","Ban Công tác Mặt trận ở tổ dân phố nơi ông cư trú"],"why":"Đại biểu HĐND cấp tỉnh muốn tiếp xúc cử tri nơi cư trú thì trực tiếp hoặc thông qua Thường trực HĐND cùng cấp liên hệ với Ban Thường trực Ủy ban MTTQ cấp xã nơi cư trú để tổ chức; UBND cấp xã bố trí địa điểm, bảo đảm an ninh, trật tự.","cc":"Khoản 2 Điều 27 Nghị quyết liên tịch 72/2025/NQLT/UBTVQH15-CP-ĐCTUBTWMTTQVN (đã sửa đổi, bổ sung năm 2025)"},{"id":"ctx-019","cd":"ct","m":2,"l":"th","q":"Bà L, đại biểu HĐND tỉnh, có nguyện vọng tiếp xúc cử tri tại một xã trong tỉnh nhưng ngoài đơn vị bầu cử của mình. Theo Nghị quyết liên tịch 72/2025, trước hết bà L phải làm gì?","a":["Gửi văn bản đề nghị kèm chương trình, kế hoạch, nội dung tiếp xúc đến Thường trực HĐND tỉnh","Gửi văn bản đề nghị đến UBND xã nơi dự kiến tiếp xúc để được chấp thuận","Thông báo bằng văn bản cho Đoàn đại biểu Quốc hội tỉnh để sắp xếp, bố trí","Trực tiếp liên hệ Ban Công tác Mặt trận tại thôn để mời cử tri đến dự"],"why":"Đại biểu HĐND muốn tiếp xúc cử tri ngoài đơn vị bầu cử phải gửi văn bản đề nghị cùng chương trình, kế hoạch, nội dung tiếp xúc đến Thường trực HĐND cùng cấp; Thường trực HĐND xem xét, quyết định và thông báo lại cho đại biểu.","cc":"Khoản 1 Điều 32 Nghị quyết liên tịch 72/2025/NQLT/UBTVQH15-CP-ĐCTUBTWMTTQVN (đã sửa đổi, bổ sung năm 2025)"},{"id":"ctx-027","cd":"ct","m":2,"l":"kt","q":"Sau ngày tiếp xúc cử tri trước và sau kỳ họp thường lệ của HĐND, Tổ đại biểu HĐND phải chủ trì, phối hợp với Ban Thường trực Ủy ban MTTQ cùng cấp tổng hợp, phân loại ý kiến, kiến nghị của cử tri chậm nhất trong thời hạn nào?","a":["03 ngày làm việc","05 ngày làm việc","07 ngày làm việc","10 ngày làm việc"],"why":"Chậm nhất 03 ngày làm việc sau ngày tiếp xúc cử tri (hoặc sau khi nhận được ý kiến, kiến nghị do đại biểu gửi đến), Tổ đại biểu HĐND chủ trì, phối hợp với Ban Thường trực Ủy ban MTTQ cùng cấp tổng hợp, phân loại và báo cáo Thường trực HĐND.","cc":"Khoản 2 Điều 41 Nghị quyết liên tịch 72/2025/NQLT/UBTVQH15-CP-ĐCTUBTWMTTQVN (đã sửa đổi, bổ sung năm 2025)"},{"id":"ctx-032","cd":"ct","m":2,"l":"th","q":"Tổ đại biểu HĐND tỉnh nhận được văn bản của một sở trả lời kiến nghị của cử tri xã A. Theo Nghị quyết liên tịch 72/2025 (đã sửa đổi năm 2025), Tổ đại biểu có trách nhiệm xử lý thế nào?","a":["Ngay sau khi nhận, thông báo kết quả đến cử tri và công khai văn bản trả lời trên phương tiện thông tin đại chúng","Lưu hồ sơ, đến kỳ tiếp xúc cử tri định kỳ kế tiếp mới thông báo kết quả cho cử tri","Chuyển văn bản cho UBND xã A để UBND xã quyết định việc có thông báo hay không","Trong thời hạn 30 ngày, báo cáo HĐND tỉnh tại kỳ họp rồi mới thông báo đến cử tri"],"why":"Ngay sau khi nhận được văn bản trả lời cử tri, Tổ đại biểu HĐND có trách nhiệm thông báo kết quả giải quyết, trả lời đến cử tri và thông tin công khai văn bản trả lời trên các phương tiện thông tin đại chúng ở địa phương.","cc":"Khoản 3 Điều 50 Nghị quyết liên tịch 72/2025/NQLT/UBTVQH15-CP-ĐCTUBTWMTTQVN (đã sửa đổi, bổ sung năm 2025)"},{"id":"ctx-033","cd":"ct","m":2,"l":"kt","q":"Theo Nghị quyết liên tịch 72/2025, kết quả giải quyết, trả lời kiến nghị của cử tri được niêm yết ở đâu và trong thời gian bao lâu?","a":["Tại trụ sở tiếp công dân cấp giải quyết kiến nghị, trong vòng 30 ngày","Tại nhà văn hóa thôn, tổ dân phố nơi cử tri kiến nghị, trong vòng 15 ngày","Tại trụ sở HĐND cấp tỉnh, trong vòng 60 ngày","Tại trụ sở tiếp công dân cấp giải quyết kiến nghị, trong vòng 07 ngày"],"why":"Kết quả giải quyết, trả lời kiến nghị của cử tri được niêm yết trong vòng 30 ngày tại trụ sở tiếp công dân cấp giải quyết kiến nghị, bên cạnh việc công khai trên phương tiện thông tin đại chúng và trang thông tin điện tử.","cc":"Khoản 2 Điều 51 Nghị quyết liên tịch 72/2025/NQLT/UBTVQH15-CP-ĐCTUBTWMTTQVN (đã sửa đổi, bổ sung năm 2025)"},{"id":"ctx-034","cd":"ct","m":2,"l":"th","q":"Thường trực HĐND tỉnh yêu cầu một Tổ đại biểu HĐND tỉnh đánh giá việc các cơ quan ở địa phương giải quyết kiến nghị của cử tri trên địa bàn. Theo Nghị quyết liên tịch 72/2025, Tổ đại biểu có trách nhiệm gì?","a":["Đánh giá kết quả giải quyết và gửi kết quả đến Thường trực HĐND","Chuyển yêu cầu cho Ban của HĐND, vì Tổ đại biểu không có trách nhiệm đánh giá","Đề nghị UBND tỉnh tự đánh giá rồi báo cáo thay cho Tổ đại biểu","Ra kết luận buộc cơ quan liên quan giải quyết lại kiến nghị của cử tri"],"why":"Theo yêu cầu của Thường trực HĐND, căn cứ kiến nghị của cử tri và kết quả giải quyết của cơ quan có thẩm quyền ở địa phương, Tổ đại biểu HĐND có trách nhiệm đánh giá kết quả giải quyết và gửi kết quả đến Thường trực HĐND.","cc":"Khoản 5 Điều 53 Nghị quyết liên tịch 72/2025/NQLT/UBTVQH15-CP-ĐCTUBTWMTTQVN (đã sửa đổi, bổ sung năm 2025)"},{"id":"ctx-035","cd":"ct","m":2,"l":"kt","q":"Tại kỳ họp HĐND, sau khi trình báo cáo giám sát kết quả giải quyết, trả lời kiến nghị của cử tri, trong trường hợp cần thiết Thường trực HĐND đề nghị HĐND làm gì?","a":["Ban hành nghị quyết về việc giải quyết, trả lời kiến nghị của cử tri","Lấy phiếu tín nhiệm người đứng đầu cơ quan chậm trả lời kiến nghị","Thành lập Ban lâm thời để giải quyết thay cơ quan có thẩm quyền","Tổ chức một kỳ họp chuyên đề riêng về kiến nghị của cử tri"],"why":"Thường trực HĐND trình HĐND báo cáo giám sát kết quả giải quyết, trả lời kiến nghị của cử tri tại kỳ họp; trong trường hợp cần thiết thì đề nghị HĐND ban hành nghị quyết về việc giải quyết, trả lời kiến nghị của cử tri.","cc":"Khoản 2 Điều 54 Nghị quyết liên tịch 72/2025/NQLT/UBTVQH15-CP-ĐCTUBTWMTTQVN (đã sửa đổi, bổ sung năm 2025)"},{"id":"ctd-010","cd":"ct","m":3,"l":"th","q":"Đại biểu HĐND tỉnh nhận được một đơn tố cáo không ghi họ tên, địa chỉ người viết. Đơn nêu rõ người có hành vi vi phạm pháp luật, kèm tài liệu, chứng cứ cụ thể và có cơ sở để thẩm tra, xác minh. Theo Nghị quyết 116/2025/UBTVQH15, đơn này được phân loại thế nào?","a":["Cũng được coi là đơn đủ điều kiện xử lý","Là đơn không đủ điều kiện xử lý, chỉ lưu đơn","Là đơn kiến nghị, phản ánh, không phải đơn tố cáo","Phải hủy ngay vì không xác định được người gửi"],"why":"Đơn tố cáo không rõ họ tên, địa chỉ người viết nhưng nêu rõ người vi phạm, có tài liệu, chứng cứ cụ thể và có cơ sở để thẩm tra, xác minh thì cũng được coi là đủ điều kiện xử lý. Không phải mọi đơn nặc danh đều bị xếp lưu.","cc":"Điểm b khoản 2 Điều 13 Nghị quyết số 116/2025/UBTVQH15"},{"id":"ctd-011","cd":"ct","m":3,"l":"th","q":"Thường trực HĐND xã A nhận được đơn khiếu nại của một hộ dân. Đơn ghi gửi đồng thời nhiều nơi, trong đó có Chủ tịch UBND xã A là người có thẩm quyền giải quyết. Theo Nghị quyết 116/2025/UBTVQH15, Thường trực HĐND xã A xử lý đơn này thế nào?","a":["Xếp vào loại đơn không đủ điều kiện xử lý và thực hiện việc lưu đơn","Chuyển ngay đơn đến Chủ tịch UBND xã A và đôn đốc giải quyết","Chuyển đến Thường trực HĐND cấp tỉnh để xem xét, xử lý","Tổ chức Đoàn giám sát việc giải quyết khiếu nại của UBND xã A"],"why":"Đơn gửi cho nhiều cơ quan, tổ chức, cá nhân trong đó đã có nơi có thẩm quyền giải quyết thuộc loại đơn không đủ điều kiện xử lý; đơn không đủ điều kiện xử lý thì được lưu, không phải chuyển lại.","cc":"Điểm b khoản 3 Điều 13 và điểm a khoản 1 Điều 19 Nghị quyết số 116/2025/UBTVQH15"},{"id":"ctd-013","cd":"ct","m":3,"l":"th","q":"Bà T nhiều lần gửi đơn đến một Ban của HĐND tỉnh về một vụ việc đã được cơ quan nhà nước có thẩm quyền xem xét, giải quyết, trả lời và không có căn cứ để xem xét lại. Theo Nghị quyết 116/2025/UBTVQH15, Ban xử lý các đơn này thế nào?","a":["Lưu đơn; khi xét thấy cần thiết thì hướng dẫn, trả lời bà T biết","Mỗi lần nhận đơn đều chuyển lại cho cơ quan đã giải quyết","Kiến nghị Thường trực HĐND tổ chức Đoàn giám sát vụ việc","Trả lại đơn và yêu cầu bà T chấm dứt việc gửi đơn"],"why":"Đơn đã được cơ quan có thẩm quyền giải quyết, trả lời mà không có căn cứ xem xét lại thì được lưu. Nếu người gửi tiếp tục gửi nhiều lần, khi xét thấy cần thiết Ban của HĐND hướng dẫn, trả lời người gửi đơn biết.","cc":"Điểm b khoản 1 và khoản 3 Điều 19 Nghị quyết số 116/2025/UBTVQH15"},{"id":"ctd-014","cd":"ct","m":3,"l":"kt","q":"Theo Nghị quyết 116/2025/UBTVQH15, khi cơ quan có thẩm quyền ở trung ương không giải quyết, không trả lời đơn do Thường trực HĐND cấp tỉnh chuyển đến, Thường trực HĐND cấp tỉnh có thể kiến nghị chủ thể nào tổ chức giám sát?","a":["Ủy ban Thường vụ Quốc hội, Hội đồng Dân tộc, Ủy ban của Quốc hội theo lĩnh vực phụ trách","Chính phủ, Thủ tướng Chính phủ hoặc Bộ trưởng quản lý ngành, lĩnh vực có liên quan","Thanh tra Chính phủ hoặc cơ quan thanh tra của Bộ, ngành có liên quan","Ủy ban Trung ương MTTQ Việt Nam và các tổ chức chính trị - xã hội ở trung ương"],"why":"Với đơn thuộc thẩm quyền của cơ quan trung ương, Thường trực HĐND cấp tỉnh không tự giám sát mà kiến nghị Ủy ban Thường vụ Quốc hội, Hội đồng Dân tộc, Ủy ban của Quốc hội theo lĩnh vực phụ trách tổ chức giám sát.","cc":"Điểm b khoản 6 Điều 20 Nghị quyết số 116/2025/UBTVQH15"},{"id":"ctd-016","cd":"ct","m":3,"l":"th","q":"Qua tiếp xúc cử tri, đại biểu HĐND xã A nhận được đơn kiến nghị về một nội dung thuộc thẩm quyền giải quyết của cơ quan có thẩm quyền ở trung ương. Theo Nghị quyết 116/2025/UBTVQH15, đại biểu chuyển đơn này đến đâu?","a":["Thường trực HĐND cấp tỉnh để xem xét, xử lý","Trực tiếp đến cơ quan trung ương có thẩm quyền giải quyết","Đoàn đại biểu Quốc hội của tỉnh để xử lý","Chủ tịch UBND xã A để báo cáo lên cấp trên"],"why":"Đơn thuộc thẩm quyền giải quyết của cơ quan trung ương thì đại biểu HĐND cấp tỉnh, cấp xã không chuyển thẳng mà chuyển đến Thường trực HĐND cấp tỉnh để xem xét, xử lý.","cc":"Khoản 4 Điều 22 Nghị quyết số 116/2025/UBTVQH15"},{"id":"ctd-018","cd":"ct","m":3,"l":"th","q":"Đại biểu HĐND xã A chuyển đơn khiếu nại của cử tri đến một cơ quan có thẩm quyền ở cấp tỉnh. Cơ quan này đã trả lời nhưng đại biểu không đồng ý với kết quả giải quyết. Theo Nghị quyết 116/2025/UBTVQH15, đại biểu có thể kiến nghị chủ thể nào tổ chức giám sát?","a":["Thường trực HĐND cấp tỉnh","Thường trực HĐND xã A","Ủy ban Thường vụ Quốc hội","Đoàn đại biểu Quốc hội của tỉnh"],"why":"Khi cơ quan có thẩm quyền ở cấp tỉnh không giải quyết, không trả lời hoặc đại biểu HĐND cấp xã không đồng ý với kết quả giải quyết, đại biểu kiến nghị Thường trực HĐND cấp tỉnh tổ chức giám sát.","cc":"Điểm b khoản 6 Điều 22 Nghị quyết số 116/2025/UBTVQH15"},{"id":"ctd-021","cd":"ct","m":3,"l":"th","q":"Đại biểu HĐND xã B đã chuyển đơn khiếu nại của cử tri đến Chủ tịch UBND xã B nhưng không được giải quyết, không được trả lời. Theo Nghị quyết 116/2025/UBTVQH15, quyền nào sau đây thuộc về cá nhân đại biểu HĐND trong trường hợp này?","a":["Gặp người đứng đầu cơ quan, tổ chức có liên quan để tìm hiểu, yêu cầu xem xét lại","Tổ chức Đoàn giám sát để giám sát việc giải quyết khiếu nại","Giao Ban của HĐND xã B giám sát việc giải quyết khiếu nại","Ra quyết định giải quyết khiếu nại thay Chủ tịch UBND xã B"],"why":"Đại biểu HĐND có quyền gặp người đứng đầu cơ quan, tổ chức có liên quan để tìm hiểu, yêu cầu xem xét lại. Tổ chức Đoàn giám sát là quyền của Thường trực HĐND, Ban của HĐND; giao Ban giám sát là quyền của Thường trực HĐND.","cc":"Điểm a khoản 2 Điều 31 Nghị quyết số 116/2025/UBTVQH15"},{"id":"ctd-022","cd":"ct","m":3,"l":"kt","q":"Theo Nghị quyết 116/2025/UBTVQH15, Thường trực HĐND, Ban của HĐND báo cáo HĐND cùng cấp về kết quả tiếp công dân, xử lý đơn và giám sát việc giải quyết khiếu nại, tố cáo, kiến nghị, phản ánh theo định kỳ nào?","a":["Định kỳ hằng năm hoặc đột xuất","Định kỳ hằng tháng, hằng năm hoặc đột xuất","Định kỳ hằng quý, hằng năm hoặc đột xuất","Định kỳ 06 tháng, hằng năm hoặc đột xuất"],"why":"Ở địa phương, Thường trực HĐND, Ban của HĐND báo cáo HĐND cùng cấp định kỳ hằng năm hoặc đột xuất. Chế độ hằng tháng, hằng năm hoặc đột xuất là của các cơ quan của Quốc hội, Đoàn đại biểu Quốc hội báo cáo Ủy ban Thường vụ Quốc hội.","cc":"Khoản 2 Điều 32 Nghị quyết số 116/2025/UBTVQH15"},{"id":"ctx-009","cd":"ct","m":3,"l":"kt","q":"Với đại biểu HĐND, hoạt động tiếp xúc cử tri nào được Nghị quyết liên tịch 72/2025 quy định áp dụng hình thức hội nghị, còn các hoạt động khác thì có thể tổ chức hoặc không tổ chức hội nghị?","a":["Tiếp xúc cử tri định kỳ trước kỳ họp thường lệ của HĐND","Tiếp xúc cử tri định kỳ sau kỳ họp thường lệ của HĐND","Tiếp xúc cử tri trước và sau kỳ họp chuyên đề của HĐND","Tiếp xúc cử tri theo chuyên đề, lĩnh vực, đối tượng"],"why":"Với HĐND, hội nghị tiếp xúc cử tri được áp dụng cho tiếp xúc định kỳ trước kỳ họp thường lệ. Sau kỳ họp thường lệ, trước và sau kỳ họp chuyên đề, tiếp xúc theo chuyên đề... thì tùy mục đích, yêu cầu mà có thể tổ chức hoặc không tổ chức hội nghị.","cc":"Khoản 1, khoản 2 Điều 21 Nghị quyết liên tịch 72/2025/NQLT/UBTVQH15-CP-ĐCTUBTWMTTQVN (đã sửa đổi, bổ sung năm 2025)"},{"id":"ctx-010","cd":"ct","m":3,"l":"th","q":"Đoàn đại biểu Quốc hội tỉnh và Thường trực HĐND tỉnh thống nhất để đại biểu Quốc hội và đại biểu HĐND tỉnh cùng tiếp xúc cử tri tại xã A. Theo Nghị quyết liên tịch 72/2025, cơ quan nào chủ trì xây dựng kế hoạch tiếp xúc cử tri chung này?","a":["Thường trực HĐND cấp tỉnh","Đoàn đại biểu Quốc hội tỉnh","Ban Thường trực Ủy ban MTTQ cấp tỉnh","Văn phòng Đoàn ĐBQH và HĐND tỉnh"],"why":"Đoàn đại biểu Quốc hội phối hợp với Thường trực HĐND cấp tỉnh xem xét, quyết định việc cùng tiếp xúc; còn kế hoạch chung do Thường trực HĐND cấp tỉnh chủ trì, phối hợp với Đoàn đại biểu Quốc hội và Ban Thường trực Ủy ban MTTQ cùng cấp xây dựng.","cc":"Khoản 1 Điều 22 Nghị quyết liên tịch 72/2025/NQLT/UBTVQH15-CP-ĐCTUBTWMTTQVN (đã sửa đổi, bổ sung năm 2025)"},{"id":"ctx-012","cd":"ct","m":3,"l":"th","q":"Hội nghị tiếp xúc cử tri của đại biểu HĐND tỉnh được tổ chức tại xã A. Theo Nghị quyết liên tịch 72/2025 (đã sửa đổi năm 2025), thành phần đại diện MTTQ tham dự hội nghị được quy định như thế nào?","a":["Đại diện Ban Thường trực Ủy ban MTTQ cấp tỉnh và Ban Thường trực Ủy ban MTTQ xã A","Chỉ đại diện Ban Thường trực Ủy ban MTTQ cấp tỉnh, vì đại biểu thuộc HĐND tỉnh","Chỉ đại diện Ban Thường trực Ủy ban MTTQ xã A, vì hội nghị tổ chức tại xã","Đại diện Ban Công tác Mặt trận các thôn thay cho Ban Thường trực Ủy ban MTTQ"],"why":"Với tiếp xúc cử tri của đại biểu HĐND cấp tỉnh, thành phần gồm đại diện Ban Thường trực Ủy ban MTTQ cấp tỉnh và cấp xã nơi tiếp xúc. Chỉ khi là tiếp xúc cử tri của đại biểu HĐND cấp xã thì thành phần này mới chỉ gồm đại diện MTTQ cấp xã.","cc":"Khoản 3 Điều 23 Nghị quyết liên tịch 72/2025/NQLT/UBTVQH15-CP-ĐCTUBTWMTTQVN (đã sửa đổi, bổ sung năm 2025)"},{"id":"ctx-020","cd":"ct","m":3,"l":"th","q":"Thường trực HĐND tỉnh đã đồng ý để một đại biểu HĐND tỉnh tiếp xúc cử tri ngoài đơn vị bầu cử, tại xã A. Thường trực HĐND tỉnh phải thông báo chương trình, kế hoạch, nội dung tiếp xúc đến Thường trực HĐND và Ban Thường trực Ủy ban MTTQ nơi đại biểu tiếp xúc chậm nhất khi nào?","a":["03 ngày làm việc trước ngày tiếp xúc cử tri","05 ngày làm việc trước ngày tiếp xúc cử tri","07 ngày làm việc trước ngày tiếp xúc cử tri","20 ngày làm việc trước ngày tiếp xúc cử tri"],"why":"Thường trực HĐND cùng cấp thông báo chậm nhất 03 ngày làm việc trước ngày tiếp xúc. Mốc 05 ngày làm việc là hạn Thường trực HĐND xem xét, quyết định đề nghị của đại biểu; 20 ngày làm việc là quy định với đại biểu Quốc hội tiếp xúc ngoài tỉnh.","cc":"Khoản 3 Điều 32 Nghị quyết liên tịch 72/2025/NQLT/UBTVQH15-CP-ĐCTUBTWMTTQVN (đã sửa đổi, bổ sung năm 2025)"},{"id":"ctx-021","cd":"ct","m":3,"l":"kt","q":"Sau khi kết thúc gặp gỡ, tiếp xúc với cá nhân hoặc nhóm cử tri, đại biểu HĐND tổng hợp ý kiến, kiến nghị gửi cơ quan có thẩm quyền xem xét, giải quyết trong thời hạn nào và đồng thời gửi đến đâu?","a":["Chậm nhất 05 ngày làm việc; đồng gửi Tổ đại biểu HĐND, Ban Thường trực Ủy ban MTTQ cùng cấp","Chậm nhất 03 ngày làm việc; đồng gửi Thường trực HĐND và UBND cùng cấp","Chậm nhất 05 ngày làm việc; đồng gửi UBND và Văn phòng HĐND và UBND cùng cấp","Chậm nhất 07 ngày làm việc; đồng gửi Tổ đại biểu HĐND và Ban Công tác Mặt trận"],"why":"Chậm nhất 05 ngày làm việc sau khi kết thúc gặp gỡ, tiếp xúc, đại biểu HĐND tổng hợp ý kiến, kiến nghị gửi cơ quan có thẩm quyền, đồng thời gửi Tổ đại biểu HĐND và Ban Thường trực Ủy ban MTTQ cùng cấp.","cc":"Khoản 8 Điều 33 Nghị quyết liên tịch 72/2025/NQLT/UBTVQH15-CP-ĐCTUBTWMTTQVN (đã sửa đổi, bổ sung năm 2025)"},{"id":"ctx-022","cd":"ct","m":3,"l":"th","q":"HĐND tỉnh chuẩn bị họp kỳ họp chuyên đề; Thường trực HĐND tỉnh quyết định có tổ chức tiếp xúc cử tri trước kỳ họp này. Theo Nghị quyết liên tịch 72/2025 (đã sửa đổi năm 2025), chủ thể nào quyết định hình thức tiếp xúc cử tri?","a":["Tổ đại biểu HĐND cấp tỉnh","Thường trực HĐND cấp tỉnh","Ban Thường trực Ủy ban MTTQ cấp tỉnh","UBND cấp tỉnh"],"why":"Với kỳ họp chuyên đề hoặc kỳ họp giải quyết công việc đột xuất, Thường trực HĐND quyết định có tổ chức tiếp xúc cử tri hay không; khi có tổ chức thì Tổ đại biểu HĐND quyết định hình thức và chủ trì xây dựng báo cáo tổng hợp kiến nghị.","cc":"Khoản 2 Điều 34 Nghị quyết liên tịch 72/2025/NQLT/UBTVQH15-CP-ĐCTUBTWMTTQVN (đã sửa đổi, bổ sung năm 2025)"},{"id":"ctx-028","cd":"ct","m":3,"l":"kt","q":"Báo cáo tổng hợp ý kiến, kiến nghị của cử tri và Nhân dân địa phương phải được gửi đến UBND cùng cấp để xem xét, giải quyết theo thẩm quyền chậm nhất khi nào?","a":["07 ngày làm việc trước ngày khai mạc kỳ họp HĐND","03 ngày làm việc trước ngày khai mạc kỳ họp HĐND","15 ngày trước ngày khai mạc kỳ họp HĐND","30 ngày trước ngày khai mạc kỳ họp HĐND"],"why":"Báo cáo tổng hợp ý kiến, kiến nghị của cử tri được gửi UBND cùng cấp chậm nhất 07 ngày làm việc trước ngày khai mạc kỳ họp. Dễ nhầm với mốc 30 ngày trước kỳ họp: hạn cơ quan giải quyết báo cáo kết quả trả lời kiến nghị đến Thường trực HĐND.","cc":"Khoản 2 Điều 42 Nghị quyết liên tịch 72/2025/NQLT/UBTVQH15-CP-ĐCTUBTWMTTQVN (đã sửa đổi, bổ sung năm 2025)"},{"id":"ctx-029","cd":"ct","m":3,"l":"th","q":"Cử tri xã A kiến nghị về chương trình giám sát của HĐND xã, là vấn đề ngoài lĩnh vực các Ban của HĐND xã phụ trách. Theo Nghị quyết liên tịch 72/2025 (đã sửa đổi năm 2025), cơ quan nào có trách nhiệm giúp Thường trực HĐND xã xem xét, giải quyết, trả lời kiến nghị này?","a":["Văn phòng HĐND và UBND xã A","Ban Thường trực Ủy ban MTTQ xã A","Tổ đại biểu HĐND xã nơi cử tri kiến nghị","Chủ tịch UBND xã A"],"why":"Kiến nghị về chương trình kỳ họp, nội dung, chương trình giám sát của HĐND, Thường trực HĐND và vấn đề khác ngoài lĩnh vực các Ban phụ trách thì Văn phòng HĐND và UBND cấp xã giúp Thường trực HĐND cùng cấp xem xét, giải quyết, trả lời.","cc":"Khoản 2 Điều 45 Nghị quyết liên tịch 72/2025/NQLT/UBTVQH15-CP-ĐCTUBTWMTTQVN (đã sửa đổi, bổ sung năm 2025)"},{"id":"ctx-031","cd":"ct","m":3,"l":"kt","q":"Cơ quan, tổ chức, cá nhân có thẩm quyền giải quyết kiến nghị của cử tri phải báo cáo tổng hợp kết quả giải quyết, trả lời kiến nghị của cử tri tại kỳ họp trước đến Thường trực HĐND chậm nhất khi nào?","a":["30 ngày trước ngày khai mạc kỳ họp HĐND","07 ngày làm việc trước ngày khai mạc kỳ họp HĐND","20 ngày làm việc trước ngày khai mạc kỳ họp HĐND","15 ngày trước ngày khai mạc kỳ họp HĐND"],"why":"Hạn báo cáo tổng hợp kết quả giải quyết, trả lời kiến nghị đến Thường trực HĐND là chậm nhất 30 ngày trước ngày khai mạc kỳ họp HĐND. Mốc 20 ngày làm việc là hạn báo cáo Ủy ban Thường vụ Quốc hội đối với kiến nghị qua đại biểu Quốc hội.","cc":"Khoản 2 Điều 50 Nghị quyết liên tịch 72/2025/NQLT/UBTVQH15-CP-ĐCTUBTWMTTQVN (đã sửa đổi, bổ sung năm 2025)"},{"id":"vb-001","cd":"vb","m":1,"l":"kt","q":"Theo Luật Ban hành văn bản quy phạm pháp luật, văn bản quy phạm pháp luật (VBQPPL) là văn bản như thế nào?","a":["Có chứa quy phạm pháp luật, ban hành đúng thẩm quyền, hình thức, trình tự, thủ tục","Mọi văn bản do cơ quan nhà nước ban hành, có chữ ký và con dấu hợp lệ","Có chứa quy phạm pháp luật, không phụ thuộc vào thẩm quyền, thủ tục ban hành","Văn bản áp dụng một lần đối với một cá nhân, tổ chức được nêu đích danh"],"why":"VBQPPL phải đồng thời có chứa quy phạm pháp luật và được ban hành đúng thẩm quyền, hình thức, trình tự, thủ tục theo Luật. Thiếu một trong các yếu tố này thì không phải là VBQPPL hợp lệ.","cc":"Điều 2 Luật Ban hành văn bản quy phạm pháp luật số 64/2025/QH15 (sửa đổi, bổ sung bởi Luật số 87/2025/QH15)"},{"id":"vb-002","cd":"vb","m":1,"l":"kt","q":"Trong hệ thống VBQPPL hiện hành, \"cấp xã\" (nơi HĐND được ban hành nghị quyết quy phạm pháp luật) gồm những đơn vị hành chính nào?","a":["Xã, phường, đặc khu trực thuộc cấp tỉnh","Xã, phường, thị trấn","Xã, thị trấn và đặc khu","Huyện, thị xã và xã, phường"],"why":"Luật 87/2025 đưa nghị quyết của HĐND xã, phường, đặc khu trực thuộc cấp tỉnh (gọi chung là cấp xã) vào hệ thống VBQPPL, thay cho nghị quyết của HĐND cấp huyện trong Luật 64/2025.","cc":"Khoản 14 Điều 4 Luật Ban hành văn bản quy phạm pháp luật số 64/2025/QH15 (sửa đổi, bổ sung bởi Luật số 87/2025/QH15)"},{"id":"vb-003","cd":"vb","m":1,"l":"kt","q":"Theo hệ thống VBQPPL hiện hành, cá nhân nào trong chính quyền địa phương cấp tỉnh, cấp xã được ban hành VBQPPL dưới hình thức quyết định?","a":["Chủ tịch UBND cấp tỉnh","Chủ tịch HĐND cấp tỉnh","Chủ tịch UBND cấp xã","Giám đốc sở thuộc UBND cấp tỉnh"],"why":"Luật 87/2025 bổ sung quyết định của Chủ tịch UBND cấp tỉnh vào hệ thống VBQPPL. Ở cấp xã chỉ có nghị quyết của HĐND và quyết định của UBND; Chủ tịch UBND cấp xã không ban hành VBQPPL.","cc":"Khoản 12 Điều 4 Luật Ban hành văn bản quy phạm pháp luật số 64/2025/QH15 (sửa đổi, bổ sung bởi Luật số 87/2025/QH15)"},{"id":"vb-004","cd":"vb","m":1,"l":"kt","q":"Trong hệ thống VBQPPL, Chính phủ ban hành VBQPPL dưới những hình thức nào (không kể nghị quyết liên tịch)?","a":["Nghị định, nghị quyết","Nghị định, quyết định, chỉ thị","Nghị định, thông tư","Pháp lệnh, nghị định"],"why":"Chính phủ ban hành nghị định và nghị quyết. Quyết định là hình thức VBQPPL của Thủ tướng Chính phủ, thông tư của Bộ trưởng, còn pháp lệnh là của Ủy ban Thường vụ Quốc hội.","cc":"Khoản 5 Điều 4 Luật Ban hành văn bản quy phạm pháp luật số 64/2025/QH15 (sửa đổi, bổ sung bởi Luật số 87/2025/QH15)"},{"id":"vb-005","cd":"vb","m":1,"l":"th","q":"Ông H là cử tri ở xã A, muốn góp ý vào dự thảo nghị quyết quy phạm pháp luật của HĐND xã đang được soạn thảo. Theo Luật Ban hành VBQPPL, quyền của ông H được xác định thế nào?","a":["Có quyền và được tạo điều kiện tham gia góp ý kiến về dự thảo","Chỉ được góp ý thông qua đại biểu HĐND xã nơi mình cư trú","Chỉ được góp ý khi cơ quan soạn thảo có giấy mời bằng văn bản","Không có quyền góp ý vì chỉ cơ quan, tổ chức mới được tham gia"],"why":"MTTQ Việt Nam, các tổ chức thành viên của Mặt trận và các cơ quan, tổ chức, cá nhân đều có quyền và được tạo điều kiện tham gia góp ý kiến về chính sách, dự thảo VBQPPL.","cc":"Khoản 3 Điều 6 Luật Ban hành văn bản quy phạm pháp luật số 64/2025/QH15 (sửa đổi, bổ sung bởi Luật số 87/2025/QH15)"},{"id":"vb-007","cd":"vb","m":1,"l":"th","q":"Xã A có đông đồng bào dân tộc thiểu số. UBND xã cho dịch một nghị quyết quy phạm pháp luật của HĐND xã ra tiếng dân tộc để phổ biến. Bản dịch này có giá trị thế nào?","a":["Có giá trị tham khảo","Có giá trị như văn bản gốc","Có giá trị thay thế bản tiếng Việt tại địa bàn xã","Không có giá trị vì VBQPPL không được dịch ra tiếng dân tộc"],"why":"Ngôn ngữ của VBQPPL là tiếng Việt. Văn bản có thể được dịch ra tiếng dân tộc thiểu số, tiếng nước ngoài nhưng bản dịch chỉ có giá trị tham khảo.","cc":"Khoản 4 Điều 7 Luật Ban hành văn bản quy phạm pháp luật số 64/2025/QH15 (sửa đổi, bổ sung bởi Luật số 87/2025/QH15)"},{"id":"vb-008","cd":"vb","m":1,"l":"kt","q":"Về nguyên tắc, một VBQPPL chỉ được sửa đổi, bổ sung, thay thế bằng văn bản nào?","a":["VBQPPL của chính cơ quan, người có thẩm quyền đã ban hành văn bản đó","Văn bản hành chính của cơ quan cấp trên trực tiếp","VBQPPL của bất kỳ cơ quan nhà nước nào cùng cấp","Công văn hướng dẫn của cơ quan chủ trì soạn thảo"],"why":"VBQPPL chỉ được sửa đổi, bổ sung, thay thế bằng VBQPPL của chính chủ thể đã ban hành, trừ trường hợp chia, nhập đơn vị hành chính hoặc luật, nghị quyết của Quốc hội có quy định khác.","cc":"Khoản 1 Điều 8 Luật Ban hành văn bản quy phạm pháp luật số 64/2025/QH15 (sửa đổi, bổ sung bởi Luật số 87/2025/QH15)"},{"id":"vb-010","cd":"vb","m":1,"l":"th","q":"HĐND xã A vừa thông qua một nghị quyết quy phạm pháp luật. Theo quy định hiện hành, nghị quyết này phải được đăng tải trên công báo nào?","a":["Công báo điện tử cấp tỉnh","Công báo điện tử nước Cộng hòa xã hội chủ nghĩa Việt Nam","Công báo điện tử cấp xã","Không phải đăng công báo, chỉ niêm yết tại trụ sở xã"],"why":"VBQPPL của HĐND và UBND các cấp, kể cả cấp xã, phải được đăng tải trên công báo điện tử cấp tỉnh. Công báo điện tử nước CHXHCN Việt Nam dành cho văn bản của cơ quan, người có thẩm quyền ở trung ương.","cc":"Khoản 3 Điều 9 Luật Ban hành văn bản quy phạm pháp luật số 64/2025/QH15 (sửa đổi, bổ sung bởi Luật số 87/2025/QH15)"},{"id":"vb-011","cd":"vb","m":1,"l":"kt","q":"VBQPPL đăng tải trên công báo điện tử có giá trị pháp lý như thế nào?","a":["Có giá trị như văn bản gốc","Chỉ có giá trị tham khảo","Có giá trị như bản sao chưa chứng thực","Chỉ có giá trị khi kèm bản giấy có đóng dấu"],"why":"VBQPPL đăng tải trên công báo điện tử có giá trị như văn bản gốc, nên có thể dùng trực tiếp bản trên công báo điện tử để tra cứu, áp dụng.","cc":"Khoản 4 Điều 9 Luật Ban hành văn bản quy phạm pháp luật số 64/2025/QH15 (sửa đổi, bổ sung bởi Luật số 87/2025/QH15)"},{"id":"vb-023","cd":"vb","m":1,"l":"kt","q":"Với VBQPPL của chính quyền địa phương ban hành theo trình tự thông thường, thời điểm có hiệu lực không được sớm hơn bao nhiêu ngày kể từ ngày thông qua hoặc ký ban hành?","a":["10 ngày","07 ngày","15 ngày","45 ngày"],"why":"Văn bản của chính quyền địa phương có hiệu lực không sớm hơn 10 ngày kể từ ngày thông qua hoặc ký ban hành; mức 45 ngày áp dụng cho văn bản của cơ quan nhà nước ở trung ương.","cc":"Khoản 1 Điều 53 Luật Ban hành văn bản quy phạm pháp luật số 64/2025/QH15 (sửa đổi, bổ sung bởi Luật số 87/2025/QH15)"},{"id":"vb-026","cd":"vb","m":1,"l":"kt","q":"Nghị quyết quy phạm pháp luật của HĐND một xã có hiệu lực trong phạm vi nào?","a":["Trong phạm vi xã đó và phải được quy định cụ thể ngay trong nghị quyết","Trong phạm vi toàn tỉnh nếu được đăng công báo điện tử cấp tỉnh","Trong phạm vi xã đó và các xã giáp ranh có điều kiện tương tự","Trong phạm vi do UBND tỉnh xác định sau khi nghị quyết được ban hành"],"why":"VBQPPL của HĐND, UBND, Chủ tịch UBND ở đơn vị hành chính nào thì có hiệu lực trong phạm vi đơn vị hành chính đó và phạm vi này phải được quy định cụ thể ngay trong văn bản.","cc":"Khoản 2 Điều 54 Luật Ban hành văn bản quy phạm pháp luật số 64/2025/QH15 (sửa đổi, bổ sung bởi Luật số 87/2025/QH15)"},{"id":"vb-032","cd":"vb","m":1,"l":"kt","q":"Khi các VBQPPL có hiệu lực pháp lý khác nhau lại quy định khác nhau về cùng một vấn đề thì áp dụng văn bản nào?","a":["Văn bản có hiệu lực pháp lý cao hơn","Văn bản được ban hành sau","Văn bản được ban hành trước","Văn bản do cơ quan áp dụng tự lựa chọn"],"why":"Các VBQPPL quy định khác nhau về cùng một vấn đề thì áp dụng văn bản có hiệu lực pháp lý cao hơn. Quy tắc áp dụng văn bản ban hành sau chỉ dùng khi các văn bản do cùng một cơ quan ban hành.","cc":"Khoản 3 Điều 58 Luật Ban hành văn bản quy phạm pháp luật số 64/2025/QH15 (sửa đổi, bổ sung bởi Luật số 87/2025/QH15)"},{"id":"vb-033","cd":"vb","m":1,"l":"th","q":"Hai nghị quyết quy phạm pháp luật do HĐND tỉnh ban hành ở hai thời điểm khác nhau, đều đang có hiệu lực, có quy định khác nhau về cùng một vấn đề. Áp dụng quy định của nghị quyết nào?","a":["Nghị quyết được ban hành sau","Nghị quyết được ban hành trước","Nghị quyết có lợi hơn cho ngân sách địa phương","Nghị quyết do UBND tỉnh lựa chọn áp dụng"],"why":"Các VBQPPL do cùng một cơ quan ban hành mà quy định khác nhau về cùng một vấn đề thì áp dụng quy định của văn bản ban hành sau.","cc":"Khoản 4 Điều 58 Luật Ban hành văn bản quy phạm pháp luật số 64/2025/QH15 (sửa đổi, bổ sung bởi Luật số 87/2025/QH15)"},{"id":"vb-040","cd":"vb","m":1,"l":"kt","q":"Luật số 87/2025/QH15 sửa đổi, bổ sung Luật Ban hành VBQPPL (trong đó bổ sung VBQPPL của HĐND, UBND cấp xã) có hiệu lực thi hành từ ngày nào?","a":["01/7/2025","01/4/2025","01/01/2026","01/3/2026"],"why":"Luật số 87/2025/QH15 có hiệu lực thi hành từ ngày 01/7/2025. Ngày 01/4/2025 là ngày có hiệu lực của Luật Ban hành VBQPPL số 64/2025/QH15.","cc":"Điều 2 Luật số 87/2025/QH15 sửa đổi, bổ sung một số điều của Luật Ban hành văn bản quy phạm pháp luật số 64/2025/QH15"},{"id":"vb-006","cd":"vb","m":2,"l":"kt","q":"Phản biện xã hội của MTTQ Việt Nam và các tổ chức chính trị - xã hội đối với dự thảo VBQPPL được thực hiện trong thời gian nào?","a":["Trong thời gian tổ chức soạn thảo văn bản","Trong thời gian cơ quan thẩm tra tiến hành thẩm tra","Sau khi văn bản được thông qua, trước khi có hiệu lực","Sau khi văn bản đã có hiệu lực thi hành"],"why":"Phản biện xã hội được thực hiện ngay trong thời gian tổ chức soạn thảo, để cơ quan chủ trì soạn thảo nghiên cứu tiếp thu, giải trình đầy đủ và công khai trước khi trình.","cc":"Khoản 1 Điều 6 Luật Ban hành văn bản quy phạm pháp luật số 64/2025/QH15 (sửa đổi, bổ sung bởi Luật số 87/2025/QH15)"},{"id":"vb-009","cd":"vb","m":2,"l":"th","q":"UBND tỉnh dự kiến sửa một quyết định quy phạm pháp luật gồm 20 điều do mình ban hành; nội dung sửa đổi, bổ sung liên quan đến 12 điều. Theo Luật Ban hành VBQPPL, UBND tỉnh cần ban hành loại văn bản nào?","a":["Quyết định mới thay thế quyết định hiện hành","Quyết định sửa đổi, bổ sung một số điều của quyết định hiện hành","Văn bản hành chính đính chính quyết định hiện hành","Quyết định bãi bỏ, rồi chờ HĐND tỉnh ban hành nghị quyết mới"],"why":"Khi sửa đổi, bổ sung về nội dung quá một phần hai tổng số điều (ở đây 12/20 điều) hoặc thay đổi cơ bản chính sách, phạm vi điều chỉnh, đối tượng áp dụng thì ban hành văn bản thay thế.","cc":"Điểm b khoản 4 Điều 8 Luật Ban hành văn bản quy phạm pháp luật số 64/2025/QH15 (sửa đổi, bổ sung bởi Luật số 87/2025/QH15)"},{"id":"vb-012","cd":"vb","m":2,"l":"kt","q":"Nội dung nào sau đây thuộc phạm vi HĐND cấp tỉnh ban hành nghị quyết quy phạm pháp luật để quy định?","a":["Thực hiện thí điểm các chính sách theo Luật Tổ chức chính quyền địa phương","Biện pháp chỉ đạo, điều hành hoạt động của UBND cấp tỉnh","Phối hợp hoạt động giữa các cơ quan chuyên môn thuộc UBND cấp tỉnh","Biện pháp thực hiện chức năng quản lý nhà nước ở địa phương"],"why":"Thí điểm chính sách theo Luật Tổ chức chính quyền địa phương do HĐND cấp tỉnh quy định bằng nghị quyết. Chỉ đạo, điều hành, phối hợp thuộc quyết định của Chủ tịch UBND cấp tỉnh; biện pháp quản lý nhà nước thuộc quyết định của UBND cấp tỉnh.","cc":"Điểm d khoản 1 Điều 21 Luật Ban hành văn bản quy phạm pháp luật số 64/2025/QH15 (sửa đổi, bổ sung bởi Luật số 87/2025/QH15)"},{"id":"vb-013","cd":"vb","m":2,"l":"kt","q":"Chủ tịch UBND cấp tỉnh ban hành quyết định quy phạm pháp luật để quy định nội dung nào sau đây?","a":["Biện pháp chỉ đạo, điều hành hoạt động của UBND cấp tỉnh","Chính sách phát triển kinh tế - xã hội, ngân sách ở địa phương","Thí điểm chính sách theo Luật Tổ chức chính quyền địa phương","Chi tiết điều, khoản, điểm được giao trong luật"],"why":"Chủ tịch UBND cấp tỉnh quy định biện pháp chỉ đạo, điều hành hoạt động của UBND cấp tỉnh, phối hợp giữa các cơ quan thuộc UBND và việc phân cấp. Chính sách, thí điểm thuộc HĐND cấp tỉnh; quy định chi tiết thuộc HĐND, UBND cấp tỉnh.","cc":"Điểm a khoản 3 Điều 21 Luật Ban hành văn bản quy phạm pháp luật số 64/2025/QH15 (sửa đổi, bổ sung bởi Luật số 87/2025/QH15)"},{"id":"vb-016","cd":"vb","m":2,"l":"th","q":"Xã A muốn ban hành VBQPPL quy định chính sách, biện pháp nhằm phát triển kinh tế - xã hội trên địa bàn xã. Theo quy định hiện hành, cơ quan nào ban hành và bằng hình thức gì?","a":["HĐND xã, bằng nghị quyết","UBND xã, bằng quyết định","Chủ tịch UBND xã, bằng quyết định","Thường trực HĐND xã, bằng nghị quyết"],"why":"HĐND cấp xã ban hành nghị quyết quy định chính sách, biện pháp nhằm phát triển kinh tế - xã hội ở địa phương. UBND cấp xã ban hành quyết định về biện pháp thi hành và biện pháp quản lý nhà nước; Chủ tịch UBND xã không ban hành VBQPPL.","cc":"Điểm c khoản 2 Điều 22 Luật Ban hành văn bản quy phạm pháp luật số 64/2025/QH15 (sửa đổi, bổ sung bởi Luật số 87/2025/QH15)"},{"id":"vb-017","cd":"vb","m":2,"l":"kt","q":"UBND cấp xã ban hành quyết định quy phạm pháp luật để quy định nội dung nào sau đây?","a":["Biện pháp thi hành nghị quyết của HĐND cùng cấp","Chính sách nhằm phát triển kinh tế - xã hội ở địa phương","Thí điểm chính sách theo Luật Tổ chức chính quyền địa phương","Biện pháp chỉ đạo, điều hành hoạt động của UBND cấp tỉnh"],"why":"UBND cấp xã quy định những vấn đề được luật, nghị quyết của Quốc hội giao; biện pháp thi hành văn bản cấp trên và nghị quyết của HĐND cùng cấp; biện pháp quản lý nhà nước ở địa phương. Chính sách phát triển kinh tế - xã hội do HĐND xã quy định.","cc":"Điểm b khoản 3 Điều 22 Luật Ban hành văn bản quy phạm pháp luật số 64/2025/QH15 (sửa đổi, bổ sung bởi Luật số 87/2025/QH15)"},{"id":"vb-018","cd":"vb","m":2,"l":"kt","q":"Trình tự, thủ tục xây dựng, ban hành VBQPPL của chính quyền địa phương (nghị quyết của HĐND, quyết định của UBND) do cơ quan nào quy định?","a":["Chính phủ","Ủy ban Thường vụ Quốc hội","Bộ Tư pháp","HĐND cấp tỉnh"],"why":"Luật 64/2025 không quy định cụ thể quy trình ở địa phương mà giao Chính phủ quy định trình tự, thủ tục xây dựng, ban hành VBQPPL của Chính phủ, Thủ tướng Chính phủ, Bộ trưởng và chính quyền địa phương.","cc":"Điều 45 Luật Ban hành văn bản quy phạm pháp luật số 64/2025/QH15 (sửa đổi, bổ sung bởi Luật số 87/2025/QH15)"},{"id":"vb-019","cd":"vb","m":2,"l":"kt","q":"Ai có thẩm quyền quyết định việc áp dụng trình tự, thủ tục rút gọn trong xây dựng, ban hành nghị quyết quy phạm pháp luật của HĐND?","a":["Thường trực HĐND, theo đề nghị của cơ quan trình","Chủ tịch UBND cùng cấp, theo đề nghị của cơ quan soạn thảo","HĐND, bằng biểu quyết tại kỳ họp gần nhất","Ban của HĐND được phân công thẩm tra dự thảo"],"why":"Thường trực HĐND quyết định áp dụng trình tự, thủ tục rút gọn đối với nghị quyết của HĐND trên cơ sở đề nghị của cơ quan trình; Chủ tịch UBND quyết định đối với quyết định của UBND.","cc":"Điểm đ khoản 2 Điều 50 Luật Ban hành văn bản quy phạm pháp luật số 64/2025/QH15 (sửa đổi, bổ sung bởi Luật số 87/2025/QH15)"},{"id":"vb-020","cd":"vb","m":2,"l":"th","q":"Sở X chủ trì soạn thảo một quyết định quy phạm pháp luật của UBND tỉnh và thấy cần ban hành gấp theo trình tự, thủ tục rút gọn. Ai quyết định việc áp dụng trình tự, thủ tục rút gọn trong trường hợp này?","a":["Chủ tịch UBND tỉnh, theo đề nghị của Sở X","Thường trực HĐND tỉnh, theo đề nghị của UBND tỉnh","Giám đốc Sở Tư pháp, theo đề nghị của Sở X","Giám đốc Sở X tự quyết định và báo cáo UBND tỉnh"],"why":"Đối với quyết định của UBND, Chủ tịch UBND quyết định áp dụng trình tự, thủ tục rút gọn theo đề nghị của cơ quan chủ trì soạn thảo. Thường trực HĐND chỉ quyết định đối với nghị quyết của HĐND.","cc":"Điểm đ khoản 2 Điều 50 Luật Ban hành văn bản quy phạm pháp luật số 64/2025/QH15 (sửa đổi, bổ sung bởi Luật số 87/2025/QH15)"},{"id":"vb-022","cd":"vb","m":2,"l":"th","q":"Một luật mới được ban hành khiến nghị quyết quy phạm pháp luật của HĐND tỉnh về cùng lĩnh vực cần được sửa đổi ngay cho phù hợp. Luật cho phép áp dụng trình tự, thủ tục nào để kịp thời ban hành nghị quyết sửa đổi?","a":["Trình tự, thủ tục rút gọn","Trình tự, thủ tục trong trường hợp đặc biệt","Chỉ trình tự, thủ tục thông thường, không có ngoại lệ","Ban hành văn bản hành chính thay cho nghị quyết sửa đổi"],"why":"Cần sửa đổi ngay cho phù hợp với VBQPPL mới được ban hành là một trường hợp được áp dụng trình tự, thủ tục rút gọn. Ban hành văn bản trong trường hợp đặc biệt chỉ dành cho Quốc hội, UBTVQH, Chủ tịch nước, Chính phủ.","cc":"Điểm d khoản 1 Điều 50 Luật Ban hành văn bản quy phạm pháp luật số 64/2025/QH15 (sửa đổi, bổ sung bởi Luật số 87/2025/QH15)"},{"id":"vb-025","cd":"vb","m":2,"l":"kt","q":"Nghị quyết của HĐND cấp tỉnh quy định chi tiết nội dung được luật giao phải được ban hành để có hiệu lực vào thời điểm nào?","a":["Cùng thời điểm có hiệu lực của văn bản hoặc nội dung giao quy định chi tiết","Chậm nhất 45 ngày sau ngày luật giao quy định chi tiết có hiệu lực","Sau ngày luật giao quy định chi tiết có hiệu lực ít nhất 10 ngày","Trong thời hạn 06 tháng kể từ ngày luật giao quy định chi tiết có hiệu lực"],"why":"Văn bản quy định chi tiết phải có hiệu lực cùng thời điểm với văn bản hoặc nội dung giao quy định chi tiết, để không tạo khoảng trống khi luật đã có hiệu lực mà chưa có quy định chi tiết.","cc":"Khoản 2 Điều 53 Luật Ban hành văn bản quy phạm pháp luật số 64/2025/QH15 (sửa đổi, bổ sung bởi Luật số 87/2025/QH15)"},{"id":"vb-029","cd":"vb","m":2,"l":"th","q":"HĐND xã A dự kiến ban hành nghị quyết quy phạm pháp luật về một chính sách hỗ trợ và muốn quy định nghị quyết có hiệu lực trở về trước từ đầu năm để người dân được hưởng sớm. Quy định như vậy có được không?","a":["Không, vì VBQPPL của HĐND cấp xã không được quy định hiệu lực trở về trước","Được, vì quy định có lợi cho người dân thì được áp dụng trở về trước","Được, nếu có trên hai phần ba tổng số đại biểu HĐND xã tán thành","Được, nếu UBND tỉnh có văn bản chấp thuận trước khi thông qua"],"why":"VBQPPL của Chủ tịch UBND cấp tỉnh, HĐND cấp xã, UBND cấp xã không được quy định hiệu lực trở về trước. Chỉ văn bản của cơ quan trung ương, HĐND và UBND cấp tỉnh mới có thể có hiệu lực trở về trước khi thật cần thiết.","cc":"Khoản 3 Điều 55 Luật Ban hành văn bản quy phạm pháp luật số 64/2025/QH15 (sửa đổi, bổ sung bởi Luật số 87/2025/QH15)"},{"id":"vb-034","cd":"vb","m":2,"l":"kt","q":"Trường hợp cần thiết, HĐND có thể giao cơ quan nào ban hành văn bản hành chính để hướng dẫn áp dụng nghị quyết quy phạm pháp luật do HĐND ban hành?","a":["Thường trực HĐND cùng cấp","UBND cùng cấp","Ban của HĐND đã thẩm tra dự thảo nghị quyết","Cơ quan chủ trì soạn thảo nghị quyết"],"why":"Cơ quan ban hành VBQPPL hướng dẫn áp dụng văn bản của mình bằng văn bản hành chính; khi cần thiết, HĐND giao Thường trực HĐND cùng cấp ban hành văn bản hành chính để hướng dẫn áp dụng nghị quyết của HĐND.","cc":"Khoản 1 Điều 61 Luật Ban hành văn bản quy phạm pháp luật số 64/2025/QH15 (sửa đổi, bổ sung bởi Luật số 87/2025/QH15)"},{"id":"vb-036","cd":"vb","m":2,"l":"kt","q":"VBQPPL do HĐND, UBND cấp xã ban hành, ngoài việc tự kiểm tra, còn được chủ thể nào kiểm tra theo thẩm quyền?","a":["Chính quyền địa phương cấp trên (cấp tỉnh)","Chính phủ","Bộ trưởng quản lý ngành, lĩnh vực liên quan","Ủy ban Thường vụ Quốc hội"],"why":"HĐND, UBND các cấp tự kiểm tra văn bản do mình ban hành; chính quyền địa phương cấp trên kiểm tra theo thẩm quyền văn bản của cấp dưới. Chính phủ và các Bộ trưởng kiểm tra văn bản của HĐND, UBND, Chủ tịch UBND cấp tỉnh.","cc":"Điểm d khoản 1 Điều 63 Luật Ban hành văn bản quy phạm pháp luật số 64/2025/QH15 (sửa đổi, bổ sung bởi Luật số 87/2025/QH15)"},{"id":"vb-037","cd":"vb","m":2,"l":"th","q":"Một người dân gửi phản ánh rằng quyết định quy phạm pháp luật của UBND xã A có dấu hiệu trái pháp luật. Theo Luật Ban hành VBQPPL, phản ánh này có ý nghĩa gì đối với UBND xã A?","a":["Là căn cứ để UBND xã A thực hiện tự kiểm tra văn bản do mình ban hành","Chỉ có giá trị tham khảo, không phải căn cứ để kiểm tra văn bản","Chỉ được xem xét khi do cơ quan, tổ chức gửi, không phải cá nhân","Phải chuyển HĐND tỉnh xử lý, UBND xã không được tự kiểm tra"],"why":"Kiến nghị, phản ánh của cơ quan, tổ chức, cá nhân về văn bản có dấu hiệu trái pháp luật là một trong các căn cứ để cơ quan ban hành tự kiểm tra, và cũng là căn cứ để cấp trên kiểm tra theo thẩm quyền.","cc":"Điểm b khoản 2 Điều 63 Luật Ban hành văn bản quy phạm pháp luật số 64/2025/QH15 (sửa đổi, bổ sung bởi Luật số 87/2025/QH15)"},{"id":"vb-039","cd":"vb","m":2,"l":"kt","q":"Cơ quan nào thực hiện rà soát, hệ thống hóa VBQPPL do HĐND cấp xã ban hành?","a":["UBND cấp xã","Thường trực HĐND cấp xã","UBND cấp tỉnh","Sở Tư pháp"],"why":"UBND cấp xã rà soát, hệ thống hóa văn bản do cả HĐND và UBND cấp xã ban hành; UBND cấp tỉnh rà soát, hệ thống hóa văn bản do HĐND, UBND và Chủ tịch UBND cấp tỉnh ban hành.","cc":"Khoản 8 Điều 64 Luật Ban hành văn bản quy phạm pháp luật số 64/2025/QH15 (sửa đổi, bổ sung bởi Luật số 87/2025/QH15)"},{"id":"vb-041","cd":"vb","m":2,"l":"kt","q":"Nếu không có văn bản xử lý khác, nghị quyết của HĐND, quyết định của UBND cấp huyện (trước sắp xếp) tiếp tục có hiệu lực trong phạm vi địa giới cấp huyện cũ đến hết ngày nào?","a":["28/02/2027","30/6/2026","31/12/2026","01/7/2027"],"why":"VBQPPL của HĐND, UBND cấp huyện tiếp tục có hiệu lực trong phạm vi địa giới cấp huyện trước sắp xếp đến hết ngày 28/02/2027, trừ khi HĐND, UBND cấp xã đã ban hành văn bản xử lý hoặc cấp trên có quy định khác.","cc":"Khoản 1 Điều 3 Luật số 87/2025/QH15 sửa đổi, bổ sung một số điều của Luật Ban hành văn bản quy phạm pháp luật số 64/2025/QH15"},{"id":"vb-014","cd":"vb","m":3,"l":"th","q":"Tỉnh cần ban hành VBQPPL quy định biện pháp thực hiện chức năng quản lý nhà nước đối với một lĩnh vực trên địa bàn (không đặt ra chính sách mới, không phải việc chỉ đạo, điều hành hoạt động của UBND). Hình thức văn bản nào đúng thẩm quyền?","a":["Quyết định của UBND cấp tỉnh","Nghị quyết của HĐND cấp tỉnh","Quyết định của Chủ tịch UBND cấp tỉnh","Nghị quyết của Thường trực HĐND cấp tỉnh"],"why":"Biện pháp thực hiện chức năng quản lý nhà nước ở địa phương do UBND cấp tỉnh quy định bằng quyết định. HĐND cấp tỉnh quy định chính sách, biện pháp phát triển; Chủ tịch UBND cấp tỉnh quy định việc chỉ đạo, điều hành hoạt động của UBND.","cc":"Điểm c khoản 2 Điều 21 Luật Ban hành văn bản quy phạm pháp luật số 64/2025/QH15 (sửa đổi, bổ sung bởi Luật số 87/2025/QH15)"},{"id":"vb-015","cd":"vb","m":3,"l":"kt","q":"HĐND cấp tỉnh được quy định chi tiết nội dung được giao trong VBQPPL của cơ quan nhà nước cấp trên. Còn HĐND cấp xã ban hành nghị quyết để quy định những vấn đề được loại văn bản nào giao?","a":["Luật, nghị quyết của Quốc hội","Mọi VBQPPL của cơ quan nhà nước cấp trên","Nghị định của Chính phủ, thông tư của Bộ trưởng","Nghị quyết của HĐND, quyết định của UBND cấp tỉnh"],"why":"Về nội dung được giao, HĐND cấp xã chỉ quy định những vấn đề được luật, nghị quyết của Quốc hội giao. Ngoài ra HĐND cấp xã còn quy định chính sách, biện pháp thi hành pháp luật, phát triển kinh tế - xã hội và thực hiện nhiệm vụ được phân cấp.","cc":"Điểm a khoản 2 Điều 22 Luật Ban hành văn bản quy phạm pháp luật số 64/2025/QH15 (sửa đổi, bổ sung bởi Luật số 87/2025/QH15)"},{"id":"vb-021","cd":"vb","m":3,"l":"kt","q":"Trong các trường hợp sau ở địa phương, trường hợp nào người có thẩm quyền được TỰ MÌNH quyết định áp dụng trình tự, thủ tục rút gọn mà không cần có đề nghị?","a":["Chủ tịch UBND cấp tỉnh, đối với quyết định của chính mình","Thường trực HĐND cấp tỉnh, đối với nghị quyết của HĐND","Chủ tịch UBND cấp tỉnh, đối với quyết định của UBND","Thường trực HĐND cấp xã, đối với nghị quyết của HĐND"],"why":"Chủ tịch UBND cấp tỉnh tự mình hoặc theo đề nghị quyết định rút gọn đối với quyết định của mình. Với nghị quyết của HĐND và quyết định của UBND, Thường trực HĐND, Chủ tịch UBND quyết định theo đề nghị của cơ quan trình, cơ quan chủ trì soạn thảo.","cc":"Điểm đ khoản 2 Điều 50 Luật Ban hành văn bản quy phạm pháp luật số 64/2025/QH15 (sửa đổi, bổ sung bởi Luật số 87/2025/QH15)"},{"id":"vb-024","cd":"vb","m":3,"l":"th","q":"Để kịp thời phòng, chống dịch bệnh, UBND tỉnh ban hành quyết định quy phạm pháp luật theo trình tự, thủ tục rút gọn và quy định quyết định có hiệu lực ngay từ ngày ký ban hành. Việc quy định thời điểm có hiệu lực như vậy có đúng luật không?","a":["Đúng, nhưng phải đăng tải ngay và đưa tin trên phương tiện thông tin đại chúng","Sai, vì văn bản của địa phương có hiệu lực không sớm hơn 10 ngày kể từ ngày ký","Đúng, và không cần đăng công báo vì là trường hợp cấp bách","Sai, vì chỉ văn bản của cơ quan trung ương mới được có hiệu lực ngay"],"why":"Văn bản ban hành theo trình tự, thủ tục rút gọn có thể có hiệu lực kể từ ngày thông qua hoặc ký ban hành, nhưng phải được đăng tải ngay trên công báo điện tử, cơ sở dữ liệu quốc gia về pháp luật, cổng thông tin của cơ quan ban hành và đưa tin trên báo chí.","cc":"Khoản 1 Điều 53 Luật Ban hành văn bản quy phạm pháp luật số 64/2025/QH15 (sửa đổi, bổ sung bởi Luật số 87/2025/QH15)"},{"id":"vb-027","cd":"vb","m":3,"l":"th","q":"Ba xã B, C, D được nhập thành xã A mới. HĐND xã B trước đây đã ban hành một nghị quyết quy phạm pháp luật còn hiệu lực. Khi HĐND xã A chưa có văn bản xử lý, nghị quyết đó được áp dụng thế nào?","a":["Tiếp tục có hiệu lực trong phạm vi địa bàn xã B trước khi nhập","Đương nhiên hết hiệu lực từ ngày thành lập xã A","Đương nhiên có hiệu lực trên toàn bộ địa bàn xã A mới","Tạm ngưng hiệu lực cho đến khi UBND tỉnh cho ý kiến"],"why":"Văn bản của đơn vị được nhập tiếp tục có hiệu lực trong phạm vi đơn vị đó cho đến khi HĐND, UBND đơn vị mới ban hành văn bản hành chính quyết định áp dụng hoặc bãi bỏ, hoặc ban hành VBQPPL mới. Quy định này được Luật 87/2025 làm rõ.","cc":"Điểm b khoản 2 Điều 54 Luật Ban hành văn bản quy phạm pháp luật số 64/2025/QH15 (sửa đổi, bổ sung bởi Luật số 87/2025/QH15)"},{"id":"vb-028","cd":"vb","m":3,"l":"th","q":"Một thôn của xã B được điều chỉnh địa giới về xã A. Cả hai xã đều có quyết định quy phạm pháp luật của UBND xã quy định khác nhau về cùng một vấn đề. Sau khi điều chỉnh, văn bản của xã nào có hiệu lực tại thôn này?","a":["Văn bản của xã A, là đơn vị hành chính được mở rộng","Văn bản của xã B, cho đến khi UBND xã A có quyết định khác","Văn bản nào có lợi hơn cho người dân của thôn","Không văn bản nào, cho đến khi UBND tỉnh quyết định"],"why":"Khi một phần địa giới được điều chỉnh về đơn vị hành chính khác thì VBQPPL của đơn vị hành chính được mở rộng có hiệu lực đối với phần địa giới được điều chỉnh; khác với trường hợp nhập nguyên đơn vị hành chính.","cc":"Điểm c khoản 2 Điều 54 Luật Ban hành văn bản quy phạm pháp luật số 64/2025/QH15 (sửa đổi, bổ sung bởi Luật số 87/2025/QH15)"},{"id":"vb-030","cd":"vb","m":3,"l":"th","q":"HĐND tỉnh dự kiến ban hành nghị quyết quy phạm pháp luật có hiệu lực trở về trước, trong đó có quy định trách nhiệm pháp lý nặng hơn đối với một hành vi so với quy định trước đó. Quy định hiệu lực trở về trước như vậy có được không?","a":["Không, vì quy định trách nhiệm pháp lý nặng hơn thì không được có hiệu lực trở về trước","Được, vì HĐND cấp tỉnh được quy định hiệu lực trở về trước trong mọi trường hợp","Được, nếu thật cần thiết để bảo đảm lợi ích chung của xã hội","Không, vì HĐND cấp tỉnh không bao giờ được quy định hiệu lực trở về trước"],"why":"HĐND cấp tỉnh có thể quy định hiệu lực trở về trước khi thật cần thiết, nhưng không được áp dụng với quy định đặt ra trách nhiệm pháp lý mới hoặc trách nhiệm pháp lý nặng hơn.","cc":"Điểm b khoản 2 Điều 55 Luật Ban hành văn bản quy phạm pháp luật số 64/2025/QH15 (sửa đổi, bổ sung bởi Luật số 87/2025/QH15)"},{"id":"vb-031","cd":"vb","m":3,"l":"th","q":"Một luật bị thay thế bằng luật mới. Nghị quyết của HĐND tỉnh quy định chi tiết luật cũ chưa được xử lý. Theo quy định hiện hành (sau sửa đổi năm 2025), hiệu lực của nghị quyết này thế nào?","a":["Hết hiệu lực, trừ trường hợp được công bố tiếp tục có hiệu lực toàn bộ hoặc một phần","Tiếp tục có hiệu lực nếu không trái luật mới, trừ khi được công bố hết hiệu lực","Đương nhiên tiếp tục có hiệu lực cho đến khi HĐND tỉnh bãi bỏ","Hết hiệu lực trong mọi trường hợp, không có ngoại lệ"],"why":"Luật 87/2025 đảo lại quy định của Luật 64/2025: văn bản quy định chi tiết hết hiệu lực theo văn bản được quy định chi tiết, trừ khi được công bố tiếp tục có hiệu lực. Văn bản công bố là văn bản hành chính, phải đăng công báo điện tử.","cc":"Khoản 2 Điều 57 Luật Ban hành văn bản quy phạm pháp luật số 64/2025/QH15 (sửa đổi, bổ sung bởi Luật số 87/2025/QH15)"},{"id":"vb-035","cd":"vb","m":3,"l":"th","q":"Thường trực HĐND tỉnh được HĐND tỉnh giao hướng dẫn áp dụng một nghị quyết quy phạm pháp luật. Dự thảo văn bản hướng dẫn bổ sung thêm một nhóm đối tượng được hưởng chính sách mà nghị quyết chưa quy định. Nội dung bổ sung này có đúng luật không?","a":["Không, vì văn bản hướng dẫn áp dụng không được đặt ra quy định mới","Đúng, vì Thường trực HĐND đã được HĐND giao hướng dẫn áp dụng","Đúng, nếu báo cáo HĐND tỉnh tại kỳ họp gần nhất","Không, vì chỉ UBND tỉnh mới được hướng dẫn áp dụng nghị quyết HĐND"],"why":"Hướng dẫn áp dụng không được làm thay đổi nội dung quy định được hướng dẫn và không được đặt ra quy định mới. Muốn bổ sung đối tượng thì HĐND phải sửa đổi, bổ sung chính nghị quyết đó.","cc":"Khoản 2 Điều 61 Luật Ban hành văn bản quy phạm pháp luật số 64/2025/QH15 (sửa đổi, bổ sung bởi Luật số 87/2025/QH15)"},{"id":"vb-038","cd":"vb","m":3,"l":"th","q":"UBND xã A ban hành một công văn đặt ra quy tắc xử sự chung, bắt buộc đối với mọi hộ kinh doanh trên địa bàn. Có người phản ánh công văn này trái pháp luật. Theo Luật Ban hành VBQPPL, công văn này được xử lý thế nào về mặt kiểm tra văn bản?","a":["Thuộc diện kiểm tra, vì chứa quy phạm pháp luật nhưng ban hành không đúng hình thức","Không thuộc diện kiểm tra, vì công văn không phải là VBQPPL","Được coi là VBQPPL hợp lệ, vì nội dung có chứa quy phạm pháp luật","Chỉ được kiểm tra khi Tòa án có yêu cầu bằng văn bản"],"why":"Cơ quan, người có thẩm quyền kiểm tra cả văn bản có chứa quy phạm pháp luật nhưng không được ban hành đúng thẩm quyền, hình thức, trình tự, thủ tục khi phát hiện dấu hiệu trái pháp luật hoặc có kiến nghị, phản ánh, yêu cầu.","cc":"Khoản 4 Điều 63 Luật Ban hành văn bản quy phạm pháp luật số 64/2025/QH15 (sửa đổi, bổ sung bởi Luật số 87/2025/QH15)"},{"id":"vb-042","cd":"vb","m":3,"l":"th","q":"Tháng 11/2026, HĐND xã A ban hành nghị quyết quy phạm pháp luật về một vấn đề đang được điều chỉnh bởi nghị quyết của HĐND huyện cũ (còn hiệu lực trên địa bàn). Nghị quyết của HĐND xã A phải có nội dung nào để xử lý quan hệ với nghị quyết của HĐND huyện?","a":["Quy định rõ thời điểm không áp dụng nghị quyết của HĐND huyện trên địa bàn xã A","Tuyên bố bãi bỏ nghị quyết của HĐND huyện trên toàn địa bàn huyện cũ","Không cần nội dung nào, vì nghị quyết của HĐND huyện đã hết hiệu lực từ 01/7/2025","Đề nghị HĐND tỉnh bãi bỏ nghị quyết của HĐND huyện trước khi áp dụng"],"why":"Khi ban hành VBQPPL liên quan đến văn bản của cấp huyện, HĐND, UBND cấp xã phải quy định rõ thời điểm không áp dụng văn bản cấp huyện trong phạm vi địa giới xã mình; việc này phải hoàn thành chậm nhất ngày 28/02/2027.","cc":"Khoản 2 Điều 3 Luật số 87/2025/QH15 sửa đổi, bổ sung một số điều của Luật Ban hành văn bản quy phạm pháp luật số 64/2025/QH15"},{"id":"ns-001","cd":"ns","m":1,"l":"kt","q":"Theo Luật Ngân sách nhà nước số 89/2025/QH15, ngân sách địa phương bao gồm những cấp ngân sách nào?","a":["Ngân sách cấp tỉnh và ngân sách cấp xã","Ngân sách cấp tỉnh, cấp huyện và cấp xã","Ngân sách trung ương và ngân sách cấp tỉnh","Ngân sách cấp tỉnh và ngân sách các sở, ngành"],"why":"Ngân sách nhà nước gồm ngân sách trung ương và ngân sách địa phương; ngân sách địa phương chỉ còn hai cấp là cấp tỉnh và cấp xã, phù hợp mô hình chính quyền địa phương 2 cấp.","cc":"Khoản 2 Điều 6 Luật Ngân sách nhà nước số 89/2025/QH15"},{"id":"ns-002","cd":"ns","m":1,"l":"kt","q":"Khoản bổ sung từ ngân sách cấp trên cho ngân sách cấp dưới để hỗ trợ thực hiện các chương trình, dự án, nhiệm vụ cụ thể được Luật Ngân sách nhà nước 2025 gọi là gì?","a":["Số bổ sung có mục tiêu","Số bổ sung cân đối ngân sách","Dự phòng ngân sách nhà nước","Quỹ dự trữ tài chính"],"why":"Số bổ sung có mục tiêu gắn với chương trình, dự án, nhiệm vụ cụ thể; còn số bổ sung cân đối là khoản giúp chính quyền cấp dưới cân đối ngân sách để thực hiện nhiệm vụ được giao.","cc":"Khoản 25 Điều 4 Luật Ngân sách nhà nước số 89/2025/QH15"},{"id":"ns-003","cd":"ns","m":1,"l":"kt","q":"Theo nguyên tắc cân đối ngân sách nhà nước, khoản vay để bù đắp bội chi ngân sách được sử dụng cho mục đích nào?","a":["Chỉ cho chi đầu tư phát triển, không cho chi thường xuyên","Chỉ cho chi thường xuyên, không cho chi đầu tư phát triển","Cho cả chi đầu tư phát triển và chi thường xuyên","Chỉ cho chi trả nợ lãi và bổ sung quỹ dự trữ tài chính"],"why":"Luật quy định vay để bù đắp bội chi chỉ được dùng cho chi đầu tư phát triển, không được dùng cho chi thường xuyên như lương, hội họp, hoạt động bộ máy.","cc":"Khoản 3 Điều 7 Luật Ngân sách nhà nước số 89/2025/QH15"},{"id":"ns-004","cd":"ns","m":1,"l":"kt","q":"Theo Luật Ngân sách nhà nước 2025, ở địa phương, cấp ngân sách nào được phép bội chi?","a":["Chỉ ngân sách cấp tỉnh","Cả ngân sách cấp tỉnh và ngân sách cấp xã","Chỉ ngân sách cấp xã","Không cấp ngân sách nào ở địa phương"],"why":"Chỉ ngân sách địa phương cấp tỉnh được bội chi, và bội chi chỉ được dùng để đầu tư các dự án thuộc kế hoạch đầu tư công trung hạn đã được HĐND cấp tỉnh quyết định. Ngân sách cấp xã không được bội chi.","cc":"Điểm a khoản 5 Điều 7 Luật Ngân sách nhà nước số 89/2025/QH15"},{"id":"ns-007","cd":"ns","m":1,"l":"kt","q":"Theo Luật Ngân sách nhà nước 2025, mức bố trí dự phòng ngân sách ở mỗi cấp là bao nhiêu so với tổng chi ngân sách của cấp đó?","a":["Từ 2% đến 5%","Từ 2% đến 4%","Từ 1% đến 3%","Từ 5% đến 10%"],"why":"Dự phòng được bố trí từ 2% đến 5% tổng chi ngân sách mỗi cấp, dùng cho thiên tai, dịch bệnh, quốc phòng, an ninh và các nhiệm vụ cần thiết khác chưa được dự toán.","cc":"Khoản 1 Điều 10 Luật Ngân sách nhà nước số 89/2025/QH15"},{"id":"ns-010","cd":"ns","m":1,"l":"kt","q":"Cơ quan nào quyết định việc phân cấp nguồn thu, nhiệm vụ chi giữa ngân sách cấp tỉnh và ngân sách cấp xã?","a":["HĐND cấp tỉnh","UBND cấp tỉnh","Chính phủ","Bộ Tài chính"],"why":"HĐND cấp tỉnh quyết định phân cấp nguồn thu, nhiệm vụ chi giữa ngân sách cấp tỉnh và ngân sách cấp xã, phù hợp với phân cấp quản lý kinh tế - xã hội, quốc phòng, an ninh và khả năng quản lý của mỗi cấp.","cc":"Khoản 3 Điều 9 và điểm d khoản 9 Điều 31 Luật Ngân sách nhà nước số 89/2025/QH15"},{"id":"ns-011","cd":"ns","m":1,"l":"kt","q":"Theo Luật Ngân sách nhà nước 2025, khoản thu nào sau đây thuộc nhóm các khoản thu ngân sách địa phương hưởng 100%?","a":["Lệ phí trước bạ","Thuế xuất khẩu, thuế nhập khẩu","Thuế thu nhập cá nhân","Thuế bảo vệ môi trường"],"why":"Lệ phí trước bạ là khoản thu ngân sách địa phương hưởng 100%. Thuế xuất khẩu, nhập khẩu do ngân sách trung ương hưởng 100%; thuế thu nhập cá nhân, thuế bảo vệ môi trường là khoản thu phân chia giữa trung ương và địa phương.","cc":"Điểm e khoản 1 Điều 38 (và điểm e khoản 1 Điều 36) Luật Ngân sách nhà nước số 89/2025/QH15"},{"id":"ns-023","cd":"ns","m":1,"l":"kt","q":"Sau khi lập quyết toán ngân sách địa phương, UBND trình cơ quan nào phê chuẩn?","a":["HĐND cùng cấp","Thường trực HĐND cùng cấp","Cơ quan tài chính cấp trên trực tiếp","Kiểm toán nhà nước"],"why":"Phê chuẩn quyết toán ngân sách địa phương là quyền của HĐND. Trước đó UBND báo cáo Thường trực HĐND cùng cấp để cho ý kiến, nhưng Thường trực HĐND không phải là cơ quan phê chuẩn.","cc":"Khoản 3 Điều 31 và khoản 2 Điều 32 Luật Ngân sách nhà nước số 89/2025/QH15"},{"id":"ns-029","cd":"ns","m":1,"l":"kt","q":"Đối với cơ quan, đơn vị có cổng thông tin điện tử, Luật Ngân sách nhà nước 2025 yêu cầu việc công khai ngân sách phải thực hiện thế nào?","a":["Bắt buộc công khai trên cổng thông tin điện tử của cơ quan, đơn vị","Chỉ cần niêm yết tại trụ sở, không bắt buộc đưa lên cổng thông tin","Được tự chọn một hình thức bất kỳ, không bắt buộc hình thức nào","Chỉ đưa lên cổng thông tin khi công dân có yêu cầu bằng văn bản"],"why":"Việc công khai được thực hiện bằng một hoặc một số hình thức (công bố tại kỳ họp, niêm yết, ấn phẩm, thông báo...), nhưng cơ quan, đơn vị có cổng thông tin điện tử thì bắt buộc phải công khai trên cổng đó.","cc":"Điểm b khoản 1 Điều 15 Luật Ngân sách nhà nước số 89/2025/QH15"},{"id":"ns-030","cd":"ns","m":1,"l":"kt","q":"Theo Luật Ngân sách nhà nước 2025, cơ quan, tổ chức nào chủ trì tổ chức việc giám sát ngân sách nhà nước của cộng đồng?","a":["MTTQ Việt Nam các cấp","Thường trực HĐND các cấp","UBND các cấp","Cơ quan tài chính các cấp"],"why":"Ngân sách nhà nước được giám sát bởi cộng đồng; MTTQ Việt Nam các cấp chủ trì tổ chức, với nội dung gồm việc chấp hành pháp luật về ngân sách, tình hình thực hiện dự toán hằng năm và việc thực hiện công khai ngân sách.","cc":"Khoản 1 Điều 16 Luật Ngân sách nhà nước số 89/2025/QH15"},{"id":"ns-031","cd":"ns","m":1,"l":"kt","q":"Luật Ngân sách nhà nước số 89/2025/QH15 có hiệu lực thi hành từ khi nào (trừ một số nội dung được thực hiện sớm từ ngày 01/7/2025)?","a":["Từ năm ngân sách 2026","Từ năm ngân sách 2025","Từ năm ngân sách 2027","Từ ngày 01 tháng 7 năm 2026"],"why":"Luật có hiệu lực từ năm ngân sách 2026 và thay thế Luật Ngân sách nhà nước số 83/2015/QH13; riêng một số nội dung như tạm cấp ngân sách được thực hiện từ ngày 01/7/2025.","cc":"Khoản 1 Điều 77 Luật Ngân sách nhà nước số 89/2025/QH15"},{"id":"ns-032","cd":"ns","m":1,"l":"kt","q":"Theo Nghị quyết 45/2025/NQ-HĐND của HĐND tỉnh Thanh Hóa, một đối tượng đủ điều kiện hưởng nhiều chính sách, chế độ tương tự nhau quy định tại các văn bản khác nhau thì được hưởng thế nào?","a":["Chỉ được hưởng một chính sách, chế độ cao nhất","Được hưởng cộng dồn các chính sách, chế độ đó","Chỉ được hưởng chính sách, chế độ ban hành sau cùng","Được hưởng tối đa hai chính sách, chế độ tự chọn"],"why":"Đây là nguyên tắc chung trong chế độ chi tiêu bảo đảm hoạt động của HĐND các cấp ở Thanh Hóa: trùng nhiều chính sách, chế độ tương tự thì chỉ hưởng một mức cao nhất, không cộng dồn.","cc":"Khoản 4 Điều 3 Quy định kèm theo Nghị quyết số 45/2025/NQ-HĐND ngày 03/11/2025 của HĐND tỉnh Thanh Hóa"},{"id":"ns-036","cd":"ns","m":1,"l":"kt","q":"Nghị quyết 36/2026/NQ-HĐND của HĐND tỉnh Thanh Hóa phân cấp cho cơ quan nào quyết định phân bổ chi tiết và điều chỉnh danh mục dự án đầu tư công thực hiện Chương trình mục tiêu quốc gia phát triển văn hóa - xã hội, nông thôn, dân tộc và miền núi?","a":["HĐND cấp xã","UBND cấp xã","Chủ tịch UBND cấp xã","Thường trực HĐND cấp xã"],"why":"HĐND tỉnh Thanh Hóa phân cấp cho HĐND cấp xã quyết định phân bổ chi tiết và điều chỉnh danh mục dự án đầu tư công vốn ngân sách trung ương, ngân sách tỉnh thực hiện Chương trình này trên địa bàn xã, phường, áp dụng cho giai đoạn 2026 - 2035.","cc":"Điều 2 Nghị quyết số 36/2026/NQ-HĐND ngày 17/10/2026 của HĐND tỉnh Thanh Hóa"},{"id":"ns-005","cd":"ns","m":2,"l":"kt","q":"Đối với địa phương nhận bổ sung cân đối từ ngân sách trung ương, mức dư nợ vay của ngân sách địa phương không vượt quá bao nhiêu phần trăm số dự toán thu ngân sách địa phương được hưởng theo phân cấp?","a":["80%","120%","60%","100%"],"why":"Địa phương nhận bổ sung cân đối từ ngân sách trung ương: dư nợ vay không quá 80% số dự toán thu ngân sách địa phương được hưởng theo phân cấp; địa phương không nhận bổ sung cân đối: không quá 120%.","cc":"Điểm b khoản 6 Điều 7 Luật Ngân sách nhà nước số 89/2025/QH15"},{"id":"ns-008","cd":"ns","m":2,"l":"th","q":"Giữa năm, xã A bị lũ quét, cần chi ngay để khắc phục hậu quả nhưng khoản chi này chưa có trong dự toán. Theo Luật Ngân sách nhà nước 2025, cơ quan nào quyết định sử dụng dự phòng ngân sách xã và phải báo cáo thế nào?","a":["UBND xã quyết định; định kỳ báo cáo Thường trực HĐND và báo cáo HĐND xã tại kỳ họp gần nhất","HĐND xã họp chuyên đề quyết định trước; sau đó UBND xã mới được sử dụng dự phòng","Thường trực HĐND xã quyết định; UBND xã thực hiện và báo cáo UBND tỉnh","Chủ tịch UBND tỉnh quyết định theo đề nghị của UBND xã; báo cáo HĐND tỉnh"],"why":"UBND các cấp quyết định sử dụng dự phòng ngân sách cấp mình, không phải chờ HĐND họp; nhưng phải định kỳ báo cáo Thường trực HĐND và báo cáo HĐND cùng cấp tại kỳ họp gần nhất.","cc":"Điểm b khoản 4 Điều 10 Luật Ngân sách nhà nước số 89/2025/QH15"},{"id":"ns-009","cd":"ns","m":2,"l":"kt","q":"Số dư của quỹ dự trữ tài chính ở mỗi cấp không được vượt quá bao nhiêu phần trăm dự toán chi ngân sách hằng năm của cấp đó (không bao gồm chi bổ sung có mục tiêu từ ngân sách cấp trên)?","a":["25%","10%","50%","70%"],"why":"Quỹ dự trữ tài chính do Chính phủ và UBND cấp tỉnh lập; số dư ở mỗi cấp không quá 25% dự toán chi ngân sách hằng năm của cấp đó. Các mức 70% và 50% là giới hạn sử dụng, tạm ứng so với số dư đầu năm của quỹ.","cc":"Khoản 1 Điều 11 Luật Ngân sách nhà nước số 89/2025/QH15"},{"id":"ns-012","cd":"ns","m":2,"l":"th","q":"Xã A được cấp trên giao dự toán thu ngân sách nhà nước trên địa bàn năm sau là 20 tỷ đồng. Khi quyết định dự toán, HĐND xã A phải bảo đảm yêu cầu nào đối với dự toán thu ngân sách nhà nước trên địa bàn?","a":["Không thấp hơn mức 20 tỷ đồng được cấp trên giao","Đúng bằng 20 tỷ đồng, không được cao hơn hay thấp hơn","Được thấp hơn 20 tỷ đồng nếu nguồn thu của xã khó khăn","Không cao hơn mức 20 tỷ đồng được cấp trên giao"],"why":"HĐND quyết định dự toán thu ngân sách nhà nước trên địa bàn căn cứ nhiệm vụ được cấp trên giao và tình hình thực tế, nhưng phải bảo đảm không thấp hơn dự toán thu được cấp trên giao; có thể quyết định cao hơn.","cc":"Điểm a khoản 1 Điều 31 Luật Ngân sách nhà nước số 89/2025/QH15"},{"id":"ns-013","cd":"ns","m":2,"l":"kt","q":"Ở địa phương, cơ quan nào quyết định danh mục các chương trình, nhiệm vụ, dự án thuộc kế hoạch đầu tư công trung hạn nguồn ngân sách nhà nước của ngân sách cấp mình?","a":["HĐND cấp đó","UBND cấp đó","Chủ tịch UBND cấp đó","Cơ quan tài chính cùng cấp"],"why":"Đây là nhiệm vụ, quyền hạn của HĐND các cấp: quyết định danh mục chương trình, nhiệm vụ, dự án thuộc kế hoạch đầu tư công trung hạn của ngân sách cấp mình và quyết định chương trình, dự án đầu tư quan trọng của địa phương.","cc":"Khoản 8 Điều 31 Luật Ngân sách nhà nước số 89/2025/QH15"},{"id":"ns-016","cd":"ns","m":2,"l":"kt","q":"Theo Luật Ngân sách nhà nước 2025, khi lập dự toán ngân sách hằng năm, UBND tổng hợp, lập dự toán ngân sách địa phương để báo cáo cơ quan nào cùng cấp xem xét, cho ý kiến?","a":["Thường trực HĐND cùng cấp","Ủy ban MTTQ Việt Nam cùng cấp","Cơ quan thu ngân sách trên địa bàn","Kho bạc Nhà nước nơi giao dịch"],"why":"UBND tổng hợp, lập dự toán ngân sách địa phương báo cáo Thường trực HĐND cùng cấp xem xét, cho ý kiến; UBND cấp tỉnh gửi Bộ Tài chính để tổng hợp, đồng thời gửi Đoàn đại biểu Quốc hội để giám sát.","cc":"Khoản 4 Điều 47 Luật Ngân sách nhà nước số 89/2025/QH15"},{"id":"ns-017","cd":"ns","m":2,"l":"kt","q":"HĐND cấp tỉnh phải quyết định dự toán ngân sách địa phương, phân bổ ngân sách cấp tỉnh năm sau trước ngày nào?","a":["Trước ngày 10 tháng 12","Trước ngày 10 tháng 11","Trước ngày 20 tháng 11","Trước ngày 31 tháng 12"],"why":"Quốc hội quyết định dự toán trước 10/11, Thủ tướng giao dự toán trước 20/11, HĐND cấp tỉnh quyết định dự toán ngân sách địa phương và phân bổ ngân sách cấp tỉnh trước 10/12; 31/12 là hạn hoàn thành việc giao dự toán cho đơn vị.","cc":"Khoản 6 Điều 46 Luật Ngân sách nhà nước số 89/2025/QH15"},{"id":"ns-018","cd":"ns","m":2,"l":"th","q":"HĐND tỉnh quyết định dự toán và phân bổ ngân sách năm sau vào ngày 08/12. HĐND xã A phải quyết định dự toán ngân sách địa phương, phân bổ ngân sách năm sau của cấp mình chậm nhất khi nào?","a":["Chậm nhất là 10 ngày, kể từ ngày HĐND tỉnh quyết định","Chậm nhất là 05 ngày làm việc, kể từ ngày HĐND tỉnh quyết định","Chậm nhất là 20 ngày, kể từ ngày HĐND tỉnh quyết định","Trước ngày 31 tháng 12, không phụ thuộc ngày HĐND tỉnh quyết định"],"why":"HĐND cấp xã quyết định dự toán, phân bổ ngân sách cấp mình chậm nhất 10 ngày kể từ ngày HĐND cấp tỉnh quyết định. Mốc 05 ngày làm việc là thời hạn UBND giao dự toán sau khi HĐND cùng cấp quyết định.","cc":"Khoản 6 Điều 46 Luật Ngân sách nhà nước số 89/2025/QH15"},{"id":"ns-019","cd":"ns","m":2,"l":"th","q":"Tại kỳ họp cuối năm, HĐND xã B chưa thông qua phương án phân bổ ngân sách cấp xã do UBND xã trình. Theo Luật Ngân sách nhà nước 2025, bước xử lý tiếp theo là gì?","a":["UBND xã lập lại phần dự toán chưa được thông qua, trình HĐND xã vào thời gian do HĐND xã quyết định","UBND tỉnh quyết định thay phương án phân bổ ngân sách cho xã B và giao UBND xã thực hiện","Thường trực HĐND xã quyết định thay HĐND xã, sau đó báo cáo HĐND xã tại kỳ họp gần nhất","UBND xã thực hiện theo phương án đã trình, báo cáo giải trình với HĐND xã tại kỳ họp giữa năm sau"],"why":"Khi dự toán hoặc phương án phân bổ chưa được HĐND thông qua, UBND lập lại dự toán với nội dung chưa được thông qua, trình HĐND vào thời gian do HĐND quyết định nhưng không chậm hơn thời gian Chính phủ quy định.","cc":"Khoản 2 Điều 50 Luật Ngân sách nhà nước số 89/2025/QH15"},{"id":"ns-024","cd":"ns","m":2,"l":"kt","q":"HĐND cấp xã xem xét, phê chuẩn báo cáo quyết toán ngân sách cấp mình trong thời hạn nào?","a":["Trước ngày 31 tháng 3 năm sau","Trước ngày 31 tháng 01 năm sau","Trước ngày 01 tháng 5 năm sau","Trước ngày 01 tháng 7 năm sau"],"why":"HĐND cấp xã phê chuẩn quyết toán trước 31/3 năm sau. Ngày 31/01 là hạn kết thúc chỉnh lý quyết toán; trước 01/5 UBND cấp tỉnh gửi quyết toán cho Bộ Tài chính, Kiểm toán nhà nước; trước 01/7 là hạn HĐND cấp tỉnh phê chuẩn.","cc":"Khoản 3 Điều 71 Luật Ngân sách nhà nước số 89/2025/QH15"},{"id":"ns-025","cd":"ns","m":2,"l":"kt","q":"Luật Ngân sách nhà nước 2025 đặt ra yêu cầu riêng nào đối với báo cáo quyết toán của ngân sách cấp xã?","a":["Không được quyết toán chi ngân sách lớn hơn thu ngân sách","Phải được Kiểm toán nhà nước kiểm toán trước khi trình HĐND xã","Phải có kết dư tối thiểu bằng 5% tổng chi ngân sách xã","Phải được UBND cấp tỉnh phê duyệt trước khi trình HĐND xã"],"why":"Ngân sách cấp xã không được bội chi, nên báo cáo quyết toán của ngân sách cấp xã không được quyết toán chi lớn hơn thu.","cc":"Khoản 5 Điều 67 Luật Ngân sách nhà nước số 89/2025/QH15"},{"id":"ns-026","cd":"ns","m":2,"l":"kt","q":"Báo cáo quyết toán ngân sách địa phương phải được cơ quan nào kiểm toán trước khi gửi HĐND cấp tỉnh xem xét, phê chuẩn?","a":["Kiểm toán nhà nước","Bộ Tài chính","Thanh tra Chính phủ","Đơn vị kiểm toán độc lập do UBND cấp tỉnh thuê"],"why":"Kiểm toán nhà nước kiểm toán báo cáo quyết toán ngân sách địa phương trước khi gửi HĐND cấp tỉnh xem xét, phê chuẩn; vì vậy UBND cấp tỉnh phải gửi quyết toán cho Bộ Tài chính và Kiểm toán nhà nước trước ngày 01/5 năm sau.","cc":"Khoản 2 Điều 73 Luật Ngân sách nhà nước số 89/2025/QH15"},{"id":"ns-033","cd":"ns","m":2,"l":"th","q":"Ở một xã của tỉnh Thanh Hóa, hoạt động của HĐND xã phát sinh một khoản chi đột xuất, cần thiết nhưng chưa được bố trí trong dự toán. Theo Nghị quyết 45/2025/NQ-HĐND của HĐND tỉnh Thanh Hóa, khoản chi này được xử lý thế nào?","a":["Thường trực HĐND chuyển UBND xem xét cân đối nguồn xử lý theo Luật Ngân sách nhà nước","Thường trực HĐND tự quyết định chi từ dự phòng ngân sách rồi báo cáo HĐND sau","Chờ HĐND họp kỳ gần nhất quyết định bổ sung dự toán rồi mới được chi","Văn phòng HĐND và UBND tạm ứng từ quỹ dự trữ tài chính để chi trước"],"why":"Kinh phí hoạt động của HĐND do ngân sách bảo đảm và nằm trong dự toán hằng năm; với khoản đột xuất cần thiết chưa có dự toán, Thường trực HĐND chuyển UBND xem xét cân đối nguồn xử lý theo Luật Ngân sách nhà nước.","cc":"Khoản 1 Điều 3 Quy định kèm theo Nghị quyết số 45/2025/NQ-HĐND ngày 03/11/2025 của HĐND tỉnh Thanh Hóa"},{"id":"ns-034","cd":"ns","m":2,"l":"kt","q":"Theo Nghị quyết 45/2025/NQ-HĐND của HĐND tỉnh Thanh Hóa, khi kỳ họp HĐND diễn ra vào thứ bảy, chủ nhật thì mức bồi dưỡng cho Chủ tọa, thư ký kỳ họp được tính thế nào?","a":["Gấp đôi mức quy định","Bằng mức quy định của ngày thường","Gấp 1,5 lần mức quy định","Gấp ba mức quy định"],"why":"Quy định của tỉnh Thanh Hóa nêu rõ trường hợp kỳ họp diễn ra vào thứ bảy, chủ nhật thì bồi dưỡng cho Chủ tọa, thư ký kỳ họp gấp đôi mức quy định.","cc":"Mục I.1 bảng tại Điều 4 Quy định kèm theo Nghị quyết số 45/2025/NQ-HĐND ngày 03/11/2025 của HĐND tỉnh Thanh Hóa"},{"id":"ns-037","cd":"ns","m":2,"l":"th","q":"Thực hiện Nghị quyết 36/2026/NQ-HĐND của HĐND tỉnh Thanh Hóa, HĐND xã A quyết định phân bổ chi tiết vốn Chương trình mục tiêu quốc gia theo danh mục dự án và mức vốn cho từng dự án trên địa bàn. Việc phân bổ này phải nằm trong giới hạn nào?","a":["Trong phạm vi tổng kế hoạch vốn được cấp có thẩm quyền giao","Được vượt tổng kế hoạch vốn được giao không quá 10% nếu dự án cấp bách","Trong phạm vi số thu ngân sách xã được hưởng theo phân cấp","Không bị giới hạn, miễn là dự án thuộc danh mục của Chương trình"],"why":"Theo quy định của tỉnh Thanh Hóa, HĐND cấp xã phân bổ chi tiết theo danh mục dự án, mức vốn bố trí cho từng dự án nhưng chỉ trong phạm vi tổng kế hoạch vốn được cấp có thẩm quyền giao.","cc":"Điều 2 Nghị quyết số 36/2026/NQ-HĐND ngày 17/10/2026 của HĐND tỉnh Thanh Hóa"},{"id":"ns-006","cd":"ns","m":3,"l":"th","q":"Tỉnh cần huy động vốn vay lớn hơn mức dư nợ vay tối đa luật định để thực hiện một dự án của địa phương. UBND tỉnh đã báo cáo HĐND tỉnh (hoặc Thường trực HĐND tỉnh khi HĐND không họp) xem xét, cho ý kiến. Việc này cuối cùng do cơ quan nào quyết định?","a":["Quốc hội quyết định, sau khi Chính phủ xem xét, trình","HĐND tỉnh quyết định, sau khi UBND tỉnh trình","Chính phủ quyết định, sau khi Bộ Tài chính trình","UBTVQH quyết định, sau khi Chính phủ trình"],"why":"HĐND tỉnh hoặc Thường trực HĐND tỉnh chỉ xem xét, cho ý kiến để UBND tỉnh báo cáo Chính phủ; Chính phủ xem xét, trình Quốc hội quyết định việc vay vượt mức dư nợ.","cc":"Điểm c khoản 6 Điều 7 Luật Ngân sách nhà nước số 89/2025/QH15"},{"id":"ns-014","cd":"ns","m":3,"l":"th","q":"HĐND xã A dự định ban hành nghị quyết đặt một khoản phí mới nằm ngoài danh mục của Luật Phí và lệ phí để tăng thu cho xã. Theo Luật Ngân sách nhà nước 2025, việc này có đúng thẩm quyền không?","a":["Không; thẩm quyền này Luật giao cho HĐND cấp tỉnh","Có; HĐND các cấp đều được ban hành phí ngoài danh mục","Có, nếu khoản phí phù hợp với khả năng của xã","Không; thẩm quyền này Luật giao cho UBND cấp tỉnh"],"why":"Chỉ riêng HĐND cấp tỉnh có thêm quyền quyết định thu phí, lệ phí, các khoản đóng góp của nhân dân và được phép ban hành một số khoản thu phí, lệ phí ngoài danh mục của Luật Phí và lệ phí; HĐND cấp xã không có quyền này.","cc":"Điểm e khoản 9 Điều 31 Luật Ngân sách nhà nước số 89/2025/QH15"},{"id":"ns-015","cd":"ns","m":3,"l":"th","q":"Kết thúc năm ngân sách, ngân sách xã B có số tăng thu so với dự toán. Theo Luật Ngân sách nhà nước 2025, cơ quan nào quyết định phương án sử dụng số tăng thu này?","a":["UBND xã quyết định; báo cáo Thường trực HĐND xã kết quả thực hiện và báo cáo HĐND xã tại kỳ họp gần nhất","Thường trực HĐND xã quyết định theo đề nghị của UBND xã; báo cáo HĐND xã tại kỳ họp gần nhất","HĐND xã quyết định tại kỳ họp; UBND xã chỉ được sử dụng sau khi có nghị quyết của HĐND xã","UBND tỉnh quyết định theo đề nghị của UBND xã; UBND xã thực hiện và báo cáo cơ quan tài chính tỉnh"],"why":"Luật 2025 giao UBND quyết định phương án sử dụng tăng thu, dự toán chi còn lại của ngân sách cấp mình; UBND báo cáo Thường trực HĐND kết quả thực hiện và báo cáo HĐND cùng cấp tại kỳ họp gần nhất. Thường trực HĐND không phải là cơ quan quyết định.","cc":"Khoản 3 Điều 32 và khoản 2 Điều 61 Luật Ngân sách nhà nước số 89/2025/QH15"},{"id":"ns-020","cd":"ns","m":3,"l":"th","q":"Đầu năm ngân sách, do HĐND tỉnh chưa quyết định dự toán nên cơ quan tài chính và Kho bạc Nhà nước phải thực hiện tạm cấp ngân sách. Khoản chi nào sau đây KHÔNG thuộc diện được tạm cấp?","a":["Chi mua sắm trang thiết bị làm việc mới cho cơ quan","Chi lương và các khoản có tính chất tiền lương","Chi nghiệp vụ phí và công vụ phí","Chi bổ sung cân đối cho ngân sách cấp dưới"],"why":"Tạm cấp chỉ áp dụng cho nhiệm vụ chi không thể trì hoãn như lương, nghiệp vụ phí, công vụ phí, bổ sung cân đối cho cấp dưới và một số khoản cần thiết khác để bảo đảm hoạt động bộ máy, nhưng loại trừ mua sắm trang thiết bị, sửa chữa.","cc":"Khoản 2 Điều 53 Luật Ngân sách nhà nước số 89/2025/QH15"},{"id":"ns-021","cd":"ns","m":3,"l":"kt","q":"Trong các trường hợp điều chỉnh dự toán ngân sách địa phương sau đây, trường hợp nào UBND phải lập dự toán điều chỉnh trình HĐND cùng cấp quyết định (thay vì UBND tự quyết định rồi báo cáo)?","a":["Khi có nghị quyết của Quốc hội về dự toán điều chỉnh tổng thể ngân sách nhà nước","Khi số thu dự kiến không đạt dự toán, cần điều chỉnh nhiệm vụ chi","Khi cần điều chỉnh cơ cấu chi đầu tư phát triển, chi thường xuyên","Khi cần điều chỉnh dự toán của một số đơn vị dự toán hoặc địa phương cấp dưới"],"why":"Căn cứ nghị quyết của Quốc hội về dự toán điều chỉnh và nhiệm vụ thu, chi được cấp trên giao, UBND lập dự toán điều chỉnh trình HĐND quyết định. Ba trường hợp còn lại do UBND quyết định, định kỳ báo cáo Thường trực HĐND và HĐND tại kỳ họp gần nhất.","cc":"Khoản 1 và khoản 3 Điều 54 Luật Ngân sách nhà nước số 89/2025/QH15"},{"id":"ns-022","cd":"ns","m":3,"l":"kt","q":"Nếu việc bố trí ngân sách của xã không phù hợp với nghị quyết của HĐND cấp tỉnh, cơ quan nào có quyền yêu cầu HĐND cấp xã điều chỉnh dự toán ngân sách?","a":["UBND cấp tỉnh","HĐND cấp tỉnh","Thường trực HĐND cấp tỉnh","Cơ quan tài chính cấp tỉnh"],"why":"Luật giao UBND cấp tỉnh yêu cầu HĐND cấp xã điều chỉnh dự toán khi bố trí ngân sách không phù hợp nghị quyết của HĐND cấp tỉnh; tương tự, Chính phủ yêu cầu HĐND cấp tỉnh điều chỉnh nếu không phù hợp nghị quyết của Quốc hội.","cc":"Khoản 5 Điều 54 Luật Ngân sách nhà nước số 89/2025/QH15"},{"id":"ns-027","cd":"ns","m":3,"l":"th","q":"Tại kỳ họp, HĐND tỉnh chưa phê chuẩn quyết toán ngân sách địa phương và yêu cầu UBND tỉnh làm rõ một số nội dung. Theo Luật Ngân sách nhà nước 2025, UBND tỉnh phải trình lại vào thời gian nào?","a":["Vào thời gian do HĐND quyết định, chậm nhất là sau 10 ngày làm việc","Vào thời gian do UBND đề xuất, chậm nhất là sau 30 ngày","Tại kỳ họp thường lệ kế tiếp, không quy định thời hạn tối đa","Vào thời gian do Thường trực HĐND quyết định, chậm nhất là sau 05 ngày làm việc"],"why":"Khi quyết toán chưa được HĐND phê chuẩn, UBND cùng cấp tiếp tục làm rõ những nội dung HĐND yêu cầu và trình lại vào thời gian do HĐND quyết định, chậm nhất là sau 10 ngày làm việc.","cc":"Khoản 4 Điều 71 Luật Ngân sách nhà nước số 89/2025/QH15"},{"id":"ns-028","cd":"ns","m":3,"l":"kt","q":"Theo Luật Ngân sách nhà nước 2025, kết dư ngân sách cấp xã được xử lý như thế nào?","a":["Hạch toán vào thu ngân sách năm sau","Trích 50% vào quỹ dự trữ tài chính, 50% vào thu ngân sách năm sau","Nộp toàn bộ về ngân sách cấp tỉnh","Dùng để trả nợ gốc và lãi các khoản vay của ngân sách xã"],"why":"Kết dư ngân sách cấp xã được hạch toán vào thu ngân sách năm sau. Việc ưu tiên trả nợ gốc, lãi rồi trích 50% vào quỹ dự trữ tài chính chỉ áp dụng với kết dư ngân sách trung ương và ngân sách cấp tỉnh.","cc":"Khoản 1 Điều 74 Luật Ngân sách nhà nước số 89/2025/QH15"},{"id":"ns-035","cd":"ns","m":3,"l":"th","q":"Ông B vừa là đại biểu HĐND xã, vừa là đại biểu HĐND tỉnh. Theo Nghị quyết 45/2025/NQ-HĐND của HĐND tỉnh Thanh Hóa, việc trang cấp thiết bị máy tính xách tay hoặc máy tính bảng đầu nhiệm kỳ cho ông B được thực hiện thế nào?","a":["Chỉ được trang bị ở cấp tỉnh","Được trang bị ở cả cấp tỉnh và cấp xã","Chỉ được trang bị ở cấp xã","Được tự chọn cấp trang bị theo nguyện vọng"],"why":"Mỗi nhiệm kỳ, đại biểu HĐND được trang cấp 01 thiết bị máy tính xách tay, máy tính bảng hoặc thiết bị tương đương; đại biểu HĐND xã đồng thời là đại biểu HĐND tỉnh thì chỉ được trang bị ở cấp tỉnh, không trang bị trùng.","cc":"Mục VI.2 bảng tại Điều 4 Quy định kèm theo Nghị quyết số 45/2025/NQ-HĐND ngày 03/11/2025 của HĐND tỉnh Thanh Hóa"},{"id":"ns-038","cd":"ns","m":3,"l":"th","q":"Kế hoạch đầu tư công năm 2026 thực hiện Chương trình mục tiêu quốc gia tại xã B đã được HĐND tỉnh phân bổ chi tiết trước khi có Nghị quyết 36/2026/NQ-HĐND của HĐND tỉnh Thanh Hóa. Nay cần điều chỉnh mức vốn giữa các dự án đã được phê duyệt. Theo Nghị quyết này, cơ quan nào được quyết định?","a":["HĐND xã B, trong phạm vi kế hoạch vốn được cấp có thẩm quyền giao","HĐND tỉnh, vì kế hoạch này do HĐND tỉnh đã phân bổ chi tiết","UBND tỉnh, theo đề nghị bằng văn bản của UBND xã B","UBND xã B, sau khi báo cáo Thường trực HĐND xã B"],"why":"Điều khoản chuyển tiếp: kế hoạch đã được HĐND tỉnh phân bổ chi tiết thì tiếp tục thực hiện theo nghị quyết đã ban hành, nhưng HĐND cấp xã được quyết định điều chỉnh danh mục, mức vốn của các dự án đã phê duyệt trong phạm vi kế hoạch vốn được giao.","cc":"Điều 3 Nghị quyết số 36/2026/NQ-HĐND ngày 17/10/2026 của HĐND tỉnh Thanh Hóa"},{"id":"th-001","cd":"th","m":1,"l":"kt","q":"Theo Nghị quyết 1686/NQ-UBTVQH15, sau sắp xếp năm 2025, tỉnh Thanh Hóa có bao nhiêu đơn vị hành chính cấp xã?","a":["166 đơn vị, gồm 147 xã và 19 phường","145 đơn vị, gồm 126 xã và 19 phường","147 đơn vị, gồm 126 xã và 21 phường","187 đơn vị, gồm 166 xã và 21 phường"],"why":"Sau sắp xếp, Thanh Hóa có 166 xã, phường: 147 xã và 19 phường. Trong đó 126 xã, 19 phường hình thành sau sắp xếp và 21 xã giữ nguyên, không sắp xếp.","cc":"Khoản 146 Điều 1 Nghị quyết số 1686/NQ-UBTVQH15 ngày 16/6/2025 của UBTVQH về sắp xếp ĐVHC cấp xã của tỉnh Thanh Hóa"},{"id":"th-002","cd":"th","m":1,"l":"kt","q":"Theo Nghị quyết 1686/NQ-UBTVQH15, chính quyền địa phương ở các xã, phường của Thanh Hóa hình thành sau sắp xếp chính thức hoạt động từ ngày nào?","a":["Ngày 01/7/2025","Ngày 16/6/2025","Ngày 30/9/2025","Ngày 01/01/2026"],"why":"Nghị quyết có hiệu lực từ ngày được thông qua (16/6/2025), nhưng chính quyền ở các xã, phường mới chính thức hoạt động từ 01/7/2025. Mốc 30/9/2025 là hạn công bố diện tích tự nhiên các xã, phường.","cc":"Khoản 2 Điều 2 Nghị quyết số 1686/NQ-UBTVQH15 ngày 16/6/2025 của UBTVQH về sắp xếp ĐVHC cấp xã của tỉnh Thanh Hóa"},{"id":"th-003","cd":"th","m":1,"l":"kt","q":"Theo Nghị quyết 1686/NQ-UBTVQH15, các phường nội đô trước đây như Trường Thi, Điện Biên, Ba Đình, Lam Sơn, Đông Hương, Đông Vệ... được sắp xếp thành phường mới có tên gọi là gì?","a":["Phường Hạc Thành","Phường Hàm Rồng","Phường Đông Quang","Phường Quảng Phú"],"why":"Phường Hạc Thành hình thành từ các phường trung tâm của thành phố Thanh Hóa trước đây; Trung tâm Hội nghị 25B ở phường này là nơi tổ chức Kỳ họp thứ nhất HĐND tỉnh khóa XIX.","cc":"Khoản 127 Điều 1 Nghị quyết số 1686/NQ-UBTVQH15 ngày 16/6/2025 của UBTVQH về sắp xếp ĐVHC cấp xã của tỉnh Thanh Hóa"},{"id":"th-006","cd":"th","m":1,"l":"kt","q":"Kỳ họp thứ nhất HĐND tỉnh Thanh Hóa khóa XIX, nhiệm kỳ 2026–2031 được tổ chức vào ngày nào?","a":["Ngày 27/3/2026","Ngày 15/3/2026","Ngày 25/3/2026","Ngày 01/4/2026"],"why":"Kỳ họp diễn ra sáng 27/3/2026 tại Trung tâm Hội nghị 25B. Ngày 15/3/2026 là ngày bầu cử; ngày 25/3/2026 là ngày Thường trực HĐND tỉnh họp thống nhất chương trình kỳ họp.","cc":"Báo Thanh Hóa điện tử, ngày 27/3/2026 (bài về Kỳ họp thứ nhất HĐND tỉnh Thanh Hóa khóa XIX)"},{"id":"th-008","cd":"th","m":1,"l":"kt","q":"Trong cuộc bầu cử đại biểu Quốc hội khóa XVI và đại biểu HĐND các cấp nhiệm kỳ 2026–2031, tỷ lệ cử tri đi bầu trên địa bàn tỉnh Thanh Hóa đạt bao nhiêu?","a":["99,94%","99,49%","98,73%","94,01%"],"why":"Tỷ lệ cử tri đi bầu ở Thanh Hóa đạt 99,94%, cao nhất trong các lần bầu cử từ trước tới nay. Các con số 94,01% và 98,73% là tỷ lệ trong đợt lấy ý kiến về sắp xếp thôn, tổ dân phố năm 2026.","cc":"Báo Thanh Hóa điện tử, ngày 30/3/2026 (bài “Trách nhiệm với Nhân dân”)"},{"id":"th-018","cd":"th","m":1,"l":"kt","q":"Kế hoạch phát triển kinh tế - xã hội 5 năm giai đoạn 2026–2030 của tỉnh Thanh Hóa được quyết định bằng văn bản nào?","a":["Nghị quyết số 55/NQ-HĐND ngày 17/7/2026 của HĐND tỉnh","Quyết định số 55/QĐ-UBND ngày 17/7/2026 của UBND tỉnh","Nghị quyết số 58-NQ/TW ngày 05/8/2020 của Bộ Chính trị","Nghị quyết số 37/2021/QH15 ngày 13/11/2021 của Quốc hội"],"why":"Kế hoạch 5 năm của tỉnh do HĐND tỉnh khóa XIX quyết định tại Kỳ họp thứ 04 bằng Nghị quyết 55/NQ-HĐND. Nghị quyết 58-NQ/TW và Nghị quyết 37/2021/QH15 là các căn cứ ban hành.","cc":"Nghị quyết số 55/NQ-HĐND ngày 17/7/2026 của HĐND tỉnh Thanh Hóa (phần mở đầu)"},{"id":"th-019","cd":"th","m":1,"l":"kt","q":"Theo Nghị quyết 55/NQ-HĐND của HĐND tỉnh Thanh Hóa, tốc độ tăng trưởng GRDP bình quân giai đoạn 2026–2030 của tỉnh phấn đấu đạt mức nào?","a":["Từ 11% trở lên","Từ 7% trở lên","Từ 9% trở lên","Từ 14% trở lên"],"why":"Chỉ tiêu tăng trưởng GRDP bình quân 2026–2030 là 11% trở lên (tăng trưởng “2 con số”). Các mức 9% và 14% là chỉ tiêu tăng của riêng khu vực dịch vụ và công nghiệp - xây dựng.","cc":"Điểm (1) tiểu mục 2.1 khoản 2 Điều 1 Nghị quyết số 55/NQ-HĐND ngày 17/7/2026 của HĐND tỉnh Thanh Hóa"},{"id":"th-026","cd":"th","m":1,"l":"kt","q":"Theo Chỉ thị 14/CT-TTg năm 2026, đến hết năm 2026 phải bảo đảm bao nhiêu phần trăm cán bộ, công chức, viên chức có hiểu biết về chuyển đổi số, có kiến thức và kỹ năng số?","a":["100%","80%","90%","95%"],"why":"Mục tiêu đến hết năm 2026 là 100% cán bộ, công chức, viên chức có hiểu biết về chuyển đổi số, kiến thức và kỹ năng số, sử dụng tốt các nền tảng, dịch vụ số phục vụ công việc.","cc":"Điểm a khoản 1 Chỉ thị số 14/CT-TTg ngày 22/4/2026 của Thủ tướng Chính phủ"},{"id":"th-030","cd":"th","m":1,"l":"kt","q":"Thành nhà Hồ ở Thanh Hóa được UNESCO công nhận là di sản văn hóa thế giới vào năm nào?","a":["Năm 2011","Năm 1999","Năm 2003","Năm 2014"],"why":"Ngày 27/6/2011, sau 6 năm đệ trình hồ sơ, Thành nhà Hồ được UNESCO công nhận là di sản văn hóa thế giới.","cc":"Wikipedia tiếng Việt, bài “Thành nhà Hồ”"},{"id":"th-031","cd":"th","m":1,"l":"kt","q":"Thành nhà Hồ (thành Tây Đô) là kinh đô của nước ta dưới thời nhà Hồ; khi đó nước ta mang quốc hiệu gì?","a":["Đại Ngu","Đại Việt","Đại Cồ Việt","Vạn Xuân"],"why":"Thành nhà Hồ là kinh đô nước Đại Ngu, quốc hiệu của nước ta dưới thời nhà Hồ (1400–1407).","cc":"Wikipedia tiếng Việt, bài “Thành nhà Hồ”"},{"id":"th-033","cd":"th","m":1,"l":"kt","q":"Khởi nghĩa Lam Sơn, dấy binh từ đất Thanh Hóa, do ai lãnh đạo và nhằm chống lại sự cai trị của triều đại nào?","a":["Lê Lợi; chống nhà Minh","Hồ Quý Ly; chống nhà Minh","Lê Hoàn; chống nhà Tống","Trần Hưng Đạo; chống nhà Nguyên"],"why":"Khởi nghĩa Lam Sơn do Lê Lợi lãnh đạo, bắt đầu từ đầu năm 1418 và kết thúc cuối năm 1427 với thắng lợi của nghĩa quân, quân Minh rút về nước.","cc":"Wikipedia tiếng Việt, bài “Khởi nghĩa Lam Sơn”"},{"id":"th-036","cd":"th","m":1,"l":"kt","q":"Năm 248, Bà Triệu cùng anh là Triệu Quốc Đạt khởi binh chống lại ách cai trị của thế lực nào?","a":["Nhà Đông Ngô","Nhà Đông Hán","Nhà Lương","Nhà Đường"],"why":"Mùa xuân năm Mậu Thìn (248), thấy quan lại nhà Đông Ngô tàn ác, dân khổ sở, Bà Triệu bàn với anh khởi binh chống lại.","cc":"Wikipedia tiếng Việt, bài “Bà Triệu”"},{"id":"th-038","cd":"th","m":1,"l":"kt","q":"Di tích Núi Đọ ở Thanh Hóa nổi tiếng trong khảo cổ học vì phát hiện nào?","a":["Công cụ đá ghè đẽo thô sơ như mảnh tước, hạch đá, rìu tay","Trống đồng và thạp đồng thời dựng nước","Tường thành bằng đá khối thời nhà Hồ","Bia đá và lăng mộ các vua thời Lê sơ"],"why":"Ở Núi Đọ, các nhà khảo cổ tìm thấy rất nhiều công cụ đá ghè đẽo thô sơ (mảnh tước, hạch đá, rìu tay...). Đa số ý kiến xếp chúng vào sơ kỳ thời đại đá cũ, coi là dấu tích của người tối cổ, dù việc định niên đại vẫn còn ý kiến khác.","cc":"Wikipedia tiếng Việt, bài “Núi Đọ”"},{"id":"th-039","cd":"th","m":1,"l":"kt","q":"Văn hóa Đông Sơn – nền văn hóa rực rỡ thời đại kim khí – được gọi theo tên địa danh nào của xứ Thanh?","a":["Một ngôi làng nhỏ ven sông Mã, nơi tìm thấy đồ đồng năm 1924","Một ngọn núi bên sông Chu, nơi tìm thấy công cụ đá cũ","Một vùng đất bên sông Chu, quê hương của Lê Lợi","Một tòa thành đá, kinh đô nước ta thời nhà Hồ"],"why":"Năm 1924, một người câu cá tìm được đồ đồng ở làng Đông Sơn ven sông Mã; tên ngôi làng nhỏ này về sau trở thành tên của cả một nền văn hóa.","cc":"Wikipedia tiếng Việt, bài “Văn hóa Đông Sơn”"},{"id":"th-040","cd":"th","m":1,"l":"kt","q":"Trên trống đồng Đông Sơn, ngôi sao nhiều cánh ở giữa mặt trống tượng trưng cho điều gì?","a":["Thần Mặt Trời","Thần Sấm","Mặt Trăng","Sao Bắc Đẩu"],"why":"Ngôi sao nhiều cánh ở giữa mặt trống tượng trưng cho thần Mặt Trời, gắn với quan niệm của người dân Văn Lang về một vị thần liên quan đến Mặt Trời.","cc":"Wikipedia tiếng Việt, bài “Trống đồng Đông Sơn”"},{"id":"th-044","cd":"th","m":1,"l":"th","q":"Một du khách đến suối cá thần Cẩm Lương, thấy cá bơi dày đặc liền hỏi mua vài con về ăn. Theo tín ngưỡng của người dân địa phương, câu trả lời phù hợp là gì?","a":["Không được, vì cá được coi là linh thiêng, không ai đánh bắt","Được, vì cá ở suối sinh sôi rất nhanh","Chỉ được bắt vào mùa nước cạn hằng năm","Được, nếu nộp phí cho ban quản lý di tích"],"why":"Người dân tin cá ở suối Cẩm Lương là cá thần linh thiêng nên chỉ đến chiêm ngưỡng, cầu may, không ai đánh bắt hay ăn thịt; đàn cá được gìn giữ qua nhiều đời.","cc":"Wikipedia tiếng Việt, bài “Suối cá Cẩm Lương”"},{"id":"th-045","cd":"th","m":1,"l":"kt","q":"Tên gọi “Pù Luông” của khu bảo tồn thiên nhiên nổi tiếng ở phía tây bắc Thanh Hóa bắt nguồn từ tiếng dân tộc Thái, có nghĩa là gì?","a":["Núi lớn","Rừng thiêng","Suối nguồn","Thung lũng mây"],"why":"“Pù Luông” bắt nguồn từ tiếng của đồng bào dân tộc Thái trong vùng, có nghĩa là “núi lớn”.","cc":"Wikipedia tiếng Việt, bài “Khu bảo tồn thiên nhiên Pù Luông”"},{"id":"th-048","cd":"th","m":1,"l":"kt","q":"Theo truyền thuyết, Mai An Tiêm – người bị đày ra đảo hoang mà tương truyền nay thuộc tỉnh Thanh Hóa – được coi là ông tổ của nghề nào ở Việt Nam?","a":["Nghề trồng dưa hấu","Nghề dệt chiếu cói","Nghề làm muối biển","Nghề đúc đồng"],"why":"Trên đảo hoang, An Tiêm gieo hạt giống lạ do chim mang tới và gây được giống dưa hấu quý; ông được coi là ông tổ của nghề trồng dưa hấu tại Việt Nam.","cc":"Wikipedia tiếng Việt, bài “Mai An Tiêm”"},{"id":"th-050","cd":"th","m":1,"l":"kt","q":"Động Từ Thức (còn gọi là động Bích Đào) ở Thanh Hóa gắn liền với truyền thuyết nào?","a":["Vị tri huyện từ quan, vào động kết duyên với tiên nữ","Người bị đày ra đảo hoang, gây được giống dưa quý","Nhà vua trả lại gươm thần cho Rùa Vàng","Hai vị thần giao tranh để cưới công chúa"],"why":"Động Từ Thức là hệ thống hang động núi đá vôi nhiều nhũ đá, gắn với truyền thuyết Từ Thức gặp tiên Giáng Hương; động được xếp hạng di tích cấp quốc gia năm 1992.","cc":"Wikipedia tiếng Việt, bài “Động Từ Thức”"},{"id":"th-007","cd":"th","m":2,"l":"kt","q":"Tại Kỳ họp thứ nhất HĐND tỉnh Thanh Hóa khóa XIX, Ủy ban Bầu cử tỉnh báo cáo kết quả xác nhận tư cách của bao nhiêu đại biểu HĐND tỉnh?","a":["85 đại biểu","75 đại biểu","80 đại biểu","95 đại biểu"],"why":"Cử tri Thanh Hóa đã bầu đủ 85 đại biểu HĐND tỉnh khóa XIX; tại kỳ họp thứ nhất, Ủy ban Bầu cử tỉnh báo cáo kết quả bầu cử và kết quả xác nhận tư cách của cả 85 đại biểu.","cc":"Báo Thanh Hóa điện tử, ngày 27/3/2026 (bài về Kỳ họp thứ nhất HĐND tỉnh Thanh Hóa khóa XIX)"},{"id":"th-009","cd":"th","m":2,"l":"kt","q":"Tại Kỳ họp thứ nhất (27/3/2026), ngoài ba Ban mà luật quy định HĐND tỉnh nào cũng có, HĐND tỉnh Thanh Hóa khóa XIX đã quyết định thành lập thêm Ban nào?","a":["Ban Dân tộc","Ban Pháp chế","Ban Kinh tế - Ngân sách","Ban Văn hóa - Xã hội"],"why":"Ban Pháp chế, Ban Kinh tế - Ngân sách, Ban Văn hóa - Xã hội là các Ban luật định của HĐND tỉnh. Sau khi bầu Chủ tịch, Phó Chủ tịch HĐND tỉnh, kỳ họp quyết định thành lập thêm Ban Dân tộc HĐND tỉnh khóa XIX rồi mới bầu Trưởng các Ban.","cc":"Báo Thanh Hóa điện tử, ngày 27/3/2026 (bài về Kỳ họp thứ nhất HĐND tỉnh Thanh Hóa khóa XIX)"},{"id":"th-010","cd":"th","m":2,"l":"kt","q":"Sau đợt sắp xếp hoàn thành ngày 25/6/2026, toàn tỉnh Thanh Hóa còn bao nhiêu thôn, tổ dân phố?","a":["1.933 thôn, tổ dân phố","2.418 thôn, tổ dân phố","4.126 thôn, tổ dân phố","4.351 thôn, tổ dân phố"],"why":"Toàn tỉnh sắp xếp từ 4.351 xuống còn 1.933 thôn, tổ dân phố, tức giảm 2.418 đơn vị, tương ứng giảm 55,6%. Con số 4.126 là số thôn, tổ dân phố đã tổ chức lấy ý kiến Nhân dân.","cc":"Báo Thanh Hóa điện tử, ngày 25/6/2026 (bài về sắp xếp thôn, tổ dân phố và phân loại đơn vị hành chính)"},{"id":"th-011","cd":"th","m":2,"l":"kt","q":"Theo Đề án phân loại đơn vị hành chính được UBND tỉnh Thanh Hóa thông qua ngày 25/6/2026, tỉnh đạt bao nhiêu điểm so với mức tối thiểu của đơn vị hành chính cấp tỉnh loại I?","a":["81,5 điểm; mức tối thiểu là 75 điểm","75 điểm; mức tối thiểu là 70 điểm","85,1 điểm; mức tối thiểu là 80 điểm","91,5 điểm; mức tối thiểu là 90 điểm"],"why":"Thanh Hóa đạt 81,5 điểm, cao hơn mức tối thiểu 75 điểm của đơn vị hành chính cấp tỉnh loại I. Đề án được UBND tỉnh thông qua để hoàn thiện hồ sơ, báo cáo Bộ Nội vụ xem xét, quyết định.","cc":"Báo Thanh Hóa điện tử, ngày 25/6/2026 (bài về sắp xếp thôn, tổ dân phố và phân loại đơn vị hành chính)"},{"id":"th-013","cd":"th","m":2,"l":"th","q":"Tháng 6/2026, xã A (tỉnh Thanh Hóa) công khai đề án sắp xếp thôn để lấy ý kiến Nhân dân. Theo cách làm của tỉnh được Báo Thanh Hóa phản ánh, ai là người trực tiếp tham gia ý kiến vào đề án?","a":["Cử tri đại diện hộ gia đình ở thôn","Chỉ các đảng viên của chi bộ thôn","Chỉ trưởng thôn và Ban công tác Mặt trận","Các đại biểu HĐND xã ứng cử tại thôn"],"why":"Đề án sắp xếp được công khai để cử tri đại diện hộ gia đình trực tiếp cho ý kiến. Toàn tỉnh có 915.370 cử tri đại diện hộ tham gia (94,01%), trong đó 98,73% đồng ý.","cc":"Báo Thanh Hóa điện tử, ngày 25/6/2026 (bài về sắp xếp thôn, tổ dân phố và phân loại đơn vị hành chính)"},{"id":"th-014","cd":"th","m":2,"l":"th","q":"Xã A (tỉnh Thanh Hóa) đã lấy ý kiến Nhân dân xong về đề án sắp xếp thôn, tỷ lệ đồng thuận rất cao. Theo cách tỉnh thực hiện tháng 6/2026, việc sắp xếp thôn của xã được quyết định bằng hình thức nào?","a":["Trình HĐND xã ban hành nghị quyết sắp xếp thôn","Trình HĐND tỉnh ban hành nghị quyết cho từng xã","Chủ tịch UBND tỉnh ra quyết định cho từng thôn","Trưởng thôn công bố kết quả lấy ý kiến là đủ"],"why":"Đến chiều 25/6/2026, cả 166/166 xã, phường của Thanh Hóa đã hoàn thành việc trình HĐND cùng cấp (HĐND xã, phường) ban hành nghị quyết sắp xếp thôn, tổ dân phố.","cc":"Báo Thanh Hóa điện tử, ngày 25/6/2026 (bài về sắp xếp thôn, tổ dân phố và phân loại đơn vị hành chính)"},{"id":"th-015","cd":"th","m":2,"l":"kt","q":"Theo Chỉ thị 08/CT-TTg năm 2026, bộ máy chính quyền địa phương nhiệm kỳ 2026–2031 phải bảo đảm đi vào hoạt động chậm nhất ngày nào?","a":["Ngày 01/4/2026","Ngày 31/3/2026","Ngày 03/4/2026","Ngày 15/4/2026"],"why":"Bộ máy phải đi vào hoạt động chậm nhất 01/4/2026. Ngày 31/3/2026 là hạn trình phê chuẩn các chức vụ; 03/4/2026 là hạn Thường trực HĐND cấp tỉnh báo cáo kết quả kỳ họp thứ nhất.","cc":"Điểm a Mục I Chỉ thị số 08/CT-TTg ngày 17/3/2026 của Thủ tướng Chính phủ"},{"id":"th-020","cd":"th","m":2,"l":"kt","q":"Theo Nghị quyết 55/NQ-HĐND của HĐND tỉnh Thanh Hóa, chỉ tiêu GRDP bình quân đầu người của tỉnh năm 2030 là bao nhiêu?","a":["7.900 USD trở lên","2.580 USD trở lên","5.200 USD trở lên","9.000 USD trở lên"],"why":"GRDP bình quân đầu người năm 2030 phấn đấu đạt 7.900 USD trở lên. Con số 2.580 USD là chỉ tiêu giá trị tăng thêm ngành chế biến, chế tạo bình quân đầu người.","cc":"Điểm (2) tiểu mục 2.1 khoản 2 Điều 1 Nghị quyết số 55/NQ-HĐND ngày 17/7/2026 của HĐND tỉnh Thanh Hóa"},{"id":"th-021","cd":"th","m":2,"l":"kt","q":"Theo Nghị quyết 55/NQ-HĐND của HĐND tỉnh Thanh Hóa, tỉ trọng giá trị tăng thêm của kinh tế số trong GRDP của tỉnh năm 2030 đạt bao nhiêu?","a":["30%","20%","36%","40%"],"why":"Chỉ tiêu kinh tế số chiếm 30% GRDP vào năm 2030. Mức 36% là chỉ tiêu tỉ trọng công nghiệp chế biến, chế tạo; 40% là tỉ lệ doanh nghiệp có hoạt động đổi mới sáng tạo.","cc":"Điểm (3) tiểu mục 2.1 khoản 2 Điều 1 Nghị quyết số 55/NQ-HĐND ngày 17/7/2026 của HĐND tỉnh Thanh Hóa"},{"id":"th-022","cd":"th","m":2,"l":"kt","q":"Theo mục tiêu tổng quát của Nghị quyết 55/NQ-HĐND, đến năm 2030 Thanh Hóa là một cực tăng trưởng mới, cùng với những địa phương nào tạo thành tứ giác phát triển ở phía Bắc?","a":["Hà Nội, Hải Phòng và Quảng Ninh","Hà Nội, Ninh Bình và Nghệ An","Hà Nội, Hải Phòng và Nghệ An","Ninh Bình, Nghệ An và Hà Tĩnh"],"why":"Mục tiêu đến năm 2030: Thanh Hóa trong nhóm tỉnh dẫn đầu cả nước, cùng Hà Nội, Hải Phòng, Quảng Ninh tạo thành tứ giác phát triển phía Bắc; sau năm 2030 đạt tiêu chuẩn đô thị loại I, thành phố trực thuộc Trung ương.","cc":"Khoản 1 Điều 1 Nghị quyết số 55/NQ-HĐND ngày 17/7/2026 của HĐND tỉnh Thanh Hóa"},{"id":"th-027","cd":"th","m":2,"l":"kt","q":"Theo Chỉ thị 14/CT-TTg năm 2026, cơ quan nào được giao phát triển trợ lý ảo hỗ trợ cán bộ, công chức, viên chức học tập kiến thức, kỹ năng số?","a":["Bộ Khoa học và Công nghệ","Bộ Công an","Bộ Giáo dục và Đào tạo","Bộ Nội vụ"],"why":"Bộ Khoa học và Công nghệ phát triển trợ lý ảo (hoàn thành trong năm 2026). Bộ Công an vận hành nền tảng “Bình dân học vụ số”; Bộ Giáo dục và Đào tạo lo bộ học liệu; Bộ Nội vụ theo dõi, đôn đốc.","cc":"Khoản 4 Chỉ thị số 14/CT-TTg ngày 22/4/2026 của Thủ tướng Chính phủ"},{"id":"th-029","cd":"th","m":2,"l":"th","q":"Bà M., Phó Chủ tịch UBND phường B, cho rằng mình bận công tác quản lý nên việc học kỹ năng số chỉ cần giao cho chuyên viên. Theo Chỉ thị 14/CT-TTg năm 2026, quan điểm nào đúng?","a":["Người giữ chức vụ lãnh đạo, quản lý phải gương mẫu, nghiêm túc học tập kỹ năng số","Lãnh đạo, quản lý được miễn học nếu đã có chuyên viên giúp việc thành thạo","Lãnh đạo, quản lý chỉ cần học khi có kế hoạch kiểm tra của cấp trên","Chỉ công chức trực tiếp giải quyết thủ tục hành chính mới phải học"],"why":"Chỉ thị yêu cầu cán bộ, công chức, viên chức giữ chức vụ lãnh đạo, quản lý phải gương mẫu, nghiêm túc trong việc học tập, nâng cao trình độ, kỹ năng số và coi đây là nhiệm vụ thường xuyên, quan trọng.","cc":"Điểm a khoản 2 Chỉ thị số 14/CT-TTg ngày 22/4/2026 của Thủ tướng Chính phủ"},{"id":"th-032","cd":"th","m":2,"l":"kt","q":"Tòa thành đá nhà Hồ được xây dựng năm 1397 trong khoảng thời gian bao lâu?","a":["Khoảng 3 tháng","Khoảng 1 năm","Khoảng 3 năm","Khoảng 10 năm"],"why":"Thành được xây rất khẩn trương, chỉ khoảng 3 tháng (từ tháng Giêng đến tháng 3 năm 1397), và sau hơn 6 thế kỷ một số đoạn thành vẫn còn tương đối nguyên vẹn.","cc":"Wikipedia tiếng Việt, bài “Thành nhà Hồ”"},{"id":"th-034","cd":"th","m":2,"l":"kt","q":"Sau thắng lợi của khởi nghĩa Lam Sơn, Lê Thái Tổ lên ngôi hoàng đế và lấy niên hiệu là gì?","a":["Thuận Thiên","Quang Thuận","Hồng Đức","Quang Thái"],"why":"Lê Thái Tổ lấy niên hiệu Thuận Thiên, đóng đô ở Đông Kinh (Thăng Long), đồng thời cho xây ở quê hương Lam Sơn một kinh thành gọi là Lam Kinh (Tây Kinh).","cc":"Wikipedia tiếng Việt, bài “Lam Kinh”"},{"id":"th-037","cd":"th","m":2,"l":"th","q":"Một trường học ở xã A tổ chức cho học sinh về nguồn, tìm hiểu nơi tương truyền Bà Triệu cùng nghĩa quân mài gươm, luyện võ khi khởi nghĩa. Nên chọn địa danh nào của xứ Thanh?","a":["Núi Nưa","Núi Đọ","Núi Tùng","Núi Rồng"],"why":"Theo truyền thuyết, núi Nưa là nơi Bà Triệu tập trận, cùng nghĩa quân mài gươm, luyện võ. Núi Tùng là nơi Bà tuẫn tiết và có lăng mộ; núi Đọ là di tích khảo cổ; núi Rồng ở đầu cầu Hàm Rồng.","cc":"Wikipedia tiếng Việt, bài “Núi Nưa”"},{"id":"th-043","cd":"th","m":2,"l":"kt","q":"Các làn điệu Hò sông Mã – dân ca đặc sắc của xứ Thanh – được hát theo lối nào?","a":["Xướng - xô: một người bắt cái kể, các trai đò đồng thanh phụ họa","Đối đáp giao duyên giữa hai bên nam nữ trên bến sông","Độc tấu: một người hát từ đầu đến cuối, không có phụ họa","Hát nói có đàn đáy và phách đệm theo từng khổ"],"why":"Hò sông Mã hát theo lối xướng - xô: câu kể của người bắt cái (thường là người cầm lái) luân phiên với câu đồng thanh phụ họa của các trai đò, gắn với nhịp chèo chống trên sông.","cc":"Wikipedia tiếng Việt, bài “Hò sông Mã”"},{"id":"th-049","cd":"th","m":2,"l":"kt","q":"Trò Xuân Phả – di sản văn hóa phi vật thể quốc gia của xứ Thanh – là các trò diễn dân gian mô tả cảnh gì?","a":["Năm quốc gia cổ đem lễ vật, múa hát chúc mừng Hoàng đế nước Việt","Nghĩa quân Lam Sơn mở hội mừng chiến thắng quân Minh","Trai đò sông Mã chèo thuyền vượt thác ghềnh","Dân làng rước nước, cầu mưa thuận gió hòa đầu năm"],"why":"Trò Xuân Phả mô tả cảnh 5 quốc gia cổ mang lễ vật cùng các tiết mục múa hát đặc sắc đến chúc mừng Hoàng đế nước Việt xưa, với 5 điệu múa trong “Ngũ quốc lân bang đồ tiến cống”.","cc":"Wikipedia tiếng Việt, bài “Trò Xuân Phả”"},{"id":"th-004","cd":"th","m":3,"l":"kt","q":"Theo Nghị quyết 1686/NQ-UBTVQH15, địa bàn thị trấn Thiệu Hóa trước đây được sắp xếp về những xã mới nào?","a":["Thiệu Hóa, Thiệu Quang và Thiệu Trung","Thiệu Hóa, Thiệu Tiến và Thiệu Toán","Thiệu Hóa, Thiệu Trung và Định Hòa","Chỉ riêng xã Thiệu Hóa"],"why":"Một phần thị trấn Thiệu Hóa nhập vào xã Thiệu Hóa (khoản 41), một phần diện tích nhập vào xã Thiệu Quang (khoản 42), phần còn lại nhập vào xã Thiệu Trung (khoản 45). Định Hòa chỉ nhận phần còn lại của xã Thiệu Long.","cc":"Khoản 41, 42 và 45 Điều 1 Nghị quyết số 1686/NQ-UBTVQH15 ngày 16/6/2025 của UBTVQH về sắp xếp ĐVHC cấp xã của tỉnh Thanh Hóa"},{"id":"th-005","cd":"th","m":3,"l":"th","q":"Ngày 20/6/2025, khi Nghị quyết 1686/NQ-UBTVQH15 đã có hiệu lực, ông T. đến UBND xã A (xã thuộc diện sáp nhập) nộp hồ sơ. Có ý kiến cho rằng chính quyền xã A đã hết nhiệm vụ nên không được tiếp nhận. Theo Nghị quyết, hiểu thế nào là đúng?","a":["Chính quyền xã A tiếp tục hoạt động đến khi chính quyền xã mới chính thức hoạt động","Chính quyền xã A chấm dứt hoạt động từ ngày Nghị quyết được thông qua","Xã A chỉ được hoạt động tiếp khi có văn bản ủy quyền của UBND tỉnh","Mọi thủ tục ở xã A phải tạm dừng cho đến hết ngày 30/9/2025"],"why":"Nghị quyết có hiệu lực từ ngày thông qua, nhưng chính quyền ở xã, phường trước sắp xếp vẫn tiếp tục hoạt động cho đến khi chính quyền ở đơn vị mới chính thức hoạt động (01/7/2025), nên việc phục vụ người dân không bị gián đoạn.","cc":"Khoản 3 Điều 2 Nghị quyết số 1686/NQ-UBTVQH15 ngày 16/6/2025 của UBTVQH về sắp xếp ĐVHC cấp xã của tỉnh Thanh Hóa"},{"id":"th-012","cd":"th","m":3,"l":"kt","q":"Theo Báo Thanh Hóa (25/6/2026), quy định về chức danh, số lượng, chế độ, chính sách đối với người hoạt động không chuyên trách ở thôn, tổ dân phố sau sắp xếp do cơ quan nào quyết định?","a":["HĐND tỉnh quyết định, sau khi UBND tỉnh thông qua để trình","UBND tỉnh tự quyết định tại phiên họp chuyên đề","HĐND cấp xã quyết định riêng cho từng địa bàn","Sở Nội vụ quyết định theo ủy quyền của UBND tỉnh"],"why":"UBND tỉnh chỉ xem xét, thống nhất thông qua tại phiên họp chuyên đề ngày 24/6/2026 để báo cáo Ban Thường vụ Tỉnh ủy cho ý kiến, sau đó trình HĐND tỉnh quyết định tại kỳ họp thường kỳ năm 2026.","cc":"Báo Thanh Hóa điện tử, ngày 25/6/2026 (bài về sắp xếp thôn, tổ dân phố và phân loại đơn vị hành chính)"},{"id":"th-016","cd":"th","m":3,"l":"th","q":"Tại kỳ họp thứ nhất nhiệm kỳ 2026–2031, HĐND xã A bầu xong Chủ tịch, Phó Chủ tịch UBND xã. Theo Chỉ thị 08/CT-TTg, Thường trực HĐND xã A phải trình ai phê chuẩn kết quả bầu và chậm nhất khi nào?","a":["Chủ tịch UBND cấp tỉnh, chậm nhất ngày 31/3/2026","Thường trực HĐND cấp tỉnh, chậm nhất ngày 31/3/2026","Chủ tịch UBND cấp tỉnh, chậm nhất ngày 03/4/2026","Bộ trưởng Bộ Nội vụ, chậm nhất ngày 05/4/2026"],"why":"Thường trực HĐND cấp xã trình Chủ tịch UBND cấp tỉnh phê chuẩn chức vụ Chủ tịch, Phó Chủ tịch UBND cấp xã chậm nhất 31/3/2026. Các mốc 03/4 và 05/4/2026 là hạn báo cáo kết quả kỳ họp thứ nhất của HĐND cấp tỉnh.","cc":"Điểm a Mục I Chỉ thị số 08/CT-TTg ngày 17/3/2026 của Thủ tướng Chính phủ"},{"id":"th-017","cd":"th","m":3,"l":"th","q":"Sau kỳ họp thứ nhất nhiệm kỳ 2026–2031, HĐND tỉnh đã bầu Chủ tịch HĐND tỉnh và Chủ tịch UBND tỉnh. Theo Chỉ thị 08/CT-TTg, hai chức vụ này lần lượt được trình cấp nào phê chuẩn?","a":["Chủ tịch HĐND: UBTVQH; Chủ tịch UBND: Thủ tướng Chính phủ","Chủ tịch HĐND: Thủ tướng Chính phủ; Chủ tịch UBND: UBTVQH","Cả hai chức vụ đều do Thủ tướng Chính phủ phê chuẩn","Cả hai chức vụ đều do UBTVQH phê chuẩn"],"why":"Chức vụ Chủ tịch, Phó Chủ tịch UBND cấp tỉnh trình Thủ tướng Chính phủ phê chuẩn; chức vụ Chủ tịch, Phó Chủ tịch HĐND cấp tỉnh trình UBTVQH phê chuẩn (Bộ Nội vụ phối hợp với Ủy ban Công tác đại biểu của Quốc hội trình).","cc":"Điểm b Mục I Chỉ thị số 08/CT-TTg ngày 17/3/2026 của Thủ tướng Chính phủ"},{"id":"th-023","cd":"th","m":3,"l":"kt","q":"Nội dung nào sau đây KHÔNG thuộc 05 trụ cột phát triển của tỉnh Thanh Hóa nêu trong Nghị quyết 55/NQ-HĐND?","a":["Khai thác khoáng sản và vật liệu xây dựng","Công nghiệp chế biến, chế tạo","Logistics và dịch vụ cảng biển","Khoa học công nghệ, đổi mới sáng tạo và chuyển đổi số"],"why":"Năm trụ cột gồm: Công nghiệp chế biến, chế tạo; Nông nghiệp; Du lịch; Khoa học công nghệ, đổi mới sáng tạo và chuyển đổi số; Logistics và dịch vụ cảng biển. Khai khoáng không nằm trong danh sách này.","cc":"Điểm (3) tiểu mục 3.1 khoản 3 Điều 1 Nghị quyết số 55/NQ-HĐND ngày 17/7/2026 của HĐND tỉnh Thanh Hóa"},{"id":"th-024","cd":"th","m":3,"l":"th","q":"Kết quả tăng trưởng quý vừa được công bố cho thấy tỉnh không đạt kịch bản tăng trưởng đã đề ra. Theo giải pháp nêu trong Nghị quyết 55/NQ-HĐND, cần xử lý thế nào?","a":["Khẩn trương rà soát, cập nhật kịch bản; nhận diện điểm nghẽn để điều chỉnh giải pháp","Giữ nguyên kịch bản, chờ kết quả cả năm rồi mới đánh giá, điều chỉnh","Đề nghị hạ mục tiêu tăng trưởng cả giai đoạn xuống dưới 11%","Tạm dừng các dự án đầu tư công đến khi tăng trưởng phục hồi"],"why":"Căn cứ kết quả tăng trưởng công bố hằng quý, nếu không đạt kịch bản thì phải khẩn trương rà soát, cập nhật kịch bản, nhận diện đầy đủ điểm nghẽn, xác định động lực, dư địa và điều chỉnh giải pháp để vẫn hoàn thành mục tiêu.","cc":"Điểm (1) tiểu mục 3.2 khoản 3 Điều 1 Nghị quyết số 55/NQ-HĐND ngày 17/7/2026 của HĐND tỉnh Thanh Hóa"},{"id":"th-025","cd":"th","m":3,"l":"th","q":"Một doanh nghiệp đề xuất đầu tư dự án chăn nuôi lợn mới tại xã A. Theo định hướng phát triển chăn nuôi trong Nghị quyết 55/NQ-HĐND của HĐND tỉnh Thanh Hóa, dự án mới chỉ được chấp thuận khi nào?","a":["Khi đáp ứng yêu cầu về môi trường và gắn với chế biến sâu","Khi cam kết tạo việc làm cho lao động của xã A","Khi quy mô đạt mức trang trại tập trung công nghệ cao","Khi nằm cách khu dân cư tập trung từ 5 km trở lên"],"why":"Nghị quyết yêu cầu quản lý chặt các dự án chăn nuôi lợn hiện có và chỉ chấp thuận dự án mới khi đáp ứng được yêu cầu về môi trường và gắn với chế biến sâu.","cc":"Tiết a điểm (3) tiểu mục 3.2 khoản 3 Điều 1 Nghị quyết số 55/NQ-HĐND ngày 17/7/2026 của HĐND tỉnh Thanh Hóa"},{"id":"th-028","cd":"th","m":3,"l":"th","q":"Năm 2026, UBND tỉnh tổ chức cho công chức xã A chủ động tự học kiến thức, kỹ năng số trên nền tảng “Bình dân học vụ số”. Theo Chỉ thị 14/CT-TTg, năm 2026 phải sử dụng bộ học liệu nào?","a":["Bộ học liệu ban hành theo Quyết định 522/QĐ-BGDĐT của Bộ Giáo dục và Đào tạo","Khung kiến thức, kỹ năng số theo Quyết định 757/QĐ-BKHCN của Bộ Khoa học và Công nghệ","Chương trình, học liệu do tỉnh tự xây dựng, ban hành và đăng tải","Tài liệu do từng xã, phường tự biên soạn theo nhu cầu"],"why":"Năm 2026 dùng bộ học liệu theo Quyết định 522/QĐ-BGDĐT. Từ năm 2027 bộ, ngành, tỉnh mới tự xây dựng, đăng tải chương trình, học liệu. Quyết định 757/QĐ-BKHCN dùng để khảo sát, đánh giá, xác nhận hoàn thành.","cc":"Điểm b khoản 2 Chỉ thị số 14/CT-TTg ngày 22/4/2026 của Thủ tướng Chính phủ"},{"id":"th-035","cd":"th","m":3,"l":"kt","q":"Năm 1424, bước ngoặt của khởi nghĩa Lam Sơn đến khi Lê Lợi nghe theo kế của ai, tiến vào giải phóng Nghệ An để làm bàn đạp đánh ra những nơi khác?","a":["Nguyễn Chích","Nguyễn Trãi","Lê Lai","Trần Nguyên Hãn"],"why":"Giai đoạn đầu nghĩa quân gặp nhiều khó khăn ở Thanh Hóa. Bước ngoặt đến khi Lê Lợi theo kế của Nguyễn Chích, tiến vào Nghệ An năm 1424, lấy đó làm bàn đạp mở rộng vùng giải phóng.","cc":"Wikipedia tiếng Việt, bài “Khởi nghĩa Lam Sơn”"},{"id":"th-046","cd":"th","m":3,"l":"kt","q":"Bộ Đại Việt sử ký của Lê Văn Hưu (người xứ Thanh) – bộ quốc sử đầu tiên của Việt Nam – ghi chép lịch sử trong khoảng thời gian nào?","a":["Từ Triệu Vũ đế đến Lý Chiêu Hoàng","Từ họ Hồng Bàng đến Lê Thái Tổ","Từ Ngô Quyền đến Trần Thái Tông","Từ An Dương Vương đến Trần Nhân Tông"],"why":"Đại Việt sử ký (30 quyển, hoàn thành năm 1272) chép gần 15 thế kỷ, từ Triệu Vũ đế đến Lý Chiêu Hoàng. Phạm vi “từ họ Hồng Bàng đến Lê Thái Tổ” là của bộ sử do Ngô Sĩ Liên soạn về sau.","cc":"Wikipedia tiếng Việt, bài “Lê Văn Hưu”"},{"id":"th-047","cd":"th","m":3,"l":"kt","q":"Danh xưng “Thanh Hóa” bắt đầu có từ thời điểm nào?","a":["Năm 1029, đời Lý Thái Tông, khi đổi Ái Châu thành phủ Thanh Hoá","Năm 1242, đời Trần Thái Tông, khi đổi 24 lộ thành 12 lộ","Năm 1397, đời Trần Thuận Tông, khi đặt trấn Thanh Đô","Năm 1469, niên hiệu Quang Thuận, khi đổi thành Thừa Tuyên Thanh Hoa"],"why":"Năm Thiên Thành thứ 2 (1029), Lý Thái Tông đổi Ái Châu thành phủ Thanh Hoá; danh xưng Thanh Hóa có từ đây. Các mốc 1242, 1397, 1469 là những lần đổi tên, đổi cấp hành chính về sau.","cc":"Wikipedia tiếng Việt, bài “Thanh Hóa”"}]};
